INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_comp_general', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'General Computer', 'top_computer', 585, 1790966319323) ON CONFLICT(id) DO UPDATE SET total_mcqs = 585;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_07b8856a59468528', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In which view headers and footers are visible?', '{"A":"Normal View","B":"Page Layout View","C":"Print Layout View","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Headers and footers are visible in Page Layout View and Print Layout View.They appear at the top and bottom of a page.They can contain page numbers, dates, document titles, and other information.Additional information:Page Layout View: Shows how the page will appear when printed, including headers and footers.Print Layout View: Displays the document with its page structure, including headers and footers.Last verified on 02-10-2026', 0, 0, 0, 1790966319434) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c4b76e6bd4aed5f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following combination of keys is used to maximize or restore a selected window?', '{"A":"Ctrl + F5","B":"Ctrl + F10","C":"Ctrl + F12","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + F10 → Maximize/Restore selected document windowAdditional information:Alt + F4 → Close the active windowAlt + Tab → Switch between open windowsWindows + Up Arrow → Maximize the current windowWindows + Down Arrow → Restore or minimize the current windowLast verified on 23-07-2026', 0, 0, 0, 1790966319434) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_05db47696deace33', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which key is used to rename a file or folder?', '{"A":"F1","B":"F2","C":"F3","D":"F4"}', 'B', NULL, 0, 0, 0, 1790966319435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d4d86afd71cd83be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which means sending and receiving data through transmission medium?', '{"A":"Data","B":"Analog signals","C":"Data Transmission","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Data transmission means sending and receiving data through a transmission medium.It allows information to move from one device to another.Transmission media can be wired or wireless.Wired: Twisted-pair cable, coaxial cable, fiber-optic cable.Wireless: Radio waves, microwaves, infrared, and satellite communication.Last verified on 28-09-2026', 0, 0, 0, 1790966319435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4f417dc5c26d0013', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Two are more computers connected to each other for sharing information from a _____?', '{"A":"Pipeline","B":"Router","C":"Server","D":"Network"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A network is a group of two or more computers connected together.It allows computers to share information and resources.Resources may include files, printers, applications, and internet connections.Additional information:Router: A device that directs data between networks.Server: A computer that provides services or resources to other computers.Pipeline: A mechanism for processing or transferring data.Last verified on 28-09-2026', 0, 0, 0, 1790966319435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_09e3f9a52af42c14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which key is used to refresh all web pages?', '{"A":"F7","B":"F5","C":"F6","D":"F8"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation F5 key is used to refresh or reload a web page.It updates the page to show the latest content.Commonly used in browsers like Google Chrome and Mozilla Firefox.Additional information:Ctrl + R → Refresh pageCtrl + Shift + R → Hard refresh (clear cache)F11 → Full screen modeCtrl + T → Open new tabCtrl + W → Close current tabLast verified on 19-04-2026', 0, 0, 0, 1790966319435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_000cff8f90988b7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The intersection of columns and rows in called a?', '{"A":"Schema","B":"Cell","C":"Table","D":"Data"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Cell is the intersection of a row and a column in a spreadsheet such as MS Excel.Each cell has a unique cell address, such as A1, B5, or C10.Rows are identified by numbers: 1, 2, 3, ...Columns are identified by letters: A, B, C, ...A cell can contain text, numbers, formulas, or functions.Last verified on 09-08-2026', 0, 0, 0, 1790966319435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b041e8b015d04022', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Another name of a cell address is ______?', '{"A":"Cell identity","B":"Cell reference","C":"Current cell","D":"Cell margin"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A cell address is also called a cell reference.It identifies a specific cell in a spreadsheet.It is written using a column letter and row number.Last verified on 27-09-2026', 0, 0, 0, 1790966319435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a23066b1c25cc754', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To insert a hyperlink which shortkey is used?', '{"A":"Ctrl+S","B":"Ctrl+M","C":"Ctrl+K","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + K → Insert HyperlinkAdditional information:Ctrl + P → PrintCtrl + F2 → Print PreviewCtrl + H → Replace dialog boxCtrl + D → Font dialog boxLast verified on 06-07-2026', 0, 0, 0, 1790966319542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_55037eac15621315', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What does the SmartArt feature help users do?', '{"A":"Compress presentation","B":"Sort table data","C":"Create organizational diagrams and visuals","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SmartArt in MS Office helps users visually represent information using diagrams like hierarchy charts, cycles, lists, and processes.It is useful for making organizational structures, workflows, and infographics in a clear and professional format.Last verified on 27-09-2026', 0, 0, 0, 1790966319542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_26eb8fb42ccdeb41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the name of a device that converts digital signals to analog signals?', '{"A":"Router","B":"Switch","C":"Modem","D":"None of above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Modem (Modulator-Demodulator) converts digital signals into analog signals and vice versa.It is used to connect computers to the internet via telephone lines or other networks.Additional information:Switch – connects multiple devices in a networkHub – basic network connectorRepeater – boosts signal strengthRouter – directs internet trafficLast verified on 19-04-2026', 0, 0, 0, 1790966319542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eb92d506715e7dac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is a portable machine?', '{"A":"Laptop","B":"Works Station","C":"Super Computer","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Laptop: A portable computer you can easily carry and use in different places.Battery-powered: Can operate without a direct power connection for a limited time.Smaller and lighter than a desktop computer.Last updated by NA ON 16-09-2026', 0, 0, 0, 1790966319542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0ca9e974f755ad9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A small or intelligent device is so called because it contains a ____ within it .', '{"A":"Sensor","B":"computer","C":"laptop","D":"Program"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Intelligent Device: Contains a microprocessor (or Sensor)Microprocessor: Acts as the brain of the device.Function: Processes data and instructions.Examples: Smartphone, smartwatch, calculator.Last updated NS on 13-09-2026', 0, 0, 0, 1790966319542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c81db93fe656a828', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The SQL command used to retrieve data from a database table is?', '{"A":"SELECT","B":"FETCH","C":"RETRIEVE","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SQL command used to retrieve data from a database table is the SELECT statement.This command is fundamental to the Data Query Language (DQL) in SQL.Last verified on 07-06-2026', 0, 0, 0, 1790966319542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7a79758b339a803a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which is a device that connects two or more networks with different types of protocols?', '{"A":"Gateway","B":"Bridge","C":"Router","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gateway — connects networks with different protocols; performs protocol conversion (works up to the application layer).Additional information:Bridge — connects networks using the same protocol (data link layer).Router — connects networks using the same protocol, typically IP (network layer).Last updated NA on 10-09-2026', 0, 0, 0, 1790966319542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d67bfb4622242ca4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'F2 is used for?', '{"A":"Spelling Checking","B":"Rename files and folders","C":"Hide file or folder","D":"Print document"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation F2: Renames a selected file, folder, or icon.Additional information:F1: HelpF2: RenameF3: Search files/foldersF4: +Alt: Close windowF5: RefreshF6: Jump to address barF7: Spell/grammar checkF8: Safe Mode at startupF9: Update fieldsF10: Activate menu barF11: Full screenF12: Save AsLast updated NA on 10-09-2026', 0, 0, 0, 1790966319542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a7aa1df766a558fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Time required for a computer to locate and transfer data is called?', '{"A":"Basic Time","B":"Starting Point","C":"Access Time","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Access time is the time required by a computer to locate and access data.It is an important measure of the speed of memory or storage devices.Lower access time generally means faster data retrieval.Last verified on 08-09-2026', 0, 0, 0, 1790966319654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cccc5d3d804edb50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is an example of Database Management System?', '{"A":"MS Word","B":"ORACLE","C":"Adobe Photoshop","D":"US Power Point"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ORACLE is a Database Management System (DBMS) used for storing, retrieving, and managing data in databases.ORACLE is specifically designed to handle database operations.Last verified on 08-09-2026', 0, 0, 0, 1790966319654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3b1c06f464536bca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which key is used to create chart from selected data in excel?', '{"A":"F10","B":"F1","C":"F11","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation F11 creates a chart from the selected data and places it on a new chart sheet.Alt + F1 creates a chart directly on the current worksheet.Last verified on 07-09-2026', 0, 0, 0, 1790966319654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ddaaa93fecf1a1e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The page orientation can be in ___ style.', '{"A":"Landscape","B":"Portrait","C":"Landscape and Portrait","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Page orientation refers to the direction in which a page is displayed or printed.Portrait is vertical in orientation.Landscape is horizontal in orientation.Both orientations are commonly available in word-processing applications such as Microsoft Word.Last verified on 07-09-2026', 0, 0, 0, 1790966319654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a8c00e5311048bb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A set of instructions/steps/rules that are followed to solve a problem is called _____?', '{"A":"Procedure","B":"Method","C":"Algorithm","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An algorithm is a step-by-step set of rules to solve a problem.It is used in programming and computer science.Algorithms must be clear, finite, and logical.Every computer program is based on an algorithm.It works like a recipe to reach a solution.Last verified on 07-02-2026', 0, 0, 0, 1790966319654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_607d1b30808faa07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The transfer of data from one place to another is called?', '{"A":"Data processing","B":"Data distribution","C":"Data communication","D":"Data encryption"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The transfer of data from one place to another is called data communication. It involves sending data through a communication medium like cables or wireless signals.Last verified on 05-09-2026', 0, 0, 0, 1790966319654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8b2758d22024ca09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which is called the physical part of computer?', '{"A":"Software","B":"Hardware","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The physical part of a computer is called hardware.Hardware refers to all the tangible parts of a computer that contribute to its functionality.Some examples of hardware include: Motherboard, RAM, CPU, Mouse, Keyboard, CD, DVD, Hard disk, Monitor, and Case.Additional information:In contrast, software is the intangible part of a computer that helps it perform its functions.Software is made up of programs, procedures, and routines that run the computer system.Last verified on 04-09-2026', 0, 0, 0, 1790966319654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_97f5d9f8abd308cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A collection of related data is called ____?', '{"A":"Database","B":"Software","C":"Hardware","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A collection of related data is called a Database.A database stores and organizes related information so it can be easily accessed, managed, and updated.Examples include student records, employee information, and customer details.A DBMS (Database Management System) is software used to create and manage databases.Last verified on 08-08-2026', 0, 0, 0, 1790966319654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d78887e6b031b20d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A collection of raw facts and figure is called _____?', '{"A":"Information","B":"Data","C":"Processing","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Data refers to a collection of raw facts and figures.Data can include numbers, words, symbols, or observations.When data is processed and organized, it becomes information.Example: 85, 90, 76 are raw data; their calculated average is information.Last verified on 03-09-2026', 0, 0, 0, 1790966319746) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9bce3d76093a0700', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How long is an IPv4?', '{"A":"64 bits","B":"48 bits","C":"32 bits","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IPv4 (Internet Protocol version 4) uses a 32-bit address system.It allows about 4.3 billion unique IP addresses.It is written in dotted decimal format (e.g., 192.168.1.1).Additional information:IPv6 length → 128 bitsLast verified on 26-05-2026', 0, 0, 0, 1790966319746) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_df9a59ced9804fb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Raw data processed by a computer becomes?', '{"A":"Information","B":"Output","C":"Memory","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Raw data processed by a computer becomes Information.Data consists of raw, unorganized facts and figures.After processing, data becomes meaningful and useful information.Information helps users make decisions.Last verified on 13-07-2026', 0, 0, 0, 1790966319746) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a11a3926152ecca7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To verify that the note text is positioned correctly on the page, switch to _____ view or display the document in print preview.', '{"A":"Print layout","B":"Page layout","C":"Page edit","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Print Layout view shows the document as it will appear when printed.It helps verify the positioning and formatting of text on the page.Print Preview also displays the document''s expected printed appearance.It is useful for checking margins, page arrangement, and text placement.Last verified on 23-08-2026', 0, 0, 0, 1790966319746) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fb58bf31d773edbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which corner of the Word window has the zoom control?', '{"A":"Lower-right","B":"Upper-left","C":"Lower-left","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location: Lower-right cornerFound On: Status BarFunction: Zoom In / Zoom OutDefault Zoom: Usually 100%Shortcut: Ctrl + Mouse Wheel (Zoom In/Out)Last verified on 18-07-2026', 0, 0, 0, 1790966319746) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_07560f7c9e6b7dab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How many margins are there on a page?', '{"A":"Two (header and footer)","B":"Four (top, bottom, right and left)","C":"Two (landscape and portrait)","D":"Four (Top, Bottom, Left & Right)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are four margins on a standard page of a documentTop marginBottom marginLeft marginRight margin These margins are the blank spaces surrounding the text,The standard margin size is generally 1 inch (or 2.54 cm) on all four sidesLast updated by NS on 06 May 2026', 0, 0, 0, 1790966319746) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3c0a645ed70c6af4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Getting data from a cell located in a different Excel Sheet is called?', '{"A":"Accessing","B":"Referencing","C":"Updating","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Referencing means referring to or retrieving data from another cell or worksheet.In Excel, a reference to another sheet can be written as =Sheet2!A1.This allows data from one worksheet to be used in another worksheet.It is especially useful for linking related data across multiple sheets.There are Three types of Cell reference in Excel.RelativeAbsoluteMixedLast verified on 26-08-2026', 0, 0, 0, 1790966319746) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_598992dc6985839b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In order to edit a chart, you can _______?', '{"A":"Click the chart object","B":"Triple click the chart object","C":"Click and drag the chart object","D":"Double click the chart object"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, double-clicking a chart object opens the chart for editing.You can then modify its data, design, layout, titles, and formatting.A single click generally selects the chart.Clicking and dragging is mainly used to move the chart.Last verified on 24-08-2026', 0, 0, 0, 1790966319746) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2cf5309033b09480', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'From which menu picture can be inserted?', '{"A":"Insert","B":"Picture","C":"Clipart","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, pictures can be inserted through the Insert tab/menu.The Pictures option is available under the Insert tab.You can insert pictures from your device or other available sources.Clip Art was available in older versions of Microsoft Office.Last verified on 24-06-2026', 0, 0, 0, 1790966319895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e02b9fabe573e68c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How do you apply bold formatting to text in Word?', '{"A":"Press Ctrl + I","B":"Press Ctrl + B","C":"Press Ctrl + U","D":"Press Ctrl + S"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To apply bold formatting to text in Microsoft Word, you can press Ctrl + B on your keyboard.This shortcut makes the selected text bold.Additional information:Ctrl + I is used to italicize text.Ctrl + U is used to underline text.Ctrl + S is used to save the document.Last verified on 24-08-2026', 0, 0, 0, 1790966319895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2334befd8f09702d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Times New Roman, Arial are examples of _____?', '{"A":"Font design","B":"Font format","C":"Font style","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Times New Roman and Arial are commonly used font styles/typefaces.A font determines the visual appearance and design of text.Font size refers to the size of the characters, such as 12 pt or 14 pt.Bold, Italic, and Underline are examples of text formatting styles.Common fonts include Arial, Times New Roman, Calibri, and Verdana.Last verified on 23-08-2026', 0, 0, 0, 1790966319895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3b2830a963acface', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the function of an antivirus software?', '{"A":"Protect against malware and viruses","B":"Manage email accounts","C":"Create and edit spreadsheets","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An antivirus software protects a computer against malware and viruses.It detects, blocks, and removes harmful software from a computer.Common threats include viruses, worms, Trojans, and spyware.Antivirus software helps protect files, programs, and system data.It can provide real-time protection against new threats.Last verified on 12-08-2026', 0, 0, 0, 1790966319895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0662f559216482ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A computer can define as an electronic device that can?', '{"A":"Carry out arithmetic operations","B":"Carry out logical operations","C":"Do complicated calculations","D":"Accept and process by implementation sequentially a set of stored instructions"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer is an electronic device that accepts, processes, stores, and produces information by executing a set of stored instructions.A computer works according to stored instructions, called a program.It performs both arithmetic and logical operations.It follows instructions sequentially, unless the program specifies a different sequence.The basic process is Input → Processing → Output → Storage.Last verified on 11-08-2026', 0, 0, 0, 1790966319895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_75f586776121c887', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which part of computer is known as Heart/Brain of Computer?', '{"A":"Monitor","B":"Microprocessor/CPU","C":"Scanner","D":"Keyboard"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The CPU (Central Processing Unit) is the brain/heart of the computer.It processes data and executes instructions.It controls other parts of the system.Additional information:First commercial CPU: Intel 4004 (1971)Invented by: Italian physicist Federico FagginCPU Examples: Clock speeds – 3.0 GHz, 3.5 GHz, 4.0 GHz, 4.5 GHz, 5.0 GHzLast updated by NA on 09-09-2026', 0, 0, 0, 1790966319895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e6fd6916980915da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Who is the founder of Google?', '{"A":"Sergen Brin","B":"Larry Page","C":"Steve Jobs","D":"Both A & B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sergen Brin & Larry Page is the founder of Google.Sergey Brin is the real owner of Google.Google, a US multinational technology company.It is a type of search engine operating since 1997.It was founded in the year: September 4, 1998The Headquarters of Google is located in the city of California.Parent organization: Alphabet Inc.Last verified on 31-03-2026', 0, 0, 0, 1790966319895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_64582e1398630f62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following computer language is written in binary codes only?', '{"A":"FORTRAN","B":"PASCAL","C":"C Language","D":"Machine Language"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Machine Language is the lowest-level computer language, written entirely in binary code (0s and 1s).It is directly understood by the computer’s CPU without any translation.All higher-level languages (like C, Pascal, Basic) are converted into machine language before execution.Last verified on 12-03-2026', 0, 0, 0, 1790966319895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_908aa7899e947f4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Compiler is the ______?', '{"A":"Name given to the computer operator","B":"Translator of source program to object / Translator of high-level program to machine","C":"Part of the digital machine to store the information","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Compiler Function: Converts high-level language into machine language.Output: Produces an object file (.obj / .exe) after compilation.Examples of Languages Using Compiler: C, C++, Java (uses compiler + JVM).Additional information:Compiler: Translates whole program at once.Interpreter: Translates line by line.Last verified on 21-02-2026', 0, 0, 0, 1790966320032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1ae04b58f3622ca2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'By default we can save the file in ______?', '{"A":"Desktop","B":"My document","C":"My computer","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation By default, most operating systems save files in the "My Documents" folder for easy access and organization.My documents is the default location of saving and opening the files in windows operating system.This location can be changed manually based on user preferences or software settings.Last verified on 10-08-2026', 0, 0, 0, 1790966320032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7a6388c05c4d96ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is a graphical representation of data?', '{"A":"Chart","B":"Spreadsheet","C":"Database","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A chart represents data visually, making it easier to understand and compare information.Common types include bar charts, line charts, pie charts, and column charts.Charts are widely used in MS Excel to present numerical data graphically.Additional information:A bar chart compares categories.A line chart shows trends over time.A pie chart represents parts of a whole.Last verified on 10-08-2026', 0, 0, 0, 1790966320032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6f83557ed0e903e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '____ includes the selected text in the index of document.', '{"A":"Table","B":"Mark Entry","C":"Table","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mark Entry is a Microsoft Word feature used to mark selected text for inclusion in an index.It is found under the References tab in the Index group.The Mark Entry command opens the Mark Index Entry dialog box.After entries are marked, Insert Index is used to create the index.An index helps readers quickly locate important topics, terms, or names in a document.Last verified on 10-08-2026', 0, 0, 0, 1790966320032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_98d6cc3da48b3718', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following functions is used to calculate the average of a range of cells in Excel?', '{"A":"AVERAGE","B":"SUM","C":"COUNT","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To calculate the average in Excel, you can use the AVERAGE function: Formula =AVERAGE(number1, [number2], …) Arguments: Number1 is required, and Number2 is optional Example =AVERAGE(A1:A20) returns the average of the numbers in the range A1:A20Last verified on 10-08-2026', 0, 0, 0, 1790966320032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a9b8bdb323ce9241', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The purpose of a device driver is ______?', '{"A":"To increase the speed of a computer","B":"To allow hardware components to communicate with the operating system","C":"To store more data in RAM","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A device driver is system software that enables the operating system to communicate with a specific hardware device.Examples include drivers for printers, keyboards, graphics cards, and network adapters.Without the correct driver, the operating system may not be able to use the hardware properly.Drivers act as a bridge between hardware and the operating system.Last verified on 10-08-2026', 0, 0, 0, 1790966320032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_50808363f9464095', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the purpose of Insert >> Picture >> Clip Art?', '{"A":"To insert text in a document","B":"To insert a table in a document","C":"To insert clip art in a document","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Clip Art consists of ready-made images or illustrations that can be inserted into a document.In older versions of MS Word, Clip Art was accessed through Insert → Picture → Clip Art.It can be used to make documents more attractive and visually informative.Clip Art may include illustrations, symbols, drawings, and decorative images.Last verified on 10-08-2026', 0, 0, 0, 1790966320032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ae673bcdb505fd9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which function in Excel tells how many numeric entries are there?', '{"A":"NUM","B":"COUNT","C":"SUM","D":"CHKNUM"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The COUNT function counts the number of cells containing numbers.Example: =COUNT(A1:A10) counts numeric entries in cells A1 through A10.Additional information:COUNTA: Counts non-empty cells.COUNTBLANK: Counts blank cells.SUM: Adds numbers.AVERAGE: Calculates the average of numbersLast verified on 10-08-2026', 0, 0, 0, 1790966320032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ba29c451516e364d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Facebook and Instagram are examples of ______?', '{"A":"Search engines","B":"Social media networks","C":"E-commerce platforms","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Facebook and Instagram are social networking platforms.They are used to connect and communicate with people.Users can share posts, photos, videos, messages, and other content.Both platforms are owned by Meta Platforms.Last verified on 10-08-2026', 0, 0, 0, 1790966320147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4bcd3c37dbff3cd2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In which part of computer execution of instructions done?', '{"A":"Control Unit","B":"Main Memory","C":"ALU","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the ALU (Arithmetic Logic Unit), arithmetic and logical operations required during instruction execution are performed.ALU performs arithmetic operations such as addition and subtraction.It also performs logical and comparison operations.Additional information:The Control Unit (CU) directs and coordinates the execution of instructions.Main Memory stores programs and data currently being used.The CPU consists mainly of the ALU, Control Unit, and registers.Last verified on 10-08-2026', 0, 0, 0, 1790966320147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_47883e0c8cb68a22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A collection of system programs that controls and co-ordinates the overall operations of a computer system is called _______ ?', '{"A":"System software","B":"Operating system","C":"Utility program","D":"Device driver"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A collection of system programs that controls and coordinates the overall operations of a computer system is called an Operating System.An Operating System (OS) manages the computer’s hardware and software resources.It controls CPU, memory, files, input/output devices, and running programs.It provides an interface between the user and computer hardware.Examples include Windows, Linux, macOS, Android, and iOS.Last verified on 10-08-2026', 0, 0, 0, 1790966320147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a561dbbd68cc7cf8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Programs designed to perform specific task is known as?', '{"A":"Operating system","B":"System software","C":"Application software","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Application software is designed to help users perform specific tasks.Examples include MS Word, MS Excel, PowerPoint, web browsers, and media players.Additional information:Operating systems manage computer hardware and provide a platform for applications.System software controls and manages the computer system.Last verified on 10-08-2026', 0, 0, 0, 1790966320147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_27eafce77c86cac8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the best definition of topology in networking?', '{"A":"The physical layout of connected devices","B":"The speed of the network","C":"The type of cables used","D":"The software used for network management"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Topology in networking refers to the physical or logical arrangement of connected devices and their communication links in a network.Network topology describes how computers, devices, and network connections are arranged.Common topologies include Star, Bus, Ring, Mesh, and Tree.Additional information:Star topology: Devices connect to a central hub or switch.Ring topology: Devices are connected in a circular arrangement.Mesh topology: Devices have multiple connections, providing high reliability.Last verified on 10-08-2026', 0, 0, 0, 1790966320147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e5d766ec8f256ee5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The language that the computer can understand and execute is called ____?', '{"A":"Machine language","B":"Application software","C":"System program","D":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The language that the computer can understand and execute directly is called Machine Language.Machine language consists of instructions in binary digits (0s and 1s).It is the lowest-level programming language.It is directly understood by the CPU.Assembly language uses mnemonics and must be translated by an assembler.Last verified on 10-08-2026', 0, 0, 0, 1790966320147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c98b5ff6241e660f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Select an option of a user interface that is more user-friendly than the other provided options?', '{"A":"GUI","B":"MS DOS","C":"Apple DOS","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GUI stands for Graphical User Interface.It uses icons, windows, and menus for interaction.It is easier to use than command-based interfaces.MS-DOS and Apple DOS are command-line interfaces.Last verified on 11-04-2026', 0, 0, 0, 1790966320147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c34ed8a02d57f649', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The files deleted from the computer are stored in _____?', '{"A":"Recycle bin","B":"Hard disk","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Recycle Bin temporarily stores deleted files and folders in Windows.Files in the Recycle Bin can usually be restored to their original location.Choosing Empty Recycle Bin permanently removes the stored items.Last verified on 10-08-2026', 0, 0, 0, 1790966320147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_819bfdad83277d8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'We can remove / hide border of a shape by selecting?', '{"A":"No Outline","B":"No Line","C":"White Line","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Selecting "No Outline" removes or hides the border of a shape.This option is available in applications like MS Word or PowerPoint.It leaves the shape without a visible border.Last verified on 10-08-2026', 0, 0, 0, 1790966320240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_22b75db981e31efa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How do you change column width to fit the contents?', '{"A":"Double-click the boundary to the right of the column heading","B":"Single-click to the boundary to the left of the column heading","C":"Press ALT and single-click anywhere in the column","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To adjust a column width to fit its contents in Excel, you can:Double-click the boundary to the right of the column heading.This action automatically resizes the column width to match the longest entry in that column.This ensuring that all data is visible without manually adjusting the width.Last verified on 10-08-2026', 0, 0, 0, 1790966320240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_637098b748d538e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A computer program that translates one program instructions at a time into machine language is called?', '{"A":"Interpreter","B":"Compiler","C":"CPU","D":"Interpreter"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer program that translates one program instruction at a time into machine language is called an Interpreter.Interpreters are commonly associated with languages such as Python, JavaScript, and BASIC.Additional information:Compiler: Translates the complete program before execution.Assembler: Converts assembly language into machine code.Machine Language: Uses binary instructions understood directly by the computer.Last verified on 10-08-2026', 0, 0, 0, 1790966320240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8c4a0c80d8e9b759', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is malware software?', '{"A":"A type of software designed to improve computer performance","B":"Software that protects against viruses and threats","C":"Malicious software designed to harm or exploit systems","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790966320240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_47b3b7443064cfd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What was the purpose of AutoCorrect originally?', '{"A":"To replace repetitive words","B":"To replace grammatically incorrect words","C":"To replace missspellings","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AutoCorrect was originally designed to automatically correct common typing errors and misspellings as you type.It replaces recognized incorrect words with their correct forms.Additional information:Spell Check: Identifies possible spelling and grammatical errors.AutoFormat: Automatically applies certain formatting while typing.Last verified on 09-08-2026', 0, 0, 0, 1790966320240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0649b05c7c511a7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Mail merge is used to?', '{"A":"Combine multiple documents together","B":"Send emails to multiple recipients","C":"Merge data into a template document","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mail Merge is used to merge data into a template document to create multiple personalized copies.It is a feature of MS Word used for bulk document creation.It combines a main document with a data source (like names or addresses).Each output document is customized automatically.Commonly used for letters, labels, and certificates.Last verified on 20-06-2026', 0, 0, 0, 1790966320240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_13b6f8c0e27fc0b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The bar at the top of the window that contains the name of Application Software is called?', '{"A":"Task bar","B":"Title bar","C":"Status bar","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Title Bar is the bar at the top of a window that displays the name of the application and usually the current document.In MS Word, it may show the document name and Microsoft Word.Additional information:The Taskbar is generally located at the bottom of the Windows desktop and shows open or pinned applications.The Status Bar displays information about the current document or application.The Scroll Bar is used to move up, down, left, or right through content.Last verified on 09-08-2026', 0, 0, 0, 1790966320240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_38602f99b2887ea8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A collection of related worksheets is called ______?', '{"A":"Workbook","B":"File","C":"Group","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Workbook is a collection of related worksheets in spreadsheet software such as MS Excel.A workbook can contain multiple worksheets, each with rows and columns.A worksheet is an individual spreadsheet page within a workbook.For example, a workbook may contain separate worksheets for Sales, Expenses, and Profit.Last verified on 09-08-2026', 0, 0, 0, 1790966320240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_958e172c4ec6392b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Who was founder of first mechanical computer?', '{"A":"Charles Babbage","B":"Alan Turing","C":"Michal Faraday","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charles Babbage is credited with designing the first mechanical computer.He is widely regarded as the Father of the Computer.Difference Engine → Designed in the 1820sAnalytical Engine → Described in 1837Additional information:Ada Lovelace → Wrote an algorithm for the Analytical EngineAlan Turing → Pioneer of theoretical computer scienceLast verified on 09-08-2026', 0, 0, 0, 1790966320328) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_141d03e5b0a667c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following languages is used for webpage development?', '{"A":"HTML","B":"FORTRAN","C":"C or C++","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTML (Hypertext Markup Language) is the standard markup language used for creating web pages.It is the backbone of webpage development.It providing the structure and content that appears on the web.Last verified on 08-08-2026', 0, 0, 0, 1790966320328) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_85b2b42794bafdba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A software that can harm your computer is called?', '{"A":"Virus","B":"Server","C":"Extension","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A software that can harm your computer is called a Virus.A computer virus is a type of malicious software (malware) that can damage files or disrupt computer operations.Viruses can spread by attaching themselves to files or programs.They may cause data loss, system slowdown, or other damage.Last verified on 08-08-2026', 0, 0, 0, 1790966320328) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_31bd2be2a05c1899', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Data is permanently stored in _____?', '{"A":"Cache Memory","B":"Hard Disk","C":"RAM","D":"Buses"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Data is permanently stored in the Hard Disk.A hard disk is a secondary storage device used to store data for long-term use.Data remains stored even when the computer is turned off.Additional information:RAM → Temporary/volatile memoryCache → High-speed temporary memoryBus → Transfers data, addresses, and control signalsLast verified on 08-08-2026', 0, 0, 0, 1790966320328) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9194f740210f769e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'AND, OR, XOR, NOT, NAND, NOR are which type of gate?', '{"A":"Automatic gate","B":"Logic gate","C":"Program gate","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Logic gates are the fundamental building blocks of digital systems.The AND, OR, and NOT gates are the most fundamental logic gates.The NAND and NOR gates are called universal gates because they can be combined to produce OR, AND, and NOT gates.Last verified on 08-08-2026', 0, 0, 0, 1790966320328) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_76856ad239885477', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which device is used to connect the nearest device?', '{"A":"NFC","B":"Wi-Fi","C":"Bluetooth","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NFC, Wi-Fi, and Bluetooth are all technologies used for connecting nearby devices for data transfer or communication.Each has specific purposes:NFC for very close-range communication.Bluetooth for medium-range.Wi-Fi for larger ranges.Last verified on 08-08-2026', 0, 0, 0, 1790966320328) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_29ed719bf3591f3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is meant by a dedicated computer?', '{"A":"Which is assigned one and only one task","B":"Which is used by one person only","C":"Which is meant for application software","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A dedicated computer is assigned one and only one specific task.It is designed to perform a particular function.Dedicated computers are commonly used in ATMs, traffic-control systems, and industrial machines.They are optimized for their specific purpose and may be part of an embedded system.Last verified on 08-08-2026', 0, 0, 0, 1790966320328) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e3b2d368ecbe40a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A computer application program that displays data arranged in rows and columns is called?', '{"A":"Spreadsheet","B":"Register","C":"Form","D":"Box"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer application program that displays data arranged in rows and columns is called a Spreadsheet.Spreadsheets organize data in cells formed by the intersection of rows and columns.They are used for calculations, data analysis, charts, and record keeping.Examples include Microsoft Excel, Google Sheets, and LibreOffice Calc.A spreadsheet file usually contains multiple worksheets.Last verified on 07-08-2026', 0, 0, 0, 1790966320328) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7b130019bbdd18e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which key is used to align the text to center?', '{"A":"Ctrl+ B","B":"Ctrl + C","C":"Ctrl + D","D":"Ctrl + E"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shortcut key for center alignment: Ctrl+EAdditional information:Center align means middle of the page.Ctrl + R -- Align selected text or line to the right.Ctrl + M -- Indent the paragraph.Last verified on 07-08-2026', 0, 0, 0, 1790966320416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1fbbd208135d8ecf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which key is used to select the whole document?', '{"A":"Ctrl + S","B":"Ctrl + C","C":"Ctrl + P","D":"Ctrl + A"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The keyboard shortcut to select the entire document (or all items in a window) is Ctrl + A.Function: Selects all content, text, or files in the active window.Additional information:Ctrl + R = used for aligning selected text to the right.Ctrl + E = used for aligning selected text to the center.Ctrl + J = use for Justify paragraph alignment.Ctrl + L = used for aligning selected text to the left.Ctrl + Q = used to Align the selected paragraph to the left.Last verified on 07-08-2026', 0, 0, 0, 1790966320416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_25eec13ed80d07e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A number of letter that appears a little above the normal text is called?', '{"A":"Superscript","B":"Subscript","C":"Supertext","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Superscript is text written slightly above the normal line.It is commonly used in mathematical powers, formulas, and footnotes.Example: x², a³, 10⁵Shortcut in MS Word: Ctrl + Shift + =Additional information:In MS-Word, a subscript is a number or letter written slightly below the normal text.Subscript shortcut: Ctrl + =Last verified on 29-05-2026', 0, 0, 0, 1790966320416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1927373a6f3450fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Coded entries are used to gain access to a computer system are called?', '{"A":"Entry Codes","B":"Passwords","C":"Security Commands","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Coded entries used to gain access to a computer system are called passwords.Definition: A secret string of letters, numbers, or symbols.Purpose: User verification and account security.Last verified on 07-08-2026', 0, 0, 0, 1790966320416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1a6a9d3267b86066', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the main difference between a mainframe and a super computer?', '{"A":"Super computer is much larger than mainframe computers","B":"Super computers are much smaller than mainframe computers","C":"Supercomputers are focused to execute few programs as fast as possible while mainframe uses its power to execute as many programs concurrently","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Supercomputers are designed for maximum computational speed and complex calculations.Mainframe computers are designed to process huge volumes of data and support many users/tasks simultaneously.Supercomputers are commonly used in weather forecasting, scientific research, simulations, and space research.Mainframes are widely used in banking, airlines, government systems, and large organizations.Last verified on 07-08-2026', 0, 0, 0, 1790966320416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a2c556fa1280068a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the maximum number of lines you can set for a drop cap?', '{"A":"5","B":"10","C":"15","D":"20"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The maximum number of lines that can be set for a Drop Cap in Microsoft Word is 10.Additional information:The minimum number of lines is 1.The default setting is 3 lines.A Drop Cap enlarges the first letter of a paragraph and makes it extend down several lines.Last verified on 07-08-2026', 0, 0, 0, 1790966320416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9a7519863816465b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Dot matrix is a type of ____?', '{"A":"Bus","B":"Disk","C":"Printer","D":"Tape"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Type: Impact PrinterPrinting Method: Pins strike an ink ribbonCommon Pin Configurations: 9-pin, 24-pinOutput: Text and graphicsMain Advantage: Can print multi-part formsLast verified on 07-08-2026', 0, 0, 0, 1790966320416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7178db21941382cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the largest font size available in the font size tool on formatting toolbar?', '{"A":"68","B":"72","C":"75","D":"78"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest listed font size on the Formatting Toolbar is 72 pt.Font size is measured in points (pt).You can manually type sizes larger than 72 pt (e.g., 100, 150) in Microsoft Word.72 points = 1 inch in typography.The list contains font size in points 8, 9, 10, 11, 12, 14, 16, 18, 20, 22, 24, 26, 28, 36, 48 and 72.• Word supports font sizes between 1 and 1638.Last update 0n 21-07-2026 by NA', 0, 0, 0, 1790966320416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7e74239046160d0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is not a high-level programming language?', '{"A":"C / C++","B":"Java","C":"Fortran / Python","D":"Machine Language / Assembly"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Machine Language / Assembly is NOT a high-level programming language.High-level languages are closer to human language and easier to read.Machine and assembly languages are closer to hardware.They are used for low-level system control.They require more technical understanding than high-level languages.Last verified on 07-06-2026', 0, 0, 0, 1790966320485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ca023c054e383a15', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which function calculates the largest value in a set of numbers in Excel?', '{"A":"Average","B":"Count","C":"Minimum","D":"Maximum"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The MAX function returns the largest value in a set of numbers in Excel.It compares all selected values and displays the highest one.It is commonly used for finding the maximum score, salary, or price.Additional information:MIN() → Returns the smallest valueAVERAGE() → Returns the average valueCOUNT() → Counts cells containing numbersSUM() → Adds all numbersLast verified on 18-07-2026', 0, 0, 0, 1790966320485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4cb2732d53b97e62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which formula is used to find the number of numerical cells in a range of cells in Excel?', '{"A":"COUNTIF","B":"COUNT","C":"COUNTA","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Function: COUNTPurpose: Counts cells containing numbers onlySyntax: =COUNT(range)Example: =COUNT(A1:A10)Ignores: Text, blank cells, and logical values (TRUE/FALSE)Additional information:COUNTA → Counts all non-empty cells.COUNTIF → Counts cells that meet a specific condition.COUNTIFS → Counts cells meeting multiple conditions.COUNTBLANK → Counts blank cells.Last verified on 18-07-2026', 0, 0, 0, 1790966320485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fa4cb0f0afc44b6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which data structure uses LIFO (Last In, First Out) principle?', '{"A":"Stack","B":"Queue","C":"Linked List","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Stack follows the LIFO (Last In, First Out) principle.The last element added to the stack is the first one to be removed.Elements are inserted using Push and removed using Pop operations.Stacks are commonly used in function calls and expression evaluation.It is a linear data structure.Last verified on 10-06-2026', 0, 0, 0, 1790966320485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bfb012bf95ffb9ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which one is an example of database designing software?', '{"A":"MS Word","B":"MS Excel","C":"MS Access","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Access is a database designing and management software.It is used to create, store, organize, and manage databases.MS Access is part of the Microsoft Office (Microsoft 365) suite.It allows users to create tables, queries, forms, and reports.First Released: 13 November 1992Last verified on 18-07-2026', 0, 0, 0, 1790966320485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4fb0ccc91942b286', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is a feature of a relational database?', '{"A":"Stores data in tables with rows and columns","B":"Only allows sequential storage of data","C":"Does not support queries","D":"Uses key-value pairs exclusively"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A relational database organizes data into tables (relations). Each table consists of rows (records) and columns (fields). It supports SQL queries for data manipulation and retrieval. Data is related using keys (primary and foreign keys).Last verified on 18-07-2026', 0, 0, 0, 1790966320485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8ecc443bc4497330', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is NOT a binary number? 101, 1011, 0, 101.10111', '{"A":"101","B":"1011","C":"0","D":"101.10111"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 101.10111 is not binary number.Because it is a decimal number in scientific notation.In binary, the only digits used are 0 and 1.Last verified on 18-07-2026', 0, 0, 0, 1790966320485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bc146ca2207dfe10', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which alignment choice spreads the data across the width of the cell?', '{"A":"Distributed","B":"Center","C":"Justify","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Justify alignment spreads the text across the width of the cell by aligning it evenly.It adjusts text so that both the left and right edges appear aligned.This option is mainly used for long text in wrapped cells.Additional information:Center: Places text in the middle of the cell.Distributed: Spreads characters evenly within the cell.Wrap Text: Displays long text on multiple lines within the same cell.Last verified on 18-07-2026', 0, 0, 0, 1790966320485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e38e0e4f081cf1af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following can be renamed?', '{"A":"Worksheet","B":"Workbook","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Both the Worksheet and the Workbook can be renamed in Microsoft Excel.A worksheet name can be changed by double-clicking its sheet tab.A workbook can be renamed by changing its file name.Renaming helps organize and identify files and sheets easily.Last verified on 18-07-2026', 0, 0, 0, 1790966320606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7e7a6ad38fa8de96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Google Docs is an example of?', '{"A":"Operating System","B":"Web Browser","C":"Cloud-based application","D":"Antivirus Software"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Google Docs is a cloud-based application used to create, edit, and share documents online.It is part of Google Workspace.Documents are stored on Google Drive.Collaboration: Real-time editing by multiple usersLaunched: 9 March 2006Last verified on 18-07-2026', 0, 0, 0, 1790966320606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0e5791cdfcda780f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the smallest font size available in the Font Size tool on the Formatting Toolbar?', '{"A":"6","B":"8","C":"10","D":"12"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The smallest preset font size available in the Font Size drop-down list is 8 points.It appears in the standard Font Size list on the Home tab.Additional information:The largest preset font size available in the Font Size drop-down list is 72 points.Microsoft Word supports font sizes from 1 to 1638 points.Last verified on 16-07-2026', 0, 0, 0, 1790966320606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0bf41aeacceeecbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which command is used to close the window of Excel?', '{"A":"Ctrl + W","B":"Alt + F4","C":"Ctrl + F5","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alt + F4 is used to close the Excel window/application.Additional information:Ctrl + W → Close the current workbook/windowCtrl + F5 → Restore workbook window sizeCtrl + S → Save workbookCtrl + N → New workbpookLast verified on 15-07-2026', 0, 0, 0, 1790966320606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eeca7e3f0d57b11a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of these is part of computer security?', '{"A":"Installing reliable","B":"Reputable security","C":"Anti-virus software","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Installing reliable, Reputable security and Anti-virus software are part of computer security.Reliable software → Reduces security risks.Reputable security software → Detects and blocks threats.Anti-virus software → Protects against viruses and malware.Last verified on 15-07-2026', 0, 0, 0, 1790966320606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_84d6ef9ff5466f03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is a macro?', '{"A":"A style set","B":"A large file","C":"Automated sequence of commands","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A macro is an automated sequence of commands used to perform repetitive tasks quickly in software applications.It saves time by executing multiple steps with a single command.Commonly used in MS Word, Excel, and other office software.It can be recorded or programmed by the user.Last verified on 21-06-2026', 0, 0, 0, 1790966320606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3753592f723d69d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Blockchain technology is primarily associated with which of the following?', '{"A":"Artificial Intelligence","B":"Cloud Computing","C":"Cryptocurrency and secure digital transaction","D":"Virtual Reality"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blockchain technology is primarily associated with cryptocurrency and secure digital transactions.It is a decentralized digital ledger that records transactions securely and transparently.Blockchain reduces the need for intermediaries and makes data difficult to alter.It is widely used in cryptocurrencies, finance, supply chains, and digital identity systems.The technology became globally popular with the launch of Bitcoin in 2009.Last verified on 08-07-2026', 0, 0, 0, 1790966320606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a7be6f8f982e1a3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Two-Factor Authentication  2FA requires?', '{"A":"Only password","B":"Only OTP","C":"Password + second verification / A second layer of security requiring additional verification beyond a password","D":"Username only"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Two-Factor Authentication (2FA) is a security method that requires a password plus a second verification before granting access.It adds an extra layer of protection beyond a password alone.The second verification may be an OTP, fingerprint, face recognition, or an authentication app.Even if a password is stolen, 2FA helps prevent unauthorized access.It is widely used for email, banking, social media, and online accounts.Last verified on 08-07-2026', 0, 0, 0, 1790966320606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4f892dacfcd0f82a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is phishing?', '{"A":"A method of encrypting data for security","B":"Cybercrime involving fraudulent emails or messages to obtain sensitive information / Duplicitous efforts to steal delicate information by imitating trusted entity","C":"A technique to speed up network connections","D":"A way to block access to websites"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Phishing is a cybercrime where fake emails, messages, or websites are used to steal sensitive information like passwords or bank details.It tricks users into believing the message is from a trusted source.Criminals often use social media, email, or SMS for phishing attacks.The main goal is identity theft or financial fraud.Last verified on 21-06-2026', 0, 0, 0, 1790966320686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_881cd05f81130f31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Important AI, Machine Learning Techniques are', '{"A":"وضاحت میں چیک کریں","B":"یہ سوال بہت اہم ہے"}', 'A', NULL, 0, 0, 0, 1790966320686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_75df98cca5459543', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Bluetooth is a _______ technology for short range communication.', '{"A":"MAN","B":"PAN","C":"WAN","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bluetooth is a Personal Area Network (PAN) technology used for short-range communication.It connects devices within a range of about 10 meters.It is commonly used in headphones, mobile phones, and laptops.It works without cables using wireless signals.Last verified on 24-06-2026', 0, 0, 0, 1790966320686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d4e5a397f4bfbd8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Foreign key is?', '{"A":"A key that uniquely identifies a record in the same table","B":"A key used to delete records","C":"A field in one table that refers to the primary key of another table","D":"A password for database security"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Foreign Key is a field in one table that refers to the Primary Key of another table.It is used to create a relationship between two database tables.A foreign key helps maintain referential integrity by ensuring valid data links.Additional information:Primary Key: Uniquely identifies each record in a table.Candidate Key: A field that can become a primary key.Composite Key: A key made from two or more columns.Super Key: One or more columns that uniquely identify a record.Last verified on 06-07-2026', 0, 0, 0, 1790966320686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f42300e1f2c722c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The first row in an HTML table is called ______?', '{"A":"Title","B":"Heading","C":"Footer","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first row in an HTML table is called the Heading (Header Row).It usually contains table headings created with the <th> tag.The headings describe the content of each column.Data in the remaining rows is generally written using the <td> tag.Last verified on 06-07-2026', 0, 0, 0, 1790966320686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_55a0c39cf9f92ab4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which one of the following is not type of Antivirus Software? Chrome, Norton, McAfee, Avast', '{"A":"Chrome","B":"Norton","C":"McAfee","D":"Avast"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Google Chrome is not antivirus software; it is a web browser.Antivirus software protects computers from viruses, malware, spyware, and other cyber threats.Chrome is mainly used for browsing websites on the internet.Popular Antivirus Software (Examples)NortonMcAfeeAvastKasperskyBitdefenderLast verified on 02-07-2026', 0, 0, 0, 1790966320686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_12a8c3dd625ea415', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In database, columns are called?', '{"A":"Rows","B":"Fields","C":"Records","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a database, columns are called Fields or Attributes.A field represents a single type of data in a table (like Name, Age).Each column stores a specific attribute of records.Fields define the structure of the database table.Additional information:In a database, rows are called Records or Tuples.Last verified on 24-06-2026', 0, 0, 0, 1790966320686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_132e5193907f041c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The value of the base in the binary number system is?', '{"A":"2","B":"4","C":"6","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Base (Radix): 2Digits used: 0, 1Used in: Computers, programming, digital circuitsEach digit is called a bit (binary digit)Example: 1011₂Last verified on 07-06-2026', 0, 0, 0, 1790966320686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1108c0f3bb2601a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which sorting algorithm is the fastest in the average case?', '{"A":"Quick Sort","B":"Merge Sort","C":"Bubble Sort","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quick Sort is the fastest in the average case among the given options.It has an average time complexity of O(n log n).It uses a divide-and-conquer strategy to sort data efficiently.Last verified on 23-06-2026', 0, 0, 0, 1790966320771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_09ec11c73ac16d55', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In a Database table, a single row will be called?', '{"A":"Field","B":"Record","C":"Data type","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A single row(s) in a database table is called a record(s) or tuple(s).It represents a complete set of related data about one entity.Each record contains multiple fields (columns).Records store information about a single entity (e.g., one student).It is a basic unit of data storage in databases.Additional information:In a database, columns are called Fields or Attributes.Last verified on 12-04-2026', 0, 0, 0, 1790966320771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_615e96ae01bbe7e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'HTML is used for?', '{"A":"Networking","B":"Web designing","C":"Database","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTML (HyperText Markup Language) is used for web designing and creating the structure of web pages.It defines elements like headings, paragraphs, images, links, and tables on websites.HTML is the basic building block of the World Wide Web.It works with CSS and JavaScript to create interactive websites.Additional information:Developed by: Tim Berners-Lee (1991)Standardized by: World Wide Web Consortium (W3C)Last verified on 22-06-2026', 0, 0, 0, 1790966320771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ec1b31b4e67a828e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Database normalization reduces?', '{"A":"Tables","B":"Data redundancy","C":"Data size","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Database normalization reduces data redundancy in a database.It organizes data into well-structured tables.It removes duplicate (repeated) data.It improves data consistency and efficiency.It helps in reducing data anomalies during operations.Last verified on 08-06-2026', 0, 0, 0, 1790966320771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5335ef5684a313b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the purpose of inserting header and footer in the document?', '{"A":"To mark the starting of a page","B":"To enhance the overall appearance of the document","C":"To allow page headers and footers to appear on document when it is printed","D":"To make large document more readable"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main purpose of header and footer is to display information like page numbers, titles, or dates on every page when a document is printed.They appear at the top (header) and bottom (footer) of each page.They help in organizing long documents in a professional way.Commonly used in reports, books, and assignments.Last verified on 10-06-2026', 0, 0, 0, 1790966320771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0a07ba5751e88c85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In the OSI model, which layer is responsible for encryption and decryption?', '{"A":"Application layer","B":"Presentation layer","C":"Session layer","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Presentation layer is responsible for encryption and decryption in the OSI model.It ensures data is converted into a secure and usable format.It handles data translation, compression, and encryption.Last verified on 08-06-2026', 0, 0, 0, 1790966320771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0bc46ff22aa3bab7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which data structure is used for recursion?', '{"A":"Graph","B":"Queue","C":"Stack","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Stack is used for recursion.Because it stores function calls in LIFO order during execution.Recursion works by repeatedly calling the same function.Each call is stored in memory until it completes execution.Last verified on 08-06-2026', 0, 0, 0, 1790966320771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c13e6747dfc2873b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the time complexity of Linear Search?', '{"A":"O(n²)","B":"O(log n)","C":"O(n)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Linear Search works in a sequential manner:Average case: O(N/2) → O(N)Best case: O(1) (first element found)Worst case: O(N) (last element or not found)Last verified on 08-06-2026', 0, 0, 0, 1790966320771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_39672d0802334531', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A data structure known as FILO (First In Last Out) would be considered as _____?', '{"A":"Queue","B":"Stack","C":"Priority queue","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FILO (First In Last Out) means the first inserted item is removed last.This behavior matches a Stack data structure.Stack works on push and pop operations.It is used in function calls and undo operations.Elements are accessed only from the top.Additional information:Stack — FILO / LIFOQueue — FIFOLast verified on 07-02-2026', 0, 0, 0, 1790966320851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fd267c366d4e19d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which is the first computer virus in World?', '{"A":"Blaster","B":"Creeper","C":"Sasser","D":"I Love You"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Creeper virus Initial release date: 1971Creeper virus developer: Ray TomlinsonCreeper virus was created in 1971 by Bob Thomas.Creeper virus Operating system(s) affected: TENEXCreeper was the first computer worm.Additional information:Reaper was the first antivirus software.Last verified on 07-06-2026', 0, 0, 0, 1790966320851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6737cbefe90fa9cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What does the .exe extension represent?', '{"A":"Executable File","B":"Text File","C":"Image File","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The .exe extension stands for executable file.It contains programs or applications that can be run directly by the computer.These files are commonly used in Windows operating systems to launch software.Last verified on 04-06-2026', 0, 0, 0, 1790966320851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7085ed06b99a17dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The paragraph formatting is carried forward to the next paragraph by pressing the _____ key.', '{"A":"Shift","B":"Enter","C":"Ctrl","D":"Alt"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The paragraph formatting is carried forward to the next paragraph by pressing the Enter key.The formatting is carried forward to the next paragraph such as:IndentationAlignmentLine spacingShift + Enter → line break (new line, same paragraph)Last verified on 29-05-2026', 0, 0, 0, 1790966320851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a15febc284cd5947', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the best way to enforce text to start from the new page?', '{"A":"Using page break, entering more text will not affect the whole document","B":"Using page break, entering more text will affect the whole document","C":"Press Enter key repeatedly until text goes to next page, entering more text will not affect the whole document","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In word processing, text flows automatically to the next line or page.To manually start text from a new page, a Page Break is used.It does not disturb or change the rest of the document layout.It is better than pressing Enter repeatedly.Commonly used for chapters, headings, and sections.Last verified on 29-05-2026', 0, 0, 0, 1790966320851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a80661f8e0a4e467', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of these is a a type of sound file?', '{"A":".DAT files","B":".LOG files","C":".DRV files","D":".WAV files"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound files are used to store audio data in computers.Different formats exist like WAV, MP3, MIDI, etc.WAV is a standard uncompressed audio file format.It provides high-quality sound but larger file size.Commonly used in recording and editing audio.Last verified on 29-05-2026', 0, 0, 0, 1790966320851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e44d9e6390350d26', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the smallest and largest font size available in Font Size tool on formatting toolbar?', '{"A":"Smallest 8 & largest 70","B":"Smallest 8 & largest 71","C":"Smallest 8 & largest 72","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the standard MS Word Font Size toolbar list, sizes range from 8 to 72.These are the default preset font sizes shown in the dropdown menu.However, Word manually supports font sizes from 1 to 1638.Shortcut to change font size: Ctrl + Shift + P.Font size is measured in points (pt).Last verified on 29-05-2026', 0, 0, 0, 1790966320851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_50a8ee6377e3c6f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Microsoft corporation is founded by _______?', '{"A":"Billgates","B":"Paul Allen","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft was founded on April 4, 1975.It was founded by Bill Gates and Paul. Allen in Albuquerque, New Mexico.Last verified on 02-03-2026', 0, 0, 0, 1790966320851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ece98308d1d0e134', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which internal temporary location of the computer is used to process and store data?', '{"A":"Hard Disk","B":"ROM","C":"RAM","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RAM is the main temporary memory of a computer.It stores data and instructions while the computer is working.When power is off, RAM data is erased.Additional information:ROM → Permanent memory (read-only)Hard Disk → Long-term storageSSD → Fast permanent storageCache Memory → Ultra-fast CPU memoryLast verified on 07-05-2026', 0, 0, 0, 1790966320933) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9a8f91218889f057', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In Excel, to perform addition, the function used is _____?', '{"A":"=ADD()","B":"=SUM()","C":"=TOTAL()","D":"=PLUS()"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft Excel, the SUM function is used for addition.It adds numbers in a selected range of cells.Example: =SUM(A1:A5) adds values from A1 to A5.Additional information:AVERAGE → calculates meanCOUNT → counts numbersMAX → finds highest valueMIN → finds lowest valuePRODUCT → multiplies valuesLast verified on 19-04-2026', 0, 0, 0, 1790966320933) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_89725f33dd463f2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'PNG, JPEG, GIF are the formats of _____ files.', '{"A":"Image","B":"Audio","C":"Video","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PNG, JPEG, and GIF are image file formats used to store pictures.They are widely used in websites, graphics, and digital media.Each format has different compression and quality features.JPEG is best for photos.PNG for high-quality images.GIF for animations.Last verified on 19-04-2026', 0, 0, 0, 1790966320933) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e75d741aa91d472a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In binary representation, what is the decimal equivalent of 1011?', '{"A":"11","B":"12","C":"13","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To find the decimal equivalent of the binary number 1011:(1 × 2³) + (0 × 2²) + (1 × 2¹) + (1 × 2⁰)= (1 × 8) + (0 × 4) + (1 × 2) + (1 × 1)= 8 + 0 + 2 + 1= 11Last verified on 12-04-2026', 0, 0, 0, 1790966320933) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f62f05da007a2418', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How many layers does the OSI model have?', '{"A":"5","B":"6","C":"7","D":"8"}', 'C', NULL, 0, 0, 0, 1790966320933) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_890f7322decf4b72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '1024 kilobytes is equal to ____?', '{"A":"1 terabyte","B":"1 gigabyte","C":"1 megabyte","D":"Both A and B"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The size of information in the computer is measured in: 1024 kilobytes (KB) is equal to 1 megabyte (MB).One Megabyte (MB) = 1024 Kilobytes (KBOne Gigabyte (GB) = 1024 Megabytes MBOne Terabyte (TB)= 1024 gigabytes (GB).', 0, 0, 0, 1790966320933) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d2515ed7cf2af358', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Data arranged in intelligible form is called?', '{"A":"Program","B":"Software","C":"Information","D":"Alphanumeric data"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Information: Data processed and organized to be meaningful.Data Processing: The action of converting raw data into meaningful information.Tabulation: A specific, structured form of arranging data in rows and columns.', 0, 0, 0, 1790966320933) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f15f4a1d39c0c54a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'BIOS is used for?', '{"A":"Updating system information on network","B":"Loading system","C":"It helps in routing","D":"It takes inputs from keywords and other devices"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BIOS (Basic Input/Output System) is firmware that starts up the computer. It initializes hardware like CPU, memory, and storage when the computer is powered on. BIOS loads the operating system from the hard drive into memory. It also provides basic communication between the OS and hardware devices.', 0, 0, 0, 1790966320933) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1324ce094142bbff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Flowchart is a _________ representation of algorithm_?', '{"A":"Diagrammatic","B":"Symbolic","C":"Linked","D":"Both A & B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A flowchart visually represents an algorithm using diagrams and symbols. Diagrammatic representation helps in understanding the flow of the process easily. Symbolic representation uses standard shapes like ovals, rectangles, diamonds for start/end, processes, and decisions.', 0, 0, 0, 1790966321015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f8adb090cfb383d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Optical Fiber System is utilized in _____?', '{"A":"Eye operation","B":"Air raid system","C":"Telecommunication System","D":"Defence system"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Optical Fiber Systems are utilized in Telecommunication Systems to transmit data as light signals through thin glass or plastic fibers.It enabling high-speed internet, voice, and data communications over long distances.Last verified on 03-04-2026', 0, 0, 0, 1790966321015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_67ab6ca6ecb9530c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which is used to open a new tab?', '{"A":"Alt + T","B":"Ctrl + T","C":"Ctrl + B","D":"Ctrl + A"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + T: Opens a new tabCtrl + N: Opens a new windowCtrl + Shift + W: Closes the current window and all tabsCtrl + Q: Closes the current windowAlt + Right arrow: Opens the next page from your browsing history in the current tabCtrl + F4: Closes the current tabAlt + F4: Closes the active windowAlt + Space then n: Minimizes the current windowLast update 0n 21-07-2026 by NA', 0, 0, 0, 1790966321015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b695ffee5c59f245', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the time complexity of searching for an element in a balanced binary search tree?', '{"A":"O(1)","B":"O(n)","C":"O(log n)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a balanced binary search tree, the height is proportional to log n, ensuring efficient searches.The time complexity is O(log n) as the search halves the tree at each step.Last verified on 23-03-2026', 0, 0, 0, 1790966321015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a25d6e543ec8fc9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the worst case time complexity of a quick sort algorithm?', '{"A":"O(log N)","B":"O(N log N)","C":"O(N²)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quick Sort is a divide-and-conquer sorting algorithm.In the worst case, it occurs when the pivot divides the array very unevenly (e.g., always smallest or largest element).This results in O(n²) comparisons for an array of size n.Additional information:Average case → O(n log n)Best case → O(n log n)Worst case → O(n²)Last verified on 23-03-2026', 0, 0, 0, 1790966321015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_854a5e94a9cf4b8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following functions is used to sum the values in a range that meet criteria that can you specify?', '{"A":"SUM","B":"SUMIF","C":"SUMALL","D":"SUMANY"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, to sum values in a range based on a condition, the SUMIF() function is used.It allows you to add only the numbers that meet a specific criterion, such as all sales above 1000 or only a certain category.This is different from SUM(), which adds all numbers in a range without any condition.Last verified on 11-03-2026', 0, 0, 0, 1790966321015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a8599e61d3144d6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Another name for a pre-programmed formula in Excel is _____?', '{"A":"Cell","B":"Graph","C":"Function","D":"Range"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, a pre-programmed formula is called a Function.Functions perform specific calculations or tasks automatically, such as SUM, AVERAGE, or IF.They save time by automating repetitive formulas and reducing errors.Last verified on 11-03-2026', 0, 0, 0, 1790966321015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9f46de593a934521', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the name of Webpage Address?', '{"A":"Protocol","B":"Domain","C":"URL","D":"Directory"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A webpage address is called a URL,URL: Uniform Resource Locator.URL consists of five parts: SchemeSubdomainTop-level domainSecond-level domainSubdirectoryLast updated 18-02-2026', 0, 0, 0, 1790966321015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5bb0c1facedcf4cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is used to build microcomputers?', '{"A":"Vacuum tube","B":"Transistors","C":"Processors","D":"GPU s"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microcomputers are small computers designed for personal or business use.They are built around a central processing unit (CPU or processor), which executes instructions and controls the system.Processors are the brain of microcomputers, enabling them to perform calculations, run software, and manage hardware.Last verified on 11-03-2026', 0, 0, 0, 1790966321094) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7d19ac0bf9eb918b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What type of chart is useful for showing trends or changes over time?', '{"A":"Pie chart","B":"Column chart","C":"Line chart","D":"Dot chart"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel 2016, a Line Chart displays data points connected by lines.It is ideal for showing trends, patterns, or changes over time.Multiple data series can be plotted on the same line chart for comparison.', 0, 0, 0, 1790966321094) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b73ea58c9b6ea4fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What type of chart is useful for comparing values over categories?', '{"A":"Line Chart","B":"Pie Chart","C":"Column Chart","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel 2016, a Column Chart displays data as vertical bars.It is especially useful for comparing values across categories clearly.Column charts make it easy to visualize differences and trends at a glance.Last verified on 10-03-2026', 0, 0, 0, 1790966321094) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b945760f0b694e4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is not available on Home Tab? Font, Columns, Font Color, Styles', '{"A":"Font","B":"Columns","C":"Font Color","D":"Styles"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word 2016, the Home Tab contains tools for text formatting and editing.Common options include Font, Font Color, and Styles.Columns is found under the Layout Tab, not Home Tab.Last verified on 10-03-2026', 0, 0, 0, 1790966321094) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_07289f3370b34c22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To return the reminder after the number is divided by a divisor in Excel we use the function?', '{"A":"ROUND ( )","B":"FACT ( )","C":"MOD ( )","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The MOD function in Excel returns the remainder after division of one number by another.Syntax: =MOD(Number, Divisor)Example: =MOD(10, 3) → Result = 1 (10 ÷ 3 leaves remainder 1)Last verified on 07-03-2026', 0, 0, 0, 1790966321094) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_acdeee2f3aa6fb9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which one can be used as watermark in a word document?', '{"A":"Text","B":"Image","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A watermark is a faint design or text appearing behind the main content of a document.In Word, you can use:Text – Example: Confidential, DraftImage – Example: Company logo or signatureLast verified on 06-03-2026', 0, 0, 0, 1790966321094) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_80eb2eb9e08b76a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is not essential component to perform a Mail Merge operation? Word fields, Main document, Data source, Merge fields', '{"A":"Word fields","B":"Main document","C":"Data source","D":"Merge fields"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mail Merge is used to create personalized letters, labels, or emails from a main document and a data source.Essential components:Main Document – The template for the letters or emailsData Source – Contains names, addresses, or other personalized informationMerge Fields – Placeholders that pull data from the data sourceWord fields are not required for basic mail merge operations.Last verified on 06-03-2026', 0, 0, 0, 1790966321094) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_762e4d145c833f78', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'F5 is used for ______?', '{"A":"Refresh program","B":"Universal help","C":"To help","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The F5 key is primarily used to refresh or reload web pages in browserAdditional informationShift + F5: Starts PowerPoint slideshow from the current slideF6 – Moves the cursor to the address bar F7 – Used to spell check and grammar checkF8 – Used to access the boot menu in Windows Last updated 15-feb-2026', 0, 0, 0, 1790966321094) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_19561c7806d1366c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The capacity of a compact disk is _____?', '{"A":"700 MB","B":"600 MB","C":"650 MB","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Standard Capacity: 700 MB / 80 minutes.Alternative Sizes: 650 MB (earlier standard) to 800+ MB (extended).Data Type: Used for audio (CD-DA), data (CD-ROM), and rewritable (CD-RW) mediaLast updated 15-feb-2026', 0, 0, 0, 1790966321201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1a6cd5ac7c1287c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'MS access has primary _____ keys', '{"A":"1","B":"2","C":"3","D":"4"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Access has primary one key (or a single composite key) per table.This key must be a unique, non-null field or a combination of fields That identifies each record, acting as the primary identifier for database relationships. Last updated 15-feb-2026', 0, 0, 0, 1790966321201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_610ba489075a5cbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Android system is established by;', '{"A":"Microsoft","B":"Google","C":"Iphone","D":"Nonen of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Google established (acquired and further developed) the Android system. NOTE Original Development: Android Inc. was founded in 2003 by Andy Rubin, Rich Miner, Nick Sears, and Chris White.Acquisition: Google acquired Android Inc. in 2005.Release: The first commercial Android device was released in 2008Last updated 15-feb-2026', 0, 0, 0, 1790966321201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_069356f60a931e2e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'An excel workbook is a collection of __________?', '{"A":"Worksheets and Charts","B":"Charts","C":"Worksheets","D":"Workbooks"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Excel workbook is a collection of worksheets It can also contain charts, macros, and other dataA workbook is the Excel file itself, typically with an .xlsx extension.Contents: It holds one or more worksheets (grid-based spreadsheets).Last updated 15-feb-2026', 0, 0, 0, 1790966321201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1d14d07b5bae585e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'First, ever computer virus was created from -------?', '{"A":"China","B":"Pakistan","C":"USA","D":"Israel"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first-ever IBM PC-compatible computer virus, named "Brain''It also known as Pakistani Brain or LahoreDeveloped in January 1986By two brothers, Basit Farooq Alvi and Amjad Farooq Alvi,.** Other Questions Related to "COMPUTER VIRUS"A computer virus isdeliberately created***Computer Virus operates by:Dormancy and ReplicationWhich is the first computer virus in World?Creeper***First, ever computer virus was created from -------:PakistanLast updated 15-feb-2026', 0, 0, 0, 1790966321201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_19727d44436a2ee9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Errors from computer hardware and software cab be identifying and removed by which process?', '{"A":"Debugging","B":"Formating","C":"Flip flop","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Errors from computer software are primarily identified and removed through debugging, A systematic process of finding, analyzing, and fixing bugs. For hardware, this process is known as troubleshooting or maintenance', 0, 0, 0, 1790966321201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_24d864742db3aee6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'One (1) KB (Kilobytes) = ______?', '{"A":"1024 kilobytes","B":"1024 bytes","C":"1024 megabytes","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 Kilobyte (KB) = 1024 bytesOne Megabyte (MB) = 1024 Kilobytes (KBOne Gigabyte (GB) = 1024 Megabytes MBOne Terabyte (TB)= 1024 gigabytes (GB).The size of information in the computer is measured in:Kilobytes (KB)Megabytes (MB)Gigabytes (GB)Terabytes (TB)Last verified on 08-02-2026', 0, 0, 0, 1790966321201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fc364867d9555ae5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '__________ performs the computer data processing functions.', '{"A":"Control Unit","B":"ALU","C":"Registers","D":"CPU interconnection"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ALU (Arithmetic and Logic Unit) performs the computer''s data processing functions. As a primary component of the CPU, the ALU handles all arithmetic, logic, and shifting operations on data.', 0, 0, 0, 1790966321201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_185a100087c045cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Eight (8) Bits make up a _____?', '{"A":"Byte","B":"Mega byte","C":"Kilo byte","D":"Nano byte"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 byte equals 8 bits.Additional Information1024 Bytes = 1 Kilobyte (KB)1024 Kilobytes = 1 Megabyte (MB)1024 Megabytes = 1 Gigabyte (GB)1024 Gigabytes = 1 Terabyte (TB)Last verified on 04-02-2026', 0, 0, 0, 1790966321306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d36b3bf05d839948', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What key is used to take a screenshot of the screen?', '{"A":"F12","B":"PrtScn (Print Screen)","C":"Ctrl + P","D":"Esc"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The primary key to take a screenshot on Windows is PrtScn (Print Screen)PrtScn: Captures the full screen to the clipboard.Windows Key + PrtScn: Saves the full screen automatically to Pictures > Screenshots.', 0, 0, 0, 1790966321306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_99c85c0eea5c339e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What parameter is used to specify data transfer speed?', '{"A":"MHz","B":"Bps","C":"Ghz","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bps (Bits per second) measures the rate at which data is transferred from one device to another.It is commonly used for network speed, internet speed, and bus transfer rates.Additional information:Modern systems often use Mbps (Million bps) or Gbps (Billion bps) for high-speed data networks.Last verified on 28-01-2026', 0, 0, 0, 1790966321306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ce572d3765507bf8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The________is firmware that contain a computer''s startup instruction.', '{"A":"POST","B":"BIOS","C":"CMOS","D":"DIOS"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The BIOS (Basic Input/Output System) is firmware that contains a computer''s startup instructions.It resides on a motherboard chip, initializes hardware, and performs a power-on self-test (POST) to ensure components function properly before loading the operating system.', 0, 0, 0, 1790966321306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6b96a48a6ba49296', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which key is used to enter the current date in Excel?', '{"A":"Ctrl+:","B":"Ctrl + Shift + ;","C":"Ctrl+;","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790966321306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5c7e787127034c55', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Header and Footer are present in which category of the Insert Tab?', '{"A":"Text category","B":"Font","C":"Home","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft Word, Header and Footer are used to add text, page numbers, or images at the top or bottom of a page.They help in document formatting and consistency across multiple pages.Additional information:Location: Insert Tab → Text Group → Header & FooterLast verified on 17-01-2026', 0, 0, 0, 1790966321306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_55a6573425a7a38d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A device which encodes characters by the depression of keys is known as _____?', '{"A":"Hard Drive","B":"Mouse","C":"Keyboard","D":"Printer","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A device that encodes characters by pressing keys is known as a keyboardADDITIONAL INFORMATION RELATED TO KEYBOARDIt is an input device.It is used to enter text and commands.Each key represents a character or function.Christopher Latham Sholes was an American inventor who invented the QWERTY keyboard.', 0, 0, 0, 1790966321306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9f340a88eb96ada6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which algorithm is used to find the shortest path in a graph?', '{"A":"Decision Tree","B":"Dijkstra''s Algorithm","C":"K-Nearest Neighbors","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dijkstra''s Algorithm is used to find the shortest path between nodes in a graph, especially for weighted graphs.It works by iteratively selecting the closest unvisited node and updating the shortest path estimates.', 0, 0, 0, 1790966321306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_165252e0772397e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which chart type in Excel is best suited for showing the proportion of parts to a whole?', '{"A":"Pie Chart","B":"Bar Chart","C":"Lines Chart","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A pie chart is best suited for showing the proportion of parts to a whole.As it visually represents data as slices of a circle.It highlighting the relative sizes of components.', 0, 0, 0, 1790966321389) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_973b0788d3e7770a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What connects two different connections of distinct networks?', '{"A":"Router","B":"Switch","C":"Hub","D":"Modem"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A router is a device that connects two or more packet-switched networks or subnetworks. It serves two primary functions: Managing traffic between these networks by forwarding data packets to their intended IP addresses.Allowing multiple devices to use the same Internet connection.', 0, 0, 0, 1790966321389) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b546637ae2f994f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The process of removing unwanted part of an image is called?', '{"A":"Hiding","B":"Bordering","C":"Cropping","D":"Cutting"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process of removing unwanted parts of an image is called cropping. They involve trimming the outer edges or specific areas to improve focus, composition, or change the aspect ratio by eliminating distractions or extra space. While cropping cuts away parts, other methods, such as masking or cloning (inpainting), remove specific objects without altering the frame.', 0, 0, 0, 1790966321389) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e1eb6e5eebe18e05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'MS Access is program for ______?', '{"A":"Presentation","B":"Documentation","C":"Calculation","D":"Database"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS-Access is the program for Data Base.**Microsoft Access is a Database Management System (DBMS) from MicrosoftMicrosoft Access combines the relational Microsoft Jet Database Engine with a graphical user interface and software-development tools', 0, 0, 0, 1790966321389) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1878efda4309ab1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The graphical representation of a program is called ______?', '{"A":"Flowchart","B":"Source code","C":"Pseudo code","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A flowchart is a graphical representation of a program or algorithm using symbols to show the flow of control.It helps visualize logic and the sequence of operations before actual coding.', 0, 0, 0, 1790966321389) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5daedc6ef40c77d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which menu should we used, if we want to add Clip Art?', '{"A":"File","B":"View","C":"Insert","D":"Help"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS PowerPoint and MS Word, the "Insert" menu provides options for adding various elements, including clip art.Clip art is a collection of images, sounds, and animations that can be inserted into documents and presentations.The "Insert" menu also offers options for adding tables, charts, shapes, and other multimedia elements.Clip art can be used to enhance the visual appeal and illustrate key points in presentations and documents.', 0, 0, 0, 1790966321389) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f52ed05ee7ce3d60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which option is used to open a recent file?', '{"A":"Ctrl + R","B":"Ctrl + O","C":"Ctrl + M","D":"Ctrl + F"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + S = saveCtrl + F12 = Save as', 0, 0, 0, 1790966321389) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b8087f54aec7e143', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which button do you click to add up a series of numbers?', '{"A":"The auto sum button","B":"The formula button","C":"The total button","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ND29-5-2023', 0, 0, 0, 1790966321389) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b724f038ba6106ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Spooling is required for devices such as _____?', '{"A":"Disks","B":"Network adapter","C":"Printers","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Spooling allows the printer to receive data from the CPU and print at its own speed.It manages multiple print jobs efficiently by queuing them in a buffer.', 0, 0, 0, 1790966321518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1d6ca22cbbe98fe5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Docx is the extension of which of the following?', '{"A":"MS Excel","B":"MS Word","C":"MS PowerPoint","D":"MS Outlook"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DOCX is the newer version of DOC, the original official Microsoft Word file format.Microsoft Word 97 - 2003 Document extension (.doc).Microsoft Word 2007 to till date Document extension (.docx).', 0, 0, 0, 1790966321518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_44c4bfe0e0ab4110', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Software required to run the hardware is known as _____?', '{"A":"Task Bar","B":"Device Driver","C":"Task Manager","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A device driver is software that allows the operating system to communicate with hardware devices.Without drivers, the hardware cannot function properly or be recognized by the computer.', 0, 0, 0, 1790966321518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_288b15df65f1bc3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which type of software is an antivirus?', '{"A":"System Software","B":"Utility Software","C":"Application Software","D":"Development Software"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Utility Software: Helps maintain, analyze, and protect the computer (includes antivirus, disk cleanup, etc.)System Software: Runs the hardware and system (e.g., OS like Windows)Application Software: End-user programs (e.g., MS Word, Photoshop)Development Software: Tools for programming (e.g., compilers, IDEs)', 0, 0, 0, 1790966321518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d1436eba99c279b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A combination of 16 bits is called _____?', '{"A":"Memory","B":"Nibble","C":"Bit","D":"Word or Two Bytes"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A combination of 16 bits is called a "word".It is a standard unit of data used in computing to represent information.Bit: a single binary digit (0 or 1)Nibble: 4 bitsByte: 8 bitsWord: 16 bitsDouble Word: 32 bits', 0, 0, 0, 1790966321518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1f355cf811641d94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '____ is to protect data and passwords', '{"A":"Encryption","B":"Authorization","C":"Authentication","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Encryption is used to protect data and passwords by converting them into a secret code that can only be accessed with the correct decryption key. This process makes sensitive information unreadable to unauthorized parties, Protecting it both when it is stored (at rest) and when it is being sent over networks (in motion).', 0, 0, 0, 1790966321518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6b99d9631641140d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following is word processing software?', '{"A":"MS Excel","B":"MS Word","C":"Browse","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Word (Microsoft Word) is a word processing software, which allows users to create, edit, and print documents.It is a popular application software used for:Typing and editing textFormatting documentsAdding images and graphicsCreating tables and columnsPrinting and sharing documents', 0, 0, 0, 1790966321518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_18a691bf4652fb15', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The process of dividing a disk into tracks and sectors is called?', '{"A":"Partitioning","B":"Fragmentation","C":"Formatting","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process of dividing the disk into tracks and sectors is called formatting. In computer disk storage, a sector is a subdivision of a track on a magnetic disk or optical disc.', 0, 0, 0, 1790966321518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ddabfd27bd7bed2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '1 nibble is equal to _____?', '{"A":"4 bits","B":"8 bits","C":"12 bits","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A nibble can have 16 possible values due to the four bits that are the same as one hexadecimal.In computer architecture, 8-bit integers or other data units are those that are 8 bits The byte is a unit of digital information that most commonly consists of eight bits.Unit of: digital information, data sizeUnit system: unit derived from bit*********', 0, 0, 0, 1790966321739) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c3c16e8dc04a0f07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Who was the founder of C programming language?', '{"A":"Dennis Ritchie","B":"Billgates","C":"Bjarne Stroustrup","D":"James A. Gosling"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1972 by Dennis Ritchie invented the high-level language “C”?in the Bell Laboratories of the AT & T (American Telephone & Telegraph),located in U.S.A.Dennis Ritchie is known as the founder of c language.***Co developer of UnixC is a general-purpose computer programming language. It was created in the 1970s.By design, C''s features cleanly reflect the capabilities of the targeted CPUs. Designed by: Dennis RitchieFirst appeared: 1972*****', 0, 0, 0, 1790966321739) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_24d399f5f698eecd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which key is used to move the cursor to the beginning of a line?', '{"A":"Home","B":"Page up","C":"Left Arrow Key","D":"Up Arrow Key"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To move the cursor to the beginning of a line:🔹 Home keyTo move the cursor to the end of a line:🔹 End key', 0, 0, 0, 1790966321739) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ae387f78091a6008', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Shimmer, Sparkle text, Blinking Background etc. are known as _____?', '{"A":"Word art","B":"Font styles","C":"Text effects","D":"Font effects"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shimmer, Sparkle text, Blinking Background, etc. are known as Text effectsText effects are found on the text effects tab. These are simple animations that can be applied to text, for example, the blinking backgroundLas Vegas lights, shimmer, and others.sparkling symbols:･ﾟ☆✧ND06-08-2023', 0, 0, 0, 1790966321739) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_662cb6e2962c537e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following refers to set margin, paper size and layout?', '{"A":"Page orientation","B":"Formating","C":"Text security","D":"Editing"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Page orientation refers to setting margins, paper size, and layout in a document.It determines how the content is arranged on the page, such as portrait or landscape.', 0, 0, 0, 1790966321739) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_aae789bbc7097989', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How can you sum up a range of cells in Excel?', '{"A":"Use the SUM function","B":"Use the AVERAGE function","C":"Use the COUNT function","D":"Use the MAX function"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To sum up a range of cells in Excel, you use the SUM function. This function adds together all the numbers in the specified range of cells.AVERAGE function calculates the average of the numbers in a range.COUNT function counts the number of cells that contain numbers.MAX function finds the highest value in a range of cells.', 0, 0, 0, 1790966321739) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7a82bbaadd4b9f41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A device that opposes the flow of electrons in electronic circuits is called?', '{"A":"Transformer","B":"Diode","C":"Transistor","D":"Resistor"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A device that opposes the flow of electrons in electronic circuits is called a resistor.It is a passive two-terminal component used to reduce current flow, divide voltage, and perform other functions by creating resistance.Resistance is measured in ohms (Omega).', 0, 0, 0, 1790966321739) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_65ad6f6105772920', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the decimal equivalent of the binary number (1101)₂?', '{"A":"12","B":"13","C":"11","D":"16"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation (1101)₂ = 1×2³ + 1×2² + 0×2¹ + 1×2⁰= 8 + 4 + 0 + 1= 13₁₀', 0, 0, 0, 1790966321739) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f964aac29b6f965c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'With which view you can see how texts and graphics appear on the printed page?', '{"A":"Outline","B":"Web Layout","C":"Print Layout","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, With the help of Print Layout view can you see how text and graphics will appear on the printed page.Your document opens showing the entire page, just the way it will appear when it is printed on a sheet of paper.You can make changes while text formatting, images, and page layout are visible.', 0, 0, 0, 1790966321831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_188ef422f20f3b37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which would you choose to move selected text from one place to another?', '{"A":"copy and paste","B":"delete and paste","C":"move and paste","D":"cut and paste"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cut-and-paste option is used to move the selected text from one place to another.Cut using Ctrl+X, move your cursor to the new location of the text, then paste to the new location with Ctrl+V.Copy using Ctrl+C, move your cursor to the new location of the text, then paste to the new location with Ctrl+VND11-2-2023', 0, 0, 0, 1790966321831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_89740db99f44f16b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is a computer virus?', '{"A":"A type of insect that harms computer","B":"A type of program that harms computer","C":"A type of hardware that harms computer","D":"A type of firmware that harms computer"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer virus is: deliberately createdA virus can remain dormant in our computer, without showing any sign or symptom.Other Questions Related to "COMPUTER VIRUS"***Computer Virus operates by:Dormancy and Replication***From where a computer can get a virus?Email and in internet*** Which is the first computer virus in World?Creeper***First, ever computer virus was created from -------:PakistanND11-3-2023', 0, 0, 0, 1790966321831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fd6064436b6ee5f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How many bits are there in 100 bytes?', '{"A":"700","B":"900","C":"1600","D":"800"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 byte = 8 bits, so 100 bytes = 100 × 8 = 800 bits.Bits are the smallest unit of digital data, while bytes are larger grouped units.', 0, 0, 0, 1790966321831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_32391c38fb7e54fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which short cut key is used to SAVE a documents or workbook?', '{"A":"Ctrl + Z","B":"Ctrl + C","C":"Ctrl + S","D":"Ctrl + A"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + S = to save a document.Additional informationPress Ctrl + X to move text in MS Office.Ctrl + R = use for Align selected text to the right.Ctrl + E = use for Align selected text to the centre.Ctrl + L = use for Align selected text to the left.Ctrl + J = use for Justify paragraph alignment.Ctrl + Q = use for Align selected paragraph to the left.', 0, 0, 0, 1790966321831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_344e2e62643430e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which was the first programming language ever developed?', '{"A":"FORTRAN","B":"COBOL","C":"Assembly Language","D":"BASIC"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FORTRAN (Formula Translation), developed in 1957 by John Backus and his team at IBM,It is considered the first high-level programming language.It was designed for scientific and engineering calculations.', 0, 0, 0, 1790966321832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2cb4d8623137c69e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which data type allows alphanumeric characters and special symbols in MS-Access?', '{"A":"Text","B":"Number","C":"Auto Number","D":"Date/Time"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation TEXT data type contains all types of text data type. It comprises more than single-byte character that is supported by the system.', 0, 0, 0, 1790966321832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_211a34b84f1b265c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Ctrl,Shift and Alt are called --- keys', '{"A":"Modifier","B":"Function","C":"Alphanumeric","D":"Adjustment","E":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation These keys include the same letter, number, punctuation, and symbol keys found on a traditional typewriter.Control keys. Function keys. Navigation keys. Numeric keypad.ND07-3-2023', 0, 0, 0, 1790966321832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_37f13e1703f07b08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'First truly electronic computer', '{"A":"ENIAC","B":"IBM","C":"Apple","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ENIAC, in full Electronic Numerical Integrator and Computer, the first programmable general-purpose electronic digital computer.ENIAC was completed in 1945 and first put to work for practical purposes on December 10, 1945.', 0, 0, 0, 1790966321918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b1a8a55b639f9669', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The first computer were programmed using _____?', '{"A":"Assembly language","B":"Machine language","C":"Source code","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vacuum tubes as the basic components for memory and circuitry for CPU . These tubes, like electric bulbs, produced a lot of heat and the installations used to fuse frequently.First generation (1940 - 1956) vacuum tubes as a major piece of technology. The ENIAC is example of 1st generation computer.Second generation (1956 - 1963) use of transistors.Third generation (1964 - 1971) use of Integrated circuits.Fourth generation (1972 - 2010) use of the microprocessor.Fifth generation (2010 to present) use Artificial intelligence.', 0, 0, 0, 1790966321919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_04b3ce5b782fce34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The largest, fastest, and the most expensive type of computer is the ______ computer.', '{"A":"Super computer","B":"Micro computer","C":"Mini computer","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest, fastest, and most expensive type of computer is the supercomputer. These machines are used for specialized, complex tasks like weather forecasting, scientific research, and simulations that require immense computing power.', 0, 0, 0, 1790966321919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eb32e7255106da4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '_____ computers are also called personal computers.', '{"A":"Super Computers","B":"Mini Computers","C":"Micro Computers","D":"Mainframe Computers"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microcomputers are also called personal computers (PCs). These are computers designed for individual use, which include desktops, laptops, and tablets.', 0, 0, 0, 1790966321919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_69d418fa602b784c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What acts as an interface/bridge between the computer user and the computer hardware?', '{"A":"Operating System","B":"MS Word","C":"MS Excel","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The operating system is the software that connects the user with the hardware.It manages resources and provides a user-friendly environment to run applications.', 0, 0, 0, 1790966321919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_311d4778ef688226', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the base of decimal number system?', '{"A":"8","B":"16","C":"10","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The decimal system is base 10, using digits 0–9.Base 8 → Octal number system (digits 0–7).Base 16 → Hexadecimal number system (digits 0–9, A–F).Base 4 → Quaternary number system (digits 0–3).', 0, 0, 0, 1790966321919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_aa95f6df72aaaa06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Microsoft was founded in which year__________?', '{"A":"1970","B":"1972","C":"1975","D":"1981"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft was founded on April 4 1975 in the USA.Founders: Bill Gates and Paul AllenLocation: Albuquerque, New MexicoInitial purpose: To develop and sell BASIC interpreters for the Altair 8800, one of the first personal computersCompany name: "Microsoft" is a portmanteau of "microcomputer" and "software"', 0, 0, 0, 1790966321919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d54d30570c192fba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The Headquarters of Google located in the city ________?', '{"A":"California","B":"Paris","C":"London","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Headquarters of Google is located in the city: of CaliforniaGoogle, a US multinational technology companyGoogle is a type of search engine operating since 1997it was founded in the year: September 4, 1998it was founded by Sergey Brin & Larry Page Sergey Brin is the real owner of GoogleND07-3-2023', 0, 0, 0, 1790966321919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_45ec7caf90d89edc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '“Add or Remove programs” is a(an) ……?', '{"A":"File manage","B":"Utility program","C":"Productivity software","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Utility software is software designed to help analyze, configure, optimize or maintain a computer.', 0, 0, 0, 1790966321991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_21886341ba4fcf76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'PRINT INPUT is?', '{"A":"Logical","B":"Syntax","C":"Execution","D":"An error"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In standard multiple-choice questions, writing PRINT INPUT together is classified as a Syntax Error Print: Sends data from the computer system to a display (output).Input: Receives data from the user and sends it into the program (input).', 0, 0, 0, 1790966321991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a1865e352979c71d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is the oldest search engine? Google, Yahoo, MSN Search, Alta Vista', '{"A":"Yahoo","B":"Google","C":"MSN Search","D":"Alta Vista"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Yahoo is the oldest. It was founded in January 1994 by Jerry Yang and David Filo. Originally called "Jerry and David''s Guide to the World Wide Web,"Additional informationAltaVista: launched in 1995. Google: founded later in 1998. Launched by Microsoft in the fall of 1998 Last updated 15-feb-2026', 0, 0, 0, 1790966321991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f0846e166986427d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which number key is used with shift to type %?', '{"A":"5","B":"4","C":"6","D":"7"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Shift key ⇧ Shift is a modifier key on a keyboard, used to type capital letters and other alternate "upper" characters. There are typically two shift keys, on the left and right sides of the row below the home row.', 0, 0, 0, 1790966321991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e65754701d0571cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A program that time destroy all of your computer programs is called____', '{"A":"Anti-virus","B":"Virus","C":"Switched computer","D":"Dust"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A program designed to destroy data and spread to other computers is called a virus, It is malicious software that damages data.', 0, 0, 0, 1790966321991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_087d69ba6372f605', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Common name for software errors is called _____?', '{"A":"Bugs","B":"Viruses","C":"Logic Bombs","D":"Trojans"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A bug is a flaw in a software''s code that can lead to errors ranging from minor glitches to critical system crashes. The term "bug" was popularized in the 1940s When Grace Hopper discovered an actual moth was causing an issue in a computer''s relayThe process of finding and fixing these bugs is called debugging.', 0, 0, 0, 1790966321991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f1b4a8980e4d9a35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The capacity of Floppy disk is _____?', '{"A":"1.44 MB","B":"1.33 MB","C":"1.22 MB","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A typical floppy disk can store up to 1.44 megabytes of data.There are 3 types of Floppy:1. 8 Inch floppy2. Mini floppy3. Micro floppy', 0, 0, 0, 1790966321991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c9a27662dd8a0826', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which language is commonly used for writing/developing business applications?', '{"A":"Python","B":"JavaScript","C":"COBOL","D":"HTML"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation COBOL stands for Common Business-Oriented LanguageIt is a programming language specifically designed for business, finance, and administrative systems.It was designed in 1959 by CODASYL And was partly based on the programming language FLOW-MATICDesigned by Grace HopperStable release: ISO/IEC 1989:2023 / 2023', 0, 0, 0, 1790966321991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_af588e81c6592c9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What number system is used in computers?', '{"A":"Octal","B":"Decimal","C":"Binary","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The binary numbering system is used in computing.Binary system is used because it''s the simplest counting method available.', 0, 0, 0, 1790966322061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_acc7d9683fc1ce77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A system software that translates high-level language source code into machine-level object code is called _____?', '{"A":"Linker","B":"Interpreter","C":"Compiler","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A compiler is system software that translates the entire high-level language source code into machine-level object code at once.It checks for errors during translation and produces a separate executable file.', 0, 0, 0, 1790966322061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b8b5b2e9c5611c92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the file extension for python files?', '{"A":".txt","B":".java","C":".py","D":".ppt"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation .py Used for writing Python programs. Python was created by Guido van Rossum in 1991.More Details.cpp extension of C++, .java extension of Java, .html extension of Web, .docx extension of Word', 0, 0, 0, 1790966322061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_76eb027d66ac65f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'An error in software or hardware is called a bug. What is the alternative computer jargon for it?', '{"A":"Leech","B":"Squid","C":"Slug","D":"Glitch","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An error in software or hardware is called a bug. The alternative computer jargon for it Glitch A glitch is a short-lived fault in a system. A bug is an error, failure, or fault.AGM 30.4.23', 0, 0, 0, 1790966322061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b732e4795875e031', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The number system used by computers to store data and perform calculations is ______?', '{"A":"Decimal","B":"Binary","C":"Octal","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Computers use the binary number system (0 and 1) to store data and perform calculations.This system aligns with the digital circuitry, which recognizes only two states: ON (1) and OFF (0).', 0, 0, 0, 1790966322061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_123648839eb10063', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is a Terabyte?', '{"A":"Flesh memory","B":"One Trillion byte","C":"An optical storage medium","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Terabyte (TB) is a unit of digital information storage equal to approximately one trillion bytes (1,024 gigabytes).It is commonly used to measure the capacity of large storage devices.', 0, 0, 0, 1790966322061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5af2b22ffbb21968', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To copy a picture of the screen to the clipboard use?', '{"A":"Print screen key","B":"Alt key","C":"Both","D":"Shift key"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressing PRINT SCREEN captures an image of your entire screen and copies it to the Clipboard in your computer''s memory.You can then paste (CTRL+V) the image into a document, email message, or another file.**', 0, 0, 0, 1790966322061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_13f26c5e17df316b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A hybrid computer _____?', '{"A":"Resembles digital computer","B":"resembles analogue computer","C":"Resembles both digital and analogue computer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hybrid computers can perform the tasks of digital and analogue computerThese computers are used in aircraft, hospitals where measuring physical quantities and converting them into digital data to analysis is required.AGM 07.5.23', 0, 0, 0, 1790966322061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2291436a11c1ffe8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is used to transmit digital data over telephone lines?', '{"A":"Network card","B":"Sound Card","C":"Graphic card","D":"Modem"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A modem (modulator-demodulator) is used to transmit digital data over analog telephone lines By converting digital signals into analog audio tones for transmission and Converting incoming analog tones back into digital signals for computers. For digital subscriber line (DSL) services, which are a modern technology, Another type of modem is used to provide higher speeds over existing telephone wiring.', 0, 0, 0, 1790966322160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_548f9253493451ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Tool used for graphics designing or drawing is ______?', '{"A":"Word","B":"Excel","C":"Paint","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Paint is a basic tool used for drawing and graphic designing.It allows users to create, edit, and color images easily.', 0, 0, 0, 1790966322160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_47112a885ad07921', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'MS Access arranges the data in ______?', '{"A":"Rows","B":"Tables","C":"Word","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft Access (MS Access) organizes data in tables, which are the fundamental building blocks of any database.Data organization: Stores data in tables with rows and columns.Data types: Supports various data types, such as text, number, date/time, currency, and more.', 0, 0, 0, 1790966322160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1e86ffdc34589a29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Identify the device through which data and instructions are entered into a computer?', '{"A":"Memory","B":"Output Device","C":"Software","D":"Input device"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An input device is a piece of equipment used to provide data and control signals to an information processing system.An input device is used to enter data and instructions into a computer.Examples include keyboards, mice, scanners, and microphones.', 0, 0, 0, 1790966322160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e8e47c53bbe1f91c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which tool is used to convert documents into PDF format?', '{"A":"Adobe Reader","B":"Photoshop","C":"Adobe Writer","D":"Adobe Acrobat"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adobe Writer (Acrobat Pro/Writer) is used to convert documents into PDF format.It allows users to create, edit, and manage PDF files efficiently.', 0, 0, 0, 1790966322160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a12c5c8883e8c762', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which was the first computer made available for commercial use?', '{"A":"UNIVAC","B":"EDSAC","C":"ENIAC","D":"EDSAC"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The UNIVAC was the first commercial computer delivered to a business client, the U.S. Census Bureau in 1951.', 0, 0, 0, 1790966322160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1b9c2ad27fc38496', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The ______ function in Excel returns the highest value in a set of data that you specify.', '{"A":"LRG","B":"AVG","C":"MAX","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The MAX function in Excel returns the highest value in a set of dataSyntax: =MAX(number1, [number2], ...).Behavior: It evaluates numbers, arrays, or references containing numbers.Alternative: For finding the smallest value, the MIN function is used. Last updated 27-07-2026 by NA', 0, 0, 0, 1790966322160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_356b9ac15939f1e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which allow to access from one cell to another?', '{"A":"Address","B":"Formulas","C":"Values","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A cell reference or cell address is a combination of a column letter and a row number that identifies a cell on a worksheet. For example, A1 refers to the cell at the intersection of column A and row 1; B2 refers to the second cell in column B, and so on.', 0, 0, 0, 1790966322160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_abda867d27dd878b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which technology is used in compact disc?', '{"A":"Laser","B":"Mechanical","C":"Electrical","D":"Electro Magnetic"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Laser technology is used in compact discCompact Disc is an example of Optical StorageJames T. Russell invented C.D. (Compact Disc). co-developed by Philips and Sony to store and play digital audio recordings.history In August 1982, the first compact disc was manufactured. It was then released in October 1982 in Japan and branded as Digital Audio Compact Disc. It was released on March 2, 1983, in North America and Europe.', 0, 0, 0, 1790966322225) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a561dbe6f3515f0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Plotter is an example of _______?', '{"A":"Output device","B":"Input device","C":"Hardware","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A plotter is an output device used for printing large-scale images, drawings, and designs.It is commonly used in engineering, architecture, and graphic design for precise line work.', 0, 0, 0, 1790966322225) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2c9884ccf99628df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Mark Zuckerberg is associated with which of the following?', '{"A":"Oracle","B":"Microsoft","C":"Facebook","D":"WhatsApp"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mark Zuckerberg is an American internet entrepreneur, and philanthropist.He co-founded the social media service Facebook.Facebook is an online social media and social networking service founded in 2004 by Mark Zuckerberg.', 0, 0, 0, 1790966322225) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ed2fc806d227f884', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'One Perabyte is equal to?', '{"A":"1024 MB","B":"1024 GB","C":"1024 TB","D":"None of the these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In binary measurement (used in computing): 1 Petabyte (PB) = 1024 Terabytes (TB)', 0, 0, 0, 1790966322225) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_efbe965912163cd6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the name of the artificial intelligence company of Elon Musk launched in July 2023?', '{"A":"xAI","B":"Meta","C":"Giga","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Founded by Elon Musk: xAI was launched in July 2023 to develop advanced AI models.AI Development: It introduced Grok, an AI chatbot integrated into X (formerly Twitter).', 0, 0, 0, 1790966322225) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5914589370f4e9f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following is not a valid zoom percentage in Excel?', '{"A":"10","B":"100","C":"300","D":"500"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Minimum zooming is 10% and Maximum zooming is allowed in 400%. So, 500% is invalid zoom percentage in Excel.', 0, 0, 0, 1790966322225) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_142dedd3eff8c778', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Interface used in DOS is called _____?', '{"A":"Command-Line Interface (CLI)","B":"Graphical User Interface (GUI)","C":"Application Programming Interface (API)","D":"Scripting Interface (SI)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A command-line interface is used by DOS systems. By typing a program''s filename at the command prompt, a program can be launched.', 0, 0, 0, 1790966322225) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2657b7b28a0da680', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How many sheets (worksheets) are there in the Excel workbook by default?', '{"A":"2","B":"3","C":"4","D":"5"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation By default, an Excel workbook contains 3 sheets in older versions (Excel 2010 and earlier). In newer versions (Excel 2013 and later), it starts with 1 sheet, but users can add more.', 0, 0, 0, 1790966322225) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7db2fd88b8c46596', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A collection of related fields is called _____?', '{"A":"Record","B":"File","C":"Character","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A record is a collection of related fields (e.g., name, age, and ID of a student).Multiple records make up a file.', 0, 0, 0, 1790966322317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a203b14eaee35fd6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The arranging of data in logical sequence is called ______?', '{"A":"Sorting","B":"Arrangement","C":"Sequence","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sorting refers to ordering data in an increasing or decreasing manner. According to some linear relationship among the data items.Ordering: arranging items in a sequence ordered by some criterion.Categorizing: grouping items with similar properties.', 0, 0, 0, 1790966322317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0e67d6078835133b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The binary equivalent of decimal 13 is ______?', '{"A":"1101","B":"1001","C":"11011","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Solution13 ÷ 2 = 6, remainder 1 6 ÷ 2 = 3, remainder 0 3 ÷ 2 = 1, remainder 1 1 ÷ 2 = 0, remainder 1 Reading the remainders from bottom to top: 1101 So, 13 in binary = 1101.', 0, 0, 0, 1790966322317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_28ba9a8eb0a47b7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What runs all over the hardware, software, and other computer resources?', '{"A":"Operating System","B":"Processor","C":"Memory Unit","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Operating System (OS) manages and controls all hardware, software, and system resources on a computer.It acts as an intermediary between the user and the hardware, enabling smooth execution of tasks.', 0, 0, 0, 1790966322317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_83da0496819a6156', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is/are NOT a characteristic of a computer?', '{"A":"Diligence and Speed","B":"Accuracy and Automation","C":"Versatility","D":"IQ and Intelligence"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Computers do not possess IQ or intelligence; they operate based on human-programmed instructions.While they show speed, accuracy, and versatility, they lack conscious understanding or reasoning abilities.', 0, 0, 0, 1790966322317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d2289b5263bc67d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the function of Recycle Bin?', '{"A":"Store temporary file","B":"Store deleted file","C":"Store document file","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Recycle Bin temporarily stores deleted files and folders from your computer.You can restore them if needed or permanently delete them from there.', 0, 0, 0, 1790966322317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_55f58dd0e11e0ec7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Automatic Teller Machine (ATM) is the example of _____?', '{"A":"Super Computer","B":"General Purpose Computer","C":"Special General Computer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An ATM is designed to perform specific tasks like cash withdrawal, balance inquiry, etc.Hence, it is a Special Purpose Computer.', 0, 0, 0, 1790966322317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a00ff7b2fc46dfe7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To read information from cheques, banks mostly use ______?', '{"A":"Microphones","B":"Magnetic Ink Character Recognition","C":"Cameras","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MICR is a technology used by banks to read information printed on cheques using magnetic ink.It allows for fast and secure processing of cheques and reduces the chances of errors or fraud.', 0, 0, 0, 1790966322317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7ad86920ae727e4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Antivirus, WinZip, WinRAR and disk defragmenter are the examples of ________?', '{"A":"Language Translator","B":"Application software","C":"Utility programs","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antivirus, WinZip, WinRAR, and disk defragmenter are examples of utility programs that help maintain, optimize, and secure the computer system.These programs perform tasks like file compression, system cleanup, and protecting against malware.', 0, 0, 0, 1790966322430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_550f3727e1402129', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What term refers to donate unauthorized and illegal accessing of computer programmed, often with criminal intent?', '{"A":"Virus","B":"Plagiarism","C":"Hacking","D":"BlackBerry"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hacking refers to the unauthorized and illegal access of computer systems, often with criminal intent. It can involve stealing data, disrupting networks, or damaging systems.', 0, 0, 0, 1790966322430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2554da9e765aff46', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is the most important area of concern in Cloud Computing?', '{"A":"Salability","B":"Storage","C":"Security","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Security is the most important concern of cloud computing. Cloud computing presents many unique security issues and challenges. Amazon, Microsoft and Google are the three largest public cloud storage providers.Dropbox, eFolder, IBM etc. are examples of cloud service providers.', 0, 0, 0, 1790966322430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fc1ab8065733aa70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which option is used to copy formatting from one place and apply it to another?', '{"A":"Copy","B":"Copy formatter","C":"Format painter","D":"Formatting"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation With format painter, you can copy all of the formatting from one object and apply it to another one—think of it as copying and pasting for formatting.', 0, 0, 0, 1790966322430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a6f9609924dc2833', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'All hardware devices are attached directly or indirectly with ______?', '{"A":"Motherboard","B":"CPU","C":"Keyboard","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The motherboard is the central printed circuit board in a computer that serves as the foundation for all other hardware components. All other devices, including the CPU, RAM, hard drives, and peripherals, connect directly or indirectly to the motherboard.', 0, 0, 0, 1790966322430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_873c09b45ee0cfba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the ports are commonly used in a computer?', '{"A":"USB","B":"Serial","C":"Parallel","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation USB, Serial, and Parallel are common computer ports:USB is widely used for modern devices like keyboards, printers, and flash drives.Serial ports were used for modems and mice but are now mostly replaced by USB.Parallel ports were used for printers but have also largely been replaced by USB.', 0, 0, 0, 1790966322430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8f1c8d3ffd85ab95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the key is used to close the active window?', '{"A":"Ctrl+F4","B":"Ctrl+F5","C":"Alt+F6","D":"Alt+F4"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alt + F4 keyboard shortcut to close an app or program on WindowsConfused questionCtrl+F4 is the shortcut key to an application or a windowAlt + F4: Close the current app or window.Alt + Tab: Switch between open apps or windows.ND19-3-2023', 0, 0, 0, 1790966322430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7849d3d082ae27ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which file stored in computer that perform functions quickly while browsing?', '{"A":"Exe","B":"Cookies","C":"Cache","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cache is a type of file that stores temporary data or copies of files that are frequently accessed by the computer or web browser.This allows for faster access and retrieval of the data, making browsing and computer performance faster.', 0, 0, 0, 1790966322430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b759a584ebb91521', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Excel is a program that is used to prepare a ______?', '{"A":"Spreadsheet","B":"Database","C":"Workbook","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Excel is primarily used to create and manage spreadsheets.It organize data in rows and columns for analysis and calculations.While it can contain multiple workbooks.Its main function revolves around spreadsheet preparation and manipulation.', 0, 0, 0, 1790966322517) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9243ea8162da382f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Page number is inserted in _____?', '{"A":"Header and footer","B":"Animation","C":"Word Art","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A header is text that is placed at the top of a page.A footer is placed at the bottom, or foot, of a page.******RY 15-01-2023', 0, 0, 0, 1790966322517) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bbf0182a87cd5e7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following option is MOST serious threat to Computer security?', '{"A":"Viruses","B":"Trojan horse","C":"Trap door","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Trap door (or backdoor) is a hidden entry point into a system that bypasses normal authentication, making it a serious security threat.Unlike viruses or worms, it allows unauthorized access without detection, potentially exposing entire systems.', 0, 0, 0, 1790966322517) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_399870c3f2a91745', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'If a person deliberately damages data or deletes data from a computer, then this is called ______?', '{"A":"Data loss","B":"Sabotage","C":"Hard drive crash","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sabotage refers to the intentional destruction or damage of data or systems.It involves deliberate harmful actions, unlike accidental data loss or hardware failures.', 0, 0, 0, 1790966322517) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0f97433bca2279aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which modules is not part of C programming?', '{"A":"Editor","B":"Linker","C":"Converter","D":"Compiler"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Converter — not a standard module in C programming; there is no such step in the C compilation processAdditional information Editor — used to write C code (source file)Linker — combines object files into an executableCompiler — converts C source code into object code (machine language)Last updated 24-07-2026 by NA', 0, 0, 0, 1790966322517) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a8e84173adab2caa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The rules of a programing language according to which statements of program are to be written are referred as _____?', '{"A":"Variable","B":"Syntax","C":"Semantic","D":"Expression"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The rules of a programming language according to which statements are written are referred to as syntax.Syntax defines the structure and format of valid statements in the language.', 0, 0, 0, 1790966322517) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_30518606310bff9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The single character is represented by _____ format specifier.', '{"A":"g%","B":"%f","C":"%c","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The %c format specifier is used to represent a single character in C and similar programming languages.It is commonly used with functions like printf() to display characters.', 0, 0, 0, 1790966322517) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5dd33d2b409f627c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following is the highest speed slot?', '{"A":"ISA","B":"AGP","C":"PCI","D":"AGC"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Accelerated Graphics Port (AGP) is a point-to-point link used for high-speed video output.This port is used to connect the graphics card to the computer''s motherboard.The main purpose of AGP is to accelerate the output of 3D graphics for high-definition videos.AGP is primarily intended for use in 3D graphics, high-resolution games, and engineering/architecture graphics.', 0, 0, 0, 1790966322517) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_121de4c6bf34f5f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Decrease in strength of signal is known as?', '{"A":"Tuning","B":"Modulation","C":"Attenuation","D":"Amplification"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Attenuation refers to the decrease in strength or intensity of a signal as it travels through a medium or is processed by a system. This can occur due to various factors such as resistance, impedance, or absorption, and can affect the quality and fidelity of the signal.', 0, 0, 0, 1790966322625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3eade4412d346404', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In flowchart, a diamond sign indicates a _____?', '{"A":"Process","B":"Decision","C":"Display","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The diamond symbol represents a decision/condition in a flowchart.It is used to indicate a point where the flow splits based on a yes/no or true/false condition.Flow Chart List:', 0, 0, 0, 1790966322625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fff2dfc5ca7b33da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A well-defined list of steps for solving a particular problem written in a natural language is called ______?', '{"A":"Algorithm","B":"Program","C":"Flow Chart","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An algorithm is a step-by-step, well-defined list of instructions written in natural or simple language to solve a specific problem.It serves as a blueprint for writing a program or creating a flowchart.', 0, 0, 0, 1790966322625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6da39b689f2cea4d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Personal Digital Assistant (PDA) is a ______ computer.', '{"A":"Handheld","B":"Mini","C":"Super","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Personal Digital Assistant (PDA) is a handheld computer used for managing personal information like contacts, calendar, and notes.PDAs were popular before smartphones.It often included touchscreens and stylus input.', 0, 0, 0, 1790966322625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1750c311f0983515', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is/are an example of a Procedural programming language?', '{"A":"FORTRAN","B":"C","C":"Pascal","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Procedural languages are also known as third-generation languages (3GLs).Examples of third-generation languages include C, C++, Java, FORTRAN, and PASCAL.', 0, 0, 0, 1790966322625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c199773747ebf703', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A computer cannot function without _____?', '{"A":"Microsoft Office","B":"Internet Connection","C":"Operating System","D":"Antivirus Protection"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer cannot function without an Operating System (OS).As it manages hardware and software. It providing a platform for applications to run.The OS facilitates essential tasks like file management, memory allocation, and user interaction with the device.', 0, 0, 0, 1790966322625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3cae21d09d1904ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A function inside another function is called _____?', '{"A":"Text function","B":"Sum function","C":"Round function","D":"Nested function"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A function inside a function is called a Nested function.FunctionDefinitionRound FunctionThis function rounds a number to a specified number of digits.Switch FunctionIt returns a value (if matched), after matching it with other values in the list.Nested FunctionA function tucked inside a function', 0, 0, 0, 1790966322625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5ebca583c5ab2bee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Page up key is used to move ______?', '{"A":"One line up","B":"One page down","C":"One screen up","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Using navigation keysPage Up: Move the cursor or page up one screenCtrl + Home: Move to the top of a documentCtrl + End: Move to the bottom of a documentPage Down: Move the cursor or page down one screen', 0, 0, 0, 1790966322625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_92ef32afee8faad8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which one can be used for creating a document?', '{"A":"MS Excel","B":"MS Word","C":"MS Access","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Word can be used for creating a document.Microsoft Word is a word processor developed by Microsoft. It was first released on October 25, 1983.', 0, 0, 0, 1790966322710) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7fcb0c0aaa368953', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which Excel feature allows you to display only specific data based on a condition?', '{"A":"Grouping","B":"Sorting","C":"Filtering","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Filtering in Excel enables you to display rows that meet certain criteria, hiding the others.This Excel feature allows you to display only the rows that meet specific conditions while hiding the others.', 0, 0, 0, 1790966322710) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4bff76bc93e446be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What are the function of logical unit in computer?', '{"A":"To produce result","B":"To perform arithmetic and logical unit","C":"To control flow of information","D":"To store result data"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Logical Unit is also known as an Arithmetic Logic Unit (ALU).It is a digital circuit that performs arithmetic and logical operations on binary numbers, such as:Arithmetic operations (e.g., addition, subtraction, multiplication, division)Logical operations (e.g., AND, OR, NOT, XOR)', 0, 0, 0, 1790966322710) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fab56c95e9dd8c8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following best describes polymorphism in OOP?', '{"A":"The process of grouping related objects together","B":"The ability of an object to take on many forms","C":"The relationship between clauses and their objects","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Polymorphism allows objects to be treated as instances of their parent class.This enabling them to take on different forms (e.g., method overriding or overloading).It promotes flexibility and reusability in object-oriented programming.', 0, 0, 0, 1790966322710) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fc78ec41e14b7c8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In Excel, which is used to perform what if analysis?', '{"A":"Goal seek","B":"Solver","C":"Scenario Manager","D":"All of above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Goal Seek, Solver, and Scenario Manager are all tools in Excel used for What-If Analysis.It helping to analyze different possible outcomes.Goal Seek adjusts a single input to reach a desired result.Solver handles complex optimizations.Scenario Manager compares multiple data scenarios.', 0, 0, 0, 1790966322710) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6758cf48f8ed6544', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Themes in presentations are inserted from?', '{"A":"Insert Tab","B":"Home Tab","C":"Design Tab","D":"View Tab"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In PowerPoint, themes are inserted from the Design tab:Open a slideSelect the Design tabHover over the Themes group to preview the themesSelect a theme', 0, 0, 0, 1790966322710) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b890d91f0c06c083', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Comments can be added to cells using _______?', '{"A":"Data > Comments","B":"Home > Comments","C":"Insert > Comment","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Comments can be added to cells using Insert > Comment.Right-click the cell and then click Insert Comment (or press Shift+F2).', 0, 0, 0, 1790966322710) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d2f294459720ae05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following you can paste selectively using paste special command?', '{"A":"Formats","B":"Validation","C":"Formulas","D":"All of above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We can paste formula, value, formats, comments, validation using Paste Special command.', 0, 0, 0, 1790966322710) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0f5d13b539e83f49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A set of rules that governs data communication is known as?', '{"A":"Medium","B":"Sender","C":"Receiver","D":"Protocol"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A protocol is a set of rules that governs how data is transmitted and received over a network.It ensuring that communication between devices is orderly and understandable.', 0, 0, 0, 1790966322792) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c2e154c84f1cc5ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A microcomputer consists of _____?', '{"A":"CPU, Input/Output devices, and Storage","B":"Monitor, Mouse, and Keyboard","C":"Printer, Scanner, and Speakers","D":"Network, Software, and Internet"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A microcomputer typically consists of a central processing unit (CPU), input/output devices (like keyboard and monitor), and storage components (like hard drive or SSD).', 0, 0, 0, 1790966322792) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_efdc9ddefe06d39e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is not Antivirus software?', '{"A":"Oracle","B":"Avira","C":"Avast","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Avast and NAV are anti-virus software.***Symantec''s Norton Group launched Norton AntiVirus 1.0 (NAV) for PC and compatible computers.***Avast''s free antivirus software detects and blocks all types of malware in real-time to prevent them from infecting your computer.Kaspersky, Norton, and Avast are anti-virus software.***Linux is an operating system not an anti-virusanti virus Oracle is not an anti-virus software.AGM 09-2-2023', 0, 0, 0, 1790966322792) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_84e3b652f76e9970', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The computer process both analog and digital signal is ______?', '{"A":"Hybrid","B":"Analogue","C":"Digital","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The computer that processes both analog and digital signal is called hybrid computer.Hybrid computers are computers that exhibit features of analog computers and digital computers.The digital component normally serves as the controller and provides logical and numerical operations,while the analog component often serves as a solver of differential equations and other mathematically complex problems.', 0, 0, 0, 1790966322792) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bf07463241b0b3db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The term ‘Computer’ is derived from _____?', '{"A":"Latin","B":"French","C":"Arabic","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Derived from: computare Means: “to calculate”, “to count”, “to sum up” or “to think together”. ********', 0, 0, 0, 1790966322792) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2ff912ca2f78b86a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Duplication of data in multiple files is called _____?', '{"A":"Data Redundancy","B":"Data Dependence","C":"Data Inconsistency","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Data Redundancy refers to the duplication of the same data in multiple files or locations within a database or file system. This can lead to inefficiency and wasted storage.', 0, 0, 0, 1790966322792) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b4c02c835c48a0b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The basic operations performed by a computer are?', '{"A":"Arithmetic operation","B":"Logical operation","C":"Storage and relative","D":"All the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The basic operations performed by a computer are arithmetic operations, logical operations and storage and relative functions. Basically computer does 5 basic operations that are input, output, process,storing and controlling.', 0, 0, 0, 1790966322792) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d8211ff197e743dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A light sensitive device that converts drawing, printed text or other images into digital form is called?', '{"A":"Keyboard","B":"Scanner","C":"OMR","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scanner: Converts physical images/text into digital form.Uses light: Detects and captures the image.Output: Digital image or document.Last updated by NA ON 16-09-2026', 0, 0, 0, 1790966322792) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_da2eb2dcd34cc912', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A cell is defined as _____?', '{"A":"The intersection of a column and a row","B":"An input box","C":"a rectangular marker","D":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cell is the basic structural, functional, and biological unit of all known organisms.', 0, 0, 0, 1790966322871) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0aec9ea53553e6fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Who is pioneered in developing modern computer?', '{"A":"Dauglas Englebert","B":"Steve Jobes","C":"Bill Gates","D":"Charles Babbage"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation English mathematician and inventor Charles Babbage is often called the father of computers.Because he introduced the basic ideas that nearly all modern computers rely on.Babbage started designing an analytical engine in 1830, which could be programmed to perform calculations using punched cards.', 0, 0, 0, 1790966322871) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3a93f96c4410f7c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '1 Kilo Bytes (KB) = ___ bytes.', '{"A":"1000","B":"1024","C":"1032","D":"1036"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 byte equals 8 bits.Additional Information1024 Bytes = 1 Kilobyte (KB)1024 Kilobytes = 1 Megabyte (MB)1024 Megabytes = 1 Gigabyte (GB)1024 Gigabytes = 1 Terabyte (TB)', 0, 0, 0, 1790966322871) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c7f0986bee3fc067', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which function displays row data in a column and column data in a row?', '{"A":"Index","B":"Rows","C":"Transpose","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Transpose() function in MS Excel, helps to interchange the values of rows to columns and vice versa.It function returns a vertical range of cells as a horizontal range.', 0, 0, 0, 1790966322871) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8ee558b22589bc98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Headers and footers can include text and graphics, as well as the _____?', '{"A":"Current time","B":"Current date","C":"Page number","D":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Headers and FootersContents:Can include text, graphics, current time, current date, page numbers, and revision numbers.Placement:Headers: Appear at the top of the document page.Footers: Appear at the bottom of the document page.Purpose:Enhance document organization and provide essential details like dates or page numbers.', 0, 0, 0, 1790966322871) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_212d8ffe0a14a12d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A ________ contains buttons, boxes, and menus that allow tasks to be performed more quickly than using the menu bar.', '{"A":"Toolbar","B":"Format bar","C":"Status bar","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A toolbar contains buttons, boxes, and menus that allow users to perform tasks more quickly than using the menu bar. Toolbars are graphical elements that provide quick access to frequently used commands.', 0, 0, 0, 1790966322871) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_82206622d8388623', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The ______ program compresses large files into a smaller file.', '{"A":"WinShrink program","B":"WinZip program","C":"WinStyle program","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation WinZip first time-released in April 1991 as a graphical user interface (GUI) front-end for PKZIP. WinZip archiver and compress the large size file.', 0, 0, 0, 1790966322871) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_10de2a3351e8fc7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In Microsoft World which key is used to select entire text?', '{"A":"CTRL + T","B":"CTRL + U","C":"CTRL + Z","D":"CTRL + A"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + A use for select all.Ctrl + B use for bold selection.Ctrl + C use for Copy selected text.Ctrl + X use for Cut selected text.Ctrl + N use for Open new document.ND23-6-2023', 0, 0, 0, 1790966322872) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f7400e7c5f1c3277', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To stop a slideshow in MS Power point which of the following option a correct?', '{"A":"Press Escape","B":"Press F2","C":"Press CTRL","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To stop a slideshow in MS PowerPoint, you can press the Esc key on your keyboard.You can also right-click and select End Show. Additional information:F5: Starts the slide showCtrl+P: Prints the presentationCtrl+S: Saves the presentationShift+F5: Starts a presentation from the current slide', 0, 0, 0, 1790966322958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_93728fc331cb7ef3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Layout of handout defines _____?', '{"A":"Handout slave","B":"Handout master","C":"Handout slave","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The layout of a handout in PowerPoint is defined by the Handout Master.It allows customization of the appearance and arrangement of slides in printed handouts.', 0, 0, 0, 1790966322958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_91dad4a2d97638ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Bill Gates is the creator/founder of ______?', '{"A":"Yahoo","B":"Google","C":"Facebook","D":"Microsoft"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bill Gates is the co-founder of Microsoft and philanthropist.Bill Gates belongs to USA.Bill Gates was conferred upon Hilal-e-Pakistan on February 17, 2022', 0, 0, 0, 1790966322958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d2b2efdaf8589c56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A computer mainly consists of electronic _____?', '{"A":"Circuits","B":"Chips","C":"Device","D":"Parts"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer mainly consists of electronic circuits.They include integrated circuits (chips) and other components that enable the processing and transmission of data.', 0, 0, 0, 1790966322958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b9628de8108904f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Programs written to make computer function in a Desire way are called?', '{"A":"Software","B":"Hardware","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Software is a set of computer programs and associated documentation and data. This is in contrast to hardware, from which the system is built and which actually performs the work.', 0, 0, 0, 1790966322958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_26efeefd1a3a6fda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Google is a _____?', '{"A":"Search engine","B":"Number in Math","C":"Directory of images","D":"Chat service on the web"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Google, a US multinational technology companyGoogle is a type of search engine operating since 1997Google was founded in the year: September 4, 1998The Headquarters of Google is located in the city: of CaliforniaSergen Brin & Larry Page is the founder of GoogleSergey Brin is the real owner of GoogleParent organization: Alphabet Inc.ND07-3-2023', 0, 0, 0, 1790966322959) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f149cf6e1bb8630d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Who is the founder of Wiki Leaks?', '{"A":"Julian Assange","B":"Charles Babbage","C":"Steve Jobs","D":"Bill Gates"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Julian Paul Assange is an Australian editor, publisher, and activist who founded WikiLeaks in 2006.WikiLeaks came to international attention in 2010 when it published a series of leaks provided by U.S. Army intelligence analyst Chelsea Manning.', 0, 0, 0, 1790966322959) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_94e1b2cec90daee9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A user interface that is easy to use is considered to be _____?', '{"A":"User happy","B":"User simple","C":"User friendly","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A user interface that is easy to use is considered to be user friendly...A GUI (user interface design guidelines) is considered to be more user-friendly than a text-based command-line interface.such as MS-DOS, or the shell of Unix-like operating systems.**The user interface (UI) is the point of human-computer interaction and communication in a device. The user interface (UI) includes display screens, keyboards, a mouse and the appearance of a desktop.', 0, 0, 0, 1790966322959) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d5eae9599680f1d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A computer cannot do anything without _______?', '{"A":"Memory","B":"Keyboard","C":"Program","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A program is a set of instructions that a computer follows in order to perform a specific task.A computer programmer writes programs using a programming language.', 0, 0, 0, 1790966323049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e1f3cd7e39248223', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'From which of these menus can we access a text box Picture Chart Etc?', '{"A":"View","B":"Insert","C":"File","D":"Picture"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790966323049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d088713f46592e95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '_______ displays the content of active cell?', '{"A":"Row headings","B":"Name box","C":"Formula bar","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The formula bar displays the content of the active cell in MS Excel.The formula bar can be used to edit the content of any cell and can be expanded to show multiple lines for the same formula.Additional Information The name box in the worksheet displays the address of the selected cell.The title bar displays the title of the window and It includes the close, minimize, and maximize buttons.An active cell refers to a cell in an Excel spreadsheet that is currently selected by clicking the mouse pointer or keyboard keys.', 0, 0, 0, 1790966323049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f6adeec06bb60fb7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The list of coded instructions is called?', '{"A":"Computer program","B":"Algorithm","C":"Flowchart","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The list of coded instructions is called a Computer program.A computer program is a sequence or set of instructions in a programming language for a computer to execute.**agm.04.03.23', 0, 0, 0, 1790966323049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_db8d73e31f69e5e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which one of the following is the most powerful computer?', '{"A":"Personal Computer","B":"Super Computer","C":"Mobile Computer","D":"Power Computer"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Supercomputers were introduced in the 1960s as the world''s most advanced computer.A supercomputer is a powerful computer that can process a large amount of data and computation very quickly.Supercomputers perform immense amounts of mathematical calculations.Super Computers are also known as Number Crunching.Supercomputers are used for areas related to:ScienceEngineeringEducationDefenseAerospace', 0, 0, 0, 1790966323049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7171da1321f891f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Borders can be applied to _______?', '{"A":"Paragraph","B":"Text","C":"Cells","D":"All of above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Text: Borders can be applied to words, lines, or paragraphs in MS Word.Cells: Used in Excel to highlight or separate cell ranges.Pages: Borders can frame individual pages in MS Word.Tables: Add borders around tables for better structure.Pictures: Borders enhance images in MS Word.', 0, 0, 0, 1790966323049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_824e1302cc40c194', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How do you select an entire column?', '{"A":"Select Edit > Select > Column from the menu","B":"Click the column heading letter","C":"Hold down the shift key as you click anywhere in the column","D":"Hold down the Ctrl key as you click anywhere in the column"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To select an entire column in MS-EXCEL:Click the column heading letter.Press CTRL + Space Bar key.', 0, 0, 0, 1790966323049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6b6c938f6b624b0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is a database?', '{"A":"Consist of many different files linked with each other for the retrieval of information","B":"consists of integers","C":"Consists of Alphanumeric characters","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is defined as an organized collection of data or information for easy access, updating, and management in a computer.*********RY 13-12-202', 0, 0, 0, 1790966323049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_14458faba290bc1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A character that is raised and smaller above the baseline is known as ____?', '{"A":"Raised","B":"Superscript","C":"Outlined","D":"Subscript"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Superscript is a character that is set slightly above the normal line.A superscript is a number, figure, symbol, or indicator that is smaller than the normal line of type and is set slightly above it.ND11-2-2023ND4-4-20234AGM 02.05.2023', 0, 0, 0, 1790966323153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bdb0d6ebfe3e756d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In an Excel sheet the active cell is indicated by ______?', '{"A":"A dotted border","B":"A dark wide border","C":"A blinking border","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In an Excel worksheet, the active cell is indicated by a dark, wide border.The active cell is the cell that is currently selected and receives user interaction.It is the cell that you type into when you begin working on a spreadsheet.You can select any cell as the active cell by clicking on it.', 0, 0, 0, 1790966323153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b3517723e4a833fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'You can use the format painter multiple times before you turn it off by ____?', '{"A":"You can use the format painter button on ly one time when you click it","B":"Double clicking the format painter button","C":"Pressing the Ctrl key and clicking the format painter button","D":"Pressing the Alt key and clicking the format painter button"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We can use the format painter multiple times before we turn it off by double clicking the format painter button.', 0, 0, 0, 1790966323153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f104360e313744f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is a Light Pen?', '{"A":"Mechanical Input device","B":"Optical input device","C":"Electronic input device","D":"Optical output device","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Light pen is an optical input device.A light pen is a computer input device in the form of a light-sensitive wand used in conjunction with a computer''s cathode-ray tube (CRT) display.', 0, 0, 0, 1790966323153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b8ab7c3114f3cc7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A/an _____ appearing on a webpage opens another document which clicked?', '{"A":"Anchor","B":"Hyperlink","C":"URL","D":"Reference"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Hyperlink appearing on a webpage opens another document that is clicked.In computing, a hyperlink, or simply a link, is a reference to data that the user can follow by clicking or tapping.ND7-5-2023', 0, 0, 0, 1790966323153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3fab343138e220c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following helps to reduce spelling errors in a document being typed?', '{"A":"Auto Correct","B":"Auto Format","C":"Smart Tags","D":"Auto Text"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AutoCorrect helps to reduce spelling errors in a document by automatically correcting misspelled words as you type.AutoCorrect is a software feature commonly found in word processing programs, such as Microsoft Word.', 0, 0, 0, 1790966323153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a7a59df9b50ee20c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'When you insert a comment in a document, the comment appears in a ________?', '{"A":"New window","B":"Sidebar","C":"Balloon","D":"Sticky note icon bar"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft Word, when you insert a comment in a document, it appears in a "Balloon" on the side of the document.This allows the comment to be easily seen without disrupting the main text.Shortcut key to add a comment: Alt + ctrl + M', 0, 0, 0, 1790966323153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7212ec74794f5a71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In Microsoft Window 7, _______ can give you information about weather.', '{"A":"File","B":"Window explorer","C":"Gadgets","D":"Both A and C"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft Windows 7, Gadgets are small applications that can display information.Such as the weather, time, and system performance on your desktop.They provide quick access to data without needing to open a full application', 0, 0, 0, 1790966323153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ee2fb1917409781c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which type of mode takes place in both the directions at the same time?', '{"A":"Half duplex mode","B":"Full duplex mode","C":"Simplex mode","D":"Both A and B"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full duplex mode allows communication in both directions simultaneously.In contrast, half duplex mode permits communication in both directions, but not at the same timeSimplex mode allows communication only in one direction.', 0, 0, 0, 1790966323237) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a368d07de705da37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which is the largest hardware company of computers?', '{"A":"Dell","B":"HP","C":"IBM","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to the options, B is correct; the largest computer hardware company is HP (Hewlett-Packard). Otherwise The largest computer hardware company in the world, by market capitalization, is Apple Inc.', 0, 0, 0, 1790966323237) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3fcb0cc0ae22cfdf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following files have an ''mpg'' extension?', '{"A":"Audio","B":"Image","C":"Video","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation .mpg is a file extension for video files compressed using the MPEG (Moving Picture Experts Group) standard.It is commonly used for digital video distribution due to its efficient compression while maintaining good video quality.Variants of the format include MPEG-1 (used in CDs) and MPEG-2 (used in DVDs and broadcasting).', 0, 0, 0, 1790966323237) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_95316add694c8cbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which object is the output of the database application?', '{"A":"Report","B":"Table","C":"Form","D":"Query"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A report is a database application''s output that presents data in a readable, formatted format.It summarizes and analyzes data from tables or queries.This makes the information easy for users to interpret.', 0, 0, 0, 1790966323237) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d3d782c1dc7c237e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To move to the previous cell in a table inserted in a document, press?', '{"A":"Backspace","B":"Shift + Tab","C":"Alt + Tab","D":"The Tab Key"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To move to the previous cell in a table, press Shift + Tab.This allows you to navigate backward within the table.To move to the next cell, press The Tab Key.This advances the cursor to the following cell in the table.', 0, 0, 0, 1790966323237) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_97093b7d14cefa45', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Twitter is a ______?', '{"A":"Search engine","B":"E-mail service","C":"Social network service","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Twitter is a social network service that allows users to share short messages, known as tweets, and interact with others globally.Twitter was created in March 2006 by Jack Dorsey, Noah Glass, Biz Stone, and Evan Williams and launched in July of that year.', 0, 0, 0, 1790966323237) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6d7afc00381e872a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following Search Engine is developed by Microsoft?', '{"A":"Bing","B":"Yahoo","C":"Alta Vista","D":"Google"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bing is a search engine developed by Microsoft.It is launched in 2009 as a successor to its previous search engines like MSN Search and Live Search.', 0, 0, 0, 1790966323237) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a433ab901ef0d1c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following options is not located in the Page Setup dialog box?', '{"A":"Page Break Preview","B":"Page Orientation","C":"Margins","D":"Headers and Footers"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ****RY17-012-23', 0, 0, 0, 1790966323237) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d1f825999155cccc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'When two people collaborate on an online document at the same time they are collaborating?', '{"A":"Synchronously","B":"In Cloud Edit","C":"By Tracking","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When two people collaborate on an online document at the same time, they are collaborating synchronously. "Synchronously" means happening at the same time, which is what is happening when multiple users are editing a document simultaneously online.', 0, 0, 0, 1790966323315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_943af35ac5dc6d04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'An electronic path that sends signals from one part of computer to another is ______?', '{"A":"Serial Port","B":"Bus","C":"Modem","D":"Logic Gate","E":"RAM"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bus: a high-speed internal connection.A bus is an electronic path that sends signals from one part of a computer to another.It allowing different components to communicate with each other.', 0, 0, 0, 1790966323315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eb71fd6341ce037f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '"JPG" extension refers usually to ____?', '{"A":"A system file","B":"An animated movie file","C":"MS Encarta document","D":"An image file","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Image file formats are standardized means of organizing and storing digital images.FIA CBT VU PAPER 22-12-2021', 0, 0, 0, 1790966323315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fa38ff9ec5791426', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following commands is used to move selected text to another part of a document?', '{"A":"Drag-and-Drop","B":"Copy-and-Paste","C":"Find-and-Replace","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Drag-and-Drop command is used to move selected text to another part of a document.This method allows you to reposition text by dragging it to a new location.', 0, 0, 0, 1790966323315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2c0a6742c2c470ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A Word template stores common documents _____?', '{"A":"Content","B":"Style","C":"Structure","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Word template stores the structure of a document.Such as predefined formatting, styles, and layout, to maintain consistency across similar documents.It helps in creating documents with the same framework.', 0, 0, 0, 1790966323315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1a9d5340231947f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Word has web authoring tools allow you to incorporate ___ on Web pages.', '{"A":"Bullets","B":"Hyperlinks","C":"Sounds","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Word has Web authoring tools allow you to incorporate Bullets, Hyperlinks, Sound on Web pages.', 0, 0, 0, 1790966323315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_aa81440e39c9510b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which devices are used to backup data?', '{"A":"Floppy Disk","B":"Hard Disk","C":"CD","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When you decide to back up your data, the first thing to choose is the storage device or backup media to use for your backups. There are many data storage devices in the market such as tape drives, optical drives, SD cards, hard disk drives and cloud storage services.', 0, 0, 0, 1790966323315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_31e3048dd8c9c79c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which key is used to move the cursor one word right?', '{"A":"Ctrl + right arrow","B":"Ctrl + left arrow","C":"Ctrl + shift + right arrow","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + (Left arrow) -- Move one word to the left at a time. Ctrl + (Right arrow) -- Move one word to the right at a time.', 0, 0, 0, 1790966323315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_93c11321ee464ef8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'BCD code has how many bits?', '{"A":"2","B":"3","C":"4","D":"5"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Note that the BCD code is 12 bits long since each of the decimal digits is coded by four bits.', 0, 0, 0, 1790966323383) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ac94cd15cedd5d2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Gmail, Hotmail and Yahoo are _____?', '{"A":"E-mail server","B":"User server","C":"Email client","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Google Accounts come with 15 GB of storage that''s shared across Google Drive, Gmail, and Google Photos.Gmail, Hotmail, and Yahoo are examples of E-mail servers that manage and store users'' emails.It allowing them to send, receive, and organize messages over the internet.', 0, 0, 0, 1790966323384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d14d882680753728', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How many generations of computer has?', '{"A":"1","B":"3","C":"4","D":"5"}', 'D', NULL, 0, 0, 0, 1790966323384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5920a35680dcb739', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Excel is a ______ program developed by Microsoft.', '{"A":"Spreadsheet","B":"Document","C":"Data management","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790966323384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f47f869891ff9cc5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'We can use _____ to convert Word in to PDF.', '{"A":"Save","B":"New","C":"Print","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The "Print" option can be used to convert a Word document to PDF by selecting "Microsoft Print to PDF" as the printer, enabling easy conversion.', 0, 0, 0, 1790966323384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_03e170efdd05d9d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'You can check the conditions against _____ when applying conditional formatting', '{"A":"Cell value","B":"Formula","C":"Both of above","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When applying conditional formatting in spreadsheet software like Microsoft Excel, Google Sheets, or LibreOffice Calc, you can check conditions against:Cell value: You can specify a condition based on the value in a cell, such as "greater than", "less than", "equal to", etc.Formula: You can also specify a condition based on a formula, which can include references to other cells, functions, and operators.', 0, 0, 0, 1790966323384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_854a5a6051e82981', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Functional dependencies are the types of constraints that are based on _____?', '{"A":"Key","B":"Key revisited","C":"Super set key","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The functional dependency is a relationship that exists between two attributes. It typically exists between the primary key and non-key attribute within a table.', 0, 0, 0, 1790966323384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6f7a5f82b539b595', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'An application program that allows a user to set page number and spell check of a document is known as ______?', '{"A":"Notepad","B":"Wordpad","C":"Word processor","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A word processor is an application program that allows users to create, edit, and print documents. It offers various features, including:Setting page numbersSpell checkingText formatting (e.g., font styles, sizes, and colors)Alignment and justificationCut, copy, and paste functionsPrinting and saving documentsExamples of word processors include Microsoft Word, Google Docs, and LibreOffice Writer.', 0, 0, 0, 1790966323384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_320fe15cc3f546d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which one is the result of the output given by a computer?', '{"A":"Data","B":"Instruction","C":"Information","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Information is processed, organized, and structured data.It provides context for data and enables the decision-making process.The data and information are the output we receive for the input we provide to the computer.', 0, 0, 0, 1790966323459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2831e64f0e5ce9b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A collection of interrelated files in a computer is _____?', '{"A":"File manager","B":"Field","C":"Database","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A database is an organized collection of structured information, or data, typically stored electronically in a computer system. A database is usually controlled by a database management system (DBMS).', 0, 0, 0, 1790966323459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b21980cf52ff76cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What are hardware components in computing?', '{"A":"Software programs","B":"Logical operations","C":"Physical parts","D":"Virtual applications"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hardware components in computing are the physical parts of a computer system.Such as the motherboard, CPU, and memory.They are tangible elements that you can physically touch and see.', 0, 0, 0, 1790966323459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_db582f0b55f39649', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '1000 Million bytes is equal to ____?', '{"A":"1 GB","B":"5 GB","C":"6 GB","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1000 million bytes is equal to 1 billion bytes, which is equivalent to 1 gigabyte (GB).To break it down:1 million bytes = 1 megabyte (MB)1000 million bytes = 1000 megabytes (MB)1000 megabytes (MB) = 1 gigabyte (GB)', 0, 0, 0, 1790966323459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f1a2ef7f416e81f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'When you insert an Excel file into a Word document. The data are _____?', '{"A":"Hyperlinked","B":"Linked","C":"Embedded","D":"Placed in a row table"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When we insert an excel file into a word document and keep the source file linkage when data is updated in source file update data in liked file also. The data are Linked. In Embedded objects file become part of document and does not get updated when source file is updated.', 0, 0, 0, 1790966323459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5069523c310700f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Window 9 and Window 10 are known as _____?', '{"A":"Type of computer","B":"Utility software","C":"Application software","D":"Operating system"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NOTE: There was no version of Microsoft Windows officially launched as "Windows 9." BUT ACCORDING TO THE ASKED QUESTION WE SELECTED OPTION D. Microsoft skipped Windows 9, going directly from Windows 8.1 to Windows 10. Windows 9 and Windows 10 are both operating systems. Specifically, versions of Microsoft Windows. Windows 10 is the more recent version, And it is part of the Windows NT family.', 0, 0, 0, 1790966323459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_db186d3cb307ee7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'HTML is used for creating _____?', '{"A":"Web Server","B":"Webpages","C":"Websites","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTML is used to create a web page****HTML is an abbreviation for Hypertext Markup Language (HTML) is the standard markup language for documents designed to be displayed in a web browser.***************Vu FIA CBT PAPER 15-12-2021', 0, 0, 0, 1790966323459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6da859fd862a66e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which operation you will perform if you need to move a block of text?', '{"A":"Copy and paste","B":"Cut and paste","C":"Paste and cut","D":"Paste and delete"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cut Select Cut or press Ctrl + X.Paste Select Paste or press Ctrl + V.Copy Select Copy or press Ctrl + C.', 0, 0, 0, 1790966323459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_59dff526577a7f50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which software is used to access webpages?', '{"A":"Browser","B":"URL","C":"IP","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The software to view HTML documents as a Web page is called a Web browser. Popular ones are Google Chrome, Apple''s Safari, Mozilla''s Firefox, Opera and Microsoft''s much hated Internet Explorer.', 0, 0, 0, 1790966323519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_938ff016002e232c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'MAC is an example of _______?', '{"A":"Operating system","B":"System software","C":"Application software","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MAC (Macintosh Operating System) is an operating system developed by Apple Inc. for its Macintosh computers.It manages hardware resources, provides common services to applications, and acts as an interface between user and hardware.', 0, 0, 0, 1790966323519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e8b4d2607575cfd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which area in an excel window allows entering values and formulas?', '{"A":"Menu Bar","B":"Title Bar","C":"Formula Bar","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Formula Bar area in an Excel window allows entering values and formulas. It is labeled with a function symbol (fx). By clicking the Formula Bar, or when you type an equal (=) symbol in a cell, the Formula Bar will activate.ND29-5-2023', 0, 0, 0, 1790966323519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7bfd60a1be4eb6d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Landscape and Orientation come under which category?', '{"A":"Page Design","B":"Page Layout","C":"Page Setup","D":"Page Orientation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Landscape and portrait are types of page orientation, which is the direction in which a document is displayed or printed. OrientationDescriptionPortraitVertical, with the height of the page greater than the widthLandscapeHorizontal, with the width of the page greater than the height', 0, 0, 0, 1790966323519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_df47d19544ef4da1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is a Database Application?', '{"A":"MS Access","B":"MS Excel","C":"MS PowerPoint","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Access is a database application used to store, manage, and manipulate data.It allows for the creation of databases, tables, queries, and reports.', 0, 0, 0, 1790966323519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_13347b25a54f7ef6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In Excel a small square in the lower-right corner of a selected cell is called?', '{"A":"Fill Handle","B":"Fill Pointer","C":"Flash Fill","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Excel, a small square in the lower-right corner of a selected cell is called the fill handle.It is used to quickly copy or fill data into adjacent cells by dragging the fill handle.', 0, 0, 0, 1790966323519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0d6604eb6684d681', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '___________ is used to create layout or formatting changes in a portion of a document.', '{"A":"Section Break","B":"Page Break","C":"Next Page Break","D":"Text Wrapping"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A section break is used to create layout or formatting changes in a portion of a document.It allows for different formatting (like headers, footers, or column settings) in different sections without affecting the entire document.', 0, 0, 0, 1790966323519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c3cccefcf02e8e0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '____ feature is used to make selected sentence to All Capital letters and All small letters.', '{"A":"Change sentence","B":"Change latter","C":"Change case","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Change Case feature converts selected text to all capital or small letters, or toggles cases.Use Shift + F3 as a shortcut.To apply, select the text, then go to Home > Change case, and choose the desired option, such as Sentence case or lowercase.', 0, 0, 0, 1790966323519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cb800614d660abc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A _________ identifies a location or a selection of text that you name and identify for future reference.', '{"A":"Bookmark","B":"Header","C":"Page number","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A bookmark identifies a location or a selection of text that you name and identify for future reference.It allows you to mark a specific spot in a document or webpage and easily return to it later.', 0, 0, 0, 1790966323584) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c341eddb62fa4fa8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A set of instructions that operates various parts of the Computer Hardware is called?', '{"A":"URL","B":"Hardware Manager","C":"Device","D":"Software"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A set of instructions that operates various parts of the Computer Hardware is called Software**ND10-1-2023**** RY18012023', 0, 0, 0, 1790966323584) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_66da9354fb6505e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following terms refers to the ability of a computer to automatically configure a new hardware component that is added to it?', '{"A":"Formatting","B":"Multiprocessing","C":"Multi programming","D":"Plug and play"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plug and play (PnP) allows a computer to automatically configure new hardware components upon connection.This simplifies device installation, with resources like USB and IEEE 1394 allocated at boot time.', 0, 0, 0, 1790966323584) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cb3143b63ad633ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Cursor is a ______?', '{"A":"Thin Blinking Line","B":"Pixel","C":"Pointing Device","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A text cursor is the thin, blinking line on your screen that indicates exactly where your next typed character or action will appear', 0, 0, 0, 1790966323584) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_babb688cef3a0872', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which short cut key is used to save a file with two names?', '{"A":"Save as","B":"Copy","C":"Paste","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Save as" allows you to save a file under a different name, keeping the original file intact while creating a new version.The shortcut for "Save as" is typically F12 in MS Office applications.Ctrl + S save the open document. Like Shift+F12.', 0, 0, 0, 1790966323584) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ba8e4888c5c102d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The best way to define Virtualization in cloud computing is?', '{"A":"Virtualization enables simulating compute, network, and storage service platforms from the underlying virtual hardware","B":"Virtualization enables abstracting compute, network, and storage service platforms from the underlying physical hardware","C":"Virtualization enables realization of compute, network, and storage service platforms from the underlying virtual hardware","D":"Virtualization enables emulating compute, network, and storage service platforms from the underlying virtual hardware"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Virtualization enables abstracting compute, network, and storage service platforms from the underlying physical hardware.Virtualization in cloud computing allows for the creation of a layer of abstraction between the physical hardware and the virtual resources, enabling multiple virtual machines (VMs) to run on a single physical server. This abstraction enables:Multiple VMs to share the same physical hardwareVMs to be isolated from each otherVMs to be easily moved between physical serversEfficient use of physical hardware resources', 0, 0, 0, 1790966323584) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b9c46644b0a19ef5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '____ used to display data.', '{"A":"Storage devices","B":"Communication devices","C":"Input devices","D":"Output devices"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Output devices are used to display data or information from a computer or other electronic device. Examples of output devices include:Monitors (screens)PrintersPlottersSpeakersHeadphonesProjectors', 0, 0, 0, 1790966323584) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3f1fad2510b21b9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Google+ is another alternative to which of the following site?', '{"A":"Bing","B":"Facebook","C":"Amazon","D":"Flicker"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Google+ was a social networking platform launched by Google in 2011 as an alternative to Facebook.It aiming to connect users through circles and communities.', 0, 0, 0, 1790966323584) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4c64485fbf18f6c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'You can detect spelling and grammar errors by ____?', '{"A":"Press Shift + F7","B":"Press Alt + F7","C":"Press Ctrl + F7","D":"Press F7"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You can detect spelling and grammar errors by press F7***F7 is commonly used to spell check and grammar check a document in Microsoft programs such as Microsoft Word, Outlook, etc.**** RY18012023SH4-9-2023', 0, 0, 0, 1790966323670) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ae8fa9cbc95a103a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In a Word document this describes the size, weight, and spacing of a character?', '{"A":"Typeface","B":"Typography","C":"Font","D":"Points"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A font in a Word document refers to the specific style and appearance of text.Including the size, weight (bold, regular), and spacing of characters.It determines how the text looks in terms of its design.', 0, 0, 0, 1790966323670) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_40229ba0d0a14ddf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'When using computers which of the following involves reducing the electricity consumed or environmental waste generated?', '{"A":"Violation","B":"Manufacturing","C":"Green Computing","D":"Cyclic Process"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Green Computing refers to practices and technologies that reduce the electricity consumed and environmental waste generated by computers and related devices.It involves designing, manufacturing, and disposing of computers and related products in an environmentally friendly way.', 0, 0, 0, 1790966323670) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2b2ea060ae5dbc0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Amazon is a best example of _____ site.', '{"A":"Entertainment","B":"Blogging","C":"E-Commerce","D":"Social Networking"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amazon is a prime example of an E-Commerce website.It providing a platform for online shopping, product reviews, and customer ratings.It allows users to browse and purchase products from various categories.', 0, 0, 0, 1790966323670) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_147917dba81e95cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A __________ is a data communication system within a building, plant, or campus or between nearby buildings.', '{"A":"MAN","B":"LAN","C":"WAN","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation *LAN is a data communication system within a building, plant or campus or between nearly building. *A MAN is a data communication system covering an area the size of a town or city.*A WAN is *A Wan is a data Communication system spanning states, countries or whole world.', 0, 0, 0, 1790966323670) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0cb7b8446a9d0263', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In a computer system _______ work in the similar fashion as files in folders is ''physically maintained'' offices.', '{"A":"Documents","B":"Filing","C":"Directories","D":"Recycle bin"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a computer system, directories (also known as folders) work in a similar fashion as files in physical offices.Just as files are stored in folders or cabinets in an office, directories in a computer system store and organize files and subdirectories.', 0, 0, 0, 1790966323670) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_26e10c3111a8ddb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Sergen Brin and Larry Page are the founder of ____?', '{"A":"Twitter","B":"Facebook","C":"YouTube","D":"Google","E":"Instagram"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Google, a US multinational technology companyFoundedSeptember 4, 1998FounderSergen Brin & Larry PageHeadquartersCalifornia, USAParent CompanyAlphabet IncGoogleMost visited Website in World', 0, 0, 0, 1790966323671) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b8b7de94c03b51db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To create a form wizard, we use how many tables?', '{"A":"5","B":"4","C":"3","D":"2"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When creating a form wizard, these four tables are commonly used:Forms table: Stores details about each form.Fields table: Stores data about each field in the form.Submissions table: Stores user-submitted data.Steps table: Tracks the steps in multi-step form wizards.This structure helps in managing complex, multi-step forms effectively.', 0, 0, 0, 1790966323671) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e32cfffec9187fb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'F1 to F12 keys are called ____ ?', '{"A":"Fun Keys","B":"Numeric keys","C":"Function keys","D":"Alphabetic keys"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A function the key is one of the "F" keys along the top of a computer keyboard. On some keyboards, these range from F1 to F12, while others have function keys ranging from F1 to F9.****RY 16-01-2023', 0, 0, 0, 1790966323750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4b0469865b70c46c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '___________ is used to close and save documents.', '{"A":"Crtl + B","B":"Crtl + W","C":"Crtl + O","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Ctrl + W command is used to close a document in MS Word Ctrl+W is a shortcut key most often used to close a program, window, tab, or document.ND29-5-2023', 0, 0, 0, 1790966323750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_34e4c081f7ad02f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'You can edit existing Excel data by pressing the _____?', '{"A":"F1 Key","B":"F3 Key","C":"F2 Key","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Click the cell that contains the data that you want to edit, and then press F2. This starts Edit mode and positions the cursor at the end of the cell contents.F1 to F12 keys are known as function keys.**** RY18012023', 0, 0, 0, 1790966323750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e05f72445e7f7b2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the name of the form used to input chart values?', '{"A":"Microsoft Excel","B":"Microsoft graph","C":"Datasheet","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Database is the name of the form used to input chart values. A database is information that is set up for easy access, management and updating.', 0, 0, 0, 1790966323750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_990981b90309de1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The printed output from a computer is called?', '{"A":"Hard Copy","B":"Copy","C":"Soft Copy","D":"Paper"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A hard copy (or "hardcopy") is a printed copy of information from a computer. Sometimes referred to as a printout, a hard copy is so-called because it exists as a physical object***The printed output is produced by a printer.', 0, 0, 0, 1790966323750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e88f846bb41327f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '''GIF'' is an extension of which type of file?', '{"A":"Video","B":"Audio","C":"Image","D":"Word"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GIF extension is typically used for image files that use the Graphics Interchange Format (GIF).', 0, 0, 0, 1790966323750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_583ac6788fc9b83a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The tool used to find a similar word in document is called ______?', '{"A":"Finder","B":"Find and replace","C":"Thesaurus","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A thesaurus or synonym dictionary is a reference work for finding synonyms and sometimes antonyms of words.', 0, 0, 0, 1790966323750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7f1949ce103afba6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Cell entry "July 16, 2016" will be considered a _____ by Excel sheet.', '{"A":"Label","B":"Value","C":"Formula","D":"Text string"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cell entry "July 16, 2016" will be considered a value by Excel sheet.In Excel, "July 16, 2016" is recognized as a date, which is stored as a serial number.', 0, 0, 0, 1790966323750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5342b5523ba9cc5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The ______ also called the web, contains billions of documents.', '{"A":"Web portal","B":"HTFP","C":"World Wide Web","D":"Domain"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The World Wide Web is all the resources and users on the internet that are using the Hypertext Transfer Protocol (HTTP).World Wide Web was created by Timothy Berners Lee in 1989 in CERN in Geneva.', 0, 0, 0, 1790966323809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_777f5d5e3662316b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A commonly used graphic format for the web is ______?', '{"A":"Imp","B":"Bmp","C":"Text","D":"GIF"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The three most common file formats for graphics used on the web: JPG, GIF, and PNG.', 0, 0, 0, 1790966323809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_705a4eda59df03ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The device which converts instructions into the binary form that is understood by the computer and supply to the computer is known as?', '{"A":"Memory","B":"Output","C":"Automatic","D":"Input"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Input Unit converts the data, which the user enters into a language which the computer understands, i.e. it converts the data into binary format.The Output Unit is responsible for giving the results in user- understandable format.', 0, 0, 0, 1790966323809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7207fd455b6cf344', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following is enable you to make multiple changes in a document at once?', '{"A":"Find command","B":"Replace command","C":"Drag and drop","D":"Copy command"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In computing, replace is a command that is used to replace one or more existing computer files or add new files to a target directory. Files with a hidden or system attribute set cannot be replaced using replace. The command lists all files that are replaced.', 0, 0, 0, 1790966323809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c9b1bd36faea4492', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In word, the mailing list is known as the ______?', '{"A":"Data sheet","B":"Source","C":"Data source","D":"Sheet"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In word, the mailing list is known as the Data source.', 0, 0, 0, 1790966323809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2a2c2e19371d75ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following is not the part of standard office suite?', '{"A":"Word processor","B":"Data base","C":"Image editor","D":"File manager"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A file manager is used to organize and manage files and folders.It is part of the operating system, not an office suite.Additional informationDatabase - Microsoft Office AccessImage Editor - Microsoft Office Picture ManagerWord Processor - Microsoft Office WordLast update 0n 21-07-2026 by NA', 0, 0, 0, 1790966323809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_45c024ed47b56ade', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which one is an application software?', '{"A":"Windows","B":"Linux","C":"MS Excel","D":"DOS"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Excel is an application software, designed for tasks.Like creating spreadsheets, data analysis, and calculations.', 0, 0, 0, 1790966323809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a7563f16726781fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the most popular system of shorthand writing?', '{"A":"Sloan Duployan System","B":"Gregg''s System","C":"Pitman''s Shorthand","D":"Morse Code"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pitman''s Shorthand is the most popular system of shorthand writing.He is known for its efficiency and speed in capturing spoken words through phonetic symbols.It has been widely used for decades in various fields, especially in stenography.', 0, 0, 0, 1790966323809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_20e625fb39d5f267', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To delete a file without allowing it to store in recycle bin _____?', '{"A":"Press Delete key.","B":"Press Shift + Delete key","C":"Press Ctrl + Delete key","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To delete a file without allowing it to store in recycle bin Press the Shift + Delete key. ***Shift + Delete are used to delete the selected item permanently without placing the item in the Recycle Bin.', 0, 0, 0, 1790966323895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0201aecddd44e779', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'We can start the application from ____?', '{"A":"Log off","B":"Network place","C":"Recycle bin","D":"Run"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We can start the application from Run....Opening Windows applications can just launch directly from Run.', 0, 0, 0, 1790966323895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a69eef594fa07bfd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What do you mean by dialog box?', '{"A":"Group of options","B":"Interactive message box","C":"Set of controls","D":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dialog box means Group of options, Interactive message box, and Set of controls.**', 0, 0, 0, 1790966323895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e24440c500f7507d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The date and time displays on _______?', '{"A":"Task bar","B":"Status bar","C":"System tray","D":"Launch pad","E":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The time and date are displayed on the system tray.**The system tray (or "systray") is a section of the taskbars in the Microsoft Windows operating system (OS) user interface that provides easy access icons to the user''s most commonly used apps and displays the clock. A system tray is also available in other OSes such as Linux, Mac OS, Android, and iOS.', 0, 0, 0, 1790966323895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a7ea3eacb46210d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'When installing a peripheral you also usually need to install a _____?', '{"A":"Port","B":"Server","C":"Driver","D":"Password"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When installing a peripheral you also usually need to install a driver**A peripheral device is an internal or external device that connects directly to a computer or other digital device All peripheral devices connect with the motherboardND17-1-2023', 0, 0, 0, 1790966323895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f69be97b5fb2661a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is not of the merge process?', '{"A":"Preview the merge results","B":"Format a main document","C":"Edit a data source","D":"Identify the main document"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The merge process generally involves identifying the main document, formatting it, and previewing the results. Editing the data source is a separate task and not typically part of the merge process.****RY17-012-23', 0, 0, 0, 1790966323895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_57605abaaf05c77d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is referred by the term ‘Hypertext’?', '{"A":"That links a PC to server","B":"Text which is used between a PC and ISP","C":"Text which is secret","D":"Text that links to other information"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hypertext refers to text that links to other information.It allows users to navigate from one document to another via hyperlinks.It facilitating easy access to related content.', 0, 0, 0, 1790966323895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_01279bb5627c9e89', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A computer program consists of ______?', '{"A":"Only instructions","B":"Only data","C":"Both instructions and data","D":"Neither instructions nor data"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer program consists of Both instructions and data.Instructions are the commands that direct the computer to perform specific operations.Data represents the information that these instructions operate on.', 0, 0, 0, 1790966323895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2b34dfdcba6beca5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The device which provides display to user is?', '{"A":"CPU","B":"Printer","C":"Memory Unit","D":"Monitor"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The device that provides a display to the user is the Monitor.The monitor visually presents the output from the computer.It allowing users to see and interact with their data and applications.', 0, 0, 0, 1790966324002) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_404edbdd761cac06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which feature is used for monitoring all document changes?', '{"A":"Edit Document","B":"Monitor Change","C":"Track Change","D":"Track all"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Track Change feature is used for monitoring all document changesٹریک چینج فیچر تمام دستاویزات کی تبدیلیوں کی نگرانی کے لیے استعمال کیا جاتا ہے۔*****', 0, 0, 0, 1790966324002) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_748ac6a147177f8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'By default the cell content alignment is', '{"A":"Text right aligned  and numbers left alignment","B":"Left aligned","C":"Text left aligned and numbers right aligned","D":"Centrally aligned"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As a default in Microsoft Excel, text typed into a cell is aligned to the left border of the cell while numbers are aligned to the right.To align the text left, press Ctrl+L.To align the text right, press Ctrl+R.To center the text, press Ctrl+E.', 0, 0, 0, 1790966324002) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8baa75ea38548cef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The process of breaking down an instruction into a series of smaller steps that can be executed simultaneously is known as?', '{"A":"Pipelining","B":"Parallel processing","C":"Multithreading","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pipelining is the process of storing and prioritizing computer instructions that the processor executes.', 0, 0, 0, 1790966324002) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1a43e0401cd9b252', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the purpose of the system clock in a computer?', '{"A":"Control the execution speed of programs","B":"Measure the CPU''s Speed","C":"Synchronize the activities of various components","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Computers use an internal clock to synchronize all of their calculations.', 0, 0, 0, 1790966324002) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8e1bdf20aba9d517', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which technology is used to make web pages interactive and dynamic by updating parts of the page without a full page reload?', '{"A":"HTML","B":"CSS","C":"AJAX","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AJAX is a technique for creating fast and dynamic web pages.', 0, 0, 0, 1790966324002) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c5758326194459ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which type of join returns all rows from both tables, matching rows from the left table, and NULL values for non-matching rows from the right table?', '{"A":"INNER JOIN","B":"OUTER JOIN","C":"LEFT JOIN","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Left Join: Returns all rows from the left table and the matched rows from the right table. If there is no match, the result is NULL on the side of the right table.In SQL, the syntax for a left join would look like this:', 0, 0, 0, 1790966324002) ON CONFLICT(id) DO NOTHING;
