INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ea63e186e0ef718b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the purpose of CSS (Cascading Style Sheets) in web development?', '{"A":"Creating databases","B":"Styling and formatting web pages","C":"Managing server-side scripts","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790966324077) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_58917587936ca840', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What type of database model organizes data in a tree-like structure with parent and child relationships?', '{"A":"Hierarchical","B":"Relational","C":"Network","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A hierarchical database is a data model in which data is stored in the form of records and organized into a tree-like structure, or parent-child structure, in which one parent node can have many child nodes connected through links.', 0, 0, 0, 1790966324077) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d0d42a76faec89cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which networking device operates at the Data Link Layer of the OSI model and forwards data based on MAC address?', '{"A":"Router","B":"Hub","C":"Switch","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A network switch and a bridge operate at the Data Link Layer (Layer 2) of the OSI modelThey use Media Access Control (MAC) addresses to send data frames to specific devices on the same local network.Last updated 07-09-2026 by NA', 0, 0, 0, 1790966324077) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6e949dc454c62a63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Identify Software in Computer technology', '{"A":"Physical equipment","B":"Collection of programme","C":"Graphical representation","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation software is the programs and routines for a computer or this system material for an electronic tool which make it run. An example of software is Excel or home windows or iTunes. noun.', 0, 0, 0, 1790966324077) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f850455d06b2e749', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Servers are computers that provide resources to other computers connected to a___________?', '{"A":"Cell","B":"Network","C":"Mainframe","D":"Supercomputer","E":"Client"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A network is a collection of computers, servers, mainframes, network devices, peripherals, or other devices connected to allow data sharing. An example of a network is the Internet, which connects millions of people all over the world.A computer or device that provides resources and services to other systems connected to the same network is called a server.', 0, 0, 0, 1790966324077) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cb510ba50b4c9c19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Vacuum tubes have been replaced by _________?', '{"A":"Conductors","B":"Diodes","C":"Transistors","D":"None of these","E":"all of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation vacuum Tubes were replaced by Transistors. Second-generation computers emerged with the development of Transistors. The transistor was invented in 1947 by three scientists J. Bardeen, W.H Brattain and W. Shockley.ND16-3-2023ND5-07-2023', 0, 0, 0, 1790966324077) ON CONFLICT(id) DO NOTHING;
