INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ccf9d64ed116f279', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Short cut key to change font is?', '{"A":"ctrl+}","B":"ctrl+{","C":"Both","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Shift + F is the shortcut key for “Change the font" in MS Word.Open the Font dialog box to change the font. Ctrl+Shift+F.Increase the font size. Ctrl+Shift+>Decrease the font size. Ctrl+Shift+<Increase the font size by 1 point. Ctrl+]Decrease the font size by 1 point. Ctrl+[RK11.06.2023', 0, 0, 0, 1790966324166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d621480d155b61f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following is HTML tag', '{"A":"# and #","B":"{ and }","C":"! and ?","D":"< and >"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTML stands for HyperText Markup LanguageAll HTML tags must be enclosed within angular < > brackets.The correct sequence of HTML tags for starting a webpage is HTML, Head, Title, BodyWhich character is used to represent the closing of a tag in HTML /*******VU CBT FIA PAPER 30-12-2021,2023', 0, 0, 0, 1790966324166) ON CONFLICT(id) DO NOTHING;
