INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_78d21e05208a5446', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which key is used for Excel to select the whole column highlight?', '{"A":"Shift + space","B":"CTRL + space","C":"Alt + space","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To highlight a column, Ctrl+Space is used.Additional information:Shift + Space is used for row.Help in MS Excel: F1Display active cells in Excel: Shift+BackspaceCurrent date in Excel: Ctrl+;GO TO tab in Ms. Excel: F5 Column highlight: CTRL + spaceSUM formula in MS Excel: ALT + =New worksheet in Excel: Shift + F11Format numbers in comma format: Shift+1Last updated NA on 10-09-2026', 0, 0, 0, 1790966324261) ON CONFLICT(id) DO NOTHING;
