INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7300ba038772d83f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What are system software to facilitate editing of text and data?', '{"A":"MS Word","B":"Editors","C":"PowerPoint","D":"MS publisher"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Text Editors:Function:Primarily focus on editing text files, which can include source code, configuration files, or simple documents. Examples:Notepad (Windows): Notepad++ (Windows):BBEdit (macOS): vi/vim (Unix-like systems): nano (Unix-like systems): Features:Typically includes basic editing functions like inserting, deleting, copying, pasting, and searching/replacing text. ND7-5-2023', 0, 0, 0, 1790966324321) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_467fa8ac840c6022', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Microprocessors can be used to make:', '{"A":"Computers","B":"Digital Systems","C":"Calculators","D":"All of these","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microprocessors are used in many other electronic devices, including:Computers, Digital systems, Calculators***Microprocessors are used in many other electronic devices.Inventor of Microprocessors: Marcian E HoffMicroprocessors in 4th generation computer.ND7-5-2023', 0, 0, 0, 1790966324321) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_032dbc1852217a7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The Digital Computer operates on_____', '{"A":"Binary system","B":"Octal system","C":"Hexadecimal system","D":"Decimal system"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation John Vincent Atanasoff invented the first digital computer in 1930. The inventor of the first Digital Computer belonged to the country: USAJohn Vincent Atanasoff died in 1995.Digital computer:The Digital Computer operates on a Binary systemThe computer that processes both analog and digital signals is called a hybrid computer.ND7-5-2023', 0, 0, 0, 1790966324321) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ead5055079c25b75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'computer is free from tiresome and board room we call it', '{"A":"programmability","B":"versatility","C":"diligence","D":"reliability"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Deligance : A computer can perform hundreds of tasks or calculations with the same flexibility and accuracy. Computer will not feel tired.****AGM 07.5.23', 0, 0, 0, 1790966324321) ON CONFLICT(id) DO NOTHING;
