INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e9b81b78d3a1cf26', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The _____project allows access to the universe of online information using two simple user interface operations ?', '{"A":"World-Wide Web Worm","B":"World-Wide Web","C":"World-Wide Worm","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation World Wide Web (WWW)World-Wide Web Worm (WWWW)English scientist Tim Berners-Lee invented the World Wide Web in 1989.WWW Birth place CERN near Geneva, Switzerland.The browser was released for general public in August 1991.', 0, 0, 0, 1790966324396) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6198641b89e933e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What do you call a single point on a computer screen', '{"A":"Cell","B":"Element","C":"Pixel","D":"Point"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pixel is the smallest addressable point on a computer screen.****RY17-012-23', 0, 0, 0, 1790966324396) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d3c78400a807bd19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Title Bar is horizontal area located at the very ___________ of the screen.', '{"A":"Top","B":"Left","C":"Bottom","D":"Right"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Title Bar is a horizontal bar placed at the top of a window.', 0, 0, 0, 1790966324396) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cc620a7aa6584e55', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '_________ key is used to change lowercase letters mode to uppercase and vice versa?', '{"A":"ALT","B":"Caps Lock","C":"CTRL","D":"Enter"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Change case in MS Word: Shift +F3Caps Lock is used to change lowercase letters mode to uppercase', 0, 0, 0, 1790966324396) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_39648aafd45ad392', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'SMTP is a _______?', '{"A":"Communication Protocol","B":"Operating system","C":"FDM","D":"TDM"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SMTP pushes email messages to the server.SMTP is part of the application layer of the TCP/IP protocol.SMTP is used for sending emails while POP is used for receiving emails.SMPT: Simple Mail Transfer ProtocolPOP: Post Office Protocol', 0, 0, 0, 1790966324396) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a30383a442ae207f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Where is computer''s BIOS stored?', '{"A":"DRAM","B":"Flash memory chip","C":"SRAM","D":"EEPROM","E":"Hard Disk"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BIOS stands for Basic input/output system.BIOS firmware was stored in a ROM chip on the PC motherboard. In later computer systems, the BIOS contents are stored on flash memory ND18-4-2023', 0, 0, 0, 1790966324396) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2a6ad3172fca4e72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A computer consists of :', '{"A":"Motherboard","B":"Hard Disk Drive","C":"Central processing unit","D":"All of the above","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer system consists of a: computer case, a power supply unit, a motherboard, a central processing unit , main memory, and a hard disk drive.***while: Input devices include :a keyboard, mouse, microphone, video camera, and image scanner.*** Output devices include: a monitor, speakers, and a printer.******VU FIA CONSTABLE PAPER 2021****RY 16-01-2023ND11-4-2023', 0, 0, 0, 1790966324478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7cc50bd7496e9157', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'You need to jump to the next column breaking current column right at the cursor position. How can you break column ?', '{"A":"Pressing Ctrl+Shift+Enter","B":"Pressing Alt+Shift+Enter","C":"Break command from Insert menu","D":"Both b and c"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The keyboard shortcut Ctrl+Shift+Enter also inserts a column break where you''ve placed your cursor.', 0, 0, 0, 1790966324478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1779a685f1d960c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'From where a computer can get a virus?', '{"A":"Email","B":"internet","C":"both A and B","D":"none of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation the computer can get a virus in Email and in internetAn email virus looks simple but can erase files, destroy information and cause computer crashes******Other Questions Related to "COMPUTER VIRUS"A computer virus isdeliberately created***Computer Virus operates by:Dormancy and Replication*** Which is the first computer virus in World?Creeper***First, ever computer virus was created from -------:PakistanND11-3-2023', 0, 0, 0, 1790966324478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1ad658ab3e78fb43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Smart card is a ________', '{"A":"Micro-procedure","B":"Micro-processor","C":"Micro-phone","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A microprocessor smart card is defined as an IC chip contact card with a microprocessor and memory. The size of a credit card, this smart card contains a small microchip that can process and store thousands of bits of electronic data.', 0, 0, 0, 1790966324478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_944cdf789fb3f96c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'You can use the formula palette to', '{"A":"Enter assumptions data","B":"Create and edit formula containing functions","C":"Format cells containing numbers","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Formula palette is used to create and edit formula.It is also possible to type a function directly into a cell.', 0, 0, 0, 1790966324478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0a3a91229dc1e61e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Macintosh series of PC  was developed by following company?', '{"A":"IBM","B":"Apple","C":"Microsoft","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Apple has developed a series of Macintosh operating systems. Release date: January 24, 1984; 41 years agoLifespan: 1984–presentOperating system macOS"Classic" Mac OS (formerly)Related Apple IIApple LisaiPad', 0, 0, 0, 1790966324478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1062b089b28ad56f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Margin in page Layout is found in which Tab ?', '{"A":"Home Tab in PPT","B":"Insert tab","C":"Animation Tab","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On the Page Layout tab, in the Page Setup group, choose Margins and the Margins gallery appears', 0, 0, 0, 1790966324478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5b5e5d987b944a42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which function will you use to enter current time in a woksheet cell ?', '{"A":"=time()","B":"=nowtime()","C":"=now()","D":"=currentTime()"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term Worksheet used in Excel documents is a collection of cells organized in rows and columns.', 0, 0, 0, 1790966324478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3f9e591cc5b16b5b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In which topology there is a central controller or hub?', '{"A":"Star","B":"Mesh","C":"Ring","D":"Bus"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Star topology is a topology for a Local Area Network (LAN).In which all nodes are individually connected to a central connection point, like a hub or a switch.', 0, 0, 0, 1790966324566) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2c286510985b51d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Arithmetic Operations performed by?', '{"A":"RAM","B":"ROM","C":"ALU","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Arithmetic operations are performed by the ALUALU stands for Arithmetic & Logical Unit. This is the core component responsible for executing arithmetic (ADD, SUB, etc.) and logical (AND, OR, NOT) operations.The ALU is housed within the CPU, which acts as the "brain" of the computer.Last updated 15-feb-2026', 0, 0, 0, 1790966324567) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_12abf489faf15dae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Analogue computer works on_____', '{"A":"Continuous electrical pulses","B":"Continuous electronic pulses","C":"Electrical pulses but not continuous","D":"Magnetic strength"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Analogue computers work on continuous physical quantities (or analog signals)They handle data that changes continuously over time.Examples: Speedometers, mercury thermometers, and slide rules.Last updated by NS on 06 May 2026', 0, 0, 0, 1790966324567) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_669901b35e717ba9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Insert date format page number, and insert auto text or buttons on the ___ toolbar.', '{"A":"Edit","B":"Standard","C":"Formatting","D":"Header and footer"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A header is the top margin of each page, and a footer is the bottom margin of each page.', 0, 0, 0, 1790966324567) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e7cb37fe8f3e47bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Cyber Security is used to protect?', '{"A":"hardware","B":"data","C":"software","D":"All of those"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The practice is used by individuals and enterprises to protect against unauthorized access to data centers and other computerized systems.', 0, 0, 0, 1790966324567) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_911b2748cf27c325', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The key F12 opens a', '{"A":"Save as dialog box","B":"Open dialog box","C":"close dialog box","D":"save dialog box"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On the File menu, click Save As to open the Save As dialog box. The Save As dialog box is a standard Windows dialog box.', 0, 0, 0, 1790966324567) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_92e12c0c00f7261d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How can you access the font size tool on formatting toolbar', '{"A":"Ctrl+ S","B":"Ctrl+ P","C":"Ctrl+ Shift +S","D":"Ctrl+ Shift +P"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Shift + P is used to change the font size.', 0, 0, 0, 1790966324567) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6ff4a7b2d7dea9cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The command used to apply look of one piece of text to other parts of text document?', '{"A":"Copy","B":"Format Painter","C":"Paste","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use the Format Painter on the Home tab to quickly apply the same formatting, such as color, font style and size, and border style, to multiple pieces of text or graphics.*************VU FIA SUB INSPECTOR PAPER 30-1-2021', 0, 0, 0, 1790966324567) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_93f9d077926bfac8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The _________ folder retains copies of messages that you have started but are not yet ready to send.', '{"A":"Drafts","B":"Sent items","C":"Inbox","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The draft folder retains copies of messages that you have started but are not yet ready to send.Draft messages are saved in your Draft folder until you send them or delete them from the folder. You can enable a preference to automatically save your email as a draft while you are composing the message.', 0, 0, 0, 1790966324668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5eab921b9d02d4c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The default page size for word documents is also used in offices', '{"A":"A4","B":"Legal","C":"Letter","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A4 paper size is 210 x 297 mm*************Standard International Paper Sizes and MeasurementsNormally, the default format would be “letter” which is the standard size for a page (8.27” x 11.69” / 21 x 29.7cm).A4 size is easy to work with and print since it fits into any printer or copier.Sh4-9-2023', 0, 0, 0, 1790966324669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7704b5e126ff706c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '____ includes superscript, subscript, outline , emboss , engrave', '{"A":"Word art","B":"Text effects","C":"font effects","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Superscript, subscript, outline, emboss, and engrave are known as Font effects.*************VU FIA SUB INSPECTOR PAPER 30-1-2021****RY 16-01-2023***ND18-1-2023', 0, 0, 0, 1790966324669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1bbb01d52027fb64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following is not true regarding conditional formatting?', '{"A":"You can set condition to look for Bold and apply Italics on them","B":"You can add more than one condition to check","C":"You can apply Font, border and pattern formats that meets the specified conditions","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Conditional Formatting we cannot set condition to look for Bold and apply Italics on them.', 0, 0, 0, 1790966324669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b0a2d2f14b7d477c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'RFP means?', '{"A":"request for proposal","B":"request for payment","C":"request for punishment","D":"request for protocol"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RFP means the request for a proposal.An RFP is a document that lists all the requirements and needs of a project**whileRFI means the request for information is used when the owner wants several contractors to provide potential solutions****nd9-2-2023', 0, 0, 0, 1790966324669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a312ac69fc01a9c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of the following is an Output Device__?', '{"A":"Keyboard","B":"Printer","C":"Scanner","D":"Mouse","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An output device is any device used to send data from a computer to another device or user.Printers, monitors, projectors, etc. are examples of output devices.Keyboard, scanner & Mouse are input devices. Last updated by NS on 06-09-2026​', 0, 0, 0, 1790966324669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_de1ec016484e1cb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which feature is used to make selected sentence to All Captital Letters or All Small Letters ?', '{"A":"Change case","B":"Change letter","C":"Change sentence","D":"Change word"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To use a keyboard shortcut to change between lowercase, UPPERCASE, and Capitalize Each Word, select the text and press SHIFT + F3 until the case you want is applied.**** RY19012023', 0, 0, 0, 1790966324669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f4cd39bc8df21c66', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In chart wizard, term data series refers to ______?', '{"A":"A chart legend","B":"A collection of chart data markers","C":"A data label","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A data series is a group of related values.It is represented by bars, lines, slices, or columns in a chart.Each data series has its own label or name.Last updated 18-07-2026 by NA', 0, 0, 0, 1790966324669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bed212947f4d3006', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'One millisecond is', '{"A":"1 second","B":"10th of a seconds","C":"1000th of a seconds","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A millisecond is a unit of time in the International System of Units (SI) equal to one thousandth (0.001 or 10−3 or 1/1000) of a second and to 1000 microseconds', 0, 0, 0, 1790966324761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9627233269a29533', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which one is not an Image file ?', '{"A":".wmv","B":".png","C":".bmp","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation WMV is a video format which is compressed with Windows Media compression and contains a video encoded with one of Microsoft''s Windows Media Video.', 0, 0, 0, 1790966324761) ON CONFLICT(id) DO NOTHING;
