INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c92d61e1db00d2ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The process of removing errors in programs is called', '{"A":"debugging","B":"antivirus","C":"cutting","D":"formatting"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Debugging, in computer programming and engineering, is a multistep process that involves identifying a problem, isolating the source of the problem, and then either correcting the problem or determining a way to work around it. The final step of debugging is to test the correction or workaround and make sure it works.********VU CBT FIA PAPER 16-12-2021MUG 10-12-2022', 0, 0, 0, 1790966324761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_956b22bea3bf3a28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Be Up to your ears? means', '{"A":"to be very lazy","B":"to be very clever","C":"to be very busy","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Be Up to your ears: means "to be very busy" idiom. to be very busy, or to have more of something than you can managefor example:I''m up to my ears in work.*****ND4-12-2022', 0, 0, 0, 1790966324857) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4cb23a53997d21c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The first federal judicial is system of the world is:', '{"A":"American judicial system","B":"French judicial system","C":"Chinese Judicial system","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Judiciary Act of 1789 established the federal court system separate from individual state courts. It was one of the first acts of the First Congress, signed in September 1789.', 0, 0, 0, 1790966324857) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fa17283a1c1543fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following is justification align the text on both the sides-left and right of margin?', '{"A":"Ctrl + S","B":"Ctrl + j","C":"Ctrl + C","D":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut key for aligning the text on both the sides-left and right of the margin is Ctrl + J to justify your text.***Align and format paragraphsJustify the paragraph: Ctrl+JAlign the paragraph to the left: Ctrl+LAlign the paragraph to the right: Ctrl+RIndent the paragraph: Ctrl+MSH4-9-2023', 0, 0, 0, 1790966324857) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2e161cfed46d5c83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A device through which we enter data in a computer known as ___________?', '{"A":"Software","B":"Output Device","C":"Input Device","D":"Memory","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scanner, Keyboard, Mouse, Microphone etc. are the examples of Input Devices.', 0, 0, 0, 1790966324857) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b20d954f53e067e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In which type of computer, data are represented as discrete signals?', '{"A":"Analog computer","B":"Digital computer","C":"Hybrid Computer","D":"A and B"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Digital computer, data are represented as discrete signalsڈیجیٹل کمپیوٹر، ڈیٹا کو مجرد سگنل کے طور پر پیش کیا جاتا ہے۔', 0, 0, 0, 1790966324857) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_218fdc3b1c0be101', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Microsoft power point is ___ type of program.', '{"A":"Graphical","B":"Calculating","C":"Presentation","D":"All"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft PowerPoint is a powerful slide show presentation program. The program uses slides to convey information rich in multimedia.PowerPoint, a presentation program created by Robert Gaskins and Dennis, was released on April 20, 1987.', 0, 0, 0, 1790966324857) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ea114ff98b5a935f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A program written in a non machine language is called', '{"A":"translator program","B":"source program","C":"Machine program","D":"All"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A program written in a non-machine language is called source code.Source code refers to the code written in high-level programming languages like C, Java, Python, etc., which must be compiled or interpreted into machine language for execution by a computer.', 0, 0, 0, 1790966324857) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7b9fd748f6c157fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Each type of computer has its own machine language which consists of:', '{"A":"Ones","B":"Zeros","C":"Both A & B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer is built to carry out instructions that are written in a very simple type of language called machine language.', 0, 0, 0, 1790966324857) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b347518fceed65b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Machine language and Assembly language is an examples of ______language', '{"A":"Low level","B":"High level","C":"Intermediate","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A machine language doesn''t need a compiler to execute its commands. Assembly Language:One needs an assembler (commonly called a compiler) to execute the commands of an assembly language properly.', 0, 0, 0, 1790966324999) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_874dcee7cfdc559f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which short keys are used to cut selected items in file menu?', '{"A":"CTRL+X","B":"CTRL+A","C":"CTRL+U","D":"CTRL+B"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + X Cut selected items. Ctrl + V Paste content from the clipboard. Ctrl + A Select all content.', 0, 0, 0, 1790966324999) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c4e7889376c88d6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'output devices are_________', '{"A":"speaker","B":"printer","C":"screen","D":"All"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An output device is any device used to send data from a computer to another device or user.******VU FIA CONSTABLE PAPER 2021', 0, 0, 0, 1790966325000) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0ee86ead3f7ef122', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The interface between user and computer is?', '{"A":"Modem","B":"Monitor","C":"Hard Disk","D":"Programming"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The interface between user and computer is called Programming', 0, 0, 0, 1790966325000) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b0b97b0d041cb12c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The programs that control and manage the basic operations of a computer are generally referred to as system software. Which of the following types of programs are typically included in system software?', '{"A":"Utility Programs","B":"Software Development Tools","C":"Game Programs","D":"Both A and B","E":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Computer hardware is virtually useless without computer software. Software is the programs that are needed to accomplish the input, processing, output, storage, and control activities of information systems.*********VU FIA ASSISTANT PAST PAPER 01-01-2022', 0, 0, 0, 1790966325000) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_31f448c30a44a794', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Table in database must Have ?', '{"A":"Primary Key","B":"Function Key","C":"Numeric key","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the relational model of databases, a primary key is a specific choice of a minimal set of attributes that uniquely specify a tuple in a relation. Informally, a primary key is "which attributes identify a record", and in simple cases are simply a single attribute: a unique id.A field is also known as a columnthat stores the same type of data and hence can be called a category of data.***************vu FIA CBT PAPER 15-12-2021', 0, 0, 0, 1790966325000) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fc2e772121a654df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'You use to create chart?', '{"A":"Wizard","B":"Ms word","C":"Excel","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chart Wizard use to create a chart.A wizard found in the Microsoft Excel program that takes users step-by-step through the process of creating a chart in Microsoft Excel.f11 kay used to create auto chart.********VU CBT FIA PAPER 16-12-2021', 0, 0, 0, 1790966325000) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_65fec3ec8a99cdd9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '_____ is not a valid data type in excel', '{"A":"Number","B":"Label","C":"Character","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are Three types of data in cells: labels, values, and formulas. Values (numbers) are generally raw numbers or dates. Formulas are instructions for Excel to perform calculations.', 0, 0, 0, 1790966325000) ON CONFLICT(id) DO NOTHING;
