INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_dfa2f34d4e82ec47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Hard disc in a computer is a or an ___________?', '{"A":"Processor","B":"Output Device","C":"Software","D":"Storage Device"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The hard disk is a secondary storage device, which is designed to store data permanently.', 0, 0, 0, 1790966325101) ON CONFLICT(id) DO NOTHING;
