INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eafdcb1c5821122c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Landscape is a:', '{"A":"Page Orientation","B":"Page Layout","C":"Paper Size","D":"Font Size","E":"all of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Landscape is a horizontal orientation mode used to display wide-screen content, such as a Web page, image, document or text.', 0, 0, 0, 1790966325101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9225c0f79b7ff57d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'n-1 link formula is used in which topoloy ______?', '{"A":"Mesh Topology","B":"Star Topology","C":"Ring Topology","D":"Hybrid Topology"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A mesh topology is a network setup where each computer and network device is interconnected with one another.', 0, 0, 0, 1790966325101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_20bfeea69d3e47a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Malware is short form of __________ ?', '{"A":"malicious hardware","B":"malicious software","C":"Both A and B","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation میلویئر نقصان دہ سافٹ ویئر کی مختصر شکل ہے۔malicious software نقصان دہ سافٹ ویئر', 0, 0, 0, 1790966325101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_277dae5b951b7e71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Cookies were originally designed for __________?', '{"A":"Server side programming","B":"Client side programming","C":"Both a and b","D":"None of the mentioned"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cookies were originally designed for server-side programming, and at the lowest level, they are implemented as an extension to the HTTP protocol.', 0, 0, 0, 1790966325184) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0b7f5378986d60a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Cookies are used to do which of the following?', '{"A":"Store contents of electronic shopping carts","B":"To track web activity","C":"Store your ID and password for subsequent logons to the site","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cookies are text files with small pieces of data such as a username and password etc.The purpose of the computer cookie is to help the website keep track of your visits and activity.That is used to identify your computer as you use a computer network.Specific cookies known as HTTP cookies are used to identify specific users and improve your web browsing experience.', 0, 0, 0, 1790966325184) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6b0c826ed4881848', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'A program written in a high level language is referred to as :', '{"A":"Machine program","B":"Assembly program","C":"Source code","D":"Subset"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Source code is the set of instructions written by a programmer using various programming languages. Source Code is generally written in English though it may vary from one computer to another.', 0, 0, 0, 1790966325184) ON CONFLICT(id) DO NOTHING;
