INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fa16d9a297d987d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In which situation running applications of an user account remains active ?', '{"A":"When we Log Off","B":"When we Shut Down","C":"When we Switch User","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Switches to another user account on the computer without closing your open programs and Windows processes.', 0, 0, 0, 1790966325184) ON CONFLICT(id) DO NOTHING;
