INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_22c6025112d748bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'IBMS has replaced the:', '{"A":"KPCES","B":"PISNSC","C":"PIWSQ","D":"PISCES"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PISCES stand for Personal Identification Secure Comparison & Evaluation System”', 0, 0, 0, 1790966325273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c996496f2128b747', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How many types of computer buses are?', '{"A":"2","B":"4","C":"3","D":"5"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Three types of bus are used.Address bus: carries memory addresses from the processor to other components such as primary storage and input/output devices. Data bus : carries the data between the processor and other components.Control bus: carries control signals from the processor to other components.', 0, 0, 0, 1790966325273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fb21ef15c4b0410f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How can you remove boarded applied on cells?', '{"A":"Choose None on Border tab of Format cells","B":"Open the list on Border tool in Format Cell toolbar then choose first tool","C":"Both","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On the Home tab, in the Font group, click the arrow next to Borders Button, and then click No Border Button.--OR--Click Home > the Borders arrow > Erase Border, and then select the cells with the border you want to erase.', 0, 0, 0, 1790966325273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_304f3f8adf1d6795', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Hardware of computer includes ___', '{"A":"Physical part","B":"Hard disk","C":"Both","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Computer hardware includes the physical parts of a computer, such as the case, central processing unit, monitor, mouse, keyboard, computer data storage, graphics card, sound card, speakers and motherboard.', 0, 0, 0, 1790966325273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0579a9cda30f8f53', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'FDM is used in _______?', '{"A":"Analog Signals","B":"Time Division Multiplexing","C":"Network","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FDM stands for Frequency Division Multiplexing.', 0, 0, 0, 1790966325273) ON CONFLICT(id) DO NOTHING;
