INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_72aab122f01398ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Change the ----- to create a document in the wide format.', '{"A":"Paper style","B":"Page margins","C":"Paper source","D":"Page orientation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Page orientation is the direction in which a document is displayed or printed. The two basic types of page orientation are portrait (vertical) and landscape (horizontal).', 0, 0, 0, 1790966325332) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_072e79ba37104c23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'automata theory is the ____?', '{"A":"Study of heart","B":"Study of coins","C":"Study of the earth","D":"Study of Abstract Machine"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Automata theory is the study of abstract machines and automata, as well as the computational problems that can be solved using them. It is a theory in theoretical computer science. The word automata (the plural of automaton) comes from the Greek word αὐτόματα, which means "self-making".', 0, 0, 0, 1790966325332) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4d1df48deb961da8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Normally, A spread contains:', '{"A":"documents","B":"rows","C":"rows and columns","D":"columns"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A spreadsheet is a file that exists of cells in rows and columns and can help arrange, calculate and sort data. Data in a spreadsheet can be numeric values, as well as text, formulas, references and functions.', 0, 0, 0, 1790966325332) ON CONFLICT(id) DO NOTHING;
