INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4afeec874b0cff03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What was the first personal computer (PC) made in the 1970s called?', '{"A":"Apple-I","B":"Altair","C":"Apple II","D":"Intel"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AltairFrom interest computer systems to AppleA small organization named MITS made the primary private laptop, the Altair. This laptop, which used Intel Corporation`s 8080 microprocessor, turned into advanced in 1974.', 0, 0, 0, 1790966325332) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_22fd225e9ae6ed50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Router see information from', '{"A":"Browser History","B":"Modem","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You can set up your router to log a user''s browser history. Collecting data such as someone''s browsing history is a violation of their privacy.', 0, 0, 0, 1790966325405) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_82049485f04775ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Shortcut for document views toolbar is situated in ___ bar.', '{"A":"task bar","B":"Status bar","C":"tool bar","D":"Micro"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A status bar is a horizontal window at the bottom of a parent windowIn which an application can display various kinds of status information.', 0, 0, 0, 1790966325405) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_dbd4c55772039ee6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Social networks are organized primarily around __________.', '{"A":"discussions","B":"people","C":"organizations","D":"brands"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Social networks are organized primarily around people.', 0, 0, 0, 1790966325405) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5aaf943061ba5ccd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'software that are available for free of cast is called', '{"A":"freeware","B":"Hardware","C":"software","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Freeware is software, most often proprietary, that is distributed at no monetary cost to the end user.', 0, 0, 0, 1790966325405) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_323bb86d5d7172d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Soft copy refers to :', '{"A":"Input","B":"output","C":"Screen output","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A soft copy (sometimes spelled "softcopy") is an electronic copy of some type of data, such as a file viewed on a computer''s display or transmitted as an e-mail attachment. Such material, when printed, is referred to as a hard copy .', 0, 0, 0, 1790966325405) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e250509e427826b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Speakers are?', '{"A":"Output devices","B":"Input devices","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The speakers receive audio input from a device such as a computer or an audio receiver. This input may be either in analog or digital form. Analog speakers simply amplify the analog electromagnetic waves into sound waves.', 0, 0, 0, 1790966325405) ON CONFLICT(id) DO NOTHING;
