INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_50f49f536e9efae6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'TDM is used in ______?', '{"A":"Low speed transmission","B":"High speed transmission","C":"Weak speed transmission","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation TDM stands for Time Division Multiplexing.', 0, 0, 0, 1790966325405) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ae5e1c5038e0aedf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The process of systematic arrangement of data in rows and columns is called ___________________?', '{"A":"Frequency","B":"Tabulation","C":"Classification","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tabulation is the presentation of figures from an investigation in a table which consists of rows and columns of cells, or spaces, each of which provides one unit of information.', 0, 0, 0, 1790966325482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6216c92c5e31e818', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The system unit of a personal computer typically contains all of the following except:', '{"A":"Modem","B":"Serial interface","C":"Disk controller","D":"Microprocessor","E":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The system unit of a personal computer typically contains all of the following except Modem.The main part of a personal computer.the chassismicroprocessormain memorybusand ports', 0, 0, 0, 1790966325482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_133085bb641f5fc9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The _________displays the name of every computer user on the computer', '{"A":"command screen","B":"welcome screen","C":"wish list screen","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first screen that appears when you turn on Windows. The Welcome screen lists all the accounts on the computer.', 0, 0, 0, 1790966325482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d6d3254fdaf819d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To auto fit the width of column _', '{"A":"Double click the column header","B":"Double click the left border of column","C":"Double click the right border of column","D":"All"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Automatically adjust your table or columns to fit the size of your content by using the AutoFit button.Select your table.On the Layout tab, in the Cell Size group, click AutoFit.Do one of the following. To adjust column width automatically, click AutoFit Contents.', 0, 0, 0, 1790966325482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a6d4c439f90c4228', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'To move the cursor page to page of document press ___.', '{"A":"Ctrl + Pg Up","B":"Ctrl + Pg Dn","C":"Both","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Page Down and Ctrl + Page Up move the cursor up and down one page at a time.', 0, 0, 0, 1790966325482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_05a53e5036ffaf6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Track of location of files stored in a system kept by?', '{"A":"inodes.","B":"Operating system","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The system keeps track of files and directories using inodes. An inode is a representation of a file that stores all the data belonging to that file, such as owner, type, size, access permissions, access times and the file''s layout on disk.', 0, 0, 0, 1790966325482) ON CONFLICT(id) DO NOTHING;
