INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_df94848b50eab561', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'If the operations in a transaction do not modify the database but only retrieve the data, what does this transaction called?', '{"A":"Read Write Transaction","B":"Read only Transaction","C":"Consistent Transaction","D":"Isolated Transaction"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If the database operations do not update the database but only retrieve data, this type of transaction is called a read-only transaction. If the database were in an inconsistent state before a transaction, it would remain in the inconsistent state after the transaction.', 0, 0, 0, 1790966325565) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ec8497107ae23975', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'The main unit of a computer is:', '{"A":"CPU","B":"Input Unit","C":"Memory Unit","D":"Output Unit"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPU Menas central processing unit, CPU is a principal part of any digital computer system, generally composed of the main memory, control unit, and arithmetic-logic unit.', 0, 0, 0, 1790966325565) ON CONFLICT(id) DO NOTHING;
