INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_93cedcfb889254c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'How can we shift data from other place within the same document', '{"A":"Cut and paste","B":"cut","C":"paste","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Cut feature allows you to remove selected text from the document and temporarily place it on the Office Clipboard.The Paste feature allows you to get text from the clipboard and place it in the same or even another document.', 0, 0, 0, 1790966325565) ON CONFLICT(id) DO NOTHING;
