INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_991c305deab7b0e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which part of the computer is used for calculating and comparing ?', '{"A":"Odem","B":"Alu","C":"Control unit","D":"Disk unit","E":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An arithmetic-logic unit (ALU) is the part of a computer processor (CPU) that carries out arithmetic and logic operations on the operands in computer instruction words.', 0, 0, 0, 1790966325891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_637a9cb0089e2a51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which Social media app has changed the company name to META?', '{"A":"Facebook","B":"Instagram","C":"WhatsApp","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Will Facebook app change its name?No. Facebook, the social media app and service, will keep the same name. Only the umbrella company that oversees all the different apps is changing to Meta.', 0, 0, 0, 1790966325891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_938e5fb679591665', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which software is not an file compression utility____ ?', '{"A":"Compress","B":"Win Zip","C":"Win Rar","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft-XP is not an example of file compression Program used in windows operating system.', 0, 0, 0, 1790966325891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e6ea6a80998d2bc6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which term is associated with decorative test', '{"A":"word art","B":"cross link","C":"cross reference","D":"clipart"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Word art or text art is a form of art that includes text, forming words or phrases, as its main component; it is a combination of language and visual imagery.', 0, 0, 0, 1790966325891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5ffd09fd305ee46e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which tool you will use to join some cells and place the content at the middle of joined cell ?', '{"A":"From Format Cells dialog box click on Merge Cells check box B.  From Format Cells dialog box select the Centered alignment C.  From Format Cells dialog box choose Merge and Center check box","B":"From Format Cells dialog box click on Merge Cells check box","C":"Merge Cells check box","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 2003 and earlier versions - From Format Cells dialog box click on Merge Cells check boxIn 2007 and subsequent versions - Merge & Center icon on the Home ribbon.', 0, 0, 0, 1790966325891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_568e285f4a80ca32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'While finding and replacing some data in Excel,which of following statement is valid', '{"A":"You can Find and Replace within the sheet or workbook","B":"Excel does not have option to match case for find","C":"All","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Excel we can Find and Replace within the sheet or workbook.', 0, 0, 0, 1790966325891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_00c22115be9e6cec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Who among the following is known for originating concept of programmable computer', '{"A":"Charles Babbage","B":"Blaise Pascal","C":"Herman Hollerith","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charles Babbage was a mathematician, philosopher, inventor and mechanical engineer, Babbage originated the concept of a digital programmable computer.Father of computer Born: December 26, 1791, London, United Kingdom', 0, 0, 0, 1790966325891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_13942a4e58422858', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'window 2007 is an_________ System.', '{"A":"Operating","B":"Application","C":"system software","D":"Noine"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Operating system is software that is required in order to run application programs and utilities.', 0, 0, 0, 1790966325976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_57b8fe757e9aaddf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Yahoo Inc. stops its services in _____?', '{"A":"China","B":"Japan","C":"USA","D":"India"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Yahoo Inc. has announced that the company has stopped providing service in mainland China with effect from November 01, 2021, due to the increasingly challenging business and legal environment in the country. With this Yahoo has ended its 22-year presence in the Chinese market.', 0, 0, 0, 1790966325976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d026223a49d741df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'You can set border in Excel from ___', '{"A":"From Line Style tool in Drawing toolbar","B":"You can not set page border in Excel","C":"From Border tool in Formatting toolbar","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There is no option to set page border in Excel.', 0, 0, 0, 1790966325976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2942bd41d8949146', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'You can auto fit the width of column by', '{"A":"Double clicking on the column name on column header","B":"Double click on the cell pointer in worksheet","C":"Double clicking on column right border on column header","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790966325976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3c7fc8e8b06a68b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '_______ are used for plotting graphs and design on paper.', '{"A":"Plotters","B":"Power point","C":"printers","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A plotter is a machine that produces vector graphics drawings. Plotters draw lines on paper using a pen, or in some applications, use a knife to cut a material like vinyl or leather.', 0, 0, 0, 1790966325976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_24af7f2344a63777', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '______ the cell pointer indicate that you can move the content to other cell .', '{"A":"Doctor’s symbol (Big Plus)","B":"Mouse Pointer with anchor at the tip","C":"Small thin plus icon","D":"All"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mouse Pointer with anchor at the tip cell pointer indicate that you can move the content to other cell.', 0, 0, 0, 1790966325976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1bb65b829dd7d2d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '________the cell pointer indicates that you can fill series', '{"A":"Doctor’s symbol (Big Plus)","B":"Small thin plus icon","C":"Mouse Pointer with anchor at the tip","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Small thin plus icon MS Excel solution image cell pointer indicates that you can fill series.', 0, 0, 0, 1790966325976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_468c8fc41b05430d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'When sharing data in office , the ____ document is the document in which the data was first entered .', '{"A":"Source","B":"Primary","C":"original","D":"Destination"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Source Document: The original file (e.g., Excel, Word) where data is initially entered or stored.Destination Document: The file (e.g., Word, PowerPoint) where the data from the source is linked or embedded.Last updated by NS on 06 May 2026', 0, 0, 0, 1790966325976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_24ea3bce9fd36a50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What type of Software is needed to control the computer’s hardware?', '{"A":"Operating system","B":"Device Driver","C":"Firmware","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation System software — specifically the Operating System (OS) — controls the computer''s hardware.It manages the CPU, memory, storage, and input/output devices.', 0, 0, 0, 1790966326049) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_comp_word', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'MS Word', 'top_computer', 142, 1790966326103) ON CONFLICT(id) DO UPDATE SET total_mcqs = 142;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b55a9042bafe66eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which of following shortcut keys is used to change the case in MS Word?', '{"A":"Ctrl+ F3","B":"Shift + F3","C":"Ctrl + F1","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut key to change case in MS-Word is: Shift + F3.There are five change cases in MS Word:Sentence CaseLowercaseUppercaseTitle CaseToggle CaseLast verified on 10-08-2026', 0, 0, 0, 1790966326181) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_edf49524c209623c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word, Ctrl + Y is used for ____?', '{"A":"Redo","B":"Paste","C":"Cut","D":"Undo"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Y is used for redoing the last undone action in most applications.Additional information:- Ctrl + Z: Undo- Ctrl + X: Cut- Ctrl + C: Copy- Ctrl + V: PasteLast verified on 09-08-2026', 0, 0, 0, 1790966326181) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_edf261a5808e685c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which shortcut key is used to open an existing file in MS Word?', '{"A":"Ctrl+O","B":"Ctrl+N","C":"Ctrl+R","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The keyboard shortcut to open an existing file in Microsoft Word is Ctrl+O.You can also open a document in Word by double-clicking its icon in Windows. Additional information: Ctrl+N: Opens a new or blank documentCtrl+S: Saves the documentCtrl+W: Closes the documentCtrl+A: Selects all contents of the pageCtrl+B: Bolds highlighted selectionCtrl+C: Copies selected textCtrl+X: Cuts selected textCtrl+P: Opens the print windowLast verified on 02-04-2026', 0, 0, 0, 1790966326181) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3c77a87997ef5090', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the Extension of MS Word documents 2007 and later?', '{"A":".docs","B":".dos","C":".docx","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DOCX is the newer version of DOC, the original official Microsoft Word file format. Microsoft Word 97 - 2003 Document extension (.doc).Microsoft Word 2007 to till date Document extension (.docx).Additional information:.xls extension of Excel..ppt extension of PowerPoint..txt extension of Text files..pdf extension of Portable Document Format.Last verified on 15-02-2026', 0, 0, 0, 1790966326181) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_69de8242c3048079', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which is not included in a Font Style in MS-Word? Bold, Italic, Regular, Superscript', '{"A":"Bold","B":"Italic","C":"Regular","D":"Superscript"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Superscript" is not a font style in MS Word.Superscript is a text effect used to raise characters above the normal line of text.Font styles include options like Bold, Italic, and Regular.Last verified on 29-09-2026', 0, 0, 0, 1790966326181) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7a79c3d9d0d4deff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the shortcut Key for justifying the text in MS Word?', '{"A":"Crtl + J","B":"Crtl + I","C":"Crtl + M","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, Ctrl + J is used to justify text.Justified text is evenly aligned on both left and right margins.It is commonly used in books, newspapers, and formal documents.Additional information:Ctrl + L → Left alignCtrl + E → Center alignCtrl + R → Right alignLast verified 29-05-2026', 0, 0, 0, 1790966326181) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cc99d6b2eee92d98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl + M Shortcut is used in Microsoft Word to?', '{"A":"New Document","B":"Close Document","C":"Increase Right Indent","D":"Increase Left Indent"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + M → Increase Left IndentAdditional information:Ctrl + Shift + M → Decrease Left IndentCtrl + N → New DocumentCtrl + W → Close DocumentLast verified on 28-09-2026', 0, 0, 0, 1790966326181) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_598fb71578379749', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl + Right Arrow shortcut key is used in MS Word to ________?', '{"A":"Moves the cursor end of the line","B":"Moves the cursor end of the document","C":"Moves the cursor one word right","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, the shortcut key Ctrl + Right Arrow moves the cursor one word to the right.Additional information:Ctrl + Left Arrow moves the cursor one word to the left.Ctrl + Up Arrow moves the cursor one paragraph up.Ctrl + Down Arrow moves the cursor one paragraph down.Last verified on 28-09-2026', 0, 0, 0, 1790966326181) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_af4cd9b5599bd868', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Where is office button located in MS Word?', '{"A":"Left Upper","B":"Left Bottom","C":"Right Upper","D":"Right Bottom"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Office Button was introduced in Microsoft Office 2007.It was located at the upper-left corner of the Word window.It provided commands such as New, Open, Save, Print, and Close.Last verified on 28-09-2026', 0, 0, 0, 1790966326252) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_49725fe630f84890', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the function of Ctrl + Shift + L in MS Word?', '{"A":"Insert a table","B":"Apply bullet points","C":"Save the document","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Shift + L → Apply bullet points.Additional information:Ctrl + S → Save the document.Ctrl + A → Select all.Ctrl + B → Bold text.Ctrl + I → Italic text.', 0, 0, 0, 1790966326252) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3daba479f6a4bdba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl + X Shortcut is used in Microsoft Word to ______?', '{"A":"Close Document","B":"Cut the Selected Contents","C":"Copy the Selected Contents","D":"Close Word Application"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + X → Cut (remove selected text)Additional information:Ctrl + R → Align text to the rightCtrl + E → Center align textCtrl + J → Justify paragraphCtrl + L → Align text to the leftCtrl + Q → Remove paragraph formatting (reset to default left alignment)Last verified on 10-06-2026', 0, 0, 0, 1790966326252) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5113f6a761e52de4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word, which key is used to increase the font size?', '{"A":"Shift + Ctrl + >","B":"Shift + Ctrl + <","C":"Shift + Ctrl + Tab","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Increase the font size. Ctrl + Shift + >Additional information:Decrease the font size: Ctrl + Shift + <Increase the font size by 1 point: Ctrl + ]Decrease the font size by 1 point: Ctrl + [Ctrl + Shift + F: Change the fontOpen the Font dialog box to change the font: Ctrl + Shift + FVerified & Updated', 0, 0, 0, 1790966326252) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_43b60a0beb007904', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word, Ctrl + H Shortcut is used for?', '{"A":"Open Help Window","B":"Find and Replace","C":"Highlight Text","D":"Insert Hyperlink"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + H is used for Find and Replace function.It allows users to search text and replace it quickly.Additional information:Ctrl + F → Find textCtrl + C → CopyCtrl + V → PasteCtrl + X → CutCtrl + Z → UndoLast verified on 19-04-2026', 0, 0, 0, 1790966326252) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c43f9fd48159b3ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl + N Shortcut key is used in MS Word to _______?', '{"A":"Save Document","B":"Open Document","C":"Create a new Document","D":"Close Document"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + N shortcut key is used to create a new, blank documentSave Document: Ctrl + SOOpen Document: Ctrl + OPrint Document: Ctrl + P (or Ctrl+F2 for Preview)Undo/Redo: Ctrl + Z (Undo),Ctrl + Y (Redo)Bold/Italic/Underline: Ctrl + B, Ctrl + I, Ctrl + UCenter Alignment: Ctrl + EInsert Hyperlink: Ctrl + KFind/Replace: Ctrl + F (Find), Ctrl + H (Replace)Last updated question by NA on 07 May 2026', 0, 0, 0, 1790966326252) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2b99e578b34f6cf5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'How many ways you can save a document in Microsoft Word?', '{"A":"3","B":"2","C":"1","D":"5"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A document in Microsoft Word can be saved in three commonly taught ways.File → Save → Saves the document.Ctrl + S → Quick Save shortcut.F12 → Opens the Save As dialog box.Save → Updates the current file.Save As → Saves with a new name, location, or format.', 0, 0, 0, 1790966326252) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6d2b6c197795e3d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'The maximum font size available in Microsoft Word from the dropdown list is ____?', '{"A":"80","B":"72","C":"70","D":"82"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maximum font size in dropdown: 72 ptYou can manually enter a larger size, such as 1638 pt.The list contains font sizes in points 8, 9, 10, 11, 12, 14, 16, 18, 20, 22, 24, 26, 28, 36, 48 and 72.', 0, 0, 0, 1790966326252) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9c70a4792e8f2848', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which of the following cannot be inserted from Insert > Picture in MS Word? Word art, Chart, Graph, Clipart', '{"A":"Word art","B":"Chart","C":"Graph","D":"Clipart"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word 2003, the Graph option is NOT available under Insert.In MS Word 2003, WordArt was inserted through Insert → Picture → WordArt.Chart and Clip Art could also be inserted through the Insert menu.Last verified on 08-09-2026', 0, 0, 0, 1790966326337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3627453386e03db3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which option in File pull-down menu is used to close a file in MS Word?', '{"A":"Close","B":"Quit","C":"Exit","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To close a file in Microsoft Word, you can select the Close option from the File menu.Select the File menuSelect CloseTo close the entire Microsoft Word application, you can select the X Close button in the upper-right corner.Last verified on 08-09-2026', 0, 0, 0, 1790966326337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f89a5d40a62aee50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the default left margin in MS Word 2003 document?', '{"A":"2 inch","B":"1 inch","C":"1.25 inch","D":"Text holders"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft Word 2003 and earlier, the default left and right margins were 1.25 inches (31.7 mm).The default top and bottom margins were 1 inch (25.4 mm).From Word 2007 onward, the default margins became 1 inch on all sides.Last verified on 08-09-2026', 0, 0, 0, 1790966326337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5d0a937a597df5b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl + B Shortcut key is used in MS Word to?', '{"A":"Search the selected text","B":"Paste the selected text","C":"Bold the selected text","D":"Open the specified file"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + B is used in MS Word to make the selected text bold (thick and dark).Additional information:MS word short key for help: F1Ctrl + A = Select allCtrl + B = BoldCtrl + I = ItalicCtrl + J = JustifyCtrl + P = PrintCtrl + Y = RedoCtrl + S = SaveLast verified on 10-06-2026', 0, 0, 0, 1790966326337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6d715044c95c3117', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'The shortcut key Ctrl + C in MS Word is used for?', '{"A":"Copy command","B":"Cut command","C":"Paste command","D":"Bold command"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + C in MS Word is used for the Copy command.Additional information:Ctrl + R → Align text to the rightCtrl + E → Center align textCtrl + J → Justify paragraphCtrl + L → Align text to the leftCtrl + Q → Remove paragraph formatting (reset to default left alignment)Last verified on 10-06-2026', 0, 0, 0, 1790966326337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_74a42b042ba038bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word default alignment for a paragraph is _____?', '{"A":"Left alignment","B":"Right alignment","C":"Centered alignment","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, the default alignment for a paragraph is Left (or Left-aligned)This setting aligns text along the left margin, leaving the right edge raggedShortcut: Ctrl+L Last updated by NA 15-feb-2026', 0, 0, 0, 1790966326337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6ad969e5b0c36e23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'How do you magnify your document in MS Word?', '{"A":"View, Zoom","B":"Format, Font","C":"Tools, Options","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Used to increase or decrease document display sizeFound in the View menu → Zoom optionHelps in reading and editing documents clearlyFormat → Font changes text style, not view sizeTools → Options/Customize are for settings, not magnificationLast updated by NS on 06 May 2026', 0, 0, 0, 1790966326337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f44a36794226d4da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is default font style in MS Word 2007 and later?', '{"A":"Calibri","B":"Roman","C":"Bold","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Calibri was the default font in MS Word 2007.The default font size was 11 points.Calibri replaced Times New Roman as the default font in Word 2007.It was part of Microsoft''s ClearType Font Collection.Last verified on 26-08-2026', 0, 0, 0, 1790966326337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_35421c8103b493c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word, Ctrl + I shortcut key used for?', '{"A":"Underline","B":"Italic","C":"Bold","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + I = ItalicAdditional information:Ctrl + A = Select allCtrl + B = BoldCtrl + P = PrintCtrl + Y = RedoCtrl + S = SaveLast verified on 09-08-2026', 0, 0, 0, 1790966326448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d5731e7f7b55377b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'A word processor would most likely be used to _____?', '{"A":"Maintaining an inventory","B":"Type a document / Writing letters","C":"Making Presentation","D":"Doing Internet Browsing"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A word processor is software used to create, edit, format, and print text documents.Common uses include typing letters, reports, applications, and other documents.Examples include Microsoft Word, Google Docs, and LibreOffice Writer.Last verified on 25-08-2026', 0, 0, 0, 1790966326448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b7ab7c006f1f34f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Header and Footer command are located on the _______ tab in MS Word.', '{"A":"Home","B":"Insert","C":"View","D":"Header"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, Header and Footer options are found in the Insert tab.Go to the Insert tab on the top ribbon.Look for the Header & Footer group.Click on Header or Footer to pick a design or create your ownLast updated 07-09-2026 by NA', 0, 0, 0, 1790966326448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ea5b29340ca9b298', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the default page orientation in MS-Word?', '{"A":"Long sides","B":"Portrait","C":"Landscape","D":"Double Long side"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The default page orientation in MS Word is Portrait.Portrait orientation means the page height is greater than its width.This orientation is commonly used for documents, letters, and reports.Additional information:Page orientation can be changed from Layout → Orientation.Landscape mode is mainly used for tables and wide content.Last verified on 17-01-2026', 0, 0, 0, 1790966326448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_23903fa5aa1dc239', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In Microsoft Word shortcut key CTRL+P is used for ______?', '{"A":"Close the current window","B":"Open the print dialog box","C":"Update the current webpage","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut key to print a document is Ctrl + P.Additional Information:Hyphen (-) is used to select a range for printing a document.By default, the documents are printed in portrait-oriented mode.Ctrl + A = select allCtrl + B = BoldCtrl + I = ItalicCtrl + P = PrintCtrl + Y = RedoCtrl + S = SaveLast verified on 10-08-2026', 0, 0, 0, 1790966326448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_018d387adada68c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl + V shortcut is used in Microsoft Word to ______?', '{"A":"Copy text or an object","B":"Cut text or an object","C":"Paste text or an object from the clipboard","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + V pastes copied or cut content from the Clipboard.Additional information:Ctrl + C copies selected content to the Clipboard.Ctrl + X cuts selected content and places it on the Clipboard.Ctrl + A selects all content in the document.Ctrl + B applies bold formatting to selected text.Last verified on 10-08-2026', 0, 0, 0, 1790966326448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e359574605a38953', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which of the following is not software? Operating System, Keyboard, Drivers, Word Processor', '{"A":"Operating System","B":"Keyboard","C":"Drivers","D":"Word Processor"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keyboard is not software; it is a hardware device used for input.Software refers to programs that run on a computer.Operating System, Drivers, and Word Processor are all software types.Hardware includes physical components you can touch.Keyboard is used to enter data into the computer.Last verified on 08-06-2026', 0, 0, 0, 1790966326448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2dd8f02d7c775171', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the shortcut key for a manual line break in MS Word?', '{"A":"Shift + Enter","B":"Space + Enter","C":"Ctrl + Enter","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shift + Enter inserts a manual line break in MS Word without starting a new paragraph.It moves the cursor to the next line while keeping the text within the same paragraph.Additional information:Enter: Starts a new paragraph.Ctrl + Enter: Page break.Last verified on 09-08-2026', 0, 0, 0, 1790966326448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a4cd0127b4371e74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the shortcut key for searching a file in MS Word 2016?', '{"A":"Ctrl + F","B":"Ctrl + S","C":"Ctrl + O","D":"Ctrl + H"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + F is the shortcut key used to search/find text within a document in MS Word 2016.It opens the Navigation Pane, where you can type the word or phrase you want to find.Additional information:Ctrl + H: Find and Replace.Ctrl + S: Save the document.Ctrl + O: Open an existing document.Ctrl + N: Create a new document.Last verified on 09-08-2026', 0, 0, 0, 1790966326540) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_02663be87e23eb71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'To delete the selected text in MS Word, which key is used?', '{"A":"Delete","B":"Ctrl","C":"Alt","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To delete selected text in MS Word, press the Delete (Del) key.The selected/highlighted text is removed immediately.The Backspace key can also remove selected text.Ctrl + X cuts the selected text and places it on the clipboard.Last verified on 09-08-2026', 0, 0, 0, 1790966326540) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f626868aeccb8937', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the maximum Zoom Percentage in MS Word?', '{"A":"400%","B":"500%","C":"10%","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zoom sizeMS Word (minimum)10%MS Word (maximum)500%MS PowerPoint (minimum)10%MS PowerPoint(maximum)400%MS Excel (maximum)400%MS Excel (minimum)10%Last verified on 05-08-2026', 0, 0, 0, 1790966326540) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6522ad7821932a8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word, Ctrl + Pageup is used to _____?', '{"A":"Move the cursor one lineup","B":"Move the cursor one screen up","C":"Move the cursor one paragraph up","D":"Move the cursor one page up"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Page Up: Move the cursor or page up one screen.Additional information:Ctrl + Home: Move to the top of a document.Ctrl + End: Move to the bottom of a document.Page Down: Move the cursor or page down one screen.Last verified on 09-08-2026', 0, 0, 0, 1790966326540) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4e9e12e665a8bd5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Why Drop Caps are used in documents in MS Word?', '{"A":"To begin a paragraph with a large dropped initial capital letter","B":"To drop all the capital letters","C":"To automatically begin each paragraph with capital letter","D":"None of above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Drop Cap enlarges the first letter of a paragraph and makes it extend down several lines.Additional information:The maximum number of lines that can be set for a Drop Cap in Microsoft Word is 10.The minimum number of lines is 1.The default setting is 3 lines.Last verified on 07-08-2026', 0, 0, 0, 1790966326540) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_86db6b4f60a9684f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'How can you insert a page break in Microsoft Word?', '{"A":"Ctrl + Tab","B":"Ctrl + Enter","C":"Ctrl + Alt","D":"Ctrl + Shift"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shortcut Key: Ctrl + EnterRibbon Path: Layout → Breaks → PagePurpose: Start a new pageWorks In: Microsoft WordType: Manual Page BreakLast verified on 03-04-2026', 0, 0, 0, 1790966326540) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7016aa3501f0fc59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'MS Word is which type of software?', '{"A":"Spreadsheet software","B":"Database software","C":"Word processor","D":"Presentation software"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Word is a widely used word processor developed by Microsoft.It was first released on October 25, 1983.MS Word is an example of application software.It allows users to type and save documents.It is helpful too for making documents.Last verified on 18-07-2026', 0, 0, 0, 1790966326540) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f507aa30325f1c1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the maximum number of columns that can be inserted in MS Word?', '{"A":"35","B":"15","C":"63","D":"65"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maximum number of columns in MS word: 63Additional information:The minimum number of rows added in MS Word: 1The minimum number of columns in MS word: 1Last verified on 29-05-2026', 0, 0, 0, 1790966326540) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9f5777081df89e81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word, Portrait and Landscape are _______?', '{"A":"Page layout","B":"Page size","C":"Page Orientation","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Portrait and Landscape are the two main page orientation options in MS Word.Portrait means the page is taller than it is wide.Landscape means the page is wider than it is tall.Orientation determines the direction in which the page is displayed or printed.It can be changed from the Layout tab in MS Word.Last verified on 07-08-2026', 0, 0, 0, 1790966326665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_21dd1add1209b2a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'The minimum number of rows and columns in MS word document is ____?', '{"A":"1 and 1","B":"2 and 2","C":"2 and 1","D":"1 and 2"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The minimum table size that can be created is 1 row and 1 column.In MS Word 2016, tables are used to organize data in rows and columns.Additional information:Tables can be formatted, merged, or split according to need.Even a 1×1 table can be expanded later by adding rows or columns.Last verified on 10-03-2026', 0, 0, 0, 1790966326665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_737d1c9f82340130', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'To apply center alignment to a paragraph in MS-Word, we can press?', '{"A":"Ctrl + E","B":"Ctrl + S","C":"Ctrl + C + A","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + E is the shortcut used to apply center alignment in MS Word.Additional information:Ctrl + L → Left AlignmentCtrl + R → Right AlignmentCtrl + J → Justify AlignmentLast verified on 06-03-2026', 0, 0, 0, 1790966326665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_88e7540e92abb03d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Thesaurus tool in MS Word is used for ______?', '{"A":"Grammar options","B":"Spelling suggestions","C":"Synonyms and Antonyms words","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Thesaurus tool in MS Word is used to find synonyms and antonyms of words.Shortcut Key: Shift + F7Location: Review tab → ThesaurusLast verified on 18-07-2026', 0, 0, 0, 1790966326665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1cb7b1d761f1a1db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl + O shortcut key is used in MS Word to ______?', '{"A":"Save Document","B":"Print Document","C":"Close Document","D":"Open Document"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + O → Open DocumentAdditional information:Ctrl + S → Save DocumentCtrl + P → Print DocumentCtrl + W → Close Current DocumentCtrl + N → New DocumentLast verified on 16-07-2026', 0, 0, 0, 1790966326665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b45423b4d41da9aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the shortcut key to open a new MS Word document?', '{"A":"Ctrl + O","B":"Ctrl + N","C":"Ctrl + W","D":"Ctrl + M"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + N is to open a new document in MS Word.Additional information:Ctrl + M -- Indent the paragraph.Ctrl + B -- Bold highlighted selection.Ctrl + D -- Font options.Alt + F -- File menu options in the current program.Alt + E -- Edits options in the current program.Last verified on 19-04-2026', 0, 0, 0, 1790966326665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fbcb0cb18a71c579', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word, which shortcut is used for print preview?', '{"A":"Alt + O","B":"Ctrl + F2","C":"Shift + P","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + F2 is the shortcut key used for Print Preview in Microsoft Word.It allows users to preview a document before printing.Print Preview helps check the layout, margins, and page formatting.Additional information:Ctrl + F2 → Print PreviewCtrl + D → Open Font dialog boxCtrl + F12 → Open a documentCtrl + H → Open Replace dialog boxCtrl + P → Print the documentLast verified on 06-07-2026', 0, 0, 0, 1790966326665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ac6b5803d87ef275', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Microsoft Word (MS Word) was launched/released in which year?', '{"A":"1981","B":"1982","C":"1983","D":"1984"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft Word was first released in 1983.It was launched on 25 October 1983 under the name Multi-Tool Word for Xenix systems.It is a word processing software developed by Microsoft.Microsoft Word is used to create, edit, format, and print documents.Last verified on 06-07-2026', 0, 0, 0, 1790966326665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c63dbe238a66e82c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is MS Word primarily used for?', '{"A":"Creating and editing presentations","B":"Creating and editing documents","C":"Creating and editing images","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Word is primarily used for creating and editing documents.As a powerful word processing program, it allows users to create, format, and edit a wide range of text-based files, including letters, reports, resumes, and academic papers.Its features, such as spell-checking, grammar tools, text formatting, and image support.They are designed for comprehensive document management.Last verified on 03-04-2026', 0, 0, 0, 1790966326783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_05b460d38bdca1f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Default name of a newly created MS Word File is?', '{"A":"Document 1","B":"Untitled 1","C":"File 1","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790966326783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_548ad877bee116ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'A screen element of MS Word that is usually located below the title bar that provides multiple options (File, Home, Insert, etc)?', '{"A":"Tool Bar","B":"Menu Bar","C":"Status Bar","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Menu Bar in MS Word is located below the Title Bar.It contains multiple options like File, Home, Insert, Design, Layout, etc.It helps users access different commands easily.It is an important part of the Word interface.Last verified on 04-06-2026', 0, 0, 0, 1790966326783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fe9596c213c3ed4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word 2016, we use _____ to keep track of changes made to a particular document.', '{"A":"Marks up","B":"Track Changes","C":"Mail Merge","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Track Changes is a feature in MS Word 2016 used to record edits made in a document.It shows insertions, deletions, and formatting changes made by users.This feature is commonly used during editing, reviewing, and collaboration.Last verified on 09-03-2026', 0, 0, 0, 1790966326783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ec1f1d60f7ecca79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'If we press the F8 key thrice in MS Word, We will?', '{"A":"Automatically align the text","B":"select a paragraph","C":"Select a sentence","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, the F8 key is used for extended selection.F8 once: Start selection modeF8 twice: Select current wordF8 three times: Select current sentenceF8 four times: Select paragraphF8 five times: Select entire documentLast verified on 10-03-2026', 0, 0, 0, 1790966326783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c6bdb25ddbd9ddc8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'The Shortcut key to split a table in MS Word is?', '{"A":"Ctrl + Alt + Enter","B":"Ctrl + Shift + Enter","C":"Alt + Shift + Enter","D":"Alt + space + Enter"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Shift + EnterSplits a table into two separate tablesCursor must be placed in the row where split is neededCommonly used in document formattingTable splitting option is also available from:Table Tools → Layout → Split TableLast verified on 29-05-2026', 0, 0, 0, 1790966326783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ed401396ebc8307e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is gutter margin in MS Word?', '{"A":"Margin that is added to the Left margin when printing","B":"Margin that is added to the binding side of page  when printing","C":"Margin that is added to the right margin when printing","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Definition: Margin added to the binding side of the documentPurpose: Prevents text from being hidden in the bindingLocation: Can be added to left or top depending on binding typeAdjustable in: Layout > Margins > Custom Margins > GutterLast verified on 16-01-2026', 0, 0, 0, 1790966326783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6a003905cd99c939', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the shortcut key for Help in MS Word?', '{"A":"F1","B":"F2","C":"F3","D":"F4"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, the Help feature is used to get guidance about tools and commands.The shortcut key to open Help is F1.It opens Microsoft Word Help window or support page.Additional information:F2: Used to move or rename text.F3: Inserts AutoText entries if available.F4: Repeats the last action performed.F5: Opens the "Find and Replace" dialog box with the "Go To" tab active.Last verified on 29-05-2026', 0, 0, 0, 1790966326783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b8e424d1b802a317', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the function of ruler in MS Word?', '{"A":"To set tabs","B":"To change page margins","C":"To set indents","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Ruler in MS Word is used for formatting and alignment.It helps set tabs, page margins, and indents.It improves document layout and text positioning.Both horizontal and vertical rulers assist in precise formatting.Last verified on 29-05-2026', 0, 0, 0, 1790966326875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3b82f8edb1127be1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which of the following is not a type of page margin in MS Word 2016? Top, Center, Left, Right', '{"A":"Top","B":"Center","C":"Left","D":"Right"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word 2016, page margins define the space between the text and the edge of the page.Common margin types are: Top, Bottom, Left, Right.“Center” is not a page margin type.Last verified on 10-03-2026', 0, 0, 0, 1790966326875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_feb24e01981dac6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which of the following is not paper size in MS-Word 2016? Legal, Executive, Landscape, A3', '{"A":"Legal","B":"Executive","C":"Landscape","D":"A3"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Landscape is a page orientation, not a paper size.Common paper sizes in MS-Word 2016 include: Letter, Legal, Executive, A4, A3.Additional information:Legal: 8.5 × 14 inchesExecutive: 7.25 × 10.5 inchesA3: 297 × 420 mmLetter: 8.5 × 11 inchesA4: 210 × 297 mmLast verified on 08-03-2026', 0, 0, 0, 1790966326875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_625005ece50162f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'A “Ctrl + Enter” command in MS-Word 2016 will ______?', '{"A":"Create a new page / Page break","B":"Create a new paragraph","C":"Create a new line","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Enter inserts a page break in a Word document.It moves the cursor to the top of the next page without adding extra paragraphs.Useful for starting a new section or chapter.Additional information:Enter – creates a new paragraphShift + Enter – creates a new line without paragraph spacingCtrl + Home – move cursor to the beginning of the documentLast verified on 08-03-2026', 0, 0, 0, 1790966326875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9878bdf918ce4e89', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In Microsoft Word, how can you increase the font size of selected text by one point every time?', '{"A":"By pressing Ctril +]","B":"By pressing Ctrl _[","C":"By pressing Ctrl = }","D":"By pressing Ctrl + {"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, Ctrl + ] increases the font size of selected text by 1 point.Similarly, Ctrl + [ decreases the font size by 1 point.Additional information:Shortcut to increase font: Ctrl + ]Shortcut to decrease font: Ctrl + [Last verified on 07-03-2026', 0, 0, 0, 1790966326875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ab23e0693b5f5174', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In Microsoft Word the Superscript, subscript, shadow, outline, emboss, and engrave are known as _____?', '{"A":"Font effects","B":"Text effects","C":"Font styles","D":"Word art"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, these options are used to enhance the appearance of text.They are part of Font formatting tools in the Home tab → Font group → Text Effects and Typography.Additional information:Superscript: Raises text above normal lineSubscript: Lowers text below normal lineShadow: Adds shadow behind textOutline: Shows text as outlined lettersEmboss: Makes text appear raisedEngrave: Makes text appear carved into the pageLast verified on 07-03-2026', 0, 0, 0, 1790966326875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a36d0373a7ebef77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'To change line height (line spacing) to 1.5 in MS-Word 2016 we use shortcut key?', '{"A":"Ctrl+Q","B":"Ctrl+1","C":"Ctrl+2","D":"Ctrl+5"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Line spacing shortcuts:Ctrl + 1 → 1.0Ctrl + 2 → 2.0Ctrl + 5 → 1.5Last verified on 07-03-2026', 0, 0, 0, 1790966326875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9c6a764070101ad2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'A number or letter that appears little below the normal text in MS-Word 2016 is called _____?', '{"A":"Subscript","B":"Superscript","C":"Supertext","D":"Toptext"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS-Word 2016, a subscript is a number or letter written slightly below the normal text.Commonly used in chemical formulas, mathematical expressions, and scientific writing.Example: H₂O → the “2” is a subscript.Additional information:Superscript: Written above the normal text (e.g., x²)Last verified on 19-01-2026', 0, 0, 0, 1790966326875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0b3bf6d87da28aae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'The paragraph mark (¶) is a formatting mark that indicates where the __________ was pressed in a MS-Word document.', '{"A":"Tab key","B":"Spacebar","C":"Enter key","D":"Shift key"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The paragraph mark (¶) in MS Word shows the end of a paragraph.It appears when the Enter key is pressed.It helps in viewing hidden formatting while editing documents.Last verified on 06-03-2026', 0, 0, 0, 1790966326986) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f77bd0c41be130d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which feature in Microsoft Word allows you to create a table of contents?', '{"A":"Page Layout","B":"Review","C":"References","D":"Home"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation With your document open, select the "References" tab on the ribbon, then select "Table of contents.Last updated 15-feb-2026', 0, 0, 0, 1790966326986) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b0bcc5a91ca85b1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which of the following is an example of a spreadsheet application? Notepad, Microsoft Word, Microsoft Excel, Adobe Photoshop', '{"A":"Notepad","B":"Microsoft Word","C":"Microsoft Excel","D":"Adobe Photoshop"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft Excel is Microsoft''s spreadsheet program that can be used to organize, format, and calculate data.Microsoft Excel is a spreadsheet application used for calculations, charts, and data analysisLast verified on 10-02-2026', 0, 0, 0, 1790966326986) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_849d43bfe20a20a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Microsoft Word displays hyperlinks as a _______?', '{"A":"Red underlined text","B":"Blue underlined text","C":"White underlined text","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft Word, hyperlinks are shown as blue underlined text by default.The blue color helps users easily identify clickable links.After clicking, the link color may change, but the default is blue.Last verified on 29-01-2026', 0, 0, 0, 1790966326986) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a7cbce449b57b96e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which ribbon tab in MS Word contains options for formatting text, such as changing font styles and sizes?', '{"A":"Home","B":"Review","C":"Insert","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Home tab contains tools for text formatting, including font style, size, color, and alignment.It is the primary tab used for editing and styling the content of a document.Additional information:Home tab also includes clipboard, paragraph, and styles groups.Last verified on 20-01-2026', 0, 0, 0, 1790966326986) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fef971f9361a7083', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Minimum and maximum font size in MS Word is _____?', '{"A":"8-72","B":"6-60","C":"12-50","D":"8-96"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Minimum font size: 8Maximum font size: 72Additional information:Standard font size: 12Manual font size range: 1–1638Shortcut to change font size manually: Ctrl + Shift + PIncrease font size: Ctrl + ]Decrease font size: Ctrl + [Last verified on 17-01-2026', 0, 0, 0, 1790966326986) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_94588a6b9088772a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Where is the Print option located in MS Word?', '{"A":"Edit > Print","B":"Insert > Print","C":"File > Print","D":"View > Print"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation File > Print. To print a document in Microsoft Word, you click on the File tab in the top-left corner of the screen, This opens the Backstage view, and then select Print from the menu that appears on the left.', 0, 0, 0, 1790966326986) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d7d491e3471f2ef1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'A Red wavy line in MS Word indicates that _____?', '{"A":"Misspelled word/Spelling Error","B":"Character mistakes","C":"Grammatical mistakes","D":"Spacing  mistakes"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A red wavy line in MS Word indicates a spelling error.A green wavy line indicates a grammar error.A blue wavy line indicates a word usage error (such as incorrect word choice).', 0, 0, 0, 1790966326986) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ba7b11554f7e7d48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word and Excel, to combine two or more cells into one is called?', '{"A":"Joining","B":"Merging","C":"Split","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process of combining two or more cells into a single cell in MS Word or Excel is called "merging."This is commonly used for formatting tables or organizing data.', 0, 0, 0, 1790966327165) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2ffd0537713d8e5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which feature in MS Word allows you to track changes made to a document?', '{"A":"Spelling and Grammar","B":"Track Changes","C":"Word Count","D":"AutoCorrect"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The "Track Changes" feature in MS Word allows you to track changes made to a document.It enabling users to see edits, additions, and deletions made by different collaborators.This tool is essential for reviewing and managing document revisions efficiently.', 0, 0, 0, 1790966327165) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_12ef115dcbfbae4f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which Short cut key for opening the font dialog box in Microsoft Word?', '{"A":"CTRL+B","B":"CTRL+D","C":"CTRL+C","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Ctrl+D key is used to open the Font dialog box with the focus on the Font combo box.Ctrl+F12 opens a document in Word. The Ctrl+D key is used to open the Font dialog box.Ctrl + H is used to open the Replace Dialog Box. ND22-6-2023', 0, 0, 0, 1790966327165) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_22d4636b51bb07ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl + F Shortcut key is used in MS Word to _____?', '{"A":"Open Find and Replace Dialog box with activating Find Tab","B":"Open Page Setup Dialog box with activating Layout Tab","C":"Open Font Dialog Box with activating Font tab","D":"Open File Save as Dialog box"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation mportant keysCtrl+N - Create a new documentCtrl+O - Open an existing documentCtrl+S - Save a documentF12 - Open the Save As dialog boxCtrl+W - Close a documentCtrl+Z - Undo an actionCtrl+Y - Redo an actionAlt+Ctrl+S - Split a window or remove the split viewCtrl+F - Search a document"Ctrl + End" is used to move the cursor to the end of the Document.Ctrl + E is used to align the text in the Centre slide of a paragraph', 0, 0, 0, 1790966327165) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ea56be56cc9b3e32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl + W Shortcut is used in Microsoft Word to _____?', '{"A":"Save and Print the Document","B":"Save and Close Word Application","C":"Save and Close document","D":"Close Document"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alternatively referred to as Control W and C-w, Ctrl+W is a shortcut key most often used to close a program, window, tab, or document.', 0, 0, 0, 1790966327165) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6d5f04e04b2b980b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the default fount size in a new word document based on normal template in word 2003?', '{"A":"12 pt","B":"11 pt","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The default font size in a new Word document in Word 2003Font: Times New Roman.Size: 12-point.Style: Normal.Last updated by NS on 06 May 2026', 0, 0, 0, 1790966327165) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_af2d2a0ad3f9af8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'The file extension of Microsoft Word 97 - 2003 is ____?', '{"A":".doc","B":".docs","C":".docx","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DOCX is the newer version of DOC, the original official Microsoft Word file format. Microsoft Word 97 - 2003 Document extension (.doc)Microsoft Word 2007 to till date Document extension (.docx)', 0, 0, 0, 1790966327165) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_518f09cea974b87e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which of the following is used to edit a chart in MS Word?', '{"A":"Drag the chart","B":"Right click on the chart","C":"Left click on the chart","D":"Double click on the chart"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Double-clicking a chart in MS Excel opens the chart editing options.This allows you to modify elements like titles, labels, colors, and data.', 0, 0, 0, 1790966327165) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_69709ace825c44d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which is the Text Styling feature in MS-Word?', '{"A":"Word style","B":"Word design","C":"Word art","D":"Design"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Word Art is the Text Styling feature in Microsoft Word.', 0, 0, 0, 1790966327273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9202f7e31ed56035', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which of the following is an application software? Microsoft word, Processing unit, Adder and logical unit, Accumulator, Comparison unit', '{"A":"Microsoft word","B":"Processing unit","C":"Adder and logical unit","D":"Accumulator","E":"Comparison unit"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Application software is designed to accomplish Operating system tasksApplication software is third-party softwareApplication software is designed to accomplish tasks for a specific purpose based on user requests.typically to be used by end-users.Word processors,media players,and accounting software******AGM 08-2-2023', 0, 0, 0, 1790966327273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5231d8512644463e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which of the following is an example of a multimedia application? Notepad, Microsoft Word, Adobe Photoshop, Microsoft Excel', '{"A":"Notepad","B":"Microsoft Word","C":"Adobe Photoshop","D":"Microsoft Excel"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adobe Photoshop is an example of Multimedia Application. Photoshop is an image creation, graphic design and photo editing software developed by Adobe.', 0, 0, 0, 1790966327273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3952ddba1095123c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl+x in Ms word used for :', '{"A":"Cut","B":"Paste","C":"Space","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft Word and other word processors, pressing Ctrl + X cuts any text, picture, or other object that is selected.Ctrl + Z used for = UndoCtrl + X used for = CutCtrl + Y used for = Redo', 0, 0, 0, 1790966327273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f3caeea3ad2ee033', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word 2007, which shortcut key is used to replace text or specific formatting?', '{"A":"CTRL + T","B":"CTRL + I","C":"CTRL + H","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CTRL + H opens the "Find and Replace" dialog box.It allows you to replace text or specific formatting in MS Word 2007.Additional informationCTRL + I: Italicizes selected text.CTRL + T: Creates a hanging indentCtrl + F: Opens the Find tab to search for text or formatting.Ctrl + G: Opens the Go To tab to navigate to a specific page or element.Ctrl + Shift + C: Copies selected text formatting.Ctrl + Shift + V: Pastes copied text formatting.', 0, 0, 0, 1790966327273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8a3da6b3f1362b9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the maximum font size you can apply for any character in Ms Word?', '{"A":"1638","B":"1636","C":"1645","D":"1600"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS word Minimum font size: 8Maximum font size: 72Standard font size: 12Ms Word manually font size (1-1638)Ctrl + Shift + P is used to change the font sizeTo increase the font size, press Ctrl + ] .To decrease the font size, press Ctrl + [ .', 0, 0, 0, 1790966327273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6c7085783dcc0193', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS word short cut "Shift+Delete " is used to', '{"A":"Delete the selected item permanently without placing the item in recycle bin","B":"Copy the selected item","C":"Rename the selected item","D":"Create a short cut to selected item"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shift + Delete in MS Word (and Windows generally) is used to: Delete the selected item permanently without placing the item in the Recycle Bin.This means the file or text bypasses the Recycle Bin and is removed immediately. Use with caution.', 0, 0, 0, 1790966327273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_85ee7eca8051a751', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which key is used to start a new paragraph in MS Word?', '{"A":"Shift + Home","B":"End","C":"Enter key","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Enter key is used to start a new paragraph in MS Word*****Most repeated questions about shortcut keyGoes to the beginning of the current line = HomeGoes to beginning of document = Ctrl + HomeGoes to end of current line = EndGoes to end of document = Ctrl + EndHighlights from the current position to the beginning of line = Shift + HomeHighlights from current position to end of line = Shift + EndCut selected item = Shift + Del & Ctrl + XCopy selected item = Ctrl + C Paste selected item = Ctrl + V', 0, 0, 0, 1790966327273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_aba0b81959ce3c77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Ctrl + D shortcut key is used for _____ in MS Word document.', '{"A":"Bold","B":"Font","C":"Alignment","D":"Justification"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + D is used to open the Font dialog box in MS Word.It where you can change font settings. Bold: Ctrl + BAlignment:Ctrl + E (Center)Ctrl + L (Left)Ctrl + R (Right)Justification: Ctrl + J', 0, 0, 0, 1790966327362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_52f9c0765ae30897', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the shortcut key in MS Word to apply ''Change Case''?', '{"A":"Shift + F2","B":"Shift + F3","C":"Shift + F4","D":"None of These"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut key to change case in MS-Word is: Shift + F3There are five change cases in MS Word:Sentence CaseLowercaseUppercaseTitle CaseToggle Case', 0, 0, 0, 1790966327363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c057f3a6920ec418', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which key is used for left alignment in MS Word?', '{"A":"CTRL+R","B":"CTRL+M","C":"CTRL+L","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To align the text left, press Ctrl+L. To align the text right, press Ctrl+R. To center the text, press Ctrl+E.', 0, 0, 0, 1790966327363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f583100d1c59e2fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'MS Word is mostly used for ______?', '{"A":"Creating  documents","B":"Letters","C":"Assignments","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft Word is a word processor developed by Microsoft. It was first released on October 25, 1983, under the name Multi-Tool Word for Xenix systems.******', 0, 0, 0, 1790966327363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_29c5fd3c4c897d7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Microsoft Word is _____?', '{"A":"Cell","B":"Document","C":"Workbook","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft Word is a document-based word processing application used for creating, editing, and formatting text documents.It allows users to produce a variety of content such as letters, reports, essays, and more.', 0, 0, 0, 1790966327363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6062e46deff5439f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'The shortcut key to close the currently opened document in Microsoft Word is ______?', '{"A":"Ctrl + T","B":"Ctrl + D","C":"Ctrl + W","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + W is a shortcut key to close a document in MS Word.Additional Information:open in documentCrtl+OCreate a new documentCrtl+NSave the documentCrtl+XCut the selected content to the clipboardCrtl+CPaste the contents of the clipboardCrtl+VSelect all document contentCrtl+AApply italic formatting to the textCrtl+IApply underlined formatting to text.Crtl+UDecrease the font size by 1 point.Crtl+[Increase the font size by 1 pointCrtl+]ND13-1-2023', 0, 0, 0, 1790966327363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_63ad4758cedb8c48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word, we can create another copy of documents by _____?', '{"A":"Save as","B":"Save","C":"Print","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You can save the document in Microsoft Word in three ways:You can save by clicking File on the top left corner You can also save by just pressing ctrl + S Just press F12', 0, 0, 0, 1790966327363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3c1128bea35ba0ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Green line in MS Word document represent ________?', '{"A":"Spell error","B":"Grammatical error","C":"Sentence error","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The red line indicates a misspelled word.The green line indicates a grammatical error. The blue line indicates a contextual spelling error. This feature is turned off by default.', 0, 0, 0, 1790966327363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_56d8cf17ddbfaecb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word Ctrl + E is used to align the text in _____ slide of a paragraph.', '{"A":"Left","B":"Centre","C":"Right","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Important keysCtrl+N - Create a new documentCtrl+O - Open an existing documentCtrl+S - Save a documentF12 - Open the Save As dialog boxCtrl+W - Close a documentCtrl+Z - Undo an actionCtrl+Y - Redo an actionAlt+Ctrl+S - Split a window or remove the split viewCtrl+F - Search a document"Ctrl + End" is used to move the cursor to the end of the Document.Ctrl + E is used to align the text in the Centre slide of a paragraphND7-5-2023', 0, 0, 0, 1790966327509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_62cae1d0a8468f67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which wavy line shows that the word is repeated in MS Word?', '{"A":"Green","B":"Red","C":"Blue","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word,a blue wavy line indicates a grammar problem. Blue Wavy Line: Repeated word or phrase.Red Wavy Line: Potential spelling error.Green Wavy Line: Possible grammatical error.Purple Dotted Line: Suggests a contextual refinement for style or clarity.', 0, 0, 0, 1790966327509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fb43881a25abed7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'MS Word standard page size which is used in offices is ______?', '{"A":"Legal","B":"B4","C":"A4","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Word standard page size which is used in offices is A4.The standard includes the A4 size, which is a common size worldwide for business and personal use.', 0, 0, 0, 1790966327509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7ae4694b153ed17d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'F9 key in Microsoft Word used for _____?', '{"A":"Enter word  and expand a selection","B":"Enter word selection  and expand a selection","C":"Enter word selection mode and expand a selection","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790966327509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a154d924da5738ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which file starts MS Word?', '{"A":"Word.exe.","B":"Msword.exe.","C":"Winword.exe","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Winword.exe stands for Microsoft Word or Windows WordWinword.exe is the executable file name for Microsoft Word which is used when Word is launched.Winword.exe is Microsoft Word,the most popular word-processing softwareND5-2-2023', 0, 0, 0, 1790966327509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5fa2f38be9e83f20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word 2016, which of the following shortcut key is used to use paste special?', '{"A":"CTRL + V","B":"CTRL + ALT + V","C":"CTRL + TAB + V","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To use Paste Special in Microsoft Word 2016, you can use the keyboard shortcut Ctrl+Alt+V.This will open the Paste Special dialog box, where you can choose to paste formatted or unformatted text, or an image.', 0, 0, 0, 1790966327509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_17fd0e7053253e38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'MS Word is ________ software?', '{"A":"Application","B":"C++","C":"Compiler","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Word is a widely used word processor developed by Microsoft.It was first released on October 25, 1983.MS Word is an example of application software.It allows users to type and save documents.It is helpful too for making documents.', 0, 0, 0, 1790966327509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_33a091650d155493', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'By default on which page the header or the footer is printed in MS Word Document?', '{"A":"On first page","B":"On alternate page","C":"On every page","D":"None of above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A header is a text that is placed at the top of a page, while a footer is placed at the bottom, or foot, of a page. By default, on MS-Word the header or footer is printed on every page. It can be changed in the Header and Footer menu.', 0, 0, 0, 1790966327509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_109b8f5b438bfc18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'How can you run an already existing document in Microsoft Word?', '{"A":"Save","B":"Open","C":"New","D":"Edit"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To work on an already existing document in MS Word, you select "Open" from the File menu.It allowing you to access and edit the document.', 0, 0, 0, 1790966327687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4aedc52894761bca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What appears at the bottom of the MS Word Page?', '{"A":"Header","B":"Footer","C":"Footnote","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Footer is the text that appears at the bottom of every page of the document. In Microsoft Word, the top margin of a page is called its header, and the bottom margin is called the footerND10-3-2023', 0, 0, 0, 1790966327687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_298c26ee48c363fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the shortcut key create subscript in MS-Word?', '{"A":"Alt+Shift+delete","B":"Ctrl+ =","C":"Ctrl+S","D":"Alt+=","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Superscript & subscript are known as Font effects.Superscript is used to create small letters above the line of text.Subscript is used to create small letters below the line of textSubscript shortcut key: Ctrl, Shift + Plus sign (+)Superscript shortcut key: Ctrl, Shift, and the Plus sign (+) at the same time.', 0, 0, 0, 1790966327687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5f403050e86032d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which tab of MS-Word contains the shapes option', '{"A":"Home","B":"Review","C":"Insert","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Step 1: On the navigation menu click on the insert option. Step 2: In the illustration section select the shapes option as shown in the figure: Step 3: A list of shapes will pop up on the screen where you can select different types of shapes.', 0, 0, 0, 1790966327687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4c03c45a16789913', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Single spacing in MS-Word document causes ____ point line spacing?', '{"A":"10","B":"12","C":"14","D":"16"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The point unit represents the size of the font and space between lines; 1 point equals 1/72 of an inch.The default line spacing in Word is 1.15.', 0, 0, 0, 1790966327687) ON CONFLICT(id) DO NOTHING;
