INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_de7555cb1cccbc95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'To edit the Header & Footer in MS Word 2016, which option is used?', '{"A":"Page Layout","B":"References","C":"Insert","D":"Home"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To edit the Header/Footer in MS Word 2016, you would typically use the "Header & Footer" option located under the "Insert" tab on the ribbon.This option allows you to add, edit, or remove headers and footers in your document.', 0, 0, 0, 1790966327687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0b7ec1f1e60e0198', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'The shortcut for copy command in MS Word is ____?', '{"A":"Ctrl+C","B":"Ctrl+X","C":"Alt+X","D":"Shift+Alt+X"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Important Short cut keysCopy: Ctrl+CCut: Ctrl+XPaste: Ctrl+VND22-6-2023', 0, 0, 0, 1790966327687) ON CONFLICT(id) DO NOTHING;
