INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4377cb01ff8084e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'The default language of Microsoft Word is ______?', '{"A":"UK English","B":"Canadian English","C":"USA English","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The default language of Microsoft Word is set to USA English unless changed by the user.This setting applies to spelling, grammar checks, and formatting in the document.', 0, 0, 0, 1790966327789) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d3ab3daa6078526b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word 2007 which shortcut key is used to insert a comment?', '{"A":"Alt+Ctrl+M","B":"Alt+Ctrl+C","C":"Shift+Ctrl+M","D":"Shift+Ctrl+C","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Comments can be added to cells using Insert > Comment.Right-click the cell and then click Insert Comment (or press Shift+F2).ND4-672023', 0, 0, 0, 1790966327789) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_40ef759465125911', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word, a master document contains _______ of subdocument?', '{"A":"Links","B":"Placeholders","C":"Files","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, a master document contains links (or sometimes referred to as pointers/files) of subdocuments. When the master document is saved, each subdocument is saved as a separate fileLast updated by NS on 06 May 2026', 0, 0, 0, 1790966327789) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ba673fa40a9ab6d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Home Keyboard Key is used in MS Word to _______?', '{"A":"Moves the cursor beginning of the line","B":"Moves the cursor beginning of the document","C":"Moves the cursor beginning of the paragraph","D":"Moves the cursor beginning of the screen"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, the "Home" keyboard key is used to move the cursor to the beginning of the current line.This shortcut is often used to quickly navigate to the start of a line, especially when editing or formatting text.', 0, 0, 0, 1790966327789) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9883194c71a9105e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'A table in Microsoft Word consists of ______?', '{"A":"Rows and columns","B":"Text and images","C":"Charts and graphs","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A table in Microsoft Word is a grid-like structure composed of:Rows (horizontal lines)Columns (vertical lines)These rows and columns intersect to form cells, which can contain text, images, or other content.Last updated 27-07-2026 by NA', 0, 0, 0, 1790966327789) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d547e4b0ec4d6522', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the smallest width of a column in MS Word?', '{"A":"0.5","B":"1.0","C":"1.5","D":"2.5"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Minimum column width: 0.5 inchesUsed when setting columns in MS Word.Additional information:Microsoft Word page limit: Maximum 22 inches on any sideWord table width limit: Cannot exceed the 22-inch page maximum.Microsoft Excel column limit: Maximum of 255 characters per cell. Last updated NA on 10-09-2026', 0, 0, 0, 1790966327789) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_371ca5759a93c938', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the shortcut key for “Change the font" in MS Word?', '{"A":"Ctrl + Shift + F","B":"Alt + shift + F","C":"Alt + F","D":"None of These"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Shift + F is the shortcut key for “Change the font" in MS Word.Open the Font dialog box to change the font. Ctrl+Shift+F.Increase the font size. Ctrl+Shift+>Decrease the font size. Ctrl+Shift+<Increase the font size by 1 point. Ctrl+]Decrease the font size by 1 point. Ctrl+[RK11.06.2023', 0, 0, 0, 1790966327789) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8ed75c2f2c914b6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which of following is not available on the ruler of MS Word screen?', '{"A":"Tab stop box","B":"Left indent","C":"Right indent","D":"Center indent","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Center Indent is not available on the Ruler of MS Word screen.', 0, 0, 0, 1790966327902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_99c0170e9bb6486e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'MS Word''s default spacing line is?', '{"A":"1.5","B":"1.15","C":"1.115","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The default spacing is 1.15 lines, which gives you a bit more room between lines and 10 points of spacing after each paragraph for better readabilityRemove paragraph formatting. Ctrl+QApply single spacing to the paragraph. Ctrl+1Apply double spacing to the paragraph. Ctrl+2Apply 1.5-line spacing to the paragraph. Ctrl+5ND1-5-2023', 0, 0, 0, 1790966327902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_da525e1934235e20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Which menu is used to insert table in Ms Word?', '{"A":"File Menu","B":"Tool Menu","C":"Insert Menu","D":"Format Menu","E":"Font Menu"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Insert tab (or menu) on the top ribbon is used to insert a table in Microsoft Word. ان سولات کو ضرور پڑھیںClick hereLast updated 27-07-2026 by NA', 0, 0, 0, 1790966327902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_52dceda776d9b059', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Enable drawing text in an MS Word document?', '{"A":"Word art","B":"Macros","C":"Templates","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To enable and use WordArt in Microsoft Word for stylized, "drawn" text WordArt button (represented by a slanted ''A'')This creates a customizable text box for applying effects like transforms, shadows, and 3D rotations. Last updated 15-feb-2026', 0, 0, 0, 1790966327902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e49a58b402239737', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS-Word, Thesaurus option is available in?', '{"A":"Reference Tab","B":"Review Tab","C":"View Tab","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Word, the Thesaurus tool is used for synonyms and antonyms.Shift + F7 is the shortcut key for the Thesaurus tool.', 0, 0, 0, 1790966327902) ON CONFLICT(id) DO NOTHING;
