INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f51ce69ffc8297c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'We can start MS Word by typing ____ in the run Dialogue Box :', '{"A":"MSword ,exe","B":"Winword.exe","C":"Word.exe","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Command winword.exe is used to start MS Word in the Run Dialog boxTo quickly access the Run command dialog box, simply press the Windows key + RUseful Run Commands are• Temp -Opens Windows temporary folder• %temp% - Opens the user''s temporary folder• PowerPoint - Microsoft PowerPoint• MSpaint- Microsoft Paint• Shutdown - Shutdown Computer', 0, 0, 0, 1790966327902) ON CONFLICT(id) DO NOTHING;
