INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_622a30cac44d9c2d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Press _______ key to display the print dialogue box, in MS Word.', '{"A":"Ctrl+B","B":"Alt+P","C":"Ctrl+N","D":"Ctrl+P"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS-word, Ctrl + F2 is used for print preview.Ctrl+D key is used to open the Font dialog box with the focus on the Font combo box.Ctrl+F12 opens a document in the Word. Ctrl+D key is used to open the Font dialog box.Ctrl + H is used to open the Replace Dialog Box.', 0, 0, 0, 1790966328056) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cba8f501cdeab7ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In Microsoft word , Micros are______?', '{"A":"Small program created in MS Word  to automate repetitive tasks by using VBA","B":"Large tool in word such as mail merge","C":"both","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A macro is a series of commands and instructions that you group together as a single command to accomplish a task automatically. **********VU CBT FIA PAPER 25-12-2021', 0, 0, 0, 1790966328056) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1c55ff4dc5e88ec5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In Microsoft word,ctrl+1 is used for which of following?', '{"A":"To set 1.5 line spacing","B":"To set double line spacing","C":"To set 0.5 line spacing","D":"To set single line spacing","E":"All"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft Word, Ctrl + 1 is used to set single-space lineCtrl + 2: Double-space lines (2.0 spacing)Ctrl + 5: Set 1.5-line spacingAdditional information:In Microsoft Excel, Ctrl+1 is used to open the Format Cells dialog box. Last updated NA on 10-09-2026', 0, 0, 0, 1790966328144) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2a0f5c485b982982', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'What is the minimum number of rows in MS-word----?', '{"A":"2 rows 2 columns","B":"3 rows 3 columns","C":"1 row 1 column","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The minimum number of rows and columns in MS Word document is 1 row and 1 column.', 0, 0, 0, 1790966328144) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e052a775c57c9e4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'In MS Word 2016, which of the following command is not available in Insert menu?', '{"A":"Columns","B":"Table","C":"Page number","D":"Object"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The insert menu is used to place various objects into your document, such as page numbers, pictures, symbols, comments and other objects. Commands include break, date and time, field, symbol, reference, web component, text box, file and hyperlink.', 0, 0, 0, 1790966328144) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8f3bafcdca63d0d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'Graphics in MS Word is called ?', '{"A":"Clip art","B":"Word Art","C":"Home menu","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ClipArt refers to a pre-made image ready for use in MS Word documents.', 0, 0, 0, 1790966328144) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4f62468fd396c917', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', 'You cannot close MS word application by ___', '{"A":"Choosing close submenu from file Menu","B":"Clicking X button on title bar","C":"Choosing file menu first then exit sub menu","D":"Alt+ F4"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You cannot close the MS Word application by choosing the "File" menu, then the "Exit" submenu. Choosing the File menu, then the Exit submenu: While this is a common way to access exit options within a program, it doesn''t directly close the entire MS Word application.', 0, 0, 0, 1790966328144) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e8861aa46dc621b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_word', '“Ctrl + Down Arrow” Shortcut key is used in Ms Word to ____?', '{"A":"Moves the cursor one paragraph down","B":"Moves the cursor one line down","C":"Moves the cursor one page down","D":"Moves the cursor one screen down","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Ctrl + Up Arrow” Shortcut key is used in Microsoft Word to move the cursor one paragraph up.', 0, 0, 0, 1790966328144) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_comp_hardware', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Hardware & Components', 'top_computer', 142, 1790966328224) ON CONFLICT(id) DO UPDATE SET total_mcqs = 142;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cdfb7473be23052d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is a volatile memory? RAM, ROM, Cache, Both A and C', '{"A":"RAM","B":"ROM","C":"Cache","D":"Both A and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RAM and Cache are volatile memories.It means their data is lost when power is turned off.Volatile memory requires continuous power to retain data.RAM is used for running programs and storing temporary data.Cache is a high-speed memory that stores frequently used data for the CPU.Additional information:ROM is non-volatile and retains data without power.Last verified on 16-02-2026', 0, 0, 0, 1790966328322) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_72e3d518acf7724a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of following holds the ROM, CPU, RAM and Expansion cards?', '{"A":"Hard disk","B":"floppy disk","C":"All","D":"Motherboard"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Motherboard is the main circuit board of a computer.It holds or provides connections for the CPU, RAM, ROM, and expansion cards.It allows different computer components to communicate with each other.Additional information:CPU → Processes instructionsRAM → Temporary memoryROM → Stores permanent/basic instructionsExpansion cards → Add extra functions to a computerLast verified on 29-09-2026', 0, 0, 0, 1790966328322) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6c20d750823c2d07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'CPU stands for?', '{"A":"Central Processing Unit","B":"Central Procedural Unit","C":"Central Processing Unique","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPU stands for Central Processing Unit.It is the main part of a computer that processes all instructions.It is considered the brain of the computer system.It performs all calculations and decision-making tasks.It controls the operations of all hardware and software.It is located on the motherboard.Last verified on 10-06-2026', 0, 0, 0, 1790966328322) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9fca0271f732419a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'If a computer has more than one processor then it is known as _____?', '{"A":"Uniprocess","B":"Multiprocessor","C":"Multi_threaded","D":"Multi programming"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Definition: Uses 2 or more CPUs.Benefit: Faster processing.Main Memory: Processors usually share RAM.Purpose: Handles multiple tasks efficiently.Additional information:Uniprocessor: One processorMultithreaded: Multiple threadsMultiprogramming: Multiple programs in memory', 0, 0, 0, 1790966328322) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bd87f2c0c4135f4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is an Output Device? Monitor, Printer, Headphones, All of these', '{"A":"Monitor","B":"Printer","C":"Headphones","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Monitor, Printer, and Headphones are all output devices.Output devices present or produce information from a computer for the user.Additional information:Monitor: Displays text, images, and videos.Printer: Produces information on paper.Headphones: Produce audio or sound output.Last verified on 28-09-2026', 0, 0, 0, 1790966328322) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_309329aa6b651d79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Bit is the most famous basic unit in computing which stands for?', '{"A":"Binary digit","B":"Base digit","C":"Basic digit","D":"Byte digit"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bit stands for Binary Digit.A bit is the smallest unit of data in a computer.Represents 0 or 1 (off/on state)8 bits = 1 byteUsed in all digital systems and computer memory.Last verified on 08-06-2026', 0, 0, 0, 1790966328322) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1f0ea4e541f46892', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The speed of a processor (microprocessor) is measured in ______?', '{"A":"Pixels","B":"Hertz","C":"Megabytes","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The speed of a microprocessor is measured in Hertz (Hz).Hertz indicates the number of clock cycles per second.Modern processors are commonly measured in Gigahertz (GHz).Additional information:Hertz (Hz): 1 cycle per secondKilohertz (kHz): 1,000 HzMegahertz (MHz): 1,000,000 HzGigahertz (GHz): 1,000,000,000 HzTerahertz (THz): 1,000,000,000,000 HzLast verified on 26-09-2026', 0, 0, 0, 1790966328322) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_30e7ce0868dde1ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'RAM is a ______ memory.', '{"A":"Permanent","B":"Volatile","C":"Primary Memory","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RAM is categorized as volatile and temporary (or primary / main) memoryIt means its data is lost when power is turned off.Volatile memory requires continuous power to retain data.Additional information:ROM is non-volatile and retains data without power.Last verified on 16-02-2026', 0, 0, 0, 1790966328322) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_005bc7cba836fd83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'MICR stands for ______?', '{"A":"Magnetic Ink Code Reader","B":"Magnetic Ink Cases Reader","C":"Magnetic ink character recognition","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MICR stands for Magnetic Ink Character Recognition. It is a technology used mainly in the banking industry.It helps machines read and process checks quickly.Last updated NA on 10-09-2026', 0, 0, 0, 1790966328409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0d5009d6b6164e74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is a type of non-volatile storage device that is used to store data permanently, even when the power is turned off?', '{"A":"ROM","B":"RAM","C":"CPU","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ROM (Read Only Memory) is a non-volatile storage device.It stores data permanently even without power.Additional information:RAM (Random Access Memory) is a volatile storage device.It loses data when power is off.Last verified on 17-06-2026', 0, 0, 0, 1790966328409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d720a13940c330be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The component responsible for performing arithmetic and logical operations in the CPU is called ______?', '{"A":"ALU","B":"Cache Memory","C":"Control Unit","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ALU (Arithmetic Logic Unit) is the core component of the CPU.It performs both arithmetic operations (calculations) and logical operations (comparisons).Without ALU, a computer cannot process data.ALU works together with the Control Unit (CU).Last verified on 06-05-2026', 0, 0, 0, 1790966328409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_65240a34da4a8dae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following are input devices? Keyboard, Mouse, Card reader, Scanner', '{"A":"Keyboard","B":"Mouse","C":"Card reader","D":"Scanner","E":"All of these"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An input device is any hardware component used to send data, signals, and commands to a computer. Keyboard: Used to type text and enter commands.Mouse: Used to control the cursor and select items.Microphone: Used to record sound.Scanner: Used to convert physical documents into digital fileLast updated by NA on 09-09-2026', 0, 0, 0, 1790966328409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_62c75341e48fa591', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of following is not hardware? Compiler/Windows XP, Chip/Hard disk, RAM, CPU/Monitor', '{"A":"Compiler/Windows XP","B":"Chip/Hard disk","C":"RAM","D":"CPU/Monitor"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Compiler/Windows XP is not hardware; it is software.Compiler: A program that translates computer code into machine language.Windows XP: An operating system that runs computer programs.Additional information:CPU, RAM, Hard Disk, Monitor, and Chip are all hardware.A compiler is software that converts code into machine language.Windows XP is an operating system.Last updated by NA on 09-09-2026', 0, 0, 0, 1790966328409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_dcef2a4b148620f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'If CPU executes multiple programs simultaneously, it is known as?', '{"A":"Multiprocessing","B":"Multitasking","C":"Timesharing","D":"Multiprogramming"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Multiprocessing means using two or more processors/CPU cores to execute multiple programs or processes simultaneously (at the same time).Additional information:Multitasking generally means running multiple tasks by sharing CPU time.Multiprogramming means keeping multiple programs in memory and switching the CPU among them.Last verified on 08-09-2026', 0, 0, 0, 1790966328409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a1de8fca41d6ec75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which memory acts as a buffer Between CPU and the main memory (RAM)?', '{"A":"Cache memory","B":"RAM","C":"ROM","D":"Static RAM"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cache Memory — the buffer between CPU and RAM.Stores frequently used data for quick CPU accessFaster but smaller than RAMFalls between the CPU and main memoryHas levels (L1, L2, L3) — L1 is fastest/closest to CPUReduces memory access time, boosting performanceAdditional information:RAM = the main memory itselfROM = read-only, holds firmware (BIOS)SRAM = a type used to build cache, not the buffer itselfLast updated 07-09-2026 by NA', 0, 0, 0, 1790966328409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_51b477eaea4ecb10', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'RAM stands for ____?', '{"A":"Random Access Memory","B":"Random Access Money","C":"Random Accurate Memory","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RAM stands for Random Access Memory.It is a type of fast, temporary computer memory.It is essentially short-term memory.It is the hardware in a computing device where the operating system (OS).Last verified on 26-04-2026', 0, 0, 0, 1790966328409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_aeefa0cd4713cf70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'USB stands for ______?', '{"A":"Universal serial Bussiness","B":"Universal Serial Bus","C":"Universal Secondary Bus","D":"Unary Serial Bus"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation USB stands for Universal Serial Bus.USB is a standard used to connect and transfer data between electronic devices.A USB flash drive is a data storage device that uses flash memory with an integrated USB interface.Ajay Bhatt is widely credited as a key figure in the development of USB technology in the 1990s.Last verified on 05-09-2026', 0, 0, 0, 1790966328492) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_590af36179d48c31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'ROM stands for _____?', '{"A":"Random Only Memory","B":"Read Only Memory","C":"Read Only Meaning","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ROM stands for Read Only Memory.It is a type of non-volatile memory.So its contents are retained when power is turned off.ROM stores important instructions such as firmware and boot instructions.Additional information:RAM → Random Access MemoryPROM → Programmable Read Only MemoryEPROM → Erasable Programmable Read Only MemoryLast verified on 08-08-2026', 0, 0, 0, 1790966328492) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3a1951d6e64fdb1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'What is a solid-state drive (SSD) advantage over a hard disk drive (HDD)?', '{"A":"SSDs are faster and more durable than HDDs","B":"SSDs are slower than HDDs","C":"SSDs cannot store data permanently","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SSDs use flash memory and have no moving mechanical parts.They provide faster data access and transfer speeds than HDDs.SSDs are generally more durable and resistant to physical shock.HDDs use spinning magnetic disks and mechanical read/write heads.Last verified on 04-09-2026', 0, 0, 0, 1790966328492) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_df09054d48635983', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is both an input and output device?', '{"A":"Modem","B":"Touchscreen","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A modem (Modulator-Demodulator) is both an input and output device as it sends (uploads) and receives (downloads) data over communication networks. It converts digital signals to analog for transmission and vice versa for reception.A touchscreen is also both an input and output device.It displays information (output) and detects touch (input).Last verified on 02-09-2026', 0, 0, 0, 1790966328492) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7f5ca359b159679d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which keyboard shortcut Italic selected text?', '{"A":"Ctrl+I","B":"Alt+I","C":"File/Format/Bold","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + I = ItalicAdditional information:Ctrl + A = Select allCtrl + B = BoldCtrl + P = PrintCtrl + Y = RedoCtrl + S = SaveLast verified on 09-08-2026', 0, 0, 0, 1790966328492) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4ba70fcdc00284fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The function of Alt + Tab on the keyboard is?', '{"A":"Switch between open program / Open applications/windows","B":"Switch between close program","C":"Active search","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alt + Tab is used to switch between open applications or windows.Hold Alt and press Tab to move through currently open windows.It is a useful shortcut for multitasking.Additional information:Alt + F4 — Close the active windowWindows + Tab — Open Task ViewCtrl + Tab — Switch between tabsWindows + D — Show/Hide desktopLast verified on 24-08-2026', 0, 0, 0, 1790966328492) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9bac93c1f5454331', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'What are the main functions of the CPU?', '{"A":"Process input","B":"Output result","C":"Store data","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPU (Central Processing Unit) = the brain of a computer.It processes data and instructions.It controls the computer’s operations.It follows instructions from computer programs.', 0, 0, 0, 1790966328492) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0e2073f7df84380a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following holds data and processing instructions temporarily until the CPU needs it?', '{"A":"Main memory","B":"ROM","C":"Control unit","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Primary storage, also known as main storage or memory.It is the area in a computer in which data is stored for quick access by the computer''s processor.The terms random access memory (RAM) and memory are often as synonyms for primary or main storage.Last verified on 10-08-2026', 0, 0, 0, 1790966328492) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d0a1f479d8899bab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'A physical connection between the microprocessor memory and other parts of the microcomputer is known as?', '{"A":"Path","B":"Address bus","C":"Route","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A physical connection between the microprocessor memory and other parts of the microcomputer is known as an address bus.Additional information:Address Bus carries the addresses of memory locations or I/O devices.Data Bus carries actual data between the CPU, memory, and other components.Control Bus carries control and timing signals.Last verified on 10-08-2026', 0, 0, 0, 1790966328600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_03960c3f9bd072ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Where is RAM located?', '{"A":"External drive","B":"Motherboard","C":"Expansion board","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RAM (Random Access Memory) is installed on the motherboard of a computer.RAM is usually placed in DIMM slots on desktop motherboards.RAM temporarily stores data and programs currently being used by the CPU.RAM is volatile memory, meaning its contents are lost when power is turned off.Last verified on 10-08-2026', 0, 0, 0, 1790966328600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fa14303187c24326', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'How much data can a single layer, single sided DVD can store?', '{"A":"34.7 GB","B":"24.7 GB","C":"4.7 GB","D":"14.7 GB"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A standard single-sided, single-layer DVD holds 4.7 GB of data.A double-layer DVD can store up to 9.4 GB.A single-layer HD-DVD holds 15 GB of data.A dual-layer HD-DVD provides up to 30 GB of storage capacity.Last verified on 10-08-2026', 0, 0, 0, 1790966328600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_605cb8f70ebd5c9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which provides process and memory management services that allow two or more tasks, jobs, or programs to run simultaneously?', '{"A":"Multi-computing","B":"Multi-processing","C":"Multi-tasking","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Multi-tasking provides process and memory management services that allow two or more tasks, jobs, or programs to run simultaneously.The operating system manages CPU time, memory, and other resources among the running tasks.Additional information:Multiprocessing refers to using two or more processors/CPU cores to execute processes.Multithreading allows multiple threads within a process to execute concurrently.Multicomputing involves using multiple separate computers or computing systems.Last verified on 10-08-2026', 0, 0, 0, 1790966328600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_dc0c81197dae2dd6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which memory type is fastest and is typically located inside the CPU?', '{"A":"Main Memory","B":"SRAM","C":"Cache Memory","D":"DRAM"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cache Memory is the fastest memory.It is typically located inside or very close to the CPU.Additional information:L1 Cache: Usually the fastest and smallest CPU cache.L2 Cache: Larger than L1 but generally slower.L3 Cache: Larger and usually shared among CPU cores.Last verified on 09-08-2026', 0, 0, 0, 1790966328600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_faab6fa6c49369e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The only difference between memory and storage is _____?', '{"A":"Permanent, Temporary","B":"Temporary, Permanent","C":"Slow, Fast","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Memory (RAM): Temporary, volatile, fast accessStorage (HDD/SSD): Permanent, non-volatile, slower than RAMExample Memory: RAM in computers (4GB, 8GB, 16GB)Example Storage: Hard disk, SSD (256GB, 512GB, 1TB)Purpose: Memory = active tasks, Storage = long-term dataLast verified on 17-01-2026', 0, 0, 0, 1790966328600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c6dabbb2312d584f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', '1 Terabyte (TB) is equal to  how many GB?', '{"A":"100 GB","B":"1000 GB","C":"10000 GB","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 Terabyte (TB) = 1000 Gigabytes (GB)Additional information:1 Gigabyte (GB) = 1000 Megabytes (MB)1 Megabyte (MB) = 1000 Kilobytes (KB)Last verified on 09-08-2026', 0, 0, 0, 1790966328600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3173c297fedb0abc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Name the type of mouse which uses laser technology to detect the motion of the ball?', '{"A":"Mechanical mouse","B":"Opto Mechanical mouse","C":"Optical mouse","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A laser mouse is a type of optical mouse that uses laser technology for motion detection.Optical mice utilize a light source, such as an LED, along with a light detector to track movement on a surface.Laser technology provides higher precision compared to traditional optical mice.Last verified on 08-08-2026', 0, 0, 0, 1790966328600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_10407f9512606467', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The keyboard Shortcut key to decrease font size by one point is _____?', '{"A":"Ctrl+Shift+<","B":"Ctrl+Shift+v","C":"Ctrl+Alt+>","D":"CTRL+["}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Decrease the font size by 1 point: Ctrl + [Additional information:Increase the font size. Ctrl + Shift + >Decrease the font size: Ctrl + Shift + <Increase the font size by 1 point: Ctrl + ]Ctrl + Shift + F: Change the fontOpen the Font dialog box to change the font: Ctrl + Shift + FVerified & Updated', 0, 0, 0, 1790966328690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_dbd76bb317ca8782', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The standard arrangement of keys on a keyboard is called?', '{"A":"QWERTY arrangement","B":"Home arrangement","C":"Basic arrangement","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The standard arrangement of keys on a keyboard is called the QWERTY arrangement.The name QWERTY comes from the first six letters in the top alphabetic row: Q, W, E, R, T, Y.It was developed from the keyboard layout used in early typewriters.QWERTY became the most widely used keyboard layout.Last verified on 07-08-2026', 0, 0, 0, 1790966328690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b8eb429365e5e0a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The output quality of a printer is measured by ____?', '{"A":"Dot per sq inch","B":"Dot per inch","C":"Dots printed per unit time","D":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The output quality of a printer is measured by Dot Per Inch (DPI).DPI indicates the number of dots a printer can produce in one inch.A higher DPI generally means higher print resolution and sharper output.Common printer resolutions include 300 DPI, 600 DPI, and 1200 DPI.Last verified on 07-08-2026', 0, 0, 0, 1790966328690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0a39cb5f33a4934d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', '1 (One) Gigabyte (GB) is equal to _____?', '{"A":"1024 bits","B":"1032 megabytes","C":"1024 kilobytes","D":"1024 megabytes"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation One Gigabyte (GB) = 1024 Megabytes (MB)Additional information:The size of information in the computer is measured in Kilobytes (KB), Megabytes (MB), Gigabytes (GB), and Terabytes (TB).1 Kilobyte (KB) = 1024 bytesOne Megabyte (MB) = 1024 Kilobytes (KB)One Gigabyte (GB) = 1024 Megabytes (MB)One Terabyte (TB)= 1024 Gigabytes (GB)Last verified on 07-08-2026', 0, 0, 0, 1790966328690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_751f63b766026b13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'An Integrated Circuit (IC) chip is primarily made up of?', '{"A":"Copper","B":"Fiber Glass","C":"Silicon","D":"Steel"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Integrated Circuit (IC) chip is primarily made from silicon, a semiconductor material.IC chips are used in computers, smartphones, calculators, and other electronic devices.Additional information:Atomic Number of Silicon: 14Silicon Group: Group 14 (Carbon Family)First Integrated Circuit Invented: 1958Inventor: Jack Kilby (Texas Instruments)Last verified on 06-08-2026', 0, 0, 0, 1790966328690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d80b1b67269858df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'One Megabyte (MB) is equal to ____?', '{"A":"1024 Bits","B":"1024 Bytes","C":"1024 Kilobytes","D":"1024 Gigabytes"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation One Megabyte (MB) is equal to:1024 Kilobytes (KB)1024 x 1024 Bytes (since 1 KB = 1024 Bytes)1,048,576 Bytes (calculating 1024 x 1024)', 0, 0, 0, 1790966328690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d5f3f8824ad40b73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is NOT an Input device? Microphone and Mouse, Keyboard, Monitor and Speaker, Scanner and Joystick', '{"A":"Microphone and Mouse","B":"Keyboard","C":"Monitor and Speaker","D":"Scanner and Joystick"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Monitor and Speaker are output devices.Because they display visual information and produce sound instead of sending data to the computerAdditional information:Input devices are used to enter data and instructions into a computer.Output devices present the processed information to the user.Common input devices: Keyboard, Mouse, Scanner, Microphone, JoystickCommon output devices: Monitor, Speaker, Printer, Projector, PlotterLast verified on 01-08-2026', 0, 0, 0, 1790966328690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_06809e93f1fa97f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which is the smallest unit of memory/data in computer?', '{"A":"Bit","B":"Byte","C":"Mega bite","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A bit (binary digit) is the smallest unit of data in a computer.It can have a value of 0 or 1, representing two possible states.Additional information:1 Byte = 8 bits1 Kilobyte (KB) = 1024 Bytes1 Megabyte (MB) = 1024 KB1 Gigabyte (GB) = 1024 MB1 Terabyte (TB) = 1024 GBLast verified on 12-03-2026', 0, 0, 0, 1790966328690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_453150e219cbbb57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which keys is/are used to lock the keyboard?', '{"A":"CTRL + Tab","B":"CTRL + Alt","C":"Windows logo + L","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Windows logo + L: Locks the Windows PC screen.Ctrl + Alt + L: Locks only the keyboard in some third-party apps.Ctrl + Tab: Switches browser tabs.Ctrl + Alt: Modifiers; they do nothing alone.Last verified on 21-07-2026', 0, 0, 0, 1790966328779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eb8bb53d1060e455', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Why we use Alt + F shortcut keys on keyboard?', '{"A":"File menu","B":"Bold option","C":"Edit option","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alt + F → Open File menuAdditional information:Alt + E → Open Edit menuCtrl + B → Bold textCtrl + S → Save documentCtrl + P → Print documentLast verified on 16-07-2026', 0, 0, 0, 1790966328779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_01c7521c9680dde9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Cache memory is located on ______?', '{"A":"CPU","B":"Software","C":"Window","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cache memory is located on the CPU to provide very fast access to frequently used data and instructions.It is much faster than RAM but has less storage capacity.Cache memory helps improve the overall speed and performance of the computer.It stores frequently accessed data temporarily.Last verified on 06-07-2026', 0, 0, 0, 1790966328779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c6a365f44951337b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following storage devices can store maximum amount of data?', '{"A":"Floppy Disk","B":"Hard Disk","C":"Compact Disk","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hard disk storage devices can store a maximum amount of data.It has the highest capacity to store data up to 2 Terabytes.It is an electromechanical data storage device that stores and retrieves digital data using magnetic storage.Last verified on 02-07-2026', 0, 0, 0, 1790966328779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cf226b5325c28339', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is the temporary storage for content copied?', '{"A":"Header","B":"Sidebar","C":"Clipboard","D":"Toolbar"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Clipboard is the temporary storage area for content that is copied or cut.It stores text, images, files, or other data temporarily until it is pasted.Copy shortcut: Ctrl + CCut shortcut: Ctrl + XPaste shortcut: Ctrl + VLast verified on 01-07-2026', 0, 0, 0, 1790966328779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_387bc482ef2f6010', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is an example of permanent storage device? RAM, Hard disk, DRAM, None of these', '{"A":"RAM","B":"Hard disk","C":"DRAM","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A permanent storage device retains data even when the computer is turned off.Hard disk is a common permanent storage device used to store files, programs, and the operating system.Examples: Hard Disk Drive (HDD), Solid State Drive (SSD), Optical Discs, USB Flash Drives, External Hard DrivesLast verified on 09-03-2026', 0, 0, 0, 1790966328779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d81e61396fb87cfe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Printer is an example of?', '{"A":"Hard copy","B":"Soft copy","C":"Photocopy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A printer is an example of a hard copy output device.A printer produces a physical copy of digital information on paper.Hard copy can be touched and stored physically.Printers and plotters are common examples of hard copy output devices.Last verified on 30-06-2026', 0, 0, 0, 1790966328779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e12d5c082100b133', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which type of memory is commonly used for storing firmware in embedded systems?', '{"A":"RAM","B":"ROM","C":"Virtual memory","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ROM is commonly used to store firmware in embedded systems.Firmware is permanent software stored in non-volatile memory.ROM retains data even when power is OFF.It is essential for device startup and basic control functions.Last verified on 24-06-2026', 0, 0, 0, 1790966328779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a8046991e09789a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which type of bus provides a path to transfer data between CPU and memory?', '{"A":"Data Bus","B":"Control Bus","C":"Address Bus","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Data Bus transfers actual data between CPU and memory.It carries information that is being processed or stored.It is a two-way communication path in most systems.Additional information:Address Bus: Carries memory location (address)Control Bus: Carries control signals (read/write)System Bus: Combination of all three busesDirection: Mostly bidirectional for data transferLast verified on 22-06-2026', 0, 0, 0, 1790966328863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_709c84db6188f132', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Communication between a computer and keyboard involves?', '{"A":"Full-duplex","B":"Simplex","C":"Half-duplex","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Communication between a keyboard and computer is simplex.It means data flows in one direction only — from keyboard to computer.The computer does not send data back to the keyboard during typing.Additional information:There are 3 main data transmission modes:Simplex: Data flows in one direction only (e.g., keyboard to computer).Half-Duplex: Data can flow both ways, but not at the same time (e.g., walkie-talkies).Full-Duplex: Data flows both ways simultaneously (e.g., telephone conversations).Last verified on 17-06-2026', 0, 0, 0, 1790966328863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b7ef07dc1624455b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is a graphics solution for processor?', '{"A":"Drop Cap","B":"Clip Art","C":"Word Art","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Clip Art is a graphic solution.It is used in word processors to insert ready-made images.It helps enhance the visual appearance of documents.Users can easily add pictures without creating them manually.It is a built-in library of images and symbols.Last verified on 10-06-2026', 0, 0, 0, 1790966328863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7d670e2bcabefd84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which is not a hardware of computer? Monitor, Keyboard, Windows, Printer', '{"A":"Monitor","B":"Keyboard","C":"Windows","D":"Printer"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Windows is not hardware; it is an operating system (software).Hardware refers to physical parts of a computer.Monitor, Keyboard, and Printer are physical devices.Software includes programs that run the computer system.Windows helps manage computer operations and hardware.Last verified on 08-06-2026', 0, 0, 0, 1790966328863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b7093f3f22751b07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'What are the keyboard shortcut keys to paste special?', '{"A":"ALT + H + V + F","B":"ALT + H + V + P","C":"ALT + H + V + O","D":"ALT + H + V + S"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, Paste Special is used to paste only specific parts like values, formulas, or formats.The correct shortcut in Ribbon-based Excel is Alt + H + V + S.It opens the Paste Special dialog box.From there, you can choose different paste options.Last verified on 29-05-2026', 0, 0, 0, 1790966328863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bf367fdfd9579b13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'A normal CD-ROM usually can store up to data is ______ MB.', '{"A":"600","B":"680","C":"900","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A standard CD-ROM is an optical storage device used for data storage.It is commonly used to store software, audio, and files.The typical storage capacity of a normal CD-ROM is 680 MB.It is now mostly replaced by DVDs and USB drives.Last verified on 17-05-2026', 0, 0, 0, 1790966328863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_535a554344a2d865', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'A processor unit that controls, coordinates and directs all operations performed by the computer is ______?', '{"A":"Cache memory","B":"Arithmetic unit","C":"Control unit","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Control Unit (CU) is a part of the CPU that manages and directs all computer operations.It fetches instructions from memory, decodes them, and coordinates execution by other units.Ensures smooth operation of arithmetic, logic, and input/output processes.Last verified on 09-02-2026', 0, 0, 0, 1790966328863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7c7258c108d707d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'ALU stands for what?', '{"A":"Arithmetic Logic Unit","B":"Arithmetic and legal unit","C":"Alternating Logic Unit","D":"Alternate Local Unit"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ALU stands for Arithmetic Logic Unit.It is a core part of the CPU (Central Processing Unit).It performs arithmetic operations like addition and subtraction.It also performs logical operations like AND, OR, NOT.It is essential for processing data in a computer system.Last verified on 26-04-2026', 0, 0, 0, 1790966328863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_564145a0d7d4c1b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is a type of computer memory that is used to temporarily store data and instructions that are currently being processed?', '{"A":"RAM","B":"CPU","C":"Motherboard","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RAM (Random Access Memory) temporarily stores data and instructions that the CPU is currently processing.It is a volatile memory, meaning it loses data when the computer is turned off.Last verified on 15-02-2026', 0, 0, 0, 1790966328956) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3689ca95d8f5de49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'How many function keys are there in the keyboard?', '{"A":"10","B":"14","C":"12","D":"13"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keyboard → An input device used to enter data and commands.Inventor: Christopher Latham SholesFunction keys: 12 (F1–F12)Alphanumeric keys: A–Z and 0–9Punctuation keys: Comma, period, semicolon, etc.Special keys: Arrow keys, Caps Lock, Enter, Ctrl, AltLongest key: SpacebarStandard keyboard: 101 keysLast updated on 14-09-2026 by NA', 0, 0, 0, 1790966328956) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bbdf9e169dd0f421', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is an example of hardcopy output device? Speaker, Printer, Scanner, Monitor', '{"A":"Keyboard","B":"Printer","C":"Mouse","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A hardcopy output device produces physical copies of data or information.Printer converts digital documents into paper copies.Examples: Plotter, Photocopier, Fax machine, Braille printerAdditional information:Softcopy vs Hardcopy:Softcopy: Screen display, audio (Monitor, Speaker)Hardcopy: Physical form (Paper, Card, etc.)Printers can be inkjet, laser, or dot-matrix.Last verified on 09-03-2026', 0, 0, 0, 1790966328956) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9a1558a74b1da385', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following technique for deadlock recovery is easily regarding CPU?', '{"A":"Starvation","B":"Resource Description","C":"Process Termination","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Regarding deadlock recovery techniques, is Process Termination. It is considered an "easy" technique regarding CPU management Because it uses simple logic to break a deadlock cycle:', 0, 0, 0, 1790966328956) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_62beb9fa9bcc5a3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The speed of CPU is measured in ______?', '{"A":"MHz","B":"Mbps","C":"Mbytes","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPU speed is primarily measured in Hertz (Hz), and Gigahertz (GHz) for modern processorsThe fundamental unit is Hertz (Hz), where 1 Hz = 1 cycle per second.Modern Units: Most, if not all, modern processors use Gigahertz (GHz), where 1 GHz = 10^9 Hz (one billion cycles per second).Context: It is often referred to as the "clock speed" or "clock rate" of the CPU.Mbps measures internet speed.Mbytes measure data size.Last updated 15-feb-2026', 0, 0, 0, 1790966328956) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3d65bc4e5bc74b51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Who invented the First Computer Mouse?', '{"A":"Douglas Engelbart","B":"Ada Lovelace","C":"Charles Babbage","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The computer mouse was invented and developed by Douglas Engelbart, In 1964, at the Stanford Research Institute (SRI). 1964: The prototype was built.1968: Introduced to the public during the famous "Mother of All Demos".Last update 0n 21-07-2026 by NA', 0, 0, 0, 1790966328956) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8fcb3d0e0fd8bbf2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'DVD stands for what?', '{"A":"Digital Video Disk","B":"Digital Value Disk","C":"Digital Versatile Disk","D":"Data Video Disk"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DVD stands for Digital Versatile Disc.It is a digital optical disc data storage formatIt was invented and developed in 1995 First released in Japan on November 1, 1996.Developed by: Sony; Panasonic; Philips; Toshiba', 0, 0, 0, 1790966328956) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fe8fb941bed14205', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Mouse is used for _____?', '{"A":"Printing","B":"Typing","C":"Selecting and pointing","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A mouse helps users select items and point to objects on the computer screen.It is a primary input device for graphical user interfaces.', 0, 0, 0, 1790966328956) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5c536967976d5a7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'What is a byte?', '{"A":"Combination of more than one character","B":"Combination of more than one alpha-bates","C":"Combination of 8 bits forms a byte","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The byte is a unit of digital information that most commonly consists of eight bits.Unit of: digital information, data sizeUnit system: unit derived from bit*********RY 13-12-202', 0, 0, 0, 1790966329013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5e4071614942e6c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is not an output device of a computer?', '{"A":"Keyboard","B":"Mouse","C":"Scanner","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Input devices are used to provide data and control signals to a computer.Examples: Keyboard, mouse, scanner, camera, joystick, and microphone.Output devices display the results of that data. Examples: Printer, Monitor, Plotter, Speaker, Headphones, Projector, GPS device, Optical mark reader, and Braille reader. Last updated 12 april 2026', 0, 0, 0, 1790966329014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7efbb2ed64fad364', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which is the secondary storage device? ROM, CD-ROM, Hard Disk, Both B and C', '{"A":"ROM","B":"CD-ROM","C":"Hard Disk","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A hard disk is a secondary storage device used to store data permanently.RAM and ROM are primary storage (main memory).Diodes and Semiconductors are basic electronic components.CD-ROM is a secondary storage device used to store data permanently.', 0, 0, 0, 1790966329014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_480d3c0560b8375e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is a way to access secondary memory?', '{"A":"Density method","B":"Transfer method","C":"Action method","D":"Random access memory"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Transfer method: This refers to the process of moving data between secondary memory (like hard drives or SSDs) and primary memory (RAM). For example, when files are loaded from a hard drive into RAM, data transfer occurs.', 0, 0, 0, 1790966329014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5943721e479c621f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'ALU and CPU are component of?', '{"A":"ROM","B":"CPU","C":"RAM","D":"CAD"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ALU (Arithmetic Logic Unit) is a core component of the CPU (Central Processing Unit), And the CPU itself is the main processing chip and core component of a computer system (or computer hardware architecture).', 0, 0, 0, 1790966329014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c4738dca9e25c180', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'CPU consists of ______ basic components.', '{"A":"Arithmetic and Logic Unit","B":"Control unit and Registers","C":"Cache and Internal buses","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The CPU (Central Processing Unit) consists of the following basic components:Arithmetic and Logic Unit (ALU) – Performs mathematical calculations and logical operations.Control Unit (CU) – Directs operations by decoding instructions and managing execution.Registers – Small, fast storage locations for temporary data during processing.Cache – High-speed memory for frequently accessed data.Internal Buses – Pathways that transfer data between CPU components.', 0, 0, 0, 1790966329014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0cd9fc1c40fe89d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The main memory of a computer can also be called ______?', '{"A":"Primary storage","B":"Internal memory","C":"Primary memory","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main memory of a computer is also known by several names, including:Primary storageInternal memoryPrimary memoryMain storageRandom Access Memory (RAM)All these terms refer to the computer''s volatile memory, which temporarily stores data and programs that are currently being used or processed by the CPU (Central Processing Unit).RAM is a primary memory.ROM is a secondary memory.RAM stands for: Random Access MemoryROM stands for: Read Only Memory', 0, 0, 0, 1790966329014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_edaa2c0af91df0d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', '1 byte is equal to _____?', '{"A":"4 bits","B":"8 bits","C":"12 bits","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 byte equals 8 bits.Additional Information1024 Bytes = 1 Kilobyte (KB)1024 Kilobytes = 1 Megabyte (MB)1024 Megabytes = 1 Gigabyte (GB)1024 Gigabytes = 1 Terabyte (TB)', 0, 0, 0, 1790966329014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7236f518f55c2cf9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is Non-volatile memory? RAM, ROM ,PROM', '{"A":"RAM","B":"ROM","C":"PROM","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Non-volatile memory is a type of computer memory That can retain stored information even after power is removed.RAM is a volatile memory.RAM: Random Access Memory.ROM and PROM is a non-volatile memories.ROM: Read-Only Memory.PROM (Programmable Read-Only Memory)', 0, 0, 0, 1790966329087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8be2571893db4810', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'CPU is an example of _____?', '{"A":"Hardware","B":"Software","C":"Application software","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The CPU (Central Processing Unit) is a hardware component of the computer.It performs all processing and calculations, acting as the computer’s brain.The CPU performs basic arithmetic, logic, controlling, and input/output (I/O) operations specified by the instructions in the program.', 0, 0, 0, 1790966329087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f83076123109a9e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is a type of storage device? Hard disk, Processor, Scanner, Router', '{"A":"CD-ROM","B":"Hard Disk","C":"Printer","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Hard Disk is a primary storage device used to store data permanently on a computer.It keeps files, software, and the operating system even when the power is off.List of Storage Devices:Hard Disk Drive (HDD)Solid State Drive (SSD)Random Access Memory (RAM)CD, DVD, Blu-ray DiscsDVD-RAMROMUSB Flash Memory', 0, 0, 0, 1790966329087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_165a3bcb79c2efca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The loading of operating system from hard disk to main memory is known as _____?', '{"A":"Running","B":"Processing","C":"Booting","D":"Initializing"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Loading the operating system into the computer''s memory is called booting.This process initializes the system and prepares it for use.', 0, 0, 0, 1790966329087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7a339e37f63451bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Keyboard is used as ______?', '{"A":"Input device","B":"Out put device","C":"Printer","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keyboard is an input device.Keyboard is similar to electric typewriter.Keyboard uses serial port to connect with computer.Keys on keyboard are of mainly three types:Alphanumeric keys: letters and numbers Punctuation keys: comma, period, semicolon, etc.Special keys: function keys, arrow keys, caps lock key, etc. Keyboard inventor: Christopher Latham Smallest key on keyboard: Space key', 0, 0, 0, 1790966329087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d5cf60775d3c1d7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Who invented keyboard _________?', '{"A":"Christopher letham","B":"Charlas Babbage","C":"Tim Berner Lee","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keyboard is an input device.Keyboard is similar to electric typewriter.Keyboard uses serial port to connect with computer.Keys on keyboard are of mainly three types:Alphanumeric keys: letters and numbers Punctuation keys: comma, period, semicolon, etc.Special keys: function keys, arrow keys, caps lock key, etc. Keyboard inventor: Christopher Latham', 0, 0, 0, 1790966329087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_64b92f9f5aceec2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following is an example of optical storage device? SSD, DVD Drive, Hard drive, None of these', '{"A":"SSD","B":"DVD Drive","C":"Hard drive","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Optical media such as compact discs (CDs) and digital versatile discs (DVDs).****There are two types of storage devices used with computers:A primary storage device, such as RAM, and A secondary storage device, such as a hard drive.****The most common type of storage devices are___?Magnetic storage devices and Flash memory***Storage devices holder ______-.data and instructions******Which device has the largest storage capacity?Hard Disk****', 0, 0, 0, 1790966329087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e6dd277f2a792985', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'In computer GB stands for _______?', '{"A":"Gigbyte","B":"Gigabit","C":"Gigabyte","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GB stands for Gigabyte.It is a unit of digital information or storage capacity.One gigabyte (GB) is equal to 1 billion bytes.', 0, 0, 0, 1790966329087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b66a5373c23ad3e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'In computing, MB stands for _____?', '{"A":"More Bytes","B":"Mega Bytes","C":"Maximum Bytes","D":"Maga Bytes"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation KB stands for KilobyteMB stands for MegabyteGB stands for Gigabyte TB stands for Terabyte', 0, 0, 0, 1790966329178) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e6de78426a74ccb0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'OCR stands for ________?', '{"A":"Optional Character Recognition","B":"Optical Character Recognize","C":"Optical Character Recognition","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OCR (Optical Character Recognition) is the technology used to convert scanned or photographed images of text into editable digital text. It uses algorithms to recognize and extract characters from images.It allowing for the conversion of printed or handwritten text into a digital format.', 0, 0, 0, 1790966329178) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c8d4750305f347a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', '…… is a computer software whose user interface and API resembles that of printer driver?', '{"A":"Digital Printer","B":"Plotter","C":"Virtual Printer","D":"None of above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An application programming interface is a connection between computers or between computer programs. It is a type of software interface, offering a service to other pieces of software.', 0, 0, 0, 1790966329178) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c76ae94f4af37db6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which of the following are the components of Central Processing Unit (CPU)?', '{"A":"Arithmetic logic unit, Mouse","B":"Arithmetic logic unit, Control unit","C":"Arithmetic logic unit, Integrated circuits","D":"Control Unit, Monitor"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main components of a Central Processing Unit (CPU) are the control unit, arithmetic logic unit, and register set.Other components include the cache, clock, and buses.', 0, 0, 0, 1790966329178) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ecbb3e7a5e7d1354', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The output shown on the computer monitor is called?', '{"A":"VDC","B":"Hard copy","C":"Screen Copy","D":"Soft copy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The output shown on the computer monitor is called a soft copy***The output that is displayed on the computer’s monitor is considered a soft copy. The computer’s monitor is the computer’s display unit.As the operations are conducted, the function or operation that is done through the software files on the computer can be seen.The files are saved either by the user or by a default that often exists.In both instances, the output becomes the data operation’s soft copy.', 0, 0, 0, 1790966329178) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f2fee194262f432f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Computer Monitor is also called?', '{"A":"DVD","B":"VDU","C":"CCTV","D":"DVU"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A monitor is also called a Visual Display Unit (VDU).Because it displays visual output from the computer.', 0, 0, 0, 1790966329178) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_566be5afbc76f3fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'A joystick is a(n) _____ device.', '{"A":"Output","B":"Storage","C":"Input","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A joystick is a device that captures user input.It typically to control movement or actions in a game or simulation.', 0, 0, 0, 1790966329178) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_11550a48b5fa87d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Barcode reader is a device ____?', '{"A":"Input","B":"Output","C":"Display","D":"Storage"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A barcode reader, also called a price scanner or point-of-sale (POS) scanner.It is a hand-held or stationary input device.It used to capture and read information contained in a barcode.', 0, 0, 0, 1790966329178) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4c6c24242aef1f29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Keyboard of a computer system is ______?', '{"A":"Hardware","B":"Software","C":"Firmware","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A keyboard is a physical input device, so it is considered hardware.It allows the user to interact with the computer by typing commands or data.', 0, 0, 0, 1790966329263) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_dd49e3458dcff849', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Another term for Main Memory is ______?', '{"A":"ROM","B":"RAM","C":"Hard Disk","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main memory of a computer is also known by several names, including:Primary storageInternal memoryPrimary memoryMain storageRandom Access Memory (RAM)All these terms refer to the computer''s volatile memory, which temporarily stores data and programs that are currently being used or processed by the CPU (Central Processing Unit).RAM is a primary memory.ROM is a primary memory.RAM stands for: Random Access MemoryROM stands for: Read Only Memory', 0, 0, 0, 1790966329263) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d6f4c39c4acfcf0b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which number system is generally adapted in a typical 32-bit computer?', '{"A":"Hexadecimal","B":"Decimal","C":"Binary","D":"Octal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A typical 32-bit computer usually uses the binary number system.A binary number is a number that is stated using the base-2 numeral system or binary numeral system, which normally utilizes just two symbols: 0 (zero) and 1 (one).It is a sort of CPU architecture with the ability to send and receive 32 bits of data.', 0, 0, 0, 1790966329263) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8611a24f3d2ba170', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'File Management, Task Management, Memory Management is/are responsibly of ______?', '{"A":"Operating System","B":"BIOS","C":"RAM","D":"Task Manager"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation File Management, Task (Process) Management, and Memory Management are responsibilities of the Operating System (OS)Memory Management: Allocates and deallocates RAM to programs, ensuring efficient access for the CPU.File Management: Handles the storage, organization, naming, and protection of files on storage devices.Task/Process Management: Creates, deletes, and schedules processes (tasks) to ensure proper CPU utilization.Last updated question by NA on 07 May 2026', 0, 0, 0, 1790966329263) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_52c09a2670a9b349', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'What do you need for an inkjet printer?', '{"A":"A drum","B":"A cartridge","C":"A ribbon","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A cartridge need for an inkjet printer.**for inkjet printers need ink cartridges to print.laser printers need a toner cartridge and a drum unit.**laser printers use a powder, called toner Inkjet printers use dye-based liquid ink.****ND10-1-2023', 0, 0, 0, 1790966329263) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2203916910e80560', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'What type of device is a computer mouse?', '{"A":"Input","B":"Output","C":"Data","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer mouse is a handheld hardware input device A computer mouse controls a cursor in a GUI (graphical user interface) for: pointing, moving and selecting text, icons, files, and folders on your computer******ND30-12-2022', 0, 0, 0, 1790966329263) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d4683dbcf301d45a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'A scanner scans _______?', '{"A":"Pictures","B":"Text","C":"Both Pictures and Text","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A scanner scans images, printed text, handwriting or an object and converts it to a digital image. Scanner is an output device. Scanner founder: Russell KirschRussell Kirsch belongs to USA.', 0, 0, 0, 1790966329263) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7eda27cf1f91adf3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Primary storage is _____ as compared to secondary storage.', '{"A":"Fast and expensive","B":"Slow and inexpensive","C":"Fast and inexpensive","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Primary memory devices are more expensive than secondary storage devices.Secondary memory devices are less expensive when compared to primary memory devices.Primary memory is also known as Main memory or internal memory.Secondary memory is also known as External memory or Auxiliary memory.', 0, 0, 0, 1790966329263) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8b5371bb807e5c30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'How many Bits are there in One Byte?', '{"A":"7","B":"9","C":"8","D":"6"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In computer architecture, 8-bit integers or other data units are those that are 8 bits The byte is a unit of digital information that most commonly consists of eight bits.Unit of: digital information, data sizeUnit system: unit derived from bit*********', 0, 0, 0, 1790966329362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e41d46f5d26d47c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Virtual memory typically located on/in ____?', '{"A":"RAM","B":"CPU","C":"Flash card","D":"Hard drive"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Feature Virtual MemoryLocation: On the hard drive or SSDSpeed: Slower (due to disk I/O operations)Capacity: Larger, limited by disk spaceCost: Lower (cost of additional disk storage)', 0, 0, 0, 1790966329362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_af5f8e2131a9eaba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Computer memory that needs its data to be refreshed otherwise it losses data is?', '{"A":"SRAM","B":"DRAM","C":"MRAM","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DRAM memories need a refresh.Dynamic Random Access Memory (DRAM).DRAM must be refreshed many times per second to store information, otherwise, it will lose what it is holding.DRAM is the most common type of memory in use today.ND18-4-2023', 0, 0, 0, 1790966329362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_913e4f8b79dbab64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'RAM (Random Access Memory) is also called?', '{"A":"Read memory","B":"Write memory","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RAM (Random Access Memory) is the hardware in a computing device where the operating system (OS).RAM is also known as read/write memory.', 0, 0, 0, 1790966329362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c415743d4410b1a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The CPU and memory are located on the ________?', '{"A":"Motherboard","B":"Hard drive","C":"Windows","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The CPU and memory are located on the motherboard.The motherboard''s job is to connect all hardware components together.The motherboard''s a thin plate that holds the:CPU, Memory, Connectors for the hard drive,Optical drives.', 0, 0, 0, 1790966329362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_74ef6770fabe3101', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'A CPU contains _______?', '{"A":"A card reader and a printing device","B":"An analytical engine and a control unit","C":"A control unit and an arithmetic logic unit","D":"An arithmetic logic and a card reader"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer system consists of a computer case, a power supply unit, a motherboard, a central processing unit, main memory, and a hard disk drive. Input devices include a keyboard, mouse, microphone, video camera, and image scanner.****', 0, 0, 0, 1790966329362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4c1c68025b91a53d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'ALU is a component of processor, which consists of ____?', '{"A":"LU (Logic Unit)","B":"AU (Arithmetic Unit)","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ALU (Arithmetic Logic Unit) is a component of the processor that consists of both the Logic Unit (LU) and the Arithmetic Unit (AU).It performs arithmetic and logical operations essential for processing data.', 0, 0, 0, 1790966329362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bc336e5284bb28c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The keyboard Shortcut key to increase font size by one point is?', '{"A":"CTRL+[","B":"Ctrl+Alt+>","C":"Ctrl+Shift+v","D":"Ctrl + ]"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS WordMinimum font size: 8Maximum font size: 72Standard font size: 12MS Word manually font size (1-1638)Ctrl + Shift + P is used to change the font size.To increase the font size, press Ctrl + ].To decrease the font size, press Ctrl + [.', 0, 0, 0, 1790966329362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_450d51afaa32146e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The circular device used for storage is _____?', '{"A":"Disk","B":"RAM","C":"ROM","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A disk is a circular storage device used for saving data, such as hard disks, CDs, and DVDs.It stores data magnetically or optically.It allows easy retrieval and rewriting (in most cases).', 0, 0, 0, 1790966329445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9314acd14bf4b9e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which device has the highest memory capacity?', '{"A":"CD","B":"Hard disk","C":"Motherboard","D":"DVD"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation the Device having the largest storage capacity is Hard Disk.hard disk has a capacity from 5 MB to 100 TBwhileThe CD has a capacity of 700 MBDVD has a capacity of 4.8 GB to 8.5 GBND5-07-2023', 0, 0, 0, 1790966329445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d7404203c525dd27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Who invented the Qwerty keyboard?', '{"A":"Georage Orville","B":"Christopher Latham Sholes","C":"Isaac Newton","D":"Kurt Keplan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation QWERTY refers to the first six letters on the upper row of the keyboard.The QWERTY layout was devised and created in the early 1870sThe key arrangement was devised by Christopher Latham Sholes104 buttons or keys in a QWERTY keyboard The QWERTY keyboard is also known as the Sholes keyboardND18-4-2023', 0, 0, 0, 1790966329445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_941d1bafb698b85d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The function of a ____ is similar to that of a mouse.', '{"A":"Keyboard","B":"Joystick","C":"Camera","D":"Moniter"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A joystick sometimes called a flight stick.The joystick is an input device consisting of a stick that pivots on a base and reports its angle or direction to the device it is controlling.ND18-4-2023', 0, 0, 0, 1790966329445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_08b85ba0f136774d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Scanner is a/an _______?', '{"A":"Output device","B":"Input device","C":"Hardware","D":"Software","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A scanner scans images, printed text, handwriting or an object and converts it to a digital image. Scanner is an input device. Scanner founder: Russell KirschRussell Kirsch belongs to USA.agm.5.3.23', 0, 0, 0, 1790966329445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e936ea1a1c47a0fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'What is the keyboard shortcut for creating a chart from the selected cells?', '{"A":"F3","B":"F8","C":"F7","D":"F11"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Excel allowed you to create a chart by selecting the data and pressing the F11 key.', 0, 0, 0, 1790966329445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_920d6cc272e892e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'What is the primary use of the "Page Down" key on a keyboard?', '{"A":"Scroll down one page in a document","B":"Move to the beginning of the document","C":"Delete the current page","D":"Open a new tab"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The "Page Down" key is used to scroll down one page at a time in a document, webpage, or other content on a computer screen.', 0, 0, 0, 1790966329445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d334a4c397322383', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which part of computer connects the motherboard and give power to different parts?', '{"A":"Power supply","B":"CPU","C":"RAM","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The power supply unit (PSU) connects to the motherboard and provides power to various components such as the CPU, RAM, and other peripherals.It converts AC power from the mains to DC power, which is then distributed to the different parts of the computer.', 0, 0, 0, 1790966329445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f81d9645c81c6384', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'In computer disk storage is a subdivision on a magnetic disk or optical disk called ______?', '{"A":"track","B":"ROM","C":"Sector","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In computer disk storage, a sector is a subdivision of a track on a magnetic disk or optical disc.****RY17-012-23', 0, 0, 0, 1790966329538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_48f520f1903a569e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'In C and C++ programming languages, which symbol is used to access the value stored at a memory address:', '{"A":"@","B":"#","C":"%","D":"*"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In both C and C++ programming languages, the symbol used to access the value stored at a memory address (dereferencing a pointer) is the asterisk (*).* and & are the operators used in pointers. * gives us the value stored at a particular address whereas “ & “ gives us the address of the variable', 0, 0, 0, 1790966329538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d6ac994674b5bd71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which key on the keyboard can be used to view slideshow?', '{"A":"F1","B":"F2","C":"F5","D":"F7","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For start Slide show view, Press F5. To exit Slide Show view, press ESC.', 0, 0, 0, 1790966329538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0755d573f2fc36bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Hard disk in computer is a _______?', '{"A":"Storage device","B":"Software","C":"Both","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The hard disk was invented on September 13, 1956, by an IBM team led by Rey JohnsonThe commercial usage of hard disk drives (HDD) began in 1957Rey Johnson (considered as “father” of the disk drive).A computer hard disk drive is a non-volatile data storage device.Hard Disk is an example of Magnetic StorageND07-3-2023', 0, 0, 0, 1790966329538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7b7fa665c288754d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The ALU of a computer responds to the commands coming from ____?', '{"A":"Primary Memory","B":"Control Section","C":"Extinction","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The control unit (CU) is a component of a computer''s central processing unit (CPU) that directs the operation of the processor. It tells the: computer''s memory, arithmetic/logic unit and input and output devicesND11-4-2023', 0, 0, 0, 1790966329538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9cd8d25c7dbcb065', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'A hard disk becomes totally inaccessible when a computer virus corrupts it''s _____?', '{"A":"Partition Table","B":"Boost Sector","C":"File Allocation Table","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A corrupted Partition Table can make a hard disk totally inaccessible, as it contains information about the disk''s partitions and how data is organized.If the Partition Table is damaged, the operating system may not be able to recognize the disk or access its contents.', 0, 0, 0, 1790966329538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c3d759752c0d1016', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'LaserJet printer is measured in _____?', '{"A":"Page per minute","B":"Line per minute","C":"Dots per inch","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The speed of a laser printer is measured in PPM i.e, Pages Per Minute. Laser printing is an electrostatic digital printing process.******', 0, 0, 0, 1790966329538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7663015b784b80f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Where a computer mouse moves over the table surface, the trackball is?', '{"A":"Stationary","B":"Difficult to move","C":"Dragged","D":"Moved in small step"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A trackball is a pointing device where the ball is held in place by a socket, allowing users to rotate the ball to move the cursor on the screen. Unlike a traditional mouse, which moves over a surface, a trackball stays stationary, and the ball''s rotation controls the cursor''s movement in different directions.', 0, 0, 0, 1790966329538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d7c9d3562c1fbac9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Terabyte is equal to how many TB?', '{"A":"1 Terabyte","B":"1 Trillion Byte","C":"1 Mega byte","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 TB equals 1,000 gigabytes or 1,000,000 megabytes (MB).Individual external hard drives often start at 1 TB of storage, with options that go up to 4 TB.', 0, 0, 0, 1790966329633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c9bd75ef9e714840', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'How many MBS are in one GB', '{"A":"500mbs","B":"100mbs","C":"1000mbs","D":"1024mbs"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation One gigabyte (GB) is equal to 1024 megabytes (MB).So, there are 1024 megabytes in one gigabyte.1024GB is the correct answer', 0, 0, 0, 1790966329633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_91fd5feeb7da3c10', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Which memory management technique swaps out entire processes to disk when they are not actively executing?', '{"A":"Paging","B":"Segmentation","C":"Swapping","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Memory Swapping is a memory management technique that involves moving some of the contents of RAM to a disk space called a swap space or swap file.', 0, 0, 0, 1790966329633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f6fe6261beea7a6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The dots that compose the image on a monitor are called?', '{"A":"Colored spots","B":"Pixies","C":"Pixels","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The basic unit of programmable color on a computer display or in a computer image. Pixel is also define as dots per inch, which indicates the resolution of an image.', 0, 0, 0, 1790966329633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1eb560f086902223', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The accuracy of the floating point numbers representable in two 16 bit words of a computer is approximately?', '{"A":"5 digits","B":"9 digits","C":"6 digits","D":"8 digits","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This means that floating point numbers have between 6 and 7 digits of precision, regardless of exponent. That means that from 0 to 1, you have quite a few decimal places to work with. If you go into the hundreds or thousands, you''ve lost a few.AGM 30.4.23', 0, 0, 0, 1790966329633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_df85fb3b15d6a67d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Programs stored in ROM are called as', '{"A":"Formware","B":"Firmware","C":"Farmware","D":"Fireware"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Programs stored in ROM are called Firmware. Firmware is held in non-volatile memory devices such as ROM, EPROM, or flash memory.ND18-4-2023', 0, 0, 0, 1790966329633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cb2b81c295152c22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The keyboard format most commonly used is called:', '{"A":"QWERTY","B":"DVORIC","C":"TWRITER","D":"SPLATTER"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation QWERTY refers to the first six letters on the upper row of the keyboard. Keyboard is an input device.Keyboard is similar to electric typewriter.Keyboard uses serial port to connect with computer.Keys on keyboard are of mainly three types:Alphanumeric keys: letters and numbers Punctuation keys: comma, period, semicolon, etc.Special keys: function keys, arrow keys, caps lock key, etc. Keyboard inventor: Christopher Latham Smallest key on keyboard: Space keyagm.5.3.23', 0, 0, 0, 1790966329633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_39c28ea6a063a8e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Floppy disk drive, hard disk drive, optical disk drive, and teleprinter are called?', '{"A":"Input device","B":"Output device","C":"Both Above","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Peripheral device (input/output)Input: Mouse, keyboard, joystick, image scanner, webcam, graphics tablet, microphoneBoth: Floppy disk drives, hard disk drive, optical disc drive, teleprinterND07-3-2023', 0, 0, 0, 1790966329633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_876301e30fd37bfb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Internal hard disk is ______?', '{"A":"Fixed","B":"Not fixed","C":"Removable","D":"Removable but not fixed"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An internal hard drive is the primary storage device located inside a computer system. It usually contains pre-installed software applications, the operating system and other files.', 0, 0, 0, 1790966329724) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f4ddf58a78e118df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'USB is a device used to carry data from one computer or laptop to another stands for:', '{"A":"Universal Secure Bus","B":"Universal Serial Bus","C":"Universal system to carry bytes","D":"Unidirectional saving bus"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation USB stands for Universal Serial Bus.USB is a device used to carry data from one to another computer.', 0, 0, 0, 1790966329724) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fcf1e922ef93ecaf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'You use an input device such as keyboard or mouse to_____ information', '{"A":"input","B":"Output","C":"Data","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keyboard is an input device.Keyboard is similar to electric typewriter.Keyboard uses serial port to connect with computer.Keys on keyboard are of mainly three types:Alphanumeric keys: letters and numbers Punctuation keys: comma, period, semicolon, etc.Special keys: function keys, arrow keys, caps lock key, etc.', 0, 0, 0, 1790966329724) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7377f54ada9e3008', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'A DVD is an example of a___?', '{"A":"Hard disk","B":"Optical Disk","C":"Output devices","D":"Solis-State Storage Devices"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A DVD is a type of optical media used for storing digital data.It is the same size as a CD, but has a larger storage capacity.**** RY18012023', 0, 0, 0, 1790966329724) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_25ffe2bb74aa5c43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'How many types of computer memory?', '{"A":"2","B":"3","C":"4","D":"5"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Computer memory is of two basic types. Primary memory(RAM and ROM) and Secondary memory(hard drive,CD,etc.*******VU FIA PAPER 18-12-2021', 0, 0, 0, 1790966329724) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5612364f2f9297ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'A Kilo Byte is equal to:', '{"A":"10000 Bytes","B":"1024 Bytes","C":"1000 Bytes","D":"10 Million Bytes"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Many people think that there are 1000 bytes in a kilobyte. But there are really 1024 bytes in a kilobyte. The reason for this is because computers are based on the binary system. That means hard drives and memory are measured in powers of 2.', 0, 0, 0, 1790966329724) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_44382d0dd96cee98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Microprocessor unlike computer are programmed to complete___ task?', '{"A":"unlike","B":"Specific","C":"similar","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A microprocessor is an electronic component that is used by a computer to do its work. Central processing unit on a single integrated circuit chip containing millions of very small components including transistors, resistors, and diodes that work together.', 0, 0, 0, 1790966329724) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fbfa0dc1f7c3be3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', '1 bit is equal to', '{"A":"0.12","B":"0.150","C":"0.125","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A 1-bit system uses combinations of numbers up to one place value (1). There are just two options: 0 or 1. A 2-bit system uses combinations of numbers up to two place values (11). *******VU CBT FIA SI ASI PAPER 13-12-2021', 0, 0, 0, 1790966329724) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8d527f011fb9a202', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Internal memory of computer is associated with ______?', '{"A":"RAM","B":"Direct Storage","C":"CPU","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RAM stands for Random Access Memory.', 0, 0, 0, 1790966329847) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a9342521f28dde3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Divide memory into sections is called.', '{"A":"Memory segmentation","B":"Primary memory","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Memory Segmentation is a computer technique of division of a computers primary memory into Segments or Sections.', 0, 0, 0, 1790966329847) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_12abfb9fbc3f1496', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'All memory units are expressed as powers of ?', '{"A":"20","B":"10","C":"5","D":"2","E":"7"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation computer memory capacity is expressed in multiples of a power of two.it is measured in megabytes (MB) and gigabytes (GB). A medium-sized novel contains about 1 MB of information. 1 MB is 1,024 kilobytes, or 1,048,576 (1024x1024) bytes, not one million bytes. Similarly, one 1 GB is 1,024 MB, or 1,073,741,824 (1024x1024x1024) bytes.', 0, 0, 0, 1790966329847) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9e4a74544d824074', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'A computer’s memory is measured in bytes, the largest unit of memory is:-', '{"A":"megabyte","B":"Gigabyte","C":"Kilobyte","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The abbreviation “MB” stands for “megabyte,” a unit of computer storage.Unit DescriptionMegabyte 1024 kilobytesGigabyte 1024 megabytesTerabyte 1024 gigabytesPetabyte 1024 terabytes', 0, 0, 0, 1790966329847) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c31c57a6b3c04ee2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'Advantage of the disparity between frequencies and uses less storage for the frequently occurring characters at the expense of having to use more storage for each of the more rare characters is called', '{"A":"Huffman encoding scheme","B":"Encoding scheme","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Huffman encoding scheme takes advantage of the disparity between frequencies and uses less storage for the frequently occurring characters at the expense of having to use more storage for each of the more rare characters.', 0, 0, 0, 1790966329847) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e13246bc12d685a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_hardware', 'The most common type of storage devices are___?', '{"A":"Magnetic Storage","B":"Flash memory","C":"Optical","D":"Both A & B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Magnetic storage devices: Today, magnetic storage is one of the most common types of storage used with computers. This technology is found mostly on huge hybrid hard drives', 0, 0, 0, 1790966329847) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_comp_internet', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Internet & Networking', 'top_computer', 107, 1790966329935) ON CONFLICT(id) DO UPDATE SET total_mcqs = 107;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1db43a87ed077038', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The first network that initiated internet was _____?', '{"A":"Inet","B":"Vnet","C":"ARPANET","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ARPANET was the first network that initiated the Internet.It was launched in 1969 by the U.S. Department of Defense''s ARPA.ARPANET stands for Advanced Research Projects Agency Network.Additional information:First message sent: 29 October 1969TCP/IP adopted: 1 January 1983World Wide Web introduced: 1989 (by Tim Berners-Lee)Public Internet growth: 1990sLast verified on 27-07-2026', 0, 0, 0, 1790966330061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0662a4aed9e15135', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The default port for HTTP traffic is?', '{"A":"20","B":"21","C":"80","D":"443"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTTP stands for Hypertext Transfer Protocol.It uses port 80 by default for non-secure web communication.For secure HTTP (HTTPS), the default port is 443.Last updated by NA on 15-02-2026', 0, 0, 0, 1790966330061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7baa29f372e6df6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Email stands for?', '{"A":"Easy mail","B":"Electronic mail","C":"Electric mail","D":"Eye mail"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Email stands for Electronic Mail.It is a method of sending and receiving digital messages through the internet.The term electronic mail has been used with its modern meaning since 1975.The shorter form E-mail became common around 1979.Additional information:Parts of a valid email address:Email PrefixEmail DomainAddress: example@mail.comexample = Email Prefixmail.com = Email DomainLast verified on 16-06-2026', 0, 0, 0, 1790966330061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b3e037eed5cf89c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Who invented the World Wide Web (WWW) with Robert Cailliau?', '{"A":"Tom Burne","B":"Tim Burner Lee","C":"Fred Zuckerberg","D":"Both a and b"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Inventor: Tim Berners-LeeCollaborator: Robert CailliauYear of invention: 1989 AugustOrganization: CERN (European physics lab, Switzerland)First website: 1991 (public release)WWWW stands for World-Wide Web Worm.Last verified on 24-06-2026', 0, 0, 0, 1790966330061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c62191ab212d4f7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which protocol is commonly used for sending emails?', '{"A":"FTP","B":"SMTP","C":"HTTP","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SMTP is the standard protocol used to send emails across the internet.SMTP stands for Simple Mail Transfer Protocol.Last verified on 16-02-2036', 0, 0, 0, 1790966330061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_55bc497452932901', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which device is required for the internet connection?', '{"A":"Joystick","B":"Modem","C":"CD drive","D":"NIC card"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Modem is a computer hardware device used for communication over a network.Modem stands for Modulator-Demodulator.A modem converts digital data into signals suitable for transmission.It also converts incoming signals back into digital data.Modems are commonly used to provide Internet connectivity.Last verified on 15-09-2026', 0, 0, 0, 1790966330061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ee2e6076666fba93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is an other name for Junk Email?', '{"A":"Spoof","B":"Spill","C":"Spam","D":"Spat"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Junk mail is also called spam.The name comes from an old Monty Python comedy sketch.It is commonly used for ads, scams, or fake promotions.Additional information:Spoof means pretending to be another sender (email spoofing).Email services use spam filters to block junk mail automatically.', 0, 0, 0, 1790966330061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8623544a6c32d676', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is the primary function of Firewall in computer networks?', '{"A":"To filter/prevent/block unauthorized access","B":"To block viruses","C":"To speed up network traffic","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A firewall’s main function is to prevent or block unauthorized access to a computer network.It acts as a security barrier between trusted and untrusted networks (like the internet).It filters incoming and outgoing network traffic based on security rules.It helps protect systems from hackers and unwanted access attempts.Last verified on 10-06-2026', 0, 0, 0, 1790966330061) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_086531085e1b1547', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which protocol is used for transferring files over the internet?', '{"A":"FTP","B":"DNS","C":"IP","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FTP (File Transfer Protocol) is specifically designed to transfer files between computers over the internet.It allows uploading, downloading, and managing files on remote servers.Last verified on 13-09-2026', 0, 0, 0, 1790966330151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fa240bb1b0f98224', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which is the computer network type that connect in a larger area, such as districts or cities?', '{"A":"LAN","B":"WAN","C":"MAN","D":"PAN"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MAN (Metropolitan Area Network): City or district coverageLAN (Local Area Network): Small area, e.g., home, officeWAN (Wide Area Network): Covers countries or continents, e.g., InternetPAN (Personal Area Network): Very small area, e.g., devices connected via BluetoothLast verified on 08-03-2026', 0, 0, 0, 1790966330151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_11fa705606b75f4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'WAN stands for?', '{"A":"Wide Area Network","B":"Wireless Area Network","C":"Web Area Network","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation WAN stands for Wide Area Network.It covers a large geographical area, potentially across countries or the whole globe.Additional information:LAN: Local Area Network covers a small area.MAN: Metropolitan Area Network generally covers a city.Last verified on 03-09-2026', 0, 0, 0, 1790966330151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4cbfd5159c8f5318', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Email is used for?', '{"A":"Sending electronic messages","B":"Browsing websites","C":"Editing images","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Email is used to send and receive electronic messages over the Internet.It allows users to communicate instantly across the world.Emails can include text, documents, images, audio, and video attachments.Additional information:Email stands for: Electronic MailSMTP: Sending emailsPOP3: Receiving/downloading emailsIMAP: Synchronizing emails across devicesEmail address format: username@domain.comLast verified on 28-07-2026', 0, 0, 0, 1790966330151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d3994e076eab3f72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'LAN stands for _____?', '{"A":"Limited Area Network","B":"Logical Area Network","C":"Local Area Network","D":"Large Area Network"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LAN stands for Local Area Network.It is a network that connects devices within a limited geographical area.LAN is commonly used in homes, schools, laboratories, university campuses, and office buildings.It provides high-speed communication and resource sharing between connected devices.Additional information:MAN: Metropolitan Area Network – Covers a city or metropolitan areaWAN: Wide Area Network – Covers a large geographical area (countries/continents)Last verified on 07-07-2026', 0, 0, 0, 1790966330151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_739c559bf2dac1aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'TCP stands for _____?', '{"A":"Transfer Communication Protocol","B":"Transmission Communication Process","C":"Transmission Control Protocol","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation TCP stands for Transmission Control Protocol.It is one of the main protocols of the Internet Protocol Suite.It was introduced in 1974.Robert Kahn and Vint Cerf are recognized as key inventors/developers of TCP/IP.Last verified on 03-09-2026', 0, 0, 0, 1790966330151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d20e1ff081ba13f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The four numbers in an IP address is called?', '{"A":"Octal","B":"Octets","C":"Bytes","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An IP address (like 192.168.1.1) consists of four numbers, each ranging from 0 to 255.Each of these numbers is called an octet because it contains 8 bits.Last verified on 02-09-2026', 0, 0, 0, 1790966330151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_27614e6d17cc43f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'URL has an abbreviation of?', '{"A":"Uniform Resource Locator","B":"Universal Resource Link","C":"Uniform Reference Link","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation URL stands for Uniform Resource Locator.It is a specific type of Uniform Resource Identifier (URI).Domain: World Wide WebFirst published: 1994Latest version: Living Standard, 2023Used:Web page (HTTP/HTTPS)File transfer (FTP)Email (mailto)Database access (JDBC)Last verified on 08-06-2026', 0, 0, 0, 1790966330151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7e3edf4b71ce3502', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What does HTTP stands for in the context of WWW?', '{"A":"Hypertext Transfer Protocol","B":"Hypertext Transfer Protection","C":"Hyper Transfer Protocol","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTTP stands for Hypertext Transfer Protocol.It is a protocol for fetching resources such as HTML documents.It provides secure communication over a computer network. It can also be used to fetch parts of documents to update Web pages on demand.https://www.google.com is called the URL.Last verified on 04-06-2026', 0, 0, 0, 1790966330233) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bbf2618be44067a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of the following is a top-level domain?', '{"A":".com","B":"Http","C":"HTML","D":"URL"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation .com is a Top-Level Domain (TLD) used mainly for commercial websites.It is part of the Domain Name System (DNS).Examples include .org, .net, .edu, and .gov.Last verified on 01-09-2026', 0, 0, 0, 1790966330233) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b403e40f4aefa4e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of the following is an example of a cloud storage service? Skype, Dropbox, Internet Explorer, Mozilla Firefox', '{"A":"Skype","B":"Dropbox","C":"Internet Explorer","D":"Mozilla Firefox"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amazon, Microsoft and Google are the three largest public cloud storage providers.Dropbox, eFolder, IBM etc. are examples of cloud service providers.Last verified on 06-07-2026', 0, 0, 0, 1790966330233) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7e854c7d7992e1a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is the function of a web browser?', '{"A":"Manage operating system updates","B":"View and interact with web content","C":"Encrypt system files","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The function of a web browser is to view and interact with web content.A web browser is software used to access and display websites on the Internet.It retrieves web pages from web servers and displays text, images, videos, and other content.Examples include Google Chrome, Mozilla Firefox, Microsoft Edge, and Safari.Browsers use web technologies such as HTML, CSS, and JavaScript to display interactive web pages.Last verified on 10-08-2026', 0, 0, 0, 1790966330234) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_564867848b1d0c3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What the the first page of a website is called?', '{"A":"First Page","B":"New Page","C":"Screen Page","D":"Home Page"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first or main page of a website is commonly called the Homepage.It usually provides an overview of the website and links to other important pages.The homepage is often the default or starting page visitors see when they visit a website.Additional information:Webpage → A single page on a websiteWebsite → Collection of related webpagesURL → Address of a webpage or websiteWeb browser → Software used to access websitesLast verified on 09-08-2026', 0, 0, 0, 1790966330234) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_80364593dea3a4b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'If you want to connect two nearby situated buildings then which of the following type of network you will use?', '{"A":"Metropolitan Area Network (MAN)","B":"Local Area Network (LAN)","C":"Wide Area Network (WAN)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LAN is ideal for connecting computers in closely located buildings, such as within a campus or office block.LAN stands for Local Area Network.It offers high speed and cost-effective connectivity over short distances.Last verified on 19-04-2026', 0, 0, 0, 1790966330234) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f01fb75e959b2aa4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Email is used to send _____?', '{"A":"Video","B":"File","C":"Audio","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Email is used to send video, files, audio, text, pictures, and other digital content.Email (electronic mail) allows users to send messages through the internet.Users can attach different types of files, including documents, images, audio, and videos.Email is also used for notifications, reminders, and communication.Last verified on 08-08-2026', 0, 0, 0, 1790966330234) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b9e0c0f4219af5ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is internet?', '{"A":"Interconnection of wide area networks","B":"A single network","C":"A collection of unrelated computers","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The internet is a global system of interconnected computer networks.It primarily composed of wide area networks (WANs).It allows data sharing and communication between devices worldwide through standardized protocols like TCP/IP.Last verified on 07-08-2026', 0, 0, 0, 1790966330234) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d092f9b3d88d7523', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is the use of a firewall in a computer?', '{"A":"For data transmission","B":"For monitoring","C":"For security","D":"For authentication"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A firewall is used for security by protecting a computer or network from unauthorized access and cyber threats.It monitors and filters incoming and outgoing network traffic.Firewalls block malicious connections while allowing trusted communication.They help prevent hacking, malware, and unauthorized access.Firewalls can be hardware-based or software-based.Last verified on 02-08-2026', 0, 0, 0, 1790966330324) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5c0f6a4650354841', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of the following is a type of computer network that covers a large geographic area, such as a country?', '{"A":"Metropolitan Area Network (MAN)","B":"Local Area Network (LAN)","C":"Wide Area Network (WAN)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wide Area Network (WAN) covers a large geographic area, such as a country or multiple countries.WAN connects multiple LANs and MANs through public or private communication links.The Internet is the world''s largest example of a WAN.WAN is commonly used by governments, businesses, banks, and multinational organizations.It enables long-distance communication and data sharing.Last verified on 01-08-2026', 0, 0, 0, 1790966330324) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_62439861c001d558', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which protocol assigns IP address to the client connected in the internet?', '{"A":"DHPP","B":"DHHP","C":"DHCP","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DHCP automatically assigns IP addresses to devices.It also provides subnet mask, gateway, and DNS information.DHCP stands for Dynamic Host Configuration Protocol.Last verified on 15-01-2026', 0, 0, 0, 1790966330324) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b34f73e43ba2ee2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Who is called the Father of Internet?', '{"A":"Vint Cerf","B":"Charles Babbage","C":"Tim Berners Lee","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Name: Vinton Gray CerfKnown as: Father of InternetBorn: 23 June 1943Major Contribution: TCP/IP protocol developmentAward: National Medal of Technology (1997)Last verified on 20-06-2026', 0, 0, 0, 1790966330324) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e79f46594205eea8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Crimes committed using computers and the internet are called?', '{"A":"Cybercrime","B":"Crime against person","C":"Violent crime","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790966330324) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f6b1e7e36ea32b9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is the purpose of DNS (Domain Name System) in computer networks?', '{"A":"Manage network hardware","B":"Translate domain names to IP addresses","C":"Establish secure connections","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main purpose of DNS (Domain Name System) is to translate domain names into IP addresses.It works like an internet phonebook.It helps users access websites using easy names instead of numeric IPs.Example: google.com → 142.250.190.14Last verified on 09-06-2026', 0, 0, 0, 1790966330324) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_51cda358a799a482', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The purpose of an IP address is _______?', '{"A":"To uniquely identify a device on a network","B":"To encrypt internet connections","C":"To speed up downloads","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An IP address is used to uniquely identify a device on a network.It allows devices to communicate and exchange data over a network or the Internet.Every device connected to a network is assigned an IP address.An IP address helps send data to the correct destination.Last verified on 07-07-2026', 0, 0, 0, 1790966330324) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9fd036a56263a1b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'How many types of network on the basis of distance?', '{"A":"3","B":"4","C":"5","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Networks are typically classified into four main types based on distance (geographical coverage):PAN (Personal Area Network) – Very short distance (e.g., Bluetooth, USB connections).LAN (Local Area Network) – Limited area (e.g., home, office, or school network).MAN (Metropolitan Area Network) – City-wide coverage (e.g., ISP networks in a city).WAN (Wide Area Network) – Large-scale, global reach (e.g., the Internet).Last verified on 08-06-2026', 0, 0, 0, 1790966330324) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b962a689661c5403', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which protocol is used to establish a secure channel of communication over a potentially insecure network?', '{"A":"HTTPS (SSL/TLS)","B":"DHCP","C":"FTP","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTTPS (SSL/TLS) is used to establish a secure channel of communication over a potentially insecure network.SSL (Secure Sockets Layer) and TLS (Transport Layer Security) are cryptographic protocols.They encrypt data to protect it from hackers during transmission.They ensure data confidentiality, integrity, and authentication.Commonly used in secure websites (HTTPS connections).Last verified on 08-06-2026', 0, 0, 0, 1790966330397) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ee6e790964d94300', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which is the largest (biggest) search engine on the internet?', '{"A":"Google","B":"MSN","C":"Yahoo","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Google is the largest search engine on the internet.It holding more than 80% of the global search market share.Google is a US multinational technology company that provides internet search services.It started as a search engine in 1997.It was officially founded on September 4, 1998.Its parent organization is Alphabet Inc.Last verified on 02-07-2026', 0, 0, 0, 1790966330397) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f628885eda94efb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which protocol is used in internet?', '{"A":"TCP/IP","B":"TCG/IP","C":"TCS/IP","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation TCP/IP is the main protocol suite used for communication over the Internet.TCP stands for Transmission Control Protocol.IP stands for Internet Protocol.IP handles the addressing and routing of data packets.TCP ensures reliable delivery of data between devices.Other protocols like HTTP, FTP, and SMTP work on top of TCP/IP.TCP/IP allows different networks and devices to communicate seamlessly.Last verified on 02-07-2026', 0, 0, 0, 1790966330397) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_937df758aadbe0a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'WWW stands for ____?', '{"A":"World Whole Web","B":"Wide World Web","C":"Web World Wild","D":"World Wide Web"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation WWW stands for World Wide Web.Additional information:It is an information system.First published: 6 August 1991Founder: Tim Berners-Lee in 1989.Birthplace: CERN near Geneva, Switzerland.Last verified on 01-07-2026', 0, 0, 0, 1790966330397) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e55989588f7ea8c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', '_______ is a type of electronic spam where unsolicited messages are sent by e-mail.', '{"A":"Trash mail","B":"Cram mail","C":"Draft mail","D":"Spam mail"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Spam (also called Junk Email) is a type of electronic spam in which unsolicited messages are sent through e-mail.Additional information:E-mail stands for Electronic Mail.It was invented by Ray Tomlinson.The first e-mail was sent in 1971.E-mail is used for sending and receiving electronic messages over the internet.Last verified on 01-07-2026', 0, 0, 0, 1790966330397) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5cbe12e9f0ff3305', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which symbol is mandatory in an email address? &, #, @, None of these', '{"A":"&","B":"#","C":"@","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Every valid email address must contain the @ (at) symbol.It separates the username from the domain name.Without @, an email address is invalid and cannot work.Last verified on 16-02-2026', 0, 0, 0, 1790966330397) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6fd722cd91021668', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'A cookie on a website is used to?', '{"A":"Clean browser history","B":"Store passwords","C":"Track and remember user preferences","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A website cookie is used to track and remember user preferences and browsing activity.It helps websites recognize returning users.It stores small data like login info, settings, and preferences.It improves user experience by personalizing content.Last verified on 24-06-2026', 0, 0, 0, 1790966330397) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9560e82f04318737', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What does the term HTTPS means?', '{"A":"Hyper Text Transfer Protocol Secure","B":"Hyper Text Translation Protocol Service","C":"Hyper Text Translation Protocol Secure","D":"Hyper Text Transfer Protocol Service"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full form: Hyper Text Transfer Protocol SecureSecurity layer: SSL/TLS encryptionPurpose: Secure data transfer on the internetDefault port: 443Used in: Banking, e-commerce, login systemsLast verified on 23-06-2026', 0, 0, 0, 1790966330397) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2cc6ca92921ba5b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'A(An) _____ is an Internet service that provides remote storage to computer users.', '{"A":"Smart TV","B":"Cloud Storage","C":"Solid-state drive (SSD)","D":"Bluetooth"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cloud storage is an internet-based service for storing data remotely.Users can save files on online servers instead of local devices.It allows access to data from anywhere with internet connection.It is widely used for backup and file sharing.Last verified on 29-05-2026', 0, 0, 0, 1790966330471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_be63c16d3f372013', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of the following is not a valid option to insert a hyperlink in Excel, which can link to? Link to home, Existing file or web page, Place in this document, Create new document, E-mail Address', '{"A":"Link to home","B":"Existing file or web page","C":"Place in this document","D":"Create new document","E":"E-mail Address"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Link to home" is not a valid option to insert a hyperlink in Excel.Additional information:To insert a hyperlink in Excel, you can follow these steps:Select the cell or text where you want to insert the hyperlink.Right-click on the selected cell or text and choose "Hyperlink" from the context menu.In the "Insert Hyperlink" dialog box, you will see different options to choose from. "Existing File or Web Page"Last verified on 29-05-2026', 0, 0, 0, 1790966330471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_31ebf02cbc7b7805', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'DNS stands for _____?', '{"A":"Dedicated Numerical Server","B":"Domain Name System","C":"Digital Network Software","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DNS stands for Domain Name System.It translates website names (like google.com) into IP addresses.It works like the “phone book of the internet.”Without DNS, users would need to remember numeric IP addresses.DNS was introduced in 1983.Last verified on 26-05-2026', 0, 0, 0, 1790966330471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4cfa9541f29f46d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'An Email address consists of two parts, Username or ID and _____?', '{"A":"URL","B":"Domain name","C":"Password","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An email address consists of two parts: Username or ID (the name or ID chosen by the user)Domain name (the name of the organization or service provider).Format: Username@Domainname.comExample: john.doe@example.comAdditional information:Email, short for Electronic Mail, has its roots in the early 1960s. The first email was sent in 1971 by Ray Tomlinson.He also introduced the "@" symbol to separate the username from the hostname.Last verified on 19-04-2026', 0, 0, 0, 1790966330471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9afed9debf6ce02b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of the following is not an example of a Web Browser? Google Chrome and Safari, Internet Explorer and Firefox, Microsoft Office and Net Beans', '{"A":"Google Chrome and Safari","B":"Internet Explorer and Firefox","C":"Microsoft Office and Net Beans","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Web Browser is a software application used to access and view websites on the Internet.Examples include Google Chrome, Safari, Internet Explorer, and Firefox.Microsoft Office is an office suite, and NetBeans is an IDE (Integrated Development Environment), not browsers.Last verified on 10-03-2026', 0, 0, 0, 1790966330471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fe52a08f5ae91e9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Bandwidth is usually measured in _____ ?', '{"A":"Cycles per second","B":"Bits per second","C":"Bytes per second","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bandwidth refers to the amount of data transmitted per second.It is measured in bits per second (bps).It indicates the speed or capacity of a network connection.Last updated 15-feb-2026', 0, 0, 0, 1790966330471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c3279195dfad025e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'In a network with 25 computers which topology would require the most extensive cabling?', '{"A":"Star","B":"Mesh","C":"Bus","D":"None of above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a network with 25 computers, a full mesh topology requires the most extensive cabling. Mesh Topology: Every node is connected to every other node, creating 300 unique connections for 25 computers.Last updated 15-feb-2026', 0, 0, 0, 1790966330471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_09dacaf4b5e81256', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which is an example of WAN?', '{"A":"Share it","B":"Mobile broadband connections","C":"Bluetooth","D":"VPN"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The internet, large corporate networks, and banking networks are common examples of WANsA WAN can cover country, continent or even a whole world. Other examples of WAN are mobile broadband connections such as 3G, 4G etc.Last updated 15-feb-2026', 0, 0, 0, 1790966330471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d3f9f0a71e6e0dc8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'NIC stands for _______?', '{"A":"Network Internet Card","B":"Network Interface Card","C":"Network Intranet Card","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NIC stands for Network Interface Card.It connects a computer to a network or internet.It can be wired (Ethernet) or wireless (Wi-Fi).Every NIC has a unique MAC address.It enables data communication between devices.Last verified on 07-02-2026', 0, 0, 0, 1790966330552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_db12bf99b1fe7f9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Famous social website Facebook was founded by ____?', '{"A":"Elon Musk","B":"Steve Jobs","C":"Bill Gates","D":"Mark Zekerburg"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Founder: Mark ZuckerbergFounded in: February 4, 2004Headquarters: Menlo Park, California, USAUsers (2023): Over 3 billion monthly active usersParent Company: Meta Platforms Inc.Last verified on 16-01-2026', 0, 0, 0, 1790966330552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_620cf657b9dfbc7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The man who built the first Mechanical Calculator was ______?', '{"A":"Blaise Pascal","B":"Harward Aliken","C":"John Mauchly","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blaise Pascal, a French mathematician, created it in 1642.The first mechanical calculator was invented to perform addition and subtraction automatically.It was powered by gears and wheels.Additional information:Pascal’s calculator was called the Pascaline.John Mauchly co-invented the ENIAC (first electronic computer) much later.Harvard Aliken is unrelated to the first calculator.Last verified on 16-01-2026', 0, 0, 0, 1790966330552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e40160e6bca1c276', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'A computer on internet is identified by its ______?', '{"A":"E-mail Address","B":"Street Address","C":"Login Password","D":"IP Address"}', 'D', NULL, 0, 0, 0, 1790966330552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_98c726854bc2992c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The first network called ______?', '{"A":"CNNET","B":"NSFNET","C":"ASAPNT","D":"ARPANET"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ARPA stand for Advanced Research Projects Agency.ARPANET was the basis of the Internet. ARPANET Concept first published in 1967. ARPANET was developed by the U.S.A.', 0, 0, 0, 1790966330552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a8c568e8d7698386', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The process of transferring files from a computer on the Internet to your computer is called?', '{"A":"Forwarding","B":"Downloading","C":"Uploading","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Downloading means receiving data or a file from the Internet on your computer. Uploading means sending data or a file from your computer to somewhere on the Internet.', 0, 0, 0, 1790966330552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cd55edb33184c1f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which unit is typically used to measure network bandwidth or internet speed?', '{"A":"Gigahertz (GHz)","B":"Megabit per second (Mbps)","C":"Terabyte (TB)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mbps: Megabits per secondCommonly used for: Internet speed and network bandwidth1 Megabit: 1,000,000 bitsHigher Mbps: Faster internet/data transferAdditional information:GHz measures frequency.TB measures data storage capacity.', 0, 0, 0, 1790966330552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d983a392758c06c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is the process of data copying from a server to a personal computer called?', '{"A":"Uploading","B":"Sharing","C":"Copying","D":"Downloading"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The data copying process from a server to a personal computer is called:Downloading / a downloadReverse (PC → server) = uploading', 0, 0, 0, 1790966330552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cec328539852d47c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', '________ is a network that connects computers and devices in a limited geographical area, such as a home, school, computer laboratory, or office building.', '{"A":"Metropolitan Area Network (MAN)","B":"Local Area Network (LAN)","C":"Wide Area Network (WAN)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A local area network (LAN) is a network that connects devices and computers in a limited geographical area. LANs can be found in homes, schools, offices, computer labs, and other nearby buildings.', 0, 0, 0, 1790966330655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_84e73b9a0cdca21b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is an IP address?', '{"A":"A software application used to access the internet","B":"A type of computer hardware","C":"A type of computer virus","D":"A unique identifier assigned to a computer on a network"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The IP address is a group of numbers that identify user system on the network.IP address means Internet Protocol Address. There are two types of IP addressesIPv4..it consists of 32 bitsIPv6.it consists of 128 bits', 0, 0, 0, 1790966330655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7fbc5e8c711c11b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of the following is not a type of computer network? Universal Area Network (UAN), Local Area Network (LAN), Wide Area Network (WAN), Personal Area Network (PAN)', '{"A":"Universal Area Network (UAN)","B":"Local Area Network (LAN)","C":"Wide Area Network (WAN)","D":"Personal Area Network (PAN)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation UAN is not a recognized type of computer network.LAN, WAN, and PAN are all standard computer network types.', 0, 0, 0, 1790966330655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3ed4dd59dc237e79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Internet is also called', '{"A":"the Net","B":"a network of networks","C":"Both","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Internet sometimes called simply "the Net,"***Internet explorer falls under BrowserThe Internet is a worldwide system of computer networks***the function of the internet:To receive e-mailTo advertise commercial productsTo connect one computer to another', 0, 0, 0, 1790966330655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8528ef8c4d3a5050', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Small files that are deposed on user''s hard drive when they visit a website are best described as', '{"A":"Codes","B":"Cookies","C":"Trackers","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cookies are text files with small pieces of data.like a username and password .That are used to identify your computer as you use a computer network. Specific cookies known as HTTP cookies are used to identify specific users and improve your web browsing experience.', 0, 0, 0, 1790966330655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_61dbdbe15739a6e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The browser _____keep a list of web pages you have visited in the current session?', '{"A":"History","B":"Cache","C":"Trail","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The browser history keeps a list of web pages you have visited in the current session. It records the URL, title, and visit time, allowing you to go back to previous pages and use the back/forward buttons.', 0, 0, 0, 1790966330655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cd91189647e7b862', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of the following is a correct email format of Email address?', '{"A":"Name.website.com","B":"Www.nameofebsite.com","C":"Name@website.com","D":"Name@website@info"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation there are two parts of A valid email address.email prefix an email domain, In the address example@mail.com, "example" is the email prefix, "mail.com" is the email domain.', 0, 0, 0, 1790966330655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_61079e9968fdd2f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of the following is not a major reason for an email bounce?', '{"A":"Domain server is down","B":"Stale file handle","C":"bad domain name","D":"Bad user account name"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An email bounce usually occurs due to issues like a bad domain name or a bad user account name.However, a temporary issue like the domain server being down is not a major or common cause for permanent email bounce.', 0, 0, 0, 1790966330655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7b1b6f3216c16596', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of following is a web browser?', '{"A":"Paint and Database","B":"Word and PowerPoint","C":"Fire fox and Chrome","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Firefox and Google Chrome are popular web browsers used to access the internet.They allow users to view and interact with web pages.Mozilla Firefox, or simply Firefox, is a free and open-source web browserInitial release September 23, 2002.In 2017, Firefox began incorporating new technology under the code name Quantum to promote parallelism and a more intuitive user interface.', 0, 0, 0, 1790966330731) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_aa6cabeb6ca359fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'FTP stands for _____?', '{"A":"File transfer protection","B":"Film transfer protocol","C":"File transfer protocol","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation File Transfer Protocol (FTP) FTP is a communications protocol used to send files from computer to computer FTP does not use encryption.FTP is built on a client-server model FTP first Introduction: April 16, 1971', 0, 0, 0, 1790966330731) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b70ede1595e32d65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is used in a computer to protect a networked server from damage by those who log in to it?', '{"A":"Gateway","B":"Flow Control","C":"Antivirus","D":"Firewall"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Firewall is used in a computer network to protect a server from unauthorized access and potential damage by those who log in.It monitors and controls incoming and outgoing network traffic based on predetermined security rules.', 0, 0, 0, 1790966330731) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5fbf3558ce4166e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which internet protocol is considered the best for HTTP/IP?', '{"A":"HTTPS","B":"HTTP","C":"FTP","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTTPS (Hypertext Transfer Protocol Secure) is considered the best for HTTP/IP because it encrypts data between the client and server, ensuring privacy and security.Unlike HTTP, which is unencrypted, HTTPS adds a layer of security using SSL/TLS protocols, preventing data from being intercepted during transmission.', 0, 0, 0, 1790966330731) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_29f6ff7435a0fe20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which connection type is commonly used for an internet cable?', '{"A":"Ethernet","B":"HDMI","C":"USB","D":"VGA"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Ethernet connection is the standard for wired internet connectivity, using Ethernet cables to connect devices like computers, routers, and modems to a network. Other options like HDMI, USB, and VGA are used for different purposes, such as video or data transfer.', 0, 0, 0, 1790966330731) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8437e4591a7987c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of following item is not usually in Local Area Network (LAN)?', '{"A":"Computer modem","B":"Modem","C":"Cable","D":"Interface card"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A local area network is a group of computers and associated devices that share a common communications line or wireless link to a server.Modem is a combined device for modulation and demodulation.For example, between the digital data of a computer and the analogue signal of a phone line.', 0, 0, 0, 1790966330731) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_63481596768beedb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'A unique address for a file that is accessible on the Internet is ______?', '{"A":"IP","B":"URL","C":"Password","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Uniform Resource Locator (URL), colloquially termed a web address.It refers to a web resource that specifies its location on a computer network and a mechanism for retrieving it.', 0, 0, 0, 1790966330731) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f753a8b921e074db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which is a technology that provides high-speed Internet connection using regular copper telephone lines?', '{"A":"ISP","B":"CMOS","C":"DSL","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DSL (Digital Subscriber Line) is a technology that uses standard copper telephone lines to deliver high-bandwidth information.It provides high-speed internet without disrupting regular phone services.DSL is commonly used for broadband internet in homes and small businesses.', 0, 0, 0, 1790966330731) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_684b0781e031fbfe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is the full form of URL?', '{"A":"Uniform routing locator","B":"Universal resource locator","C":"Uniform resource locator","D":"Uniform router locator"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The full form of URL is Uniform Resource Locator.It is commonly known as a web address. It tells your web browser how and where to find a specific resource on the internet, like a web page, image, or fileURL has three parts:Protocol such as http:// or https://. Domain name such as example.com.Path such as /about.htmlLast updated by NA on 09-09-2026', 0, 0, 0, 1790966330806) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eefbd35837cc9479', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', '________ are used to identify a user who returns to a Website.', '{"A":"Cookies","B":"Plug-ins","C":"Scripts","D":"ASPs"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cookies are used to identify a user who returns to a Website.A cookie is a small file of letters and numbers downloaded onto your computer when you access certain websites.', 0, 0, 0, 1790966330806) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2d5b24c7f68487ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What type of connection would be used to connect a printer directly to a network?', '{"A":"Ethernet cable","B":"USB","C":"Serial","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A printer is connected directly to a network using a network connection, typically one of the following:Ethernet (RJ-45) — a wired connection to a router or switch.Wi-Fi (wireless) — connects to the network without cables.Here are some other ways to connect a printer to a network:USB: A direct connection between the printer and the computerWi-Fi: A wireless connection between the printer and the LANBluetooth: A wireless connection between the printer and the computer', 0, 0, 0, 1790966330806) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fb1ed4fe7724777a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'In an email account, ______ contains a list of names and email addresses.', '{"A":"Address book","B":"Outbox","C":"Trash","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The address book contains a list of names and email addresses for easy reference and sending emails.It allows users to quickly select recipients without manually entering email addresses each time.', 0, 0, 0, 1790966330806) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d3e6bba16f98d1ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The major and most popular language of WWW is ______?', '{"A":"PHP","B":"HTML","C":"Java","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTML (Hypertext Markup Language) is the standard markup language used to create web pages and display content on the internet.It is the most widely used language on the web.It is the backbone of a website''s structure and content.', 0, 0, 0, 1790966330806) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8f5439e8e96ca6d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Physical or logical arrangement of network is _____?', '{"A":"Topology","B":"Routing","C":"Networking","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A network topology is the physical and logical arrangement of nodes and connections in a network.AGM 24-12-2022', 0, 0, 0, 1790966330806) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d7004756d396c9a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Internet explorer falls under _____?', '{"A":"Operating System","B":"Compiler","C":"Browser","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Internet Explorer is a web browser developed by Microsoft.It used for accessing and navigating the internet.', 0, 0, 0, 1790966330806) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a21776e2dec2e036', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which is used for open a website?', '{"A":"Browser","B":"Google","C":"Yahoo","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A browser, such as Chrome or Firefox.It is a software application used to access and display websites on the internet.A web browser is application software for accessing the World Wide Web or a local website.', 0, 0, 0, 1790966330806) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8f279949c0718399', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Modem stands for what?', '{"A":"Modulation Memodulation","B":"Modern Memodulation","C":"Old Memodulation","D":"Modulation and Demodulation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MODEM stands for Modulation and Demodulation. A modem''s purpose is to convert digital information to analog signals (modulation), and to convert analog signals back into useful digital information (demodulation).ND23-9-2023', 0, 0, 0, 1790966330874) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7af3b8589c2b163f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The process of connecting to the internet account is _____?', '{"A":"Sign in","B":"Log out","C":"Log in","D":"Sign out"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process of connecting to an internet account is called Log in.It involves entering your credentials to access the account.Log out refers to the process of disconnecting from your account, ending your session.', 0, 0, 0, 1790966330874) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_70db966344a23e30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Email hacking means ____?', '{"A":"Finding email password","B":"Finding email address","C":"Finding email server","D":"Illegal access to open email accounts of others"}', 'D', NULL, 0, 0, 0, 1790966330874) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8b25cac9a2bbb712', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is the primary purpose of a "Proxy Server" in a network?', '{"A":"To manage TCP/IP connections","B":"To block unauthorized access to the network","C":"To cache frequently accessed web pages","D":"To route TCP/IP requests from clients to servers"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Proxy Server — Purpose:Acts as intermediary between client and server.Routes client TCP/IP requests to servers.May cache web pages for speed.', 0, 0, 0, 1790966330874) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_663a82b43bdd11c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The IP address 192.168.1.1 is an example of which type of IP address?', '{"A":"Public IP address","B":"Private IP address","C":"Dynamic IP address","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Manufacturers of home routers use private IP addresses, including 192.168. 1.1, as the default gateway, allowing users to type http://192.168.1.1 into a web browser to access the router admin panel and change router settings.', 0, 0, 0, 1790966330874) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2a6da83de3ee3ae4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The concept that ensures a website is compatible and accessible across different devices and browsers is called', '{"A":"Web Compatibility","B":"Web Designing","C":"Web Responsiveness","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Browser compatibility refers to the ability of a website or web application to function correctly across different web browsers.', 0, 0, 0, 1790966330874) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f44f52ed4cba5692', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Modem is used for _____?', '{"A":"Storing data","B":"Connecting to the internet","C":"Printing documents","D":"Scanning images"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A modem''s purpose is to convert digital information to analog signals (modulation), and to convert analog signals back into useful digital information (demodulation).MODEM stands for Modulation and Demodulation.', 0, 0, 0, 1790966330874) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bba7ca3132a057e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The most widely used internet search engine in the world is:', '{"A":"Yahoo","B":"Google","C":"MSN","D":"YouTube"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Google. With over 80% of the search market shareGoogle, a US multinational technology companyGoogle is a type of search engine operating since 1997Google was founded in the year: September 4, 1998The Headquarters of Google is located in the city: of CaliforniaSergey Brin & Larry Page is the founder of GoogleSergey Brin is the real owner of GoogleParent organization: Alphabet Inc.*******The oldest search engine is YahooND23-4-2023', 0, 0, 0, 1790966330874) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2dabc2edeeb947fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of following is considered as latest browser ?', '{"A":"mosaic","B":"google chrome","C":"Mozila firebox","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Google Chrome is a cross-platform web browser developed by Google. It was first released in 2008.Firefox was first released as Firefox 1.0 on November 9, 2004.Mosaic Initial release date: January 23, 1993', 0, 0, 0, 1790966330954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c20792a81c2f5bdd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of the following protocols is used to transfer files from one host to another over the internet?', '{"A":"TCP","B":"IP","C":"UDP","D":"FTP","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation File Transfer Protocol (FTP)FTP is a communications protocol used to send files from computer to computerFTP does not use encryption.FTP is built on a client-server model FTP first Introduction: April 16, 1971*********FIA VU CONSTABLE PAST PAPER 2021', 0, 0, 0, 1790966330954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_aafffbfa6852bc29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'A website content can be viewed in', '{"A":"internet","B":"Links","C":"Wi-fi","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A web page can be viewed with the help of a web browser and active internet. A web page refers to a hypertext document on the World Wide Web. They are delivered by a web server to the user and are displayed in a web browser.', 0, 0, 0, 1790966330954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9a1574174e97e419', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Website use information called____', '{"A":"proxy","B":"defender","C":"tracker","D":"Virtual private network"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Web tracking is the practice by which operators of websites and third parties collect, store and share information about visitors’ activities on the World Wide Web.', 0, 0, 0, 1790966330954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_33e26b8e0a9cad9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which of the following cannot be a part of an email address?', '{"A":"Space()","B":"Underscore (_)","C":"At sign (@)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Email addresses cannot contain spaces, as they are not valid characters in email formatting.Other characters like underscore (_) and at sign (@) are allowed. TThe at sign (@) is essential because it separates the username from the domain in an email address.', 0, 0, 0, 1790966330954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ab32298ee04f0f06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'For creating new email from', '{"A":"Sign in","B":"Sign up","C":"create new email","D":"none"}', 'B', NULL, 0, 0, 0, 1790966330954) ON CONFLICT(id) DO NOTHING;
