INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9d608ab72e067dfe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which type of switching is used in internet:', '{"A":"Telephone","B":"Circuit","C":"Packet","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Packet switching is used in the Internet and most local area networks. The Internet is implemented by the Internet Protocol Suite using a variety of Link Layer technologies.', 0, 0, 0, 1790966330954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eb6fcaaa0c420d7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'MAN stands for', '{"A":"Metropolitan Area Network","B":"Main Area Network","C":"Median  Area Network","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A metropolitan area network (MAN) It''s a computer network that connects computers within a metropolitan area A MAN is larger than a local area network (LAN) but smaller than a wide area network (WAN).*******VU CBT FIA PAPER 30-12-2021', 0, 0, 0, 1790966331016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5d22cfb963d58297', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'In Internet explorer, favorites bar can be shown and hidden by choosing it in toolbars option under……………tab?', '{"A":"View","B":"Edit","C":"Help","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The View tab enables you to switch between Normal or Master Page, and Single Page or Two-Page Spread views', 0, 0, 0, 1790966331016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0dcef19ef4c026a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Who among the following is considered the inventor of the World Wide Web(WWW)', '{"A":"Japan","B":"Emile Durkheim","C":"Vinod Dham","D":"Tim Berners-Lee"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation English scientist Tim Berners-Lee invented the World Wide Web in 1989.WWW Birthplace CERN near Geneva, Switzerland.The browser was released to the general public in August 1991.WWW is an information system.The major and most popular language of www is Html (Hypertext markup language)', 0, 0, 0, 1790966331016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bc70e6fff92a7aae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Free of cost repair of software bug available at internet is called :', '{"A":"IP Address","B":"Patch","C":"Bug","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Patch management is the process of applying fixes and upgrades to software. ***************vu FIA CBT PAPER 15-12-2021', 0, 0, 0, 1790966331016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b5c3c873e8fb383f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Which one is used to divide Email into two parts?', '{"A":"@","B":"&","C":"#","D":"*","E":"All of the above"}', 'A', NULL, 0, 0, 0, 1790966331016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5d570768a6baa103', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'If you want to close your email account, you should click on:', '{"A":"Sign Out","B":"Log Out","C":"Exit","D":"Deactivate Account"}', 'A', NULL, 0, 0, 0, 1790966331016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2e0136b4d649315d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Internet Explorer is used for :', '{"A":"Listning Music","B":"Viewing Web Pages","C":"Viewing Movie","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Internet Explorer is a free web browser, commonly called IE or MSIE, that allows users to view web pages on the internet.', 0, 0, 0, 1790966331016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_54c0d1af91ddcee4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'What is the function of internet?', '{"A":"To receive e-mail","B":"To advertise commercial products","C":"To connect one computer to another","D":"All of these"}', 'D', NULL, 0, 0, 0, 1790966331016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0738bef5cec4a4df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'Several computers linked to server to share programs and storage space ___', '{"A":"Network","B":"Library","C":"Grouping","D":"Integrated system"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer network is a set of computers sharing resources located on or provided by network nodes. The computers use common communication protocols over digital interconnections to communicate with each other.', 0, 0, 0, 1790966331081) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a1bcc3c633c11cf4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'URL has how many parts_?', '{"A":"Two","B":"Three","C":"Four","D":"Five","E":"Six"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation URL stands for Uniform Resource Locater.URL has three parts:01. Protocol02. Domain name03. Path', 0, 0, 0, 1790966331081) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ff97f47228bf09ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_internet', 'The network in which we connect each node to the network to a single piece of network cable is called___.', '{"A":"Bus network topology","B":"Star network topology","C":"Ring network topology","D":"All","E":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Network topology in which you connect each node to the network along a single piece of network cable is called bus topology.', 0, 0, 0, 1790966331081) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_comp_excel', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'MS Excel', 'top_computer', 90, 1790966331140) ON CONFLICT(id) DO UPDATE SET total_mcqs = 90;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ffac388472bc8fd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel formula and function start with ____?', '{"A":"+","B":"-","C":"=","D":"["}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, every formula and function starts with the equal sign (=).The = tells Excel that the cell contains a formula, not plain text.Functions such as SUM, AVERAGE, and IF also begin with =.Without the =, Excel treats the entry as ordinary text.Last verified on 10-02-2026', 0, 0, 0, 1790966331217) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_544386c548444dc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'What is the default file extension for Microsoft Excel 2007 and later?', '{"A":".xls","B":".xlsx","C":".pptx","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Excel 2007–2026 (Default): .xlsxAdditional information:Excel 97–2003 (Default): .xlsExcel Macro-Enabled Workbook: .xlsmExcel Binary Workbook: .xlsbExcel Template: .xltxLast verified on 12-07-2026', 0, 0, 0, 1790966331217) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c9e9b343674dfdef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel ______ shortcut key is used for hiding rows.', '{"A":"Ctrl+H","B":"Ctrl+7","C":"Ctrl+9","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel Ctrl+9 shortcut key is used for hiding rows.Additional information:Ctrl+0 (zero) to Hide Columns.Ctrl+Shift+( to Unhide Rows.Ctrl+Shift+) to Unhide Columns Ctrl + N New WorkbookCtrl + O Open WorkbookCtrl + S Save WorkbookCtrl + P PrintCtrl + K Insert HyperlinkCtrl + ; Insert Current DateCtrl + Shift + ; Insert Current TimeLast updated NA on 10-09-2026', 0, 0, 0, 1790966331217) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1ae37283c773a527', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which keyboard shortcut key is used to edit the formula or the selected cell in MS Excel?', '{"A":"F2","B":"F4","C":"CTRL + 1","D":"CRTL + F"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressing F2 allows you to edit the contents or formula of the current cell in MS Excel.Additional information:F4: Repeat last action / toggle absolute and relative referencesCTRL + 1: Opens Format Cells dialogCTRL + F: Opens Find dialogWorks in: Excel 2007, 2010, 2013, 2016, 2019, 365Last verified on 12-03-2026', 0, 0, 0, 1790966331217) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_63169337cdd9efb3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Shortcut key to insert a new worksheet in Excel is _______?', '{"A":"Alt + Shift + F1","B":"Shift + F11","C":"Shift + F10","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alt + Shift + F1 / Shift + F11 → Insert a new worksheetAdditional information:Shift + F10 → Open shortcut/context menuCtrl + Page Up → Previous worksheetCtrl + Page Down → Next worksheetLast verified on 15-07-2026', 0, 0, 0, 1790966331217) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ca32c05cef174e04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'What is MS Excel primarily used for?', '{"A":"Creating and editing presentations","B":"Creating and editing spreadsheets / Data Calculations","C":"Creating and editing images","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft Excel is a spreadsheet program used to organize, calculate, and analyze data efficiently. It is widely used in offices, schools, and businesses for data management.Additional information:Allows calculations using formulas and functions.Can create charts, graphs, and pivot tables for data analysis.Supports data sorting, filtering, and visualization.Last verified on 17-01-2026', 0, 0, 0, 1790966331217) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9bf9ea17efcb5318', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which sign is used to create an absolute cell reference in MS Excel?', '{"A":"@","B":"=","C":"$","D":"%"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The dollar sign ($) is used to create an absolute cell reference in MS Excel.Additional information:Absolute Reference: $D$2 (Row and column fixed)Relative Reference: D2 (Row and column change)Mixed Reference: $D2 (Column fixed)Mixed Reference: D$2 (Row fixed)Shortcut Key: F4 toggles between reference types.Last verified on 18-07-2026', 0, 0, 0, 1790966331217) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fc32d5332d64389b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, which function counts only non-empty cells in a range?', '{"A":"COUNTA()","B":"COUNT()","C":"COUNTIF()","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation COUNTA() counts only non-empty cells in a selected range.It counts cells containing numbers, text, logical values (TRUE/FALSE), errors, and formulas that return values.It does not count completely empty cells.COUNTA() is commonly used for counting filled entries in datasets.Additional information:COUNT() → Counts only numeric cellsCOUNTBLANK() → Counts empty (blank) cellsCOUNTIF() → Counts cells matching a specific conditionCOUNTIFS() → Counts cells matching multiple conditionsLast verified 08-07-2026', 0, 0, 0, 1790966331217) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_05d5b9b3e48eeba3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'The correct syntax of using the COUNTIF() function in MS Excel 2016 is ______?', '{"A":"=COUNTIF (Criteria, Range)","B":"=COUNTIF (Range, Criteria)","C":"=COUNTIF (Criteria, True, False)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Order of arguments:First argument: Range – the cells you want to countSecond argument: Criteria – the condition that defines which cells to countExample:=COUNTIF(A1:A10, ">20") counts how many cells in range A1 to A10 have a value greater than 20.Last verified on 05-09-2026', 0, 0, 0, 1790966331297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7e0cf6e4d49c9ad7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In Microsoft Excel, what is the purpose of conditional formatting?', '{"A":"To apply formatting based on specified criteria or rules.","B":"To create custom functions for complex calculations.","C":"To sort data in alphabetical or numerical order.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Conditional formatting highlights cells automatically based on set conditions or rules (e.g., values greater than 100).It helps in quickly analyzing data trends by using colors, icons, or data bars.Last verified on 02-09-2026', 0, 0, 0, 1790966331297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3f704d5edf4a5cd7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Computer spreadsheet cell that is highlighted with a heavy border is a ______?', '{"A":"Active cell","B":"Cell containing a formula","C":"Locked cell","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The active cell is the currently selected cell in a spreadsheet.It is usually highlighted with a heavy/thick border.Data entered from the keyboard is placed into the active cell.Only one cell is normally active at a time.Last verified on 26-08-2026', 0, 0, 0, 1790966331297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b46d6ad31d5297c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In a computer spreadsheet, which is true if the current or active cell is B4 and you pressed Enter key?', '{"A":"You will be in the cell A1","B":"You will be in the cell B5","C":"You will be in the cell B3","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Excel, pressing Enter normally moves the active cell down one row.If the current cell is B4, pressing Enter moves the selection to B5.This is the default behavior unless the Enter key direction has been changed in Excel settings.Last verified on 26-08-2026', 0, 0, 0, 1790966331297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8f118afb9c7d20e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which of the following is NOT an element of spreadsheet interface? Pencil work, Active cell, Menu bar, Workbook', '{"A":"Pencil work","B":"Active cell","C":"Menu bar","D":"Workbook"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pencil work is not an element of the spreadsheet interface.Active Cell, Menu Bar, and Workbook are associated with a spreadsheet environment.The Active Cell is the currently selected cell where data can be entered or edited.A Workbook is an Excel file containing one or more worksheets.Last verified on 26-08-2026', 0, 0, 0, 1790966331297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_62fd08b65bf2f118', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel to add two cells (A1 and A2) together you use the following formula?', '{"A":"= add(A1+A2)","B":"= A1+A2","C":"= together A1:A2","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To add the values in A1 and A2, enter =A1+A2.In Excel, the plus (+) operator is used to add values from cells.Excel calculates the result automatically.The SUM function can also be used: =SUM(A1,A2).Last verified on 24-08-2026', 0, 0, 0, 1790966331297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e26c8f47d9204285', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'MS Excel''s _____ function allows you to add the numbers in multiple cells.', '{"A":"MAX","B":"SUM","C":"MIN","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SUM function in MS Excel is used to add numbers from selected cells or ranges (e.g., =SUM(A1:A5)).It is one of the most commonly used functions for quick total calculations in spreadsheets.Last verified on 26-05-2026', 0, 0, 0, 1790966331297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_afbef337100e5b4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel = Now () is used ______?', '{"A":"To show current date","B":"To show current time","C":"To show current date and time","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The =NOW() function in MS Excel returns the current date and time.It is updated automatically whenever the worksheet is opened or calculations are performed.Additional information: =TODAY() - returns the current date (without time)=YEAR() - returns the year from a given date=MONTH() - returns the month from a given date=DAY() - returns the day from a given date=HOUR() - returns the hour from a given time=MINUTE() - returns the minute from a given time=SECOND() - returns the second from a given timeLast verified on 10-08-2026', 0, 0, 0, 1790966331297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6ff746e2f6fade3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'What does the “Pivot Table” tool primarily allow users to do?', '{"A":"Generate new worksheets","B":"Create graphs from data","C":"Summarize and analyze data","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The “Pivot Table” tool primarily allows users to summarize and analyze data.It can group, sort, filter, and calculate data.Common calculations include Sum, Count, Average, Maximum, and Minimum.Pivot Tables help identify patterns, comparisons, and trends in data.Last verified on 10-08-2026', 0, 0, 0, 1790966331370) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b40a85f3095c939d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which formula is used to calculate the sum of cells A1 through A10 in a spreadsheet?', '{"A":"=SUM(A1:A10)","B":"=ADD(A1:A10)","C":"=TOTAL(A1:A10)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation =SUM(A1:A10) is the formula used to calculate the sum of cells A1 through A10.The SUM function adds values in a specified range of cells.It is one of the most commonly used spreadsheet functions.The colon (:) indicates a continuous range of cells.It works in spreadsheet software like Excel and Google Sheets.Last verified on 08-06-2026', 0, 0, 0, 1790966331370) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7f1dd60f0fe1917e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'The thin black cross-shaped pointer in MS Excel is used to _____?', '{"A":"Move a group of cells","B":"Highlight duplicate cells","C":"Complete lists and fill patterns","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The thin black cross-shaped pointer in MS Excel is used to complete lists and fill patterns.It is known as the Fill Handle.The Fill Handle appears at the bottom-right corner of the selected cell.Dragging it can automatically fill adjacent cells with data, formulas, numbers, dates, or patterns.It can extend sequences such as 1, 2, 3, 4... or Monday, Tuesday, Wednesday...It saves time by automatically completing repetitive data.Last verified on 10-08-2026', 0, 0, 0, 1790966331370) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7493fa0d9eae31cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which is used for arranging data in ascending/descending order in MS Excel?', '{"A":"Data, order","B":"Data, sort","C":"Data, all","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Data, sort is used for arranging data in ascending/descending order in MS Excel.Sort A to Z to perform an ascending sort (A to Z or smallest number to largest).Sort Z to A to perform a descending sort (Z to A or largest number to smallest).Last verified on 10-08-2026', 0, 0, 0, 1790966331370) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b240855a12f5e41f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which one is an example of spreadsheet software?', '{"A":"MS Word","B":"MS Excel","C":"MS PowerPoint","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Spreadsheet software is used for calculations and data organization.MS Excel is a widely used spreadsheet program.It works with rows, columns, and formulas.Last verified on 11-04-2026', 0, 0, 0, 1790966331370) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_572889fb1b915145', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, you can sort data in?', '{"A":"Ascending order","B":"Descending order","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Excel allows data to be sorted in both Ascending and Descending order.Ascending order: Smallest to largest, A to Z, or oldest to newest.Descending order: Largest to smallest, Z to A, or newest to oldest.Excel can sort numbers, text, dates, and other data types.The Sort command is available under the Data tab in Excel.Last verified on 09-08-2026', 0, 0, 0, 1790966331370) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_43a7090131d16eaf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, comments put in the cell are called?', '{"A":"Smart tip","B":"Vip tip","C":"Soft tip","D":"Cell tips"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cell Tips are comments or notes placed in an Excel cell to provide additional information.They help users understand or explain the data entered in a cell.In older versions of MS Excel, cell comments were displayed when the cell was selected or pointed to.Last verified on 09-08-2026', 0, 0, 0, 1790966331370) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d3d32bb337147102', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Columns in MS Excel are called?', '{"A":"Fields","B":"Chart","C":"Both","D":"Letters"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Columns: Run vertically and are identified by letters (A, B, C … AA, AB).Additional information:Rows: Run horizontally and are identified by numbers (1, 2, 3 …).Cells: Intersection of a row and column, e.g., A1.Fields: In database terminology, a column is often called a field.Last verified on 09-08-2026', 0, 0, 0, 1790966331370) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b28b686f72e6ad87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'B2:B6 in MS Excel represents the ______?', '{"A":"Range of cell","B":"Cell column","C":"Cell Row","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation B2:B6 in MS Excel represents a range of cells.B2 is the starting cell, while B6 is the ending cell.The range includes B2, B3, B4, B5, and B6.All these cells are located in Column B.A colon : is used in Excel to indicate a range of cells.Last verified on 08-08-2026', 0, 0, 0, 1790966331442) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_85682921e895ec40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, we can add a chart from which tab?', '{"A":"File","B":"Chart","C":"Insert","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charts in MS Excel are added from the Insert tab.The Insert tab contains the Charts group for creating different chart types.Users can create Column, Bar, Line, Pie, Area, Scatter, and other charts.Charts help present data visually for easier analysis.Last verified on 27-07-2026', 0, 0, 0, 1790966331442) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3acad1e1b609927e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In Microsoft Excel, what is the function of the F11 key?', '{"A":"Opens the Save As dialog box","B":"Creates a chart on a new chart sheet","C":"Inserts a new worksheet","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressing F11 instantly creates a chart from the selected data on a separate chart sheet.First, select the data range, then press F11 to generate the default chart.Additional information:F1 → Open HelpF2 → Edit the active cellF4 → Repeat the last action / Toggle absolute references in formulasAlt + F1 → Create a chart embedded in the current worksheetLast verified on 23-07-2026', 0, 0, 0, 1790966331442) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3506d293f298d05e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, to insert a sum formula in a cell?', '{"A":"=Sum(A1:A2)","B":"=Add(a1:a2)","C":"=Sum(1A:2A)","D":"=Add(1A:2A)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct formula to add values in Excel is =SUM(A1:A2).The SUM function adds numbers from the selected cell range.Excel formulas always begin with the =` (equal) sign.A1:A2 means all cells from A1 to A2.Last verified on 14-07-2026', 0, 0, 0, 1790966331442) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_475dc2abf636fdea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which of the following is not a correct method of editing the contents of a cell in MS Excel?', '{"A":"Double clicking the cell","B":"Press the Alt key","C":"Pressing the F2 key","D":"Clicking the formula bar"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressing the Alt key alone does not edit the contents of a cell.The Alt key is mainly used to access the Ribbon shortcuts and menu commands.In MS Excel, you can edit a cell by double-clicking the cell, pressing F2, or clicking in the Formula Bar.Last verified on 21-07-2026', 0, 0, 0, 1790966331442) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7871e4ac362348d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Default name of a newly created MS Excel File is?', '{"A":"Book1","B":"Document 1","C":"File 1","D":"All of these"}', 'A', NULL, 0, 0, 0, 1790966331442) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c5e1b9ca26f31abb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, VLOOKUP is _____?', '{"A":"Logical function","B":"Lookup and reference function","C":"Mathematical function","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation VLOOKUP stands for Vertical Lookup.It is used to search for a value in the first column of a table.It is categorized under Lookup and Reference functions in Excel.Last verified on 26-05-2026', 0, 0, 0, 1790966331442) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6abaf6cec6a8f13e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, if B3 ids the address of a cell then B is it''s _____?', '{"A":"Row number","B":"Column number","C":"Cell address","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, letters (like B) represent columns, while numbers (like 3) represent rows.So, in cell address B3, B is the column number, and 3 is the row number.Last verified on 26-05-2026', 0, 0, 0, 1790966331442) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_64df21deef06b8ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'How do you display current date and time in MS Excel?', '{"A":"DATE()","B":"TODAY()","C":"YEAR()","D":"NOW()"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, different functions are used to handle dates and times.To display the current date and time, the NOW() function is used.Additional information:DATE() – Returns a date based on year, month, and dayTODAY() – Returns today’s date onlyTIME() – Constructs a specific time from hours, minutes, and secondsLast verified on 11-03-2026', 0, 0, 0, 1790966331507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_71adfa9307744b41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which function converts text to uppercase in MS Excel 2016?', '{"A":"UPPER","B":"UPPERCASE","C":"TOPPER","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel 2016, the UPPER() function is used to convert text to uppercase letters.It changes all lowercase characters in a cell to capital letters.Additional information:LOWER() – Converts text to lowercasePROPER() – Capitalizes the first letter of each wordLast verified on 11-03-2026', 0, 0, 0, 1790966331507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cd00832b7a85a6f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which function returns the average of all the cells in a range that meet a given criteria in MS Excel 2016?', '{"A":"AVERAGEIF","B":"AVERAGE","C":"AVERAGEALL","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AVERAGEIF calculates the average of cells that meet a specific condition.Formula: =AVERAGEIF(range, criteria, [average_range])Useful for conditional averaging in large datasets.Last verified on 08-03-2026', 0, 0, 0, 1790966331507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_40951ddf03038463', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which of the following formulas MS-Excel 2016 will not able to calculate? =SUM(Sales)-A3, =SUM(A1:A5)*.5, =SUM(A1:A5)/(10-10), =SUM(A1:A5)-10', '{"A":"=SUM(Sales)-A3","B":"=SUM(A1:A5)*.5","C":"=SUM(A1:A5)/(10-10)","D":"=SUM(A1:A5)-10"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Excel 2016 can perform calculations using formulas like SUM, subtraction, multiplication, and division.However, a formula referring to a non-existent range or name will produce an error.Additional information:=SUM(Sales)-A3: ❌ Produces an error if ‘Sales’ is not a defined range or named range.*=SUM(A1:A5)0.5: ✅ Multiplies the sum of A1:A5 by 0.5.=SUM(A1:A5)/(10-10): ✅ Produces #DIV/0! error (division by zero) but Excel can calculate it.=SUM(A1:A5)-10: ✅ Subtracts 10 from the sum of A1:A5.Last verified on 07-03-2026', 0, 0, 0, 1790966331507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8307474f63984c95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which of the following us correct syntax in MS Excel? =IF(LogicalTest, TrueResult, FalseResult), =IF(LogicalTest, TrueResult), IF(LogicalTest, FalseResult), =IF(LogicalTest, TrueResult) IF(LogicalTest, FalseResult), None of these', '{"A":"=IF(LogicalTest, TrueResult, FalseResult)","B":"=IF(LogicalTest, TrueResult), IF(LogicalTest, FalseResult)","C":"=IF(LogicalTest, TrueResult) IF(LogicalTest, FalseResult)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, the IF function is used to return one value if a condition is TRUE and another if it is FALSE.The correct syntax always includes:=IF(LogicalTest, TrueResult, FalseResult)Additional information:LogicalTest: Condition to evaluate (e.g., A1>50)TrueResult: Value returned if condition is TRUEFalseResult: Value returned if condition is FALSEExample: =IF(A1>50, "Pass", "Fail")Last verified on 07-03-2026', 0, 0, 0, 1790966331507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fa4cdb384bcae3dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which of these keys are used to apply outline border to the selected cells in MS Excel?', '{"A":"[CTRL] + [SHIFT] + [$]","B":"[CTRL] + [SHIFT] + [%]","C":"[CTRL] + [SHIFT] + [&]","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, the shortcut Ctrl + Shift + & is used to apply an outline border to selected cells.Additional information:Ctrl + Shift + _ → Remove outline borderCtrl + Shift + $ → Apply currency formatCtrl + Shift + % → Apply percentage formatCtrl + Shift + # → Apply date formatLast verified on 06-03-2026', 0, 0, 0, 1790966331507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_832097d54fc2ba09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which of the following is a type of computer program that is used to perform a specific task, such as creating a spreadsheet or editing an image?', '{"A":"System software","B":"Application software","C":"Scripting software","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Application software is designed to perform specific tasks, like creating spreadsheets or editing images.Examples include Microsoft Excel, Adobe Photoshop, and Google Docs.Last verified on 15-02-2026', 0, 0, 0, 1790966331507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f18d8b82637865dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, which function automatically total a column or row of values?', '{"A":"SUM","B":"ADD","C":"TOTAL","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790966331507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8ae99466faf4fd15', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, Conditional Formatting is in ______ tab?', '{"A":"Home","B":"View","C":"Page Layout","D":"Insert"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tab: HomeGroup: StylesLocation: Click the "Conditional Formatting" button to see options like Highlight Cells Rules, Top/Bottom Rules, and Data Bars.', 0, 0, 0, 1790966331591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1cb5a5a07922f208', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which of following is not a valid data type in MS Excel?', '{"A":"Number","B":"Character","C":"Babel","D":"Date/Time"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, "character" is not a valid data type.There are Three types of data in cells: labels, values, and formulas.Labels (text) are descriptive pieces of information, such as names, months, or other identifying statistics, and they usually include alphabetic characters.Values (numbers) are generally raw numbers or dates. Formulas are instructions for Excel to perform calculations.', 0, 0, 0, 1790966331591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_29b22eddc2b95683', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'The software which contains rows and columns is called in MS Excel is called?', '{"A":"Database","B":"Spreadsheet","C":"Word processing","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A worksheet is an electronic spreadsheet that lets users to Calculate, Enter & Analyze data.A spreadsheet is a computer application for computation, organization, analysis and storage of data in tabular form.', 0, 0, 0, 1790966331591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a771e0186c4b4822', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'What does the VLOOKUP function do in Excel?', '{"A":"Count the number of cells","B":"Searches for a value in a column and returns a value in the same row","C":"Calculate the average of values","D":"Sorts data in ascending order"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The VLOOKUP function in Excel is used to search for a value in the first column of a range And return a value in the same row from a specified column. It is commonly used for looking up data in a table or range.', 0, 0, 0, 1790966331591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d39caeb142fa0fcb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'The first cell in EXCEL worksheet is labeled as ____?', '{"A":"AA","B":"Aa","C":"A1","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In an Excel worksheet, the first cell is labeled as A1 due to the following reasons:Grid System: Excel uses a grid to organize cells, with rows and columns.Rows Labeled by Numbers: Rows are labeled using numbers (1, 2, 3, etc.).Columns Labeled by Letters: Columns are labeled using letters (A, B, C, etc.).First Cell Location: The first cell is located at the intersection of row 1 and column A, hence labeled A1.', 0, 0, 0, 1790966331591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_71344901fc9b15e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In Microsoft Excel, the file you create and edit is called?', '{"A":"A ledger","B":"A table","C":"A workbook","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A workbook is a file created in Microsoft Excel, It containing one or more worksheets.A worksheet (spreadsheet) is organized into cells, columns, and rows for entering and calculating data.Workbooks in Excel 2016 are saved with the .xlsx extension by default.', 0, 0, 0, 1790966331591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_639dfcb6e5be7798', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'MS Excel is a ______?', '{"A":"Spreadsheet program","B":"Multimedia software","C":"Entertainment software","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft Excel is a powerful spreadsheet application developed by MicrosoftIn MS Excel,3 types of Data in a cell: labels, values, and formulas.Last updated question by NA on 07 May 2026', 0, 0, 0, 1790966331591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6ace96ef0b275220', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which of the following way cannot be used to link excel worksheet data to a Word document?', '{"A":"With the copy and paste buttons on the standard toolbar","B":"With the copy and paste special commands","C":"With a hyperlink","D":"With the right drag method"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation With a hyperlink cannot be used to link Excel worksheet data to a Word document for dynamic updates.Hyperlinks can only direct to the Excel file but do not embed or link data directly.', 0, 0, 0, 1790966331591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1c8ac53c22a02b7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Ctrl + D in MS Excel is used for?', '{"A":"Fill down in the selection","B":"Open the font dialog box","C":"Both A and B","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790966331676) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e393dffc8b47443f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'A spreadsheet is created using _____?', '{"A":"MS Word","B":"MS Excel","C":"MS PowerPoint","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS Excel is specifically designed to create and manage spreadsheets for data entry, calculation, and analysis.It organizes data in rows and columns, and supports formulas, charts, and functions.', 0, 0, 0, 1790966331676) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e24fafe251867e7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'How columns are numbered in MS Excel?', '{"A":"Numeric","B":"Alphabetic","C":"Roman","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Columns in MS Excel are numbered Alphabetically (A, B, C, etc.).Rows in MS Excel are numbered Numerically (1, 2, 3, etc.).', 0, 0, 0, 1790966331676) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f56fc0b44cfc5140', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which key is used to minimize Excel Worksheet?', '{"A":"CTRL+F9","B":"CTRL+F5","C":"CTRL+F11","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790966331676) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e842a1cbb457c966', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'What are the basic rectangular building blocks of a spreadsheet?', '{"A":"Cells","B":"Zoom slider","C":"Help button","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cells are the basic building blocks of a worksheet. A cell is the intersection of a row and a column.', 0, 0, 0, 1790966331676) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_53733952107140d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'The main window in a computer spreadsheet is called?', '{"A":"workbook","B":"work","C":"account book","D":"worksheet"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main window in a computer spreadsheet is called a workbookwhile The title bar in MS Excel displays the name of the worksheet**In Excel, when we create a new document, we always select a blank workbook, as you already have done in the previous chapter. When this blank workbook opens up, an interface you see is called a workbook window.', 0, 0, 0, 1790966331676) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bf1602550c51f7d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'MS-Excel uses the _____ function when creating a data table.', '{"A":"Average","B":"Count","C":"Both A and B","D":"Table"}', 'D', NULL, 0, 0, 0, 1790966331676) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7a649c3b3e232fa9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'What is a Macro in MS Excel?', '{"A":"A single instruction that performs a specific task","B":"A set of instructions that can be executed as a single command","C":"A type of chart or graph used for data visualization","D":"A feature that allows users to create and edit images"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A macro in MS Excel is a set of instructions that can be executed as a single command.It automates repetitive tasks by recording and playing back sequences of actions, saving time and effort.', 0, 0, 0, 1790966331676) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_87f516be99f4388a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, You can copy data or formulas _____?', '{"A":"With buttons on the standard toolbars","B":"With commands on the shortcut menu","C":"With the copy, paste and cut commands on the edit menu","D":"All of the above"}', 'D', NULL, 0, 0, 0, 1790966331733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e544fafce4cfa661', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'How are data organized in a spreadsheet?', '{"A":"Lines and spaces","B":"Layers and planes","C":"Rows and columns","D":"Height and width"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a spreadsheet, the data is organised in columns and rows.', 0, 0, 0, 1790966331733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cd2ca56d4c91104b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'The basic unit of a computer worksheet in which you enter text and numbers is known as _____?', '{"A":"Workbook","B":"Cell","C":"Row","D":"Column"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The basic unit of a worksheet in Excel where data is entered is called a cell.A cell is the intersection of a row and a column in a spreadsheet.Each cell has a unique name or cell address, which is based on its column and row.For example, the cell in column "C" and row "3" is cell C3.', 0, 0, 0, 1790966331733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ee7b837e77a37b9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which one is not a Function in MS Excel?', '{"A":"SUMB","B":"AVG","C":"MAX","D":"MIN"}', 'B', NULL, 0, 0, 0, 1790966331733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_36a2b7958dc4aa93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'A worksheet in Excel is divided into _____?', '{"A":"Height & Width","B":"Layers & Planes","C":"Columns & Rows","D":"Lines & Spaces"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A worksheet consists of rows (horizontal) and columns (vertical) where data is entered into cells at their intersections.', 0, 0, 0, 1790966331733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_860b723110f09853', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Move to the next cell in the row in MS Excel _____?', '{"A":"Tab","B":"Shift","C":"Space","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Move to the next cell in the row in MS Excel: Tab.***MS Excel stands for Microsoft ExcelIn Excel, a Data Series is defined as a collection of related data. Microsoft Excel features calculation or computation capabilities, graphing tools, pivot tables etc.In MS Excel, automatically total a column or row of values: SUM.Move to the next cell in the sheet in ms excel: shift + page down.', 0, 0, 0, 1790966331733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fb7173b631ddda0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Rows in Microsoft Excel are labeled as _____?', '{"A":"1, 2, 3, etc.","B":"A1, A2, etc.","C":"A, B, C, etc.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In an Excel worksheet, the first cell is labeled as A1 due to the following reasons:Grid System: Excel uses a grid to organize cells, with rows and columns.Rows Labeled by Numbers: Rows are labeled using numbers (1, 2, 3, etc.).Columns Labeled by Letters: Columns are labeled using letters (A, B, C, etc.).First Cell Location: The first cell is located at the intersection of row 1 and column A, hence labeled A1.', 0, 0, 0, 1790966331733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e2fd588d6bebe748', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'The actual working area of the Computer''s Microsoft Excel is?', '{"A":"Workbook","B":"Worksheet","C":"Note sheet","D":"Notebook"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The actual working area of the Computer''s Microsoft Excel is a worksheet.The title bar in MS Excel displays the name of the workbook.The main window in a computer spreadsheet is called a workbook.', 0, 0, 0, 1790966331733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_faf22318640de12b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'To create table of columns and rows for statistical or mathematical calculation using spreadsheet, which software is used?', '{"A":"Excel","B":"Word Pad","C":"Word Pertect","D":"Corel Draw"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft Excel is a spreadsheet software widely used for creating tables of columns and rows for statistical or mathematical calculations.It provides various features such as formulas, functions, charts, and pivot tables to manage and analyze data.', 0, 0, 0, 1790966331810) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_02a564db88c1ebf8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which shortcut key is used to create chart in MS Excel?', '{"A":"F10","B":"F12","C":"F11","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The F11 key allows you to activate full-screen mode in your browser.*************VU FIA SUB INSPECTOR PAPER 30-1-2021', 0, 0, 0, 1790966331810) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_74d9ba4d6a5713d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'How to activate a cell in MS Excel?', '{"A":"Pressing an arrow key","B":"Clicking the cell","C":"Pressing the Tab key","D":"All of the above"}', 'D', NULL, 0, 0, 0, 1790966331810) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5cf7a02c1df2435e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'The title bar in MS Excel displays the name of the ____?', '{"A":"Worksheet","B":"Workbook","C":"Formula","D":"Location"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The title bar in MS Excel displays the name of the workbook***in the Excel program. Click the File tab. Click Open. Press Ctrl + O to quickly display the Open tab of the Backstage view.', 0, 0, 0, 1790966331810) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_97a37b717dde2b7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'MS Excel displays the current (active) cell address in the ______?', '{"A":"Name box","B":"Cell tip","C":"Both","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Name Box normally displays the address of the "active cell" on the worksheet.Data or Formula of the Current Active Cell can be viewed inside the Cell Contents box of the Excel Formula barAGM 09-2-2023', 0, 0, 0, 1790966331810) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7ad51cd7e9aced72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel 2016, which of the following can be used to split windows into two?', '{"A":"Format > Window","B":"View > Window> Spilt","C":"Window > Spilt","D":"View > Spilt"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel 2016, you can split the window into two panes using the following steps:Go to the "View" tab in the ribbonClick on "Window" in the "Window" groupSelect "Split" from the dropdown menuAlternatively, you can also use the shortcut key:Alt + W + S', 0, 0, 0, 1790966331810) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ebce44a59989ece3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which of following function in Microsoft Excel is used to count items in a cell range?', '{"A":"Count","B":"SUM","C":"MAX","D":"Average"}', 'A', NULL, 0, 0, 0, 1790966331810) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_40c1aaff0e84bec2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which of the following is the latest version of MS Excel?', '{"A":"Excel 2024","B":"Excel 2016","C":"Excel 2017","D":"Office 365"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Excel 2024 is the latest standalone/perpetual version.It is part of Microsoft Office 2024.It includes updated data analysis and charting features.Last update 0n 21-07-2026 by NA', 0, 0, 0, 1790966331810) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_87332d4909f5016b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, the Chart wizard term data categories refers to ______?', '{"A":"A chart plot area","B":"The organization of individual values with a chart’s data series","C":"A horizontal axis","D":"The data range that supply chart data"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel, the term "data categories" refers to the horizontal axis (also known as the X-axis) in a chart.It organizes individual values within the chart''s data series and represents different categories or labels along this axis.', 0, 0, 0, 1790966331875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ea163c54c5ccbccb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS-Excel ''cells'' can be uniquely identified by:', '{"A":"Colum letters and row numbers","B":"Column numbers and row letters","C":"Numbers only","D":"Rows only"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A cell reference or cell address is a combination of a column letter and a row number that identifies a cell on a worksheet', 0, 0, 0, 1790966331875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bd3169a52fc70c67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which keyboard shortcut is used to add comments in MS Office Excel Worksheet?', '{"A":"Alt + F2","B":"Ctrl + F12","C":"Shift + F5","D":"Shift + F2"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shift + F2 is the correct answer. Comments can be added to cells using Insert > Comment.Right-click the cell and then click Insert Comment (or press Shift+F2).**', 0, 0, 0, 1790966331875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d4b855b3199c0dfb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS-Excel, for arranging data in ascending or descending order the command used is?', '{"A":"Filter in review tab","B":"Filter in data tab","C":"Sort in data tab","D":"Sort in review tab","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Data, sort is used for arranging data in ascending/descending order in MS Excel Sort A to Z to perform an ascending sort (A to Z or smallest number to largest). Sort Z to A to perform a descending sort (Z to A or largest number to smallest).***', 0, 0, 0, 1790966331875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b3eb61d7bc390561', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In a computer spreadsheet, a function that is used to count a number of entries in a given range is called?', '{"A":"length","B":"counter","C":"counting","D":"count"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a computer spreadsheet, a function that is used to count a number of entries in a given range is called length***COUNTA: To count cells that are not empty.COUNT: To count cells that contain numbers.COUNTBLANK: To count cells that are blank.COUNTIF: To count cells that meet specified criteria.', 0, 0, 0, 1790966331875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d32c41c36fc8e674', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel ready-made templates are available under ______ tab in new option.', '{"A":"File","B":"Count","C":"Table","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Excel ready-made templates are available under file tab in new option .When considering Microsoft Word, Microsoft Excel, Microsoft Power Point, the templates are in files tab_____________________________________- Use Excel''s Table command to convert a list of data into a named Excel Table. These tables have useful features, like sorting and filtering, to help organize and view data.', 0, 0, 0, 1790966331875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e932157219183b32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which elements of a worksheet can be protected from accidental modification', '{"A":"Scenarios","B":"Objects","C":"Contents","D":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All elements of a worksheet can be protected from accidental modification.To protect a worksheet in Excel 2007 and higher versions, click the Review tab, click Protect Worksheet (or Protect Sheet), and click OK.Excel 2003 and Earlier Versions click Tools > Protection, click Protect Sheet, and click OK.', 0, 0, 0, 1790966331875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b930e015215d9a36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'To select a group of worksheet we press and hold ____ key and select the sheet we want to add :', '{"A":"ctrl","B":"shift","C":"alt","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To edit an embedded Excel worksheet''s contents or resize in the future in Word, you must return to editing mode. by double-clicking the embedded Excel worksheet object in the document to switch back to Excel.Press and hold the Ctrl key on your keyboard. Select the next worksheet you want in the group.', 0, 0, 0, 1790966331875) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_481975dd5c5c580d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'Which one cannot be used to enter data in a cell in MS Excel?', '{"A":"Pressing tab key","B":"Pressing arrow key","C":"Pressing Esc key","D":"clicking the enter button to the formula bar"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressing the Esc key cannot be used to enter data in a cell in MS ExcelEsc key is used to interrupt or cancel the current process or running program, or to close a pop-up window.', 0, 0, 0, 1790966331939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d06282269f6ae8c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In a spreadsheet, letters are used to represent _____________', '{"A":"Columns","B":"Rows","C":"Cells","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Columns are denoted and identified by a unique alphabetical header letter, which is located at the top of the worksheet.', 0, 0, 0, 1790966331940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6bf305618197369a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'in Microsoft Excel template is the combination of different ______?', '{"A":"Colors","B":"Effects","C":"Fonts","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Existing TemplatesTo create a workbook based on an existing template, follow these steps.1. On the File tab, then click New.2. Use the search box to search for online templates or click a template from one of the Office templates.', 0, 0, 0, 1790966331940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_95f3efb309a49a50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel window the __________ menu system is how user navigates through Excel and access the various Excel commands.', '{"A":"First","B":"Slide","C":"Ribbon","D":"Main"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You can find Excel commands throughout the tabs in the Ribbon.You can customize the Quick Access Toolbar by adding commands you frequently use. AGM 17-12-2022', 0, 0, 0, 1790966331940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d0ed668b56c7b150', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'A worksheet is an electronic spreadsheet that lets users to :', '{"A":"Calculate data","B":"Enter data","C":"Analyze data","D":"All of these","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A worksheet is an electronic spreadsheet that lets users to Calculate, Enter & Analyze data. A spreadsheet is a computer application for computation, organization, analysis and storage of data in tabular form.', 0, 0, 0, 1790966331940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7be04ef8444140d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'In MS Excel, to clear all content, Formats and comments in selected cell, we use?', '{"A":"Clean All","B":"Clear All","C":"Clean Content","D":"Clean Format"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation More details about this question will be shared soon If you know more details about this question, let us know please*************VU FIA SUB INSPECTOR PAPER 30-1-2021', 0, 0, 0, 1790966331940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0801bdcdd00954c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'It is acceptable to let long text flow into adjacent cells on a worksheet when', '{"A":"There is not time to format the text","B":"No data will be entered in the adjacent cells","C":"Data will be entered in the adjacent cells","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When there is no data in in the adjacent cells, long text flows into adjacent cells on a worksheet.', 0, 0, 0, 1790966331940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0679d6a3d959069b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'How can you show or hide the grid-lines in Excel worksheet ?', '{"A":"Click Gridline tool on Forms toolbar","B":"Go to Tools > Options > View tab and mark or remove the check box named Gridline","C":"both","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Excel 2016, 2013, 2010, 2007, click on View > Show > GridlinesFor Excel 2003 and Earlier: Navigate to Tools > Options or Click Gridline tool on Forms toolbar.', 0, 0, 0, 1790966331940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d805755957d5e8ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'To edit in an embedded excel worksheet object in a word document?', '{"A":"Use the excel menu bar and toolbars inside the word application","B":"Edit the hyperlink","C":"Edit the data in an excel source application","D":"Use the word menu bar and toolbar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use the excel menu bar and toolbars inside the Word applicationWhen you double-click the embedded Excel object, The ribbon at the top of the Word window changes to display the Excel menus and toolbars, enabling direct editing of the embedded worksheet.', 0, 0, 0, 1790966331996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ce4733855dcdf369', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_excel', 'How you can update the values of formula cell.If auto calculate the mode of excel cell is disabled', '{"A":"f9","B":"f2","C":"f7","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Manual calculation mode means that Excel will only recalculate all open workbooks when we request it by pressing F9.', 0, 0, 0, 1790966331996) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_comp_os', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Operating Systems & Windows', 'top_computer', 84, 1790966332052) ON CONFLICT(id) DO UPDATE SET total_mcqs = 84;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ae4c018939770861', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which shortcut key is used to print a document?', '{"A":"Ctrl+M","B":"Ctrl+N","C":"Ctrl+L","D":"Ctrl+P"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut key to print a document is Ctrl + P.Additional Information:Hyphen (-) is used to select a range for printing a document.By default, the documents are printed in portrait-oriented mode.Ctrl + A = select allCtrl + B = BoldCtrl + I = ItalicCtrl + P = PrintCtrl + Y = RedoCtrl + S = SaveLast verified on 26-05-2026', 0, 0, 0, 1790966332116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_42fda75d0f856090', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the shortcut key to copy the text?', '{"A":"Ctrl + C","B":"Ctrl + B","C":"Ctrl + I","D":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + C is the shortcut key used to copy selected text or files.Additional information:Ctrl + B → BoldCtrl + A → Select AllCtrl + W → Close current tab/windowAlt + Tab → Switch between appsAlt + F4 → Close the active appWin + D → Show/Hide DesktopWin + ← / → → Snap windows left/rightWin + Tab → Open Task ViewVerified & Updated', 0, 0, 0, 1790966332116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6cdf59bcbaff0d93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The shortcut key Ctrl + K is used for ____?', '{"A":"Insert link","B":"Insert hyperlink","C":"Formate latters","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + K → Insert HyperlinkAdditional information:Ctrl + P → PrintCtrl + F2 → Print PreviewCtrl + H → Replace dialog boxCtrl + D → Font dialog boxLast verified on 06-07-2026', 0, 0, 0, 1790966332116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6b41bd6898cb3fdb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which is the shortcut key for undo/reverse the last action?', '{"A":"Ctrl + Z","B":"Ctrl + C","C":"Ctrl + V","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut key for Undo (last action reverse) is Ctrl + Z in most computer systems.It is used to cancel the last mistake or action.Additional information:Ctrl + P = PrintCtrl + Y = RedoCtrl + S = SaveCtrl + C = Copy commandCtrl + V = PasteCtrl + C = CopyCtrl + X = CutCtrl + Y = RedoLast verified on 10-06-2026', 0, 0, 0, 1790966332117) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4d79fa81865e6394', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What type of operating system MS-DOS is?', '{"A":"Command Line Interface","B":"Graphical Line Interface","C":"Multitasking","D":"Menu Drawn Interface"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS-DOS: Microsoft Disk Operating SystemDeveloped by: MicrosoftDesigned for: x86-based personal computersInterface: Command-line interface (CLI)IBM version: IBM PC DOSDOS: A term also used for MS-DOS-compatible operating systems.', 0, 0, 0, 1790966332117) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_342b4db319f98557', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Ctrl + L Shortcut key is used for _____?', '{"A":"Left Indent","B":"Left Align (Align the selected text or line to the left)","C":"Increase Left Margin","D":"Decrease Left Margin"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + L → Left AlignAdditional information:Ctrl + E → Center AlignCtrl + R → Right AlignCtrl + J → JustifyLast verified on 28-09-2026', 0, 0, 0, 1790966332117) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_66f33be768fa27e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the function of the F4 key in most systems?', '{"A":"System Settings","B":"Close a Window","C":"Repeat Last Action","D":"Refresh Page"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The F4 key is commonly used to repeat the last action in programs like Microsoft Word and Excel. For example, if you format text or perform a specific action, pressing F4 will repeat it.Last updated question by NA on 07 May 2026', 0, 0, 0, 1790966332117) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bfd572c24d55553d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the purpose of an operating system in a computer?', '{"A":"To make the most efficient use of the computer hardware","B":"Manage computer hardware and software resources","C":"To run application software","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An operating system manages computer hardware and software resources.It uses hardware efficiently and provides services to applications.It allows programs to run smoothly and interact with hardware.It acts as an interface between users, applications, and hardware.Last verified on 08-06-2026', 0, 0, 0, 1790966332117) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6a583ea34bffad53', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The F7 key is commonly used for?', '{"A":"Renaming files and folders","B":"Checking spelling and grammar","C":"Opening help","D":"Search content in various apps"}', 'B', NULL, 0, 0, 0, 1790966332180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a315fa230abb47ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which of the following operating system is based on open-source software?', '{"A":"UNIX","B":"Windows 2000","C":"Windows NT","D":"Linux"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Linux is based on open-source software.It is a Unix-like operating system.Created by: Linus Torvalds (1991).It is widely used in servers, mobile devices, and supercomputers.Last updated 18-07-2026 by NA', 0, 0, 0, 1790966332180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_75dfee7e151e8e4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'An operating system is a/an _____?', '{"A":"Personal software","B":"System software","C":"Application software","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Operating System (OS) is system software.It manages computer hardware and provides a platform for running application software.It acts as an interface between the user and computer hardware.Functions of an Operating System:Allocates resourcesMonitors activitiesManages disks and filesLast verified on 02-07-2026', 0, 0, 0, 1790966332180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0a4819b09ed32160', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which command in Windows opens the Run dialog box?', '{"A":"Win + R","B":"Ctrl + R","C":"Alt + R","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Win + R opens the Run dialog box in Windows.It allows users to quickly open programs, folders, files, and system tools by typing commandsAdditional Information:cmd: Opens the Command Prompt.notepad: Opens Notepad.msconfig: Opens System Configuration.control: Opens the Control PanelLast updated 07-09-2026 by NA', 0, 0, 0, 1790966332180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_af5eb4a8393ce410', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Crtl + E is the shortcut key for?', '{"A":"Center Align Text","B":"Open the Search Box","C":"Enable Flash Fill","D":"Open the \"Edit\" Menu"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Center the text. Ctrl+EAlign the text to the left. Ctrl+LAlign the text to the right. Ctrl+RCancel a command. EscLast updated 07-09-2026 by NA', 0, 0, 0, 1790966332180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f48e6cdca152e052', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Shortcut key of Ctrl + A use for ____?', '{"A":"To select all text","B":"To copy","C":"To paste","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + A: Select AllAdditional information:Ctrl + C: CopyCtrl + V: PasteCtrl + X: CutCtrl + Z: UndoLast verified on 02-07-2026', 0, 0, 0, 1790966332180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4e374c11b180cb23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'CTRL + S is the shortcut key for?', '{"A":"New","B":"Bold","C":"Save","D":"Copy"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + S = To save a document.Additional information:Ctrl + X → Cut (remove selected text)Ctrl + R → Align text to the rightCtrl + E → Center align textCtrl + J → Justify paragraphCtrl + L → Align text to the leftCtrl + Q → Remove paragraph formatting (reset to default left alignment)Last verified on 10-06-2026', 0, 0, 0, 1790966332180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ccf656a2a7bae51b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Shortcut key to "Save As" file is?', '{"A":"F4","B":"F12","C":"F1","D":"F2"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation F12 → Save AsAdditional information:Ctrl + S → SaveCtrl + O → OpenCtrl + P → PrintCtrl + N → New DocumentVerified & Updated', 0, 0, 0, 1790966332180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0b7a3a83ccda8d4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the primary function of the F11 key in most web browsers?', '{"A":"Open the browser''s settings menu","B":"Toggle full-screen mode","C":"Refresh the current page","D":"Open a new tab"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation F11 → Toggle Full-Screen ModeAdditional information:F5 → Refresh the current pageCtrl + T → Open a new tabCtrl + W → Close the current tabCtrl + L → Select the address barLast verified on 23-07-2026', 0, 0, 0, 1790966332246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_997e9370a05789cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the shortcut key used to find text in a document or webpage?', '{"A":"Ctrl + F","B":"Ctrl + H","C":"Ctrl + G","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + F is the shortcut key used to find/search text in a document, webpage, PDF, or many software applications.It opens the Find search box.Users can quickly locate words or phrases without reading the entire document.Additional information:Ctrl + H → Find and ReplaceCtrl + G → Go To a page, line, or sectionCtrl + A → Select AllCtrl + S → Save documentLast verified on 11-07-2026', 0, 0, 0, 1790966332246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c92bfa0d32b22c9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The shortcut key to saving any document in MS Office is?', '{"A":"Ctrl+S","B":"Ctrl+V","C":"Ctrl+C","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut key to saving any document in MS office is Ctrl+S.Additional information:· CTRL + C - copy selection.· CTRL + V - paste selection.· CTRL + X - cut selection.· CTRL + Z - undo action.· CTRL + Y - repeat action.· CTRL + B - bold text.· CTRL + I - italicize text.· CTRL + U - underline text.Last verified on 01-09-2026', 0, 0, 0, 1790966332246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_93767cd6fe0d19e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the shortcut key for double underline ?', '{"A":"Ctrl + Shift + D","B":"Ctrl + Ctrl + Shift + B","C":"Ctrl + Ctrl + Shift + U","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Shift + D applies double underline to selected text in MS Word.Additional information:Ctrl + U — Single underlineCtrl + Shift + W — Underline words onlyCtrl + B — BoldCtrl + I — ItalicLast verified on 25-08-2026', 0, 0, 0, 1790966332246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_46bfa00ba15eca1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the function of the Windows key + F1 shortcut?', '{"A":"Open Help and Support","B":"Open File Explorer","C":"Lock the computer","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Windows + F1 → Open Help and SupportAdditional information:Windows + E → Open File ExplorerWindows + L → Lock the computerWindows + R → Open Run dialog boxWindows + D → Show/DesktopLast verified on 06-07-2026', 0, 0, 0, 1790966332246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6ca1a65393b85ba3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', '"Ctrl + Home" is used to ______?', '{"A":"Moves the cursor to the beginning of Line","B":"Moves the cursor to the beginning of Paragraph","C":"Moves the cursor to the beginning of Document","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Home moves the cursor to the beginning of the document in MS Word.Home alone moves the cursor to the beginning of the current line.Additional information:Ctrl + ↑ — Beginning of previous paragraphCtrl + End — End of documentEnd — End of lineLast verified on 26-08-2026', 0, 0, 0, 1790966332246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_032152b7198f82b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The shortcut key to select the entire row in Excel?', '{"A":"Alt + Space bar","B":"Shift + Space bar","C":"Ctrl + Space bar","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The keyboard shortcut to select an entire row in Microsoft Excel is Shift + Spacebar. This command selects all cells in the current active row.For highlighting a column, CTRL+space is used.Last updated by NS on 06 May 2026', 0, 0, 0, 1790966332246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_345097377d3a240e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which shortcut key is used to use the find and replace feature?', '{"A":"CTRL + H","B":"CTRL + F","C":"CTRL + G","D":"CTRL + R"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CTRL + H is the shortcut key used in most software (like MS Word, Excel) to open the Find and Replace dialog box.It allows users to search for a word or phrase and replace it with another.Additional information:CTRL + F: Only opens the Find dialogCTRL + G: Opens the Go To dialogCTRL + R: Aligns text to the right in word processorsLast verified on 10-06-2026', 0, 0, 0, 1790966332246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ded7cfe4fb00c7f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which shortcut key is used to paste the selected and copied text?', '{"A":"Ctrl + X","B":"Ctrl + C","C":"Ctrl + V","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + V is the shortcut key used to paste copied or cut text.Additional information:Ctrl + C — CopyCtrl + X — CutCtrl + Z — UndoCtrl + A — Select AllLast verified on 23-08-2026', 0, 0, 0, 1790966332313) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_819ce78ab58b552f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which shortcut key is used to restart the computer?', '{"A":"Ctrl + F4","B":"Ctrl + Alt + Delete","C":"Alt + F6","D":"None of above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The combination of keys used for restarting the computer is Ctrl + Alt + Delete.Additional information:Alt + F4: Opens the shutdown dialog from the desktop.Windows + X: Opens the Quick Link menu.Restart: Closes the current Windows session and starts it again.Shut Down: Completely turns off the computer.Last verified on 10-09-2026', 0, 0, 0, 1790966332313) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0efdbeecdd32d573', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which shortcut key is used to moves the cursor one page down?', '{"A":"Alt + PageDown","B":"Shift + PageDown","C":"Ctrl + PageDown","D":"PageDown"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Move the cursor to the top of the next page: Ctrl + Page DownAdditional information:Move the cursor to the top of the previous page: Ctrl + Page UpMove the cursor by scrolling the document view down by one screen: Page DownMove the cursor to the end of the document: Ctrl + EndLast verified on 07-08-2026', 0, 0, 0, 1790966332313) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d48130f1752119c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which of the following is a single-user system?  DOS, Windows, Linux, None of these', '{"A":"DOS","B":"Windows","C":"Linux","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DOS (Disk Operating System) is a single-user operating system.It is designed for one user at a time.DOS uses a Command-Line Interface (CLI) instead of a graphical interface.Additional information:Examples of Multi-user OS: Windows, Linux, UNIX, macOSLast verified on 06-08-2026', 0, 0, 0, 1790966332313) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_751df067f42b8a1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Shortcut keys to switch to the next windows?', '{"A":"Shift + Tab","B":"Alt + Ctrl","C":"Ctrl + Tab","D":"Alt + Tab"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shortcut key to switch to the next/open window is Alt + Tab.It allows you to quickly move between open applications or windows.Hold Alt and press Tab to select another open window.Additional information:Windows + Tab → Open Task View.Alt + F4 → Close the active window.Windows + D → Show or hide the desktop.Alt + Esc → Switch between open windows in their opening order.Last verified on 07-08-2026', 0, 0, 0, 1790966332313) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8bbf4520742c283a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the function of the Shift + End shortcut key?', '{"A":"Select text from the cursor to the end of the current line","B":"Move the cursor to the end of the document","C":"Delete text to the end of the line","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shift + End – Select text from the cursor to the end of the current lineAdditional information:Shift + Home – Select text from the cursor to the beginning of the current lineCtrl + Shift + End – Select text from the cursor to the end of the documentEnd – Move the cursor to the end of the current lineCtrl + End – Move the cursor to the end of the documentLast verified on 20-07-2026', 0, 0, 0, 1790966332313) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e2e0b2c6cb7a3fc3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the primary function of an Operating System kernel?', '{"A":"Manage hardware and system resources","B":"Run user applications","C":"Provide internet connectivity","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The primary function of an Operating System kernel is to manage hardware and system resources.It acts as a bridge between hardware and software applications.Kernel controls CPU, memory, and input/output devices.It ensures smooth execution of all programs.It is the core part of the operating system.Last verified on 09-06-2026', 0, 0, 0, 1790966332313) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_462a39f021a6ea7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'A computer cannot ‘boot’ if it does not have the ______?', '{"A":"Loader","B":"Operating System","C":"Compiler","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer cannot boot properly if it does not have an Operating System (OS).The operating system is the main software that loads after the boot process and enables the computer to run programs.Without an OS, the computer cannot provide a usable working environment.Last verified on 22-07-2026', 0, 0, 0, 1790966332313) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b82526beb6d43f65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the function of the Shift + F10 shortcut key in Microsoft Office (Excel/Access)?', '{"A":"Close the active window","B":"Display the Control menu","C":"Display the shortcut menu","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shift + F10 displays the Shortcut (Context) Menu, just like a right-click with the mouse.Additional information:Alt + Space → Display the Control MenuAlt + F4 → Close the Active WindowCtrl + C → CopyCtrl + V → PasteLast verified on 19-07-2026', 0, 0, 0, 1790966332376) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_163073e8ecab0ef1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Ctrl + Shift + F6 = ______?', '{"A":"Go to the previous open document window","B":"Go to the internal storage","C":"Go to the previous open Excel sheet","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Shift + F6 switches to the previous open document window in MS Word.Additional information:Ctrl + F6 → Next open document windowCtrl + Tab → Next document/tab (in some Office applications)Ctrl + S → Save documentCtrl + P → Print documentLast verified on 19-07-2026', 0, 0, 0, 1790966332376) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_34b7677b267d43ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which of the following is not an application software? WinWord XP, Page Maker, Windows NT, None of these', '{"A":"WinWord XP","B":"Page Maker","C":"Windows NT","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Windows NT is not application software; it is an Operating System.It is a proprietary graphical operating system developed by Microsoft.The first version of Windows NT was released on 27 July 1993.Examples of Application Software: Microsoft Word (WinWord XP), Adobe PageMaker, MS Excel, PowerPoint, Adobe PhotoshopLast verified on 10-07-2026', 0, 0, 0, 1790966332376) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d77c79870f2d2244', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Linux is an _____?', '{"A":"Operating System","B":"Hardware","C":"Software","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Type: Operating System (Unix-like)Kernel Released: 17 September 1991Developer: Linus TorvaldsLicense: Open-source (GNU General Public License)Common Distributions: Ubuntu, Debian, Fedora, Red Hat, Linux MintLast verified on 10-07-2026', 0, 0, 0, 1790966332376) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ac483eff680ec79b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the shortcut key for grammar and spelling to check in document?', '{"A":"F1","B":"F2","C":"F5","D":"F7"}', 'D', NULL, 0, 0, 0, 1790966332376) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9147f8e5bd736fe3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The F1 key is used for _____?', '{"A":"Lock keys","B":"Insert keys","C":"Function keys","D":"Opening for help"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The F1 key is used to: Help menuAdditional information:F4: Creates a new document F2: Renames the fileF5: Reload keyF7: Spell checkLast verified on 06-07-2026', 0, 0, 0, 1790966332376) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_06ab828e36b87cab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the shortcut key to open the dialog box?', '{"A":"F12","B":"Shift F12","C":"Alt + F12","D":"Ctrl + D"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + D → Open Font dialog boxAdditional information:Ctrl + H → Open Replace dialog boxCtrl + F12 → Open an existing document in Microsoft Word (Open dialog box)F12 → Save AsShift + F12 → Save documentLast verified on 02-07-2026', 0, 0, 0, 1790966332376) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ba56c68204edb5d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Ctrl + F2 shortcut key is used for?', '{"A":"Opens the Save As dialog","B":"Opens the Print Preview window","C":"Finds text in the document","D":"Opens the Format menu"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + F2 is used to display the Print Preview window/area in MS Office applications.Additional information:In Excel, it opens the Print tab preview area in Backstage view.In PowerPoint, it displays print options.F2 → Rename selected file (Windows) / Edit cell in ExcelLast verified on 01-07-2026', 0, 0, 0, 1790966332376) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_012b454003e10f7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Ctrl + Z used for _____?', '{"A":"Redo","B":"Undo","C":"Cut","D":"Copy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Z used for = UndoAdditional information:Ctrl + X used for = CutCtrl + Y used for = RedoLast verified on 07-06-2026', 0, 0, 0, 1790966332471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d031b2e082c3b0ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which menu can be used to split windows into two?', '{"A":"Window > Split","B":"Review > Window","C":"View > Window > Split","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To split windows or document panes into two in applications like Excel or Word, use the View > Window > Split menu option. This command divides the active document window into separate', 0, 0, 0, 1790966332471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b40d5187bd636aba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the shortcut key for “Superscript” the selected text?', '{"A":"Ctrl + =","B":"Ctrl + –","C":"Ctrl + Shift + =","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Superscript raises the text slightly above the normal line, often used for exponents, footnotes, or ordinal numbers.Shortcut in MS Word: Ctrl + Shift + =Example: x² (2 is superscript)Additional information:Subscript: Ctrl + = (text goes below the line)Bold: Ctrl + BItalic: Ctrl + IUnderline: Ctrl + ULast verified on 06-03-2026', 0, 0, 0, 1790966332471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_60edf7382c9257f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The software that contains the core components of the operating system is called _____?', '{"A":"Middle","B":"Function","C":"Component","D":"Kernel"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The kernel manages system resources like CPU, memory, and devices.It acts as a bridge between hardware and software, ensuring smooth operation.', 0, 0, 0, 1790966332471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9bf6c6998d5b0b21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Ctrl+J', '{"A":"justifies the current line","B":"Underline","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation pressing Ctrl + J justifies the current line to evenly space its text or words between the left and right margins of the page.', 0, 0, 0, 1790966332471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9a49ef33f213fe23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which shortcut key used to Open Startup Button in windows 10?', '{"A":"Ctrl + Space","B":"Ctrl + Esc","C":"WIN+ Esc","D":"Alt + Esc","E":"Shift + Esc"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Windows key or Ctrl + Esc: Open Start menu.MUG 11-12-2022', 0, 0, 0, 1790966332471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fbda130ee16f1611', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which one of the following is not a search engine? Yahoo ,Windows, Google, Bing', '{"A":"Yahoo","B":"Windows","C":"Google","D":"Bing"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Windows, as it is an operating system and not a search engine.The provided Google, Yahoo, and Bing are examples of search engines.ND7-3-2023', 0, 0, 0, 1790966332471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1c2f174db2e8bb47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Shortcut key to close an application or a window _____?', '{"A":"Ctrl+F1","B":"Altl+F4","C":"Ctrl+F4","D":"Ctrl+B"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alt + F4 keyboard shortcut to close an app or program on WindowsConfused questionCtrl+F4 is the shortcut key to an application or a windowAlt + F4: Close the current app or window. Alt + Tab: Switch between open apps or windows.ND19-3-2023', 0, 0, 0, 1790966332471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_59f1736f6d27d677', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The operating system is also called the ______ between the user and the computer.', '{"A":"Interrelate","B":"Interface","C":"Interference","D":"Intermediate"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The operating system is also called the interface between the user and the computer..The Operating System is the Interface between the user and the computer. It is called the Interface because it converts the commands the user gives to a language that the computer can understand (machine language) and vice versa. Multiple operating systems are available such as Windows, Mac OS, and Linux...virus protection is not the function of the operating system Real-time system operating system reads and reacts in actual time', 0, 0, 0, 1790966332545) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bb21eac0cf355a4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Unix operating system was developed by ____?', '{"A":"Ken Thompson","B":"Dennis Ritchie","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation UNIX is an operating system that was originally AT&T.UNIX development started in 1969 at the Bell Labs research center by Ken Thompson and Dennis Ritchie.UNIX was widely used for Internet servers, workstations, and mainframe computers.', 0, 0, 0, 1790966332545) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8261285970d1c582', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'An operating system was used/developed for the first time in which generation of computers?', '{"A":"Third Generation","B":"Fourth Generation","C":"Second Generation","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation From Third generation operating systems were developed.The period of third generation was from 1965-1971. The computers of third generation used Integrated Circuits (ICs) in place of transistors. A single IC has many transistors, resistors, and capacitors along with the associated circuitry. The IC was invented by Jack Kilby.', 0, 0, 0, 1790966332545) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4de1e4affb15e110', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which is not the function of the operating system?', '{"A":"Linux","B":"DOS","C":"Oracle","D":"Window"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oracle is not a function of an operating system.It is a database management system.Whereas Linux, DOS, and Windows are examples of operating systems that manage hardware and software resources in a computer system.', 0, 0, 0, 1790966332545) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_59e344d9604dace1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Ctrl+ G is shortcut for?', '{"A":"Open Paragraph Dialog box activating Goto Tab","B":"Open Page Setup Dialog box activating Goto Tab","C":"Open Find and Replace Dialog box with activating Goto Tab","D":"Open Goto Dialog box"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl+G is a keyboard shortcut often used to advance through Find results or move to a specific line in a document, spreadsheet, or text file', 0, 0, 0, 1790966332545) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_15b8e19a2ef41e5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Ctrl + = shortcut key ______?', '{"A":"Subscript","B":"Superscript","C":"Header","D":"Footer"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + = is the shortcut key for Subscript in many word processors, lowering the selected text below the baseline.Ctrl + Shift + = is used for Superscript, which raises the selected text above the baseline.', 0, 0, 0, 1790966332545) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7c8a4bd42bd92688', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'CTRL+SHIFT+Right Arrow:', '{"A":"Select  the word in left direction","B":"Select the word in right direction","C":"Select the word from bottom","D":"All"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The CTRL+SHIFT+Right Arrow keyboard shortcutIt is primarily used to select text from the current cursor position to the end of the word to the right in most text editing programs,', 0, 0, 0, 1790966332545) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f8d357febce12dc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Select the correct shortcut key which is used to underline a written paragraph?', '{"A":"CTRL + T","B":"CTRL + U","C":"CTRL + Z","D":"CTRL + B"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut key for underlining a word in MS Word is CTRL + UAdditional information:Ctrl + A used to select all.Ctrl + B is used for bold selection.Ctrl + C is used to Copy selected text.Ctrl + X is used for cutting selected text. Ctrl + N is used to Open a new document.', 0, 0, 0, 1790966332545) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_aa4673eec82cb856', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which of the following is NOT a function of Operating System?', '{"A":"Protection again virus","B":"Scheduling","C":"Disk/Memory/Application Management","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Operating Systems manage scheduling, memory, disk, and applications.Virus protection is typically handled by antivirus software, not the OS itself.', 0, 0, 0, 1790966332618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1e450263e1330c56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The process of starting an operating system when the user turns on a computer is known as?', '{"A":"Starting","B":"Loading","C":"Booting","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process of starting an operating system when a user turns on a computer is called booting.Booting is a startup sequence that powers up the system and loads the operating system. The booting process involves the following steps: Power onThe Power-On Self TestFind and load the OSDrivers and system configurationUser login and authentication', 0, 0, 0, 1790966332619) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5fa62f81af2b5883', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which of the following is the key to close a run dialog box in the window?', '{"A":"ESC","B":"SHIFT","C":"TAB","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressing the ESC key closes the Run dialog box in Windows.ESC is a standard key for canceling or closing windows and dialog boxes.Other related keys:Enter: Confirms and runs the commandTab: Moves the cursor between fieldsShift: Used for modifying selections or keyboard shortcutsAlt + F4: Closes the current window or dialog box', 0, 0, 0, 1790966332619) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_68c27226a3f42c9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'In computer system word BOOT is used for?', '{"A":"To exit opened software","B":"To start up a software","C":"To shutdown system","D":"To start a computer"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Boot (short for bootstrap) means to start/restart a computerIt loads the operating system into memory when the computer is turned onTypes: Cold boot (turning on from off state), Warm boot (restarting)Not used for exiting software, starting a program, or shutting downLast updated 24-07-2026 by NA', 0, 0, 0, 1790966332619) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bcdb12757da0ed5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which function key is used for refreshing Windows?', '{"A":"F1","B":"F2","C":"F5","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790966332619) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b1e9f695e3805a99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The shortcut key to display a field code is _____?', '{"A":"Ctrl + F9","B":"Alt + F9","C":"Shift + F9","D":"Ctrl + F8"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut Alt + F9 displays field codes in Microsoft Word.It allowing you to view and edit the underlying codes of fields such as dates, page numbers, or references.', 0, 0, 0, 1790966332619) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b4b2ebb06240aa55', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Ctrl + Backspace = ____?', '{"A":"Delete the selected data","B":"Delete the word left of the word","C":"Add an image","D":"Delete the whole page"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Backspace = Delete the word left of the cursor.This shortcut quickly removes the entire word to the left of the cursor position in most text editors.', 0, 0, 0, 1790966332619) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b20c06c830775e71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'In Windows operating system _____ is known as a file manager.', '{"A":"Windows Explorer","B":"MS Word","C":"Device drive","D":"MS Excel"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation File Explorer, previously known as Windows Explorer.is a file manager application that is included with releases of the Microsoft Windows operating system from Windows 95 onwards. It provides a graphical user interface for accessing the file systems.******ND30-12-2022', 0, 0, 0, 1790966332619) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_af0e371ea6ef5e95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which is the default text editor for Microsoft Windows?', '{"A":"Wordpad","B":"MS Word","C":"Notepad","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Notepad is a basic text-editing program which enables computer users to create documents.Notepad is a basic text editor used to create and edit plain text files without formatting.', 0, 0, 0, 1790966332679) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e1cba073cf54aaa4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', '"Ctrl + Left Arrow" is used to?', '{"A":"Moves the cursor beginning of the Line","B":"Moves the cursor one word left","C":"Moves the cursor one paragraph up","D":"Moves the cursor one paragraph down"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Ctrl + Left Arrow" is used to: Moves the cursor one word left."Ctrl + Right Arrow" is used to: Moves the cursor one word right.', 0, 0, 0, 1790966332679) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4e0f894c6b59816c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Who is the inventor of Linux?', '{"A":"Steve Jobs","B":"Bill Gates","C":"Linus Torvalds","D":"Mark Zuckerberg"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Linus Torvalds is the inventor of the Linux kernelReleasing the first version in September 1991Create a new free operating system kernel.Last updated by NS on 06 May 2026', 0, 0, 0, 1790966332679) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a49ad68c250cfc0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which shortcut key is used to insert a text in a cell?', '{"A":"Enter","B":"F2","C":"F5","D":"Tab"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressing F2 in MS Excel allows you to editInsert text in the selected cell.', 0, 0, 0, 1790966332679) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b3e7d4980e0652e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The MAC operating system is developed by _____?', '{"A":"Samsung","B":"Microsoft","C":"Apple","D":"IBM"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mac OS is an operating system developed and marketed by Apple Inc. since 2001. It is the primary operating system for Apple''s Mac computers.NA22-9-2023', 0, 0, 0, 1790966332679) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_38c100a63dc82ca2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'In a windows PC, the shortcut key for redoing the last action in Microsoft Office is?', '{"A":"CTRL+R","B":"CTRL+Z","C":"CTRL+Y","D":"CTRL+ O"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut key for redoing the last action in Microsoft Office is CTRL+Y.CTRL+Z ___ Undo last action. **** Copy: Ctrl+CCut: Ctrl+XPaste: Ctrl+V', 0, 0, 0, 1790966332679) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_af44e103357ecd32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'In Microsoft Windows, the graphical pattern on the desktop used as background for windows is ______?', '{"A":"Icons","B":"Wallpaper","C":"Picture","D":"Background"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft Windows, the graphical pattern on the desktop used as background for windows is Wallpaper***More commonly referred to as a desktop background in Windows, wallpaper is an image that is used as a backdrop on any graphical user interface that has a desktop****RY 16-01-2023', 0, 0, 0, 1790966332679) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c7bb59091724c135', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'The taskbar is used for _____?', '{"A":"Navigation program","B":"Switching between programs","C":"Start a program","D":"All of above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Taskbar is used for: Navigation programs, Switching between programs and Starting a program.**Taskbar elements. The Start button, a button that invokes the Start menu', 0, 0, 0, 1790966332679) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_196c6d54e36c0389', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', '"OS" computer abbreviation usually means :', '{"A":"Order of Significance","B":"Open Software","C":"Operating System","D":"Optical Sensor","E":"All"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OS computer Abbreviation usually means Operating System. An Operating system is an integrated set of programs that are used to manage the various resources and overall operations of a computer system.ND5-5-2023', 0, 0, 0, 1790966332761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b62ac647f88daa36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Select the correct shortcut key mentioned below which is used to "bold" a written paragraph', '{"A":"CTRL + T","B":"CTRL + B","C":"CTRL + C","D":"CTRL + P"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Most repeated questions about shortcut keyGoes to beginning of current line = HomeGoes to beginning of document = Ctrl + HomeGoes to end of current line = End Goes to end of document = Ctrl + EndHighlights from current position to beginning of line = Shift + HomeHighlights from current position to end of line = Shift + EndCut selected item = Shift + Del & Ctrl + XCopy selected item = Ctrl + CPaste selected item = Ctrl + V Paste = Shift + Ins.*********VU FIA UDC CONSTABLE PAST PAPER 31-12-2021', 0, 0, 0, 1790966332761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_38fffaafcc8b0905', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What is the mean of the Booting in the operating system?', '{"A":"To turn off","B":"To scan","C":"Install the program","D":"Restarting computer"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Booting is a process of the restart the computer. After restarting it, there is no software in the computer''s main memory.Cold and warm are types of Booting.', 0, 0, 0, 1790966332761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a28ca2ab473548ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which shortcut key is used for pasting the copied text ?', '{"A":"CTRL + Backspace","B":"CTRL + Spacebar","C":"CTRL + R","D":"CTRL + V"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CTRL + Spacebar shortcut key combination reset highlighted text to a default font in MS Word.Some of the top shortcut keys in Microsoft Word are:Ctrl + S: SaveCtrl + C: CopyCtrl + X: CutCtrl + V: PasteCtrl + Z: UndoCtrl + Y: RedoCtrl + B: BoldCtrl + I: ItalicCtrl + U: UnderlineCtrl + F: Find', 0, 0, 0, 1790966332761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e5e1d0eaa4dcb7a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'To move the cursor to the end of the document which shortcut key is used ?', '{"A":"Ctrl + End","B":"Ctrl + Home","C":"Ctrl +F","D":"Ctrl +D"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Move the cursor to the top of the next page. Ctrl+Page downMove the cursor to the top of the previous page. Ctrl+Page up', 0, 0, 0, 1790966332761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f7833bf128a3cead', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'What will be the use of Ctrl + J ?', '{"A":"Insert Image","B":"Insert Hyperlink","C":"Align Justify","D":"Search file"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl+J aligns the selected text or line to justify the screen.', 0, 0, 0, 1790966332761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3042fd867787790e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which of the following is loaded when you start windows?', '{"A":"My computer","B":"My documents","C":"Desktop","D":"Download","E":"Microsoft"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Windows-8 does not have start button but Windows-8.1 has start button.', 0, 0, 0, 1790966332761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_977404faa6d7b47a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Ctrl + Z, Ctrl + X and Ctrl + Y are found in:', '{"A":"Format Menu","B":"File Menu","C":"Edit Menu","D":"None of the above","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Z used for = UndoCtrl + X used for = CutCtrl + Y used for = Redo', 0, 0, 0, 1790966332761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d56f6a844357425a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'How can we bring ''My Computer'' icon on the desktop if it is not there ?', '{"A":"From Display Properties","B":"From Settings","C":"From Wallpaper","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Show desktop icons in Windows 10Select the Start button, and then select Settings > Personalization > Themes.Under Themes > Related Settings, select Desktop icon settings.Choose the icons you would like to have on your desktop, then select Apply and OK.', 0, 0, 0, 1790966332839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_111c0383859aed3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which one is used to save all the open files in windows?', '{"A":"Save all","B":"save","C":"save as","D":"none of the above","E":"all of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + S = saveCtrl + F12 = Save as', 0, 0, 0, 1790966332839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_dc93dfd8a8a79a06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Which shortcut key is for auto sum ?', '{"A":"Alt + =","B":"Ctrl + Shift","C":"Alt + F1","D":"Ctrl + ="}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AutoSum is a fast, easy way to add up multiple values in Excel. You can access the AutoSum command from either the Home tab or the Formulas tab, but there is a keyboard shortcut that makes it even faster: Alt + =.', 0, 0, 0, 1790966332839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d77e361266d2696c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_os', 'Windows 95,windows 98 and windows NT are known as:', '{"A":"Processors","B":"Domain names","C":"Modems","D":"Operating system","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An operating system is system software that manages computer hardware, software resources, and provides common services for computer programs.', 0, 0, 0, 1790966332839) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_comp_ppt', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'MS PowerPoint', 'top_computer', 83, 1790966332892) ON CONFLICT(id) DO UPDATE SET total_mcqs = 83;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_47d0bbdc4367b40f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which shortcut key inserts a new slide in current presentation?', '{"A":"Ctrl+N","B":"Ctrl+M","C":"Ctrl+S","D":"None of above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortcut key to insert a new slide in a PowerPoint presentation is Ctrl + M.Additional information:Ctrl + N shortcut key used to create a new presentation document.Ctrl + S shortcut key used to save a presentation.Last verified on 29-05-2026', 0, 0, 0, 1790966332951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_09edaa6975a23c83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What is extension of MS PowerPoint presentation of file in 2007 and later?', '{"A":".pp","B":".xls","C":".pptx","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation .pptx → Default PowerPoint Presentation (2007 and later)ppt → PowerPoint Presentation (97–2003)Additional information:.ppsx → PowerPoint Show (opens directly as a slideshow).potx → PowerPoint Template.pptm → Macro-enabled PresentationLast verified on 11-07-2026', 0, 0, 0, 1790966332951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3b20473be0fe032e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'To start a slide show in PowerPoint we press _____?', '{"A":"F6","B":"F4","C":"F5","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation F5 is used to start a Slide Show from the beginning in Microsoft PowerPoint.It displays the presentation in full-screen Slide Show view.Additional information:Shift + F5 starts the slide show from the current slide.F4 repeats the last action in many Microsoft Office applications.F6 moves between different areas of the PowerPoint window.Last verified on 09-08-2026', 0, 0, 0, 1790966332951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3f2ef5b68fbe72c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'A single page of PowerPoint presentation is called _____?', '{"A":"Sheet","B":"Page","C":"Slide","D":"Document"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A single page of a PowerPoint presentation is called a Slide.A slide is a single screen/page that contains text, images, charts, videos, or other presentation elements.A collection of slides forms a PowerPoint presentation.PowerPoint is a presentation software developed by Microsoft.Slides can be displayed using Slide Show mode.The default PowerPoint file extension is .pptx.Last verified on 07-08-2026', 0, 0, 0, 1790966332951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d710d1a7dfd2afb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which file is responsible to start MS PowerPoint?', '{"A":"ppt.exe","B":"Mspoint.exe","C":"Powerpnt.exe","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Powerpnt.exe is the executable file responsible for starting Microsoft PowerPoint.The .exe extension indicates an executable program file in Windows.Powerpnt.exe is associated with launching Microsoft PowerPoint.Additional information:Winword.exe → Microsoft WordExcel.exe → Microsoft ExcelLast verified on 07-08-2026', 0, 0, 0, 1790966332951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3ffe475e528f376b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In MS PowerPoint, which view allows you to edit the global layout, font, and background for all slides?', '{"A":"Normal View","B":"Slide Master View","C":"Reading View","D":"Slide Sorter View"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Slide Master ViewUsed to edit global layouts, fonts, and backgrounds across all slidesChanges apply uniformly to the entire presentationAdditional information:Normal View – edits individual slides one at a time; no global changes.Reading View – for viewing/reviewing only; not editable.Slide Sorter View – rearranges slide order; no editing of content or layouts.Last updated 07-09-2026 by NA', 0, 0, 0, 1790966332952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_22e5d343dbd88084', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'MS PowerPoint is used for _______?', '{"A":"Presentation","B":"Drafting","C":"Worksheet","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PowerPoint is used for Create presentations from scratch or a template.Add text, images, art, and videos.Select a professional design with PowerPoint Designer.Last verified on 03-04-2026', 0, 0, 0, 1790966332952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_94b83760b3f45d57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of following software is used to prepare/create multimedia presentation?', '{"A":"PowerPoint","B":"MS Word","C":"Spreadsheet","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PowerPoint is used to create multimedia presentations.Combines text, images, audio, video, animations, and charts.Developed by Microsoft.File extension: .pptxLast updated on 14-09-2026', 0, 0, 0, 1790966332952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7364536ebab3f220', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In MS PowerPoint presentations, Mr. Ali has to designs regulate the layout and formatting for the slide for ICOMETS. These are commonly known as?', '{"A":"Templates","B":"Placeholders","C":"Blueprints","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS PowerPoint, Templates are pre-designed slide formats.They control layout, colors, fonts, and overall design.Templates help maintain consistency in presentations.They save time in designing professional slides.Last verified on 29-05-2026', 0, 0, 0, 1790966333027) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0254f191538b7536', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What is the shortcut key to duplicate a slide in Microsoft PowerPoint?', '{"A":"Ctrl + M","B":"Ctrl + D","C":"Ctrl + Shift + D","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + D is the shortcut key to duplicate the selected slide in Microsoft PowerPoint.It creates an exact copy of the selected slide.The duplicated slide is inserted immediately after the original.Additional information:Ctrl + M → Insert a new blank slideCtrl + Shift + C → Copy formattingCtrl + Shift + V → Paste formattingF5 → Start Slide Show from the beginningLast verified on 11-09-2026', 0, 0, 0, 1790966333027) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4ac103bb1f3d848d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In MS PowerPoint we press _____ key to start slideshow from current slide.', '{"A":"F5","B":"Ctrl + F5","C":"Shift + F5","D":"Alt + F5"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Start a presentation from the current slide: Shift+F5Start a presentation from the beginning: F5Additional informationCtrl + N: Create a new presentation documentCtrl + M: Insert a new slideCtrl + S: save a presentationLast verified on 26-05-2026', 0, 0, 0, 1790966333027) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7cfc32c6a6473b2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which shortcut key is used to start a presentation from the beginning in PowerPoint?', '{"A":"F1","B":"F5","C":"F4","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Start a presentation from the beginning: F5Start a presentation from the current slide: Shift + F5Last verified on 01-09-2026', 0, 0, 0, 1790966333027) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_469b948551e2aab6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of the following is not a way to create a new presentation?', '{"A":"Using the Scan-In Slides feature","B":"From scratch (create a blank presentation","C":"Using a template","D":"Using the auto content wizard"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Scan-In Slides” means converting paper/printed slides into digital formThis requires a scanner to import existing slides into a presentationAdditional informationFrom scratch → user manually creates all slides (no scanning involved)Using template → pre-designed slide layout, not based on scanned contentAuto Content Wizard → guided steps for creating structured presentationsLast updated by NS on 06 May 2026', 0, 0, 0, 1790966333027) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b863763622534511', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'The effect applied to display when slides changes in slide show view is _______?', '{"A":"Custom Animation","B":"Slide Animation","C":"Slide Transition","D":"Custom Transition"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Slide transitions are the effects applied to display when slides change in slide show view.Examples: Fades, wipes, zooms, and random bars.Additional informationSlide Show view means you can see your presentation graphics, animated effects, and transition effects, etc., on full screen.To start the slideshow view, Press F5.To exit the Slide Show view, press ESC.Last updated by NS on 06 May 2026', 0, 0, 0, 1790966333027) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4c4379f805d9d1d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'By default, PowerPoint applies the Slide Design to ______?', '{"A":"Current slides in the presentation","B":"First slides in the presentation","C":"All slides in the presentation","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation By default, when a Slide Design/Theme is applied in PowerPoint, it applies to all slides in the presentation.A design can also be applied selectively to specific slides.Themes control elements such as colors, fonts, backgrounds, and effects.Last verified on 26-08-2026', 0, 0, 0, 1790966333027) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_27351de6dfdc1141', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of the following standard file formats is used in PowerPoint when saving a presentation?', '{"A":".ppt","B":".docx","C":".xlsx","D":".pptx"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation .pptx is the standard file format for saving a Microsoft PowerPoint presentation.It is the default presentation format in modern versions of PowerPoint.The X in .pptx indicates the XML-based Office Open XML format.Last verified on 24-08-2026', 0, 0, 0, 1790966333027) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cb49aed0137a0364', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'The slide that is used to introduce a topic and set the tone for the presentation is called _____?', '{"A":"Title Slide","B":"Table slide","C":"Bullet slide","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The slide that is used to introduce a topic and set the tone for the presentation is called Title Slide.The title slide is the first slide of a presentation.It usually contains a title and a subtitle.Last verified on 24-08-2026', 0, 0, 0, 1790966333096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b52353fef1f50ad5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which command/shortcut key brings you to the first slide in your presentation?', '{"A":"Home","B":"Alt + Home","C":"Ctrl + Home","D":"Shift + Home"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS PowerPoint, Ctrl + Home takes you to the first slide of the presentation.It is useful when working with a presentation containing many slides.Ctrl + End takes you to the last slide.These shortcuts help navigate quickly through a presentation.Additional information:Page Up — Previous slidePage Down — Next slideHome — Go to first slide during Slide ShowLast verified on 24-08-2026', 0, 0, 0, 1790966333096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_abdf4e61c79654af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What is the purpose of the Slide Sorter view in PowerPoint?', '{"A":"Rearrange slides in a presentation","B":"To apply formatting to all slides in a presentation","C":"Add animations to slides","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Slide Sorter View main purpose is to rearrange, move, copy, delete, or organize slides easily.Its in PowerPoint displays all slides as small thumbnails on one screen.It is especially useful for checking the overall sequence and structure of a presentation.It can also help manage slide transitions across multiple slides.Last verified on 09-08-2026', 0, 0, 0, 1790966333096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e71bef06880335eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which command will you use in PowerPoint if you need to change the color of different objects without changing content?', '{"A":"Design template","B":"Color scheme","C":"Object color","D":"Font color"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Color Scheme is used to change the colors of different objects without changing their content.It provides a coordinated set of colors for presentation elements.Additional information:Design Template changes the overall design and appearance of slides.Object Color changes the color of a specific selected object.Font Color changes only the color of text.Last verified on 09-08-2026', 0, 0, 0, 1790966333096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_907a719e97abc2a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In Microsoft PowerPoint, which tab is used to display all slides during a presentation?', '{"A":"Slide Show","B":"Insert","C":"Design","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Slide Show tab is used to display all slides during a PowerPoint presentation.It starts the presentation in full-screen mode.You can begin the slideshow from the first slide or the current slide.Additional information:F5 starts the slideshow from the first slide.Shift + F5 starts the slideshow from the current slide.Last verified on 09-08-2026', 0, 0, 0, 1790966333096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_65083ffbe2d0088d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'The view that displays the slides of a presentation as miniature representations (thumbnails) of the slides is called _____?', '{"A":"Slide show","B":"Outline view","C":"Slide sorter view","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Slide Sorter View displays all slides of a presentation as miniature representations (thumbnails).It allows users to view, arrange, reorder, copy, and delete slides easily.Slide Sorter View is especially useful for managing the overall sequence of a presentation.Additional information:Slide Show displays slides in full-screen presentation mode.Outline View mainly displays the text content and structure of slides.Last verified on 09-08-2026', 0, 0, 0, 1790966333096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9375fc22ffe44c8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of the following is not PowerPoint view(s)? Slide show view, Slide view, Presentation View, Outline view', '{"A":"Slide show view","B":"Slide view","C":"Presentation View","D":"Outline view"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Presentation View" is not a PowerPoint view.Common PowerPoint views include: Normal viewSlide Sorter viewOutline viewSlide Show viewLast verified on 09-08-2026', 0, 0, 0, 1790966333096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7b09a1598380f173', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of following section does not exit in a slide layout?', '{"A":"Charts","B":"Animation","C":"Lists","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Animations are not a section that exists in a slide layout. The other options (charts, lists, and titles) are commonly found in slide layouts.', 0, 0, 0, 1790966333096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3ce662ff2932faf1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which view is used to sort and rearrange slides in Microsoft PowerPoint?', '{"A":"Reading View","B":"Slide Sorter View","C":"Slide Show View","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Slide Sorter View is used to sort, rearrange, copy, and delete slides in Microsoft PowerPoint.It displays all slides as thumbnails on one screen.You can easily drag and drop slides to change their order.It is useful for organizing large presentations.Last verified on 28-07-2026', 0, 0, 0, 1790966333173) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b1edb951519d79d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What is the first slide called in Microsoft PowerPoint?', '{"A":"Blank slide","B":"Title slide","C":"Title and Content slide","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first slide in a Microsoft PowerPoint presentation is called the Title Slide.It usually contains the presentation title and subtitle.It is used to introduce the topic and presenter.PowerPoint provides different slide layouts, including Title Slide, Blank Slide, and Title and Content Slide.The Title Slide is the default layout when creating a new presentation.Last verified on 27-07-2026', 0, 0, 0, 1790966333173) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b7a4cee467a2cccb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In PowerPoint 2016 ‘Rehearse Timings’ option is available in the ______?', '{"A":"Slide Show Tab","B":"Home Tab","C":"Design Tab","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ''Rehearse Timings'' option is available in the Slide Show tab of PowerPoint 2016.It allows users to practice a presentation and automatically records the time spent on each slide.Common PowerPoint Tabs:HomeInsertDesignSlide ShowReviewLast verified on 23-07-2026', 0, 0, 0, 1790966333173) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f7b10ad2fa6091dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of the following is the basic unit of a PowerPoint presentation?', '{"A":"Slide","B":"Window","C":"Document","D":"Picture"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A slide is the basic unit of a Microsoft PowerPoint presentation.Each slide can contain text, images, charts, tables, audio, video, and animations.A presentation consists of one or more slides arranged in sequence.Additional information:The default file extension of a PowerPoint presentation is .pptx (since Office 2007).PowerPoint is widely used for education, business, meetings, and seminars.Last verified on 22-07-2026', 0, 0, 0, 1790966333173) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9839e768dd6b474f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What will happen if you press ESC key during PowerPoint slideshow?', '{"A":"Returns to the first slide","B":"Pauses the presentation","C":"End of Slide Show","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressing the ESC key ends the PowerPoint Slide Show.It exits the presentation and returns to the editing (Normal) view.ESC is commonly used to stop a slideshow at any time.Additional information:F5 – Start Slide Show from the first slideShift + F5 – Start Slide Show from the current slideVerified & Updated', 0, 0, 0, 1790966333173) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_83473c55e25074fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Default name of a newly created MS Powerpoint File is?', '{"A":"Document 1","B":"Book1","C":"Presentation1","D":"All of these"}', 'C', NULL, 0, 0, 0, 1790966333173) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_039577f6b0419ff2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'How many slides can you add in a PowerPoint (PPT) presentation?', '{"A":"Unlimited","B":"100","C":"500","D":"50"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PowerPoint allows an unlimited number of slides in a presentation.There is no fixed or hard-coded slide limit in MS PowerPoint.The number of slides depends on system memory (RAM) and file size.Very large presentations may slow down performance.Last verified on 08-06-2026', 0, 0, 0, 1790966333173) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d0b7809ba6ddc445', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of these refers to the PowerPoint view used for displaying only the text (title and bullets)?', '{"A":"Slide show","B":"Outline view","C":"Slide sorter view","D":"Notes page view"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PowerPoint offers different views for editing and organizing slides.Some views show full design, while others show only text.Outline View displays only slide text (titles and bullet points).It is useful for quickly editing content structure.Helps in organizing ideas before designing slides.Last verified on 29-05-2026', 0, 0, 0, 1790966333173) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1c331931628c3ea4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What is The maximum Zoom percentage in MS PowerPoint?', '{"A":"100%","B":"200%","C":"400%","D":"500%"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ZOOM PercentageMS Word (minimum)10%MS Word (maximum)500%MS PowerPoint (minimum)10%MS PowerPoint (maximum)400%MS Excel (maximum)400%MS Excel (minimum)10%Last verified on 29-05-2026', 0, 0, 0, 1790966333244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f3c59ce0330f5066', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'The file that consists of readymade styles that we can easily use for our presentation is known as?', '{"A":"Pre formatting","B":"Template","C":"Wizard","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PowerPoint provides ready-made design formats to make presentations easier.These include predefined colors, fonts, layouts, and styles.Users can apply them directly without designing from scratch.They help save time and improve presentation quality.Commonly used by beginners and professionals.Last verified on 29-05-2026', 0, 0, 0, 1790966333244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a9bc4d4276f124e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of these PowerPoint features would allow any user to create a given simple presentation quickly?', '{"A":"Animation","B":"Chart wizard","C":"Transition Wizard","D":"AutoContent Wizard"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PowerPoint provides tools to create presentations quickly and easily.AutoContent Wizard helps users by giving ready-made templates and structure.It guides step-by-step to build a simple presentation.Useful for beginners to save time and effort.It automatically suggests slides based on topic type.Last verified on 29-05-2026', 0, 0, 0, 1790966333244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_52392102cae7b61f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'The Handout Master consists of placeholders for all of these except the? Header, Footer, Slide number, Title', '{"A":"Header","B":"Footer","C":"Slide number","D":"Title"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Handout Master is used to design printed handouts in PowerPoint.It controls layout elements like header, footer, date, and page number.It does not include a title placeholder for slides.It helps in formatting multiple slides on a single page.Mostly used for printing presentation notes for audience.Last verified on 29-05-2026', 0, 0, 0, 1790966333244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fffd5ee8247f08c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In MS PowerPoint F5 is used for _____?', '{"A":"For Slide Show","B":"To save a file","C":"To import the file","D":"For Print Preview"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation F5: Starts the slideshow from the beginning.Shift+F5: Starts the slideshow from the current slide.Alt+F5: Starts the presentation in Presenter View. Last updated 15-feb-2026', 0, 0, 0, 1790966333244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4109de1efc29c6a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which file format can be added to a PowerPoint show?', '{"A":".jpg","B":".gif","C":".wav","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PowerPoint supports a wide array of multimedia file formats to enhance presentations, including .gif (animated graphics).jpg/.jpeg (standard images).wav (audio files).', 0, 0, 0, 1790966333244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0598f10c3b2c141c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Special effects used to introduce slides in a presentation are known as _____?', '{"A":"Effects","B":"Transitions","C":"Outline","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In presentation software (like MS PowerPoint), special effects used to introduce slides are called Transitions.Transitions control how one slide moves to the next during a presentation.They can be simple fades, wipes, pushes, or dynamic animations to make the presentation more engaging.Last verified on 11-03-2026', 0, 0, 0, 1790966333244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ed1466a84e9efb5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What is the slide-tittle master pair in MS PowerPoint 2016?', '{"A":"The title area and text area of a specific slide.","B":"A slide master and title master for a specific design template.","C":"A slide master and title master merged into a single slide.","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft PowerPoint 2016, a slide-title master pair consists of a specific Slide Master (which controls the default layout, fonts, and colors for all slides) Title Master (which specifically defines the layout for the presentation''s title slide).Last updated 15-feb-2026', 0, 0, 0, 1790966333244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2999679dedd6f8a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which PowerPoint feature allows the user to create a simple presentation quickly?', '{"A":"AutoContent Wizard","B":"Transition Wizard","C":"Chart Wizard","D":"Animations"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AutoContent Wizard helps users create presentations quickly by providing predefined templates and content suggestions.It guides the user through slides, layout, and structure automatically.Useful for beginners or fast preparation of presentations.Last verified on 06-03-2026', 0, 0, 0, 1790966333315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ed1b86c2c6d0c59a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'To start Microsoft PowerPoint application _____?', '{"A":"Click on Start >> Programs >> All Programs >> Microsoft PowerPoint","B":"Hit Ctrl + R then type ppoint.exe and Enter","C":"Click Start >> Run then type powerpnt then press Enter","D":"All of above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All of above, as all mentioned methods are valid ways to start the Microsoft PowerPoint applicationA. Click on Start > Programs > All Programs > Microsoft PowerPoint: Traditional path.B. Hit Ctrl + R (Win+R) then type ppoint.exe and Enter: Opens the Run dialog to execute the file.C. Click Start > Run then type powerpnt then press Enter: Classic Run method. Last updated 15-feb-2026', 0, 0, 0, 1790966333315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_69c8841c8cc8d51b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In which menu can you find features like Slide Design, Slide Layout, etc.?', '{"A":"Insert Menu","B":"Format Menu","C":"Tools Menu","D":"Slide Show Menu"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft PowerPoint 2003 and earlier versions, Slide Design and Slide Layout are found in the Format menu.PowerPoint 2003 uses a menu-based interface.From PowerPoint 2007 onward, Microsoft introduced the Ribbon interface.In newer versions, Slide Design is under the Design tab, while Slide Layout is under the Home tab.Therefore, Format Menu is the correct answer for PowerPoint 2003 and earlier.Last verified on 28-07-2026', 0, 0, 0, 1790966333315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5eb7b4622e1bd87b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Slide Transition done on _____?', '{"A":"New Slide","B":"Current Slide","C":"Previous Slide","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Slide transitions can be applied to the current slide, previous slide, or new slide.Transitions can be set to occur when entering or exiting any of these slides.', 0, 0, 0, 1790966333315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_10379756042208da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Slideshow in Microsoft PowerPoint is launched by _______?', '{"A":"F5","B":"F4","C":"F2","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PowerPoint Shortcut:Pressing F5 starts the slideshow from the beginning.Shift + F5 starts it from the current slide.', 0, 0, 0, 1790966333315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e9931dfa17b20b60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'MS PowerPoint is example of _____?', '{"A":"Multimedia software","B":"Application software","C":"Entertainment software","D":"All above mentioned"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS PowerPoint is an example of Application software. ***Microsoft PowerPoint is a powerful slide show presentation program. The program utilizes slides to convey information rich in multimedia content.PowerPoint, a presentation program created by Robert Gaskins and Dennis, was released on May 30, 1990.**The default font size in MS PowerPoint is 18', 0, 0, 0, 1790966333315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fc45791e9196220c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of the following is not a valid MS PowerPoint view?', '{"A":"Normal view","B":"Notes page","C":"Reading page","D":"Slide show"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct answer is: Reading page.MS PowerPoint has several built-in views, including:Normal view: The default view, where you can edit and design your slides.Notes Page view: A view that shows the slides with accompanying notes.Slide Sorter view: A view that shows thumbnails of all slides for easy organization.Slide Show view: A view that displays the presentation as a slideshow.There is no "Reading page" view in MS PowerPoint.', 0, 0, 0, 1790966333315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c6b05a84e991f032', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In PowerPoint, the selected design template can be applied?', '{"A":"To current slide only","B":"To all the slides","C":"To all the new presentation you create","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In PowerPoint, the selected design template can be applied:To the current slideTo all the slides To all the new presentations you create.', 0, 0, 0, 1790966333315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_558549f4fc6a62de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'PowerPoint contains __ for creating presentation.', '{"A":"Design temples","B":"Animations","C":"Insert","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Design templates are pre-made designs and documents that can be customized.', 0, 0, 0, 1790966333386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e988831f2faec2d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What PowerPoint feature will you use to apply motion effects to different objects of a slide?', '{"A":"Animation Scheme","B":"Slide Transition","C":"Slide Design","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft PowerPoint, the feature used to apply motion effects to different objects (like text, images, shapes, charts, etc.) on a slide is the Animations feature.You can access it through the Animations tab on the ribbon.From there, you can apply different types of motion effects such as Entrance, Emphasis, Exit, and Motion Paths.The Animation Pane lets you control the order, timing, and duration of the effects.', 0, 0, 0, 1790966333386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_018f82741af0b11b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'If you insert some slides from other presentation into current one choose ______?', '{"A":"From insert Menu choose slide from files","B":"From insert Menu choose slide from presentation","C":"From insert menu choose slides","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To insert some slides from other presentation into current one choose from Insert menu choose Slides from Files in Powerpoint 2003 and earlier versions.In Powerpoint 2007 and higher versions one choose From Insert > Reuse Slides.', 0, 0, 0, 1790966333386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_84ea1f6e8ed24da6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Ctrl + D is used in Powerpoint for _____?', '{"A":"Duplicate","B":"Paste","C":"Copy","D":"Save"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Copy the selected object or text.Ctrl+CPaste cut or copied object or text.Ctrl+VDuplicate selected objects.Ctrl+D or Ctrl+Drag the mouse Office 2010 and Office 2007: Not availableCopy the formatting of the selected object or text.Ctrl+Shift+C', 0, 0, 0, 1790966333386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4e228635441d6fef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'How to create a new presentation in PowerPoint?', '{"A":"Ctrl+ M","B":"Ctrl+ U","C":"Ctrl+ S","D":"Ctrl+ N","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + N shortcut key used to Create a new presentation documentCtrl + M shortcut key used for Insert a new slideCtrl + S shortcut key used to save a presentation', 0, 0, 0, 1790966333386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b6ba7a9d8b7ce03c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'How to select multiple slides in a presentation?', '{"A":"Click on slides","B":"Ctrl + click on slide","C":"Shift + click on slides","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To select multiple slides, press and hold Ctrl while you click each slide that you want to move, and then drag them as a group to the new location.ND27-7-2023', 0, 0, 0, 1790966333386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_65b1167b4e2ddca8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What happens if you select the first and second slide and then click on the New Slide button on the toolbar?', '{"A":"A new slide is inserted as second slide in presentation","B":"A new slide is inserted as first slide in presentation","C":"A new slide is inserted as third slide in presentation","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Result: A new, blank (or default layout) slide appears as the third slide.Behavior: The software inserts the new slide immediately after the active selection (the second slide).Last updated question by NA on 07 May 2026', 0, 0, 0, 1790966333386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_93c8d965887d7170', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of the following pane is not available in the Task Pane of PowerPoint?', '{"A":"Getting Started","B":"Clip Art","C":"Word Art","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Word Art is not available in Task Pane. It is available in the Insert option and view as a drop-down not on the task pane***ND11-12-2022', 0, 0, 0, 1790966333386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_918b3c9dd8c5f285', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In MS PowerPoint, on mouse click option can be used by?', '{"A":"Transition & on mouse click","B":"Format & on mouse click","C":"Insert & on mouse click","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Go to the Transitions tab on the top ribbon.Look at the Advance Slide group on the far right side.Check the box for On Mouse Click so your slide advances when you click your mouse.', 0, 0, 0, 1790966333464) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_bbd44b1256395a98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In PowerPoint, the dotted areas in an empty slide are called?', '{"A":"Template","B":"Placeholders","C":"Theme","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The dotted areas in an empty slide in PowerPoint are called placeholders.Placeholders are containers on slide layouts that hold content like text, images, videos, and more.They are pre-formatted to make it easier to format slides consistently.', 0, 0, 0, 1790966333465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d98caee67ab4ba8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'How to edit chart in ppt presentation?', '{"A":"Triple-click the chart object","B":"Click and drag the chart object","C":"Double-click the chart object","D":"Click the chart object"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790966333465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fd2cfce1bf2fb0e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In MS PowerPoint we can go to next slide by ______?', '{"A":"Mouse","B":"Enter button","C":"Space bar","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS PowerPoint, you can advance to the next slide using:Mouse: By clicking the mouse buttonEnter button: By pressing the Enter key on your keyboardSpace bar: By pressing the Space bar on your keyboardAdditionally, you can also use other methods such as:Using the arrow keys (→ or ↓)Using the Page Down keyUsing the mouse wheelUsing the presentation remote (if you have one)', 0, 0, 0, 1790966333465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_69a2019c6c918bc1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Slide ______ of the effects that determine how a slide moves in and out of the view in the slideshow.', '{"A":"Transition","B":"Animation","C":"Layout","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Slide Show view means you can see your presentation graphics, animated effects, and transition effects, etc. on full screen.To start the Slide show view, Press F5.To exit the Slide Show view, press ESC.******ND30-12-2022', 0, 0, 0, 1790966333465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1f381e66767e028a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'You can create a new presentation by completing all of the following except ______?', '{"A":"Clicking file, new","B":"Pressing Ctrl + N","C":"Clicking the new button on the standard toolbar","D":"Clicking file open"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Clicking "File" > "New" (or Ctrl + N) creates a new presentation.Clicking the "New" button on the Standard toolbar also creates a new presentation.Pressing Ctrl + N is a shortcut to create a new presentation.However, clicking "File" > "Open" is used to open an existing presentation, not create a new one.Last updated 17 July 2026 by NA', 0, 0, 0, 1790966333465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1e81a71eedebf8a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of the following is not a MS Powerpoint View?', '{"A":"Slide View","B":"Slide Show View","C":"Orientation View","D":"Presentation View"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Orientation View" is not a MS PowerPoint View. The correct views in Microsoft PowerPoint are: Slide View (also known as Normal View) Slide Sorter View Notes Page View Reading View Slide Show View (full-screen presentation mode) ****RY12-02-23', 0, 0, 0, 1790966333465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d4ef5bbf828ec3a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which tab is not available on left panel when you open a presentation in PowerPoint?', '{"A":"Outline","B":"Slides","C":"Notes","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The "Notes" section is located below the slide, not on the left panel. The left panel mainly focuses on slide navigation and outlining.', 0, 0, 0, 1790966333465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0f7fb5087d83b78e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'How do you insert a new slide in MS PowerPoint?', '{"A":"Insert + New Slide","B":"File + New Slide","C":"Edit + New Slide","D":"View + New Slide"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To insert a new slide in MS PowerPoint, you can use the "Insert" tab and then click on "New Slide."', 0, 0, 0, 1790966333525) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_73ea281456236299', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which is the default page set up orientation of slide in MS PowerPoint ?', '{"A":"Horizontal","B":"Portrait","C":"Landscape","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The default for PowerPoint slides is landscapeLandscape orientation generally refers to the camera''s orientation in a horizontal display. ND29-5-2023', 0, 0, 0, 1790966333525) ON CONFLICT(id) DO NOTHING;
