INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1551feb5860077de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of these keys is used in PowerPoint to replace the text ?', '{"A":"Ctrl + A","B":"Ctrl + F","C":"Ctrl + V","D":"Ctrl + C"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + F is used in PowerPoint to replace the text.', 0, 0, 0, 1790966333525) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_531928620837fe8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Objects on slide that holds text are called', '{"A":"Place holders","B":"Cell tip","C":"Both","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Microsoft PowerPoint, placeholders are boxes with dotted borders that contain content (text) and reside within a slide layout. All built-in slide layouts that come with PowerPoint contain content placeholders.*************VU CBT FIA PAPER 26-12-2021', 0, 0, 0, 1790966333525) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3d89319ed1b008e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which of the following should used when you want to add a slide to an existing presentation?', '{"A":"File, open","B":"File, new","C":"Insert, new slide","D":"File, add a new slide"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Insert, new slide is used for add new slide', 0, 0, 0, 1790966333525) ON CONFLICT(id) DO NOTHING;
