INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a222d63d3a96c021', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'in MS-Office PowerPoint, we can find any and every command on the', '{"A":"Menu bar","B":"Standard tool bar","C":"Formatting tool bar","D":"Drawing tool bar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The menu bar is the part of a browser or application window, typically at the top left side, that houses drop-down menus that allow the user to interact with the content or application in various ways.', 0, 0, 0, 1790966333525) ON CONFLICT(id) DO NOTHING;
