INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_7dfb40bbe79fd8dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'The predefined slide formats in PowerPoint are called?', '{"A":"Slide Layout","B":"Speaker Notes","C":"Outline","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PowerPoint includes built-in slide layouts, and you can modify these layouts to meet your specific need', 0, 0, 0, 1790966333603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_102d5f3761c72a60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which effect we see as the slides of a PowerPoint changes over', '{"A":"Effect","B":"Transition","C":"Timing","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A slide transition is the visual effect that occurs when you move from one slide to the next during a presentation. You can control the speed, add sound, and customize the look of transition effects.', 0, 0, 0, 1790966333603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6b58d35c0eb5a6fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What is the minimum Zoom Percentage in PowerPoint?', '{"A":"5%","B":"10%","C":"400%","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ZOOM Percentage MS Word (minimum) 10% MS Word (maximum) 500% MS Power Point(minimum) 10% MS PowerPoint(maximum) 400% MS Excel (maximum) 400% MS Excel (minimum) 10%', 0, 0, 0, 1790966333603) ON CONFLICT(id) DO NOTHING;
