INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2c4b422f8288a490', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'From the following _________ view is not one of PowerPoint view', '{"A":"Slide","B":"presentation","C":"outline","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In PowerPoint, the standard views include:Slide view: where you see and edit individual slides.Outline view: where you see and edit the text in the presentation in outline form.Notes Page view: where you see and edit speaker notes.Presentation view is not a standard view nameND27-7-2023', 0, 0, 0, 1790966333603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_089b95a5375e6843', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'What is a Presentation?', '{"A":"oral communication","B":"shares factual information","C":"verbal communication","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A presentation is a kind of verbal communication in which a person shares fact-based information to an audience that is specific', 0, 0, 0, 1790966333603) ON CONFLICT(id) DO NOTHING;
