INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3d10f6e1dd1a6bdd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'In Microsoft PowerPoint customize how the new slide appears on the screen in the slideshow is applied:', '{"A":"Design","B":"Transition","C":"Animation","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Slide transitions are the animation like effects that happen when you move from one slide to the next during a presentation.', 0, 0, 0, 1790966333661) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9269c328c96763ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'How to open a presentation in power point shortcut key', '{"A":"Ctrl+D","B":"Ctrl+O","C":"Ctrl+V","D":"Ctrl+C"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl+O: Open an existing presentation.', 0, 0, 0, 1790966333661) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1c3898682f45fdea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_ppt', 'Which key is used for Help in PowerPoint?', '{"A":"F1","B":"F2","C":"F3","D":"F4"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation F1 function key is used for opening help.Some of the top shortcut keys in Microsoft Word are:Ctrl + S: SaveCtrl + C: CopyCtrl + X: CutCtrl + V: PasteCtrl + Z: UndoCtrl + Y: RedoCtrl + B: BoldCtrl + I: ItalicCtrl + U: UnderlineCtrl + F: Find', 0, 0, 0, 1790966333661) ON CONFLICT(id) DO NOTHING;
