INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e0285785ccb46619', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'What does ''PDF'' stand for?', '{"A":"Print Document Format","B":"Portable Disc Format","C":"Portable Document Format","D":"Portable Document Firewall"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: Portable Document Format (PDF)Developed by: Adobe Inc.Introduced: 1993Co-founder associated with Adobe: Charles GeschkePurpose: Reliable document sharing and viewingان سولات کو ضرور پڑھیںClick hereLast verified on 01-07-2026', 0, 0, 0, 1790966333773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_06e82107dfa2c94a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'BCC stands for _____?', '{"A":"Basic Carbon Copy","B":"Blind Carbon Copy","C":"Business Carbon Copy","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BCC stands for: Blind Carbon CopyUsed in: Email communicationPurpose: Hides recipient email addresses from other recipientsAdditional information:CC (Carbon Copy): Recipients are visible to allBCC: Recipients are hidden from everyone except the senderLast verified on 16-01-2026', 0, 0, 0, 1790966333773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5e350b9f59eadb3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'IP stands for ________?', '{"A":"Internet Process","B":"Intranet Protocol","C":"Internet Protocol","D":"Internal Protocol"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IP stands for Internet Protocol.It is a set of rules used to address and route data between devices on a network.Every device on an IP network can be identified using an IP address.Additional information:IPv4: Uses 32-bit addresses.IPv6: Uses 128-bit addresses.Example of IPv4: 192.168.1.1Last verified on 27-09-2026', 0, 0, 0, 1790966333773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_11a3952689dc9a84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'ASCII stands for:', '{"A":"American Standard Conduct for Information Interchange","B":"Armenia Standard Code for Information Interchange","C":"American Standard Code for Information Interchange","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ASCII: American Standard Code for Information InterchangePurpose: Character encoding standardRange: 0–127Represents: Letters, numbers & punctuationWork began: May 1961Definitive version: Published in 1968Last updated by NA ON 16-09-2026', 0, 0, 0, 1790966333773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b9ada4d2ce8db43d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'SATA stands for', '{"A":"Serial advanced technic attachment","B":"Serial advanced technology attachment","C":"Serial advised technology attachment","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SATA: Serial Advanced Technology AttachmentType: Computer hardware interfaceUsed for: Connecting storage devicesDevices: HDDs, SSDs & optical drivesConnection: Storage device → MotherboardLast updated NS on 13-09-2026', 0, 0, 0, 1790966333773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2a64c548449c44a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'CDMA stands for _____?', '{"A":"Code Digital Multiple Access","B":"Central Data Management Access","C":"Code Division Multiple Access","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CDMA stands for Code Division Multiple Access. It is a digital wireless radio transmission technology Used in mobile phones and communication networksLast updated NA on 10-09-2026', 0, 0, 0, 1790966333773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_53e2c0500ebf95b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'ISDN stands for _____?', '{"A":"Internet Services Data Network","B":"International Standard Digital Network","C":"Integrated Services Digital Network","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ISDN stands for Integrated Services Digital Network.It is a set of communication standards. It transmits voice, video, and data simultaneously.Last updated NA on 10-09-2026', 0, 0, 0, 1790966333773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2594ddfce7de9390', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'DHCP stands for?', '{"A":"Dynamic Host Configuration Protocol","B":"Dynamic Host Control Protocol","C":"Digital Host Configuration Protocol","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DHCP stands for Dynamic Host Configuration Protocol.It is a network protocol that automatically assigns devices IP addresses and other network configuration settings.DHCP helps devices connect to a network without manually entering an IP address.Last verified on 10-09-2026', 0, 0, 0, 1790966333773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c8cb9b0b4e16bcdc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'VLSI stands for _____?', '{"A":"Very large scale integration","B":"Very large scale immunization","C":"Very large scale industry","D":"Very low scale immunization"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation VLSI stands for Very Large Scale IntegrationVLSI began in 1970It is the process of creating an integrated circuit (IC) by combining thousands, millions, or even billions of transistors onto a single tiny silicon chip', 0, 0, 0, 1790966333862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4a5e2509f7014ba3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'BASIC stands for?', '{"A":"Beginner’s All-purpose Symbolic Instruction Code","B":"Binary Array System for Integrated Coding","C":"Basic Application Software in Computing","D":"Backup And System Interface Controller"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BASIC stands for Beginner''s All-purpose Symbolic Instruction Code.BASIC is a family of high-level programming languages.It was created in 1964 by John Kemeny and Thomas Kurtz.It was developed at Dartmouth College.Its main purpose was to make computer programming easier and accessible to students.Last verified on 08-09-2026', 0, 0, 0, 1790966333862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6d8ce63ab3c5ce24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'JPEG stands for?', '{"A":"Joint Photo Editing Group","B":"Joint Photographic Experts Group","C":"Joint Photo Expert Group","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation JPEG stands for Joint Photographic Experts Group.JPEG is a common digital image compression and file format.The name comes from the organization that developed the standard.JPEG is widely used for photographs and web images.Its common file extensions are .jpg and .jpeg.Last verified on 08-09-2026', 0, 0, 0, 1790966333862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e39f96e192a0eebb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'LCD stands for _____?', '{"A":"Liquid Crystal Disk","B":"Liquefied Crystal Display","C":"Liquid Crystal Display","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LCD = Liquid Crystal DisplayLCD is a flat-panel display technology.It is used in televisions, computer monitors, smartphones, calculators, and other electronic devices.It uses liquid crystals to control light and produce images.Last verified on 07-09-2026', 0, 0, 0, 1790966333862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_55d769728d88d8ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'SIM stands for ______?', '{"A":"Single in-line Module","B":"Single in-Line Memory","C":"Subscriber Identity Module","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SIM stands for Subscriber Identity Module.A SIM card securely stores the subscriber''s identity and enables access to a mobile network.Additional information:First SIM card developed: 1991Invented in: Munich, GermanyManufacturer: Giesecke+Devrient (G+D)PIN: Personal Identification NumberPUK: Personal Unblocking KeyLast verified on 22-07-2026', 0, 0, 0, 1790966333862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_492b3376f5574601', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'CD stands for?', '{"A":"Compact Disk","B":"Computer Device","C":"Central Data","D":"Control Disk"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "CD" most commonly stands for Compact DiscUsed for storing digital audio, software programs, documents, and videosOrigin: Co-developed by Philips and Sony, introduced in the early 1980sLast updated by NA on 26 April 2026', 0, 0, 0, 1790966333862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4abb77a76ce91dfe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'HTML stands for _____?', '{"A":"Hypertext Mark Language","B":"Hypertext Markup Language","C":"Hi Tech Meaningful Language","D":"Hypertext Markup Link"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTML: Hypertext Markup Language.Purpose: Creates and structures web pages.HTML File Extension: .html or .htm.It uses tags to structure content such as headings, paragraphs, images, links, and tables.Last verified on 11-08-2026', 0, 0, 0, 1790966333862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_45d0f1f784908909', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'SMS stands for ____?', '{"A":"Send Message Send","B":"Short Message Service","C":"Small Message Send","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SMS stands for Short Message Service.It is a text messaging service used on mobile phones and other communication systems.SMS was defined in 1986 as part of the Global System for Mobile Communications (GSM) standards.The first SMS message was sent on 3 December 1992.The first SMS was sent by Neil Papworth from a computer to a Vodafone mobile phone.First SMS Content: “Merry Christmas”.Last verified on 09-08-2026', 0, 0, 0, 1790966333862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6cf4463cb1687b61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'GUI stands for ______?', '{"A":"Graphical Use Interface","B":"Graphical User Interface","C":"Graphic User Interface","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GUI stands for Graphical User Interface.It is a type of user interface that allows users to interact with electronic devices using icons, windows, menus, and buttons instead of typing commands.The first GUI was developed at Xerox PARC in the early 1980s.Additional information:CLI – Command Line InterfaceCUI – Character User InterfaceVUI – Voice User InterfaceNUI – Natural User InterfaceLast verified on 03-07-2026', 0, 0, 0, 1790966333925) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4b861bd7a4ca9153', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'ICT stands for _____?', '{"A":"Information and Communication Technology","B":"International Computer Technology","C":"Internal Communication Tool","D":"International Communication Technology"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ICT stands for Information and Communication Technology.It refers to technologies used to collect, process, store, and communicate information.ICT includes computers, mobile phones, the internet, networks, and communication systems.It is widely used in education, business, healthcare, and government.ICT helps people access and share information quickly and efficiently.Last verified on 08-08-2026', 0, 0, 0, 1790966333926) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_392604efa2ea3afd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'EBCDIC stands for _______?', '{"A":"Extended Binary Coded Decimal Interchange Code","B":"Extended Bit Code Decimal Interchange Code","C":"Extended Bit Case Decimal Interchange Code","D":"Extended Binary Case Decimal Interchange Code"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation EBCDIC stands for Extended Binary Coded Decimal Interchange Code.Developed by IBM.Used mainly on IBM mainframe computers.It is an 8-bit character encoding system.Last verified on 08-08-2026', 0, 0, 0, 1790966333926) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e2410fa1e7374dc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'What is DMA stand for?', '{"A":"Direct Memory Access","B":"Direct Module Access","C":"Direct Memory Allocation","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DMA stands for Direct Memory Access.It is a method that allows an I/O device to transfer data directly to or from main memory (RAM).The CPU does not need to handle every individual byte of the transfer.DMA can improve data-transfer speed and reduce CPU workload.It is commonly used for devices such as disk drives, network cards, and sound cards.Last verified on 07-08-2026', 0, 0, 0, 1790966333926) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1e7b69c53a45a1d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'BIOS stands for ______?', '{"A":"Board Input Output System","B":"Back Input Output System","C":"Basic Input Output System","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BIOS stands for Basic Input Output System.Additional information:BIOS is a firmware stored on a computer’s motherboard.Initializes hardware during booting and provides runtime services.Acts as an interface between operating system and hardware.Last verified on 04-02-2026', 0, 0, 0, 1790966333926) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_875fab0a14a5abe7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'VGA stands for _____?', '{"A":"Visual Graphics Adapter","B":"Video Graphics Array","C":"Video Graphic Adapter","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation VGA stands for Video Graphics Array.It is a display standard used to transmit video signals from a computer to a monitor.VGA was introduced by IBM in 1987 with the PS/2 computer series.The original VGA standard supports a maximum resolution of 640 × 480 pixels at 60 Hz.It uses a 15-pin D-sub (DE-15) connector.Last verified on 06-08-2026', 0, 0, 0, 1790966333926) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9403417891ebdbb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'SQL stands for _____?', '{"A":"Structured Query Language","B":"Sequence Query Language","C":"Structured Query Logo","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: Structured Query LanguageSQL is the standard language used to store, retrieve, update, and manage data in relational databases.Additional information:Designed by: Donald D. Chamberlin & Raymond F. BoyceFirst appeared: 1974Latest ISO Standard: SQL:2016 (December 2016)Main SQL Commands: SELECT, INSERT, UPDATE, DELETE, CREATELast verified on 22-07-2026', 0, 0, 0, 1790966333926) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_479885c14792fdb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'AI stands for ______?', '{"A":"Artificial Information","B":"Artificial Intelligence","C":"Actual Information","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AI stands for Artificial Intelligence.It refers to machines that can think, learn, and make decisions like humans.AI is widely used in computers, mobile apps, and robotics.It helps in tasks like voice recognition, image detection, and automation.This is used in 5th generation computers.Last verified on 19-04-2026', 0, 0, 0, 1790966333926) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_4be153f67c560b27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'LLM stands for?', '{"A":"Learning Language Module","B":"Legal Law Management","C":"Large Language Model","D":"License of Law Management"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LLM stands for Large Language Model.It is an advanced Artificial Intelligence (AI) model trained on large amounts of text data.LLMs can understand, generate, summarize, and translate human language.They are widely used in chatbots, virtual assistants, and content generation.Examples include ChatGPT, Gemini, Claude, and Llama.Verified & Updated', 0, 0, 0, 1790966333995) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_27746465a56bc38b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'In networking, ''VPN'' stands for?', '{"A":"Virtual Private Network","B":"Visual Private Network","C":"Virtual Protocol Network","D":"Virtual Protocol Networking"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation VPN stands for Virtual Private Network.It creates a secure and encrypted connection over the internet to protect user data and privacy.A VPN masks the user''s IP address and helps hide their browsing activity.It is commonly used for secure remote access and online privacy.Last verified on 08-07-2026', 0, 0, 0, 1790966333996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_86cf2d2bdce06f37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'The term ''SOP'' in office administration stands for?', '{"A":"Standard Operating Procedure","B":"Standard Official Procedure","C":"System of Operations","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SOP stands for Standard Operating Procedure.It is a written document that provides step-by-step instructions for performing routine tasks consistently and correctly.SOPs improve efficiency, quality, safety, and accountability in organizations.They help employees follow the same standard process.Last verified on 08-07-2026', 0, 0, 0, 1790966333996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3456573ed46a3239', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'DOS stands for ______?', '{"A":"Digital operating system","B":"Disk operation system","C":"Disk operating system","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DOS stands for Disk Operating System.It is an early type of computer operating system used to manage files and programs.It works through text-based commands (command line).A famous example is MS-DOS used in early PCs. Dennis Ritchie is the father of MS-DOS.It was developed in 1982.Last verified on 19-04-2026', 0, 0, 0, 1790966333996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a9a82524eeabc0e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'LED stands for _____?', '{"A":"Light Emitting Diode","B":"Laser Emitting Device","C":"Low Energy Device","D":"Liquid Emitting Display"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LED (Light Emitting Diode) is a semiconductor device that emits light when electric current passes through it.It is widely used in lighting, displays, electronic indicators, and screens.Additional information:Energy efficiency: Up to 90% more efficient than traditional bulbsFirst discovery: H. J. Round – 1907Early research: Oleg Losev – 1927Practical LED development: James R. Biard – 1961First commercial production: October 1962 (Nick Holonyak)Last verified on 12-03-2026', 0, 0, 0, 1790966333996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_026491c2cca51102', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'What does SDLC stand for?', '{"A":"Software Development Life Cycle","B":"System Development Life Cycle","C":"Software Design Life Cycle","D":"System Design Life Cycle"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SDLC stands for Software Development Life Cycle.SDLC is a structured process for developing software efficiently.It defines stages from planning to maintenance.Ensures software is high-quality, cost-effective, and meets requirements.Common phases: Requirement Analysis → Design → Implementation → Testing → Deployment → Maintenance.Last verified on 07-02-2026', 0, 0, 0, 1790966333996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5099469af606f2ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'In CT Scan, CT stands for _____?', '{"A":"Computer Test","B":"Central Technology","C":"Computed Tomography","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CT Scan is a medical imaging technique.It uses X-rays and computers to create cross-sectional images of the body.Helps in diagnosing diseases, injuries, and internal conditions.Additional Details / FactsFirst CT scanner was invented in 1972 by Sir Godfrey Hounsfield.CT images are also called slices, showing body structures in detail.', 0, 0, 0, 1790966333996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3df4f3e74a738443', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'In computing, NOS stand for?', '{"A":"Network Operating System","B":"Node Open Software","C":"Non-operating software","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NOS stands for Network Operating System.It is software that manages network resources and allows computers to communicate within a network.Such as file sharing and printer access.', 0, 0, 0, 1790966333996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a94f7d334d27b45b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'PNG stands for ____?', '{"A":"Public Network Graphics","B":"Private Network Graphics","C":"Portable Network Graphics","D":"none of the above","E":"all of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PNG is a file format used for lossless image compression.', 0, 0, 0, 1790966334051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_e6c60246cba3fe5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'PB stand for', '{"A":"Petabyte","B":"Plumber","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Petabyte (PB), a unit of information equivalent to 1000 terabytes which is used, for example, to quantify computer memory or storage capacity.', 0, 0, 0, 1790966334051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_44a6ff0ea4a5316c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'CLI stands for _____?', '{"A":"Common-line interface","B":"Command-line internet","C":"Command-line interface","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A command-line interface (CLI) is a text-based user interface (UI) used to run programs, manage computer files and interact with the computer.Command-line interfaces are also called command-line user interfaces.*************VU CBT FIA PAPER 15-12-2021', 0, 0, 0, 1790966334051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ca2c9ad26727c7ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'CAI stands for ______?', '{"A":"Community Assisted Instruction","B":"Computer Assistant Instruction","C":"Computer Assisted Instruction","D":"Characteristics of Assistant Instructor"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CAI refers to using computers to help in the teaching and learning process.It enhances learning by providing interactive and personalized instruction.', 0, 0, 0, 1790966334051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2e92bafe02c91fa2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'Wi-Fi stands for ______?', '{"A":"Wireless fidelity","B":"Wire fidelity","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wi-Fi stands for Wireless fidelity.The minimum length of Wi-Fi password = 8.The maximum length of Wi-Fi password = 63.', 0, 0, 0, 1790966334051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_97104edf47650f0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'DSL stands for in computer term?', '{"A":"Digital Subscriber Loop","B":"Digital Subscriber Line","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DSL stands for Digital Subscriber LineIt is a modern technology that uses existing telephone lines to transport high-bandwidth dataThey provided dedicated, point-to-point, public network access.', 0, 0, 0, 1790966334051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5dbc56a9caa2a422', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'IC stands for _____?', '{"A":"Insulated Cable","B":"Intelligent Chip","C":"Integrated Circuit","D":"Internal Component"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Integrated Circuit (IC) is a tiny electronic device that contains a large number of electronic components.Such as transistors, diodes, and resistors, on a single piece of semiconductor material, like silicon.It''s a crucial component in modern electronics!', 0, 0, 0, 1790966334051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_db894f654bb5923f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'PIN stands for _____?', '{"A":"Personal identification number","B":"Payment identification number","C":"Personal identification numeric","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PIN is a short for a personal identification number.The PIN is a set of personal numbers used to prove positive identification.It is often used with automated bank teller machines, telephone calling cards, and accessing wireless networks.', 0, 0, 0, 1790966334051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d6deae3f955e291d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'COMPUTER stands for ________?', '{"A":"Competent Operated Machine Particularly Used for Technical Education and Research","B":"Commonly Operated Machine Particularly Used for Technical Education and Research","C":"Commonly Operated Machine Particularly Used for Trade Education and Research","D":"Commonly Operated Machine Particularly Used for Technical Electron and Research"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term COMPUTER is often expanded as an acronym in educational contexts to highlight its technical and educational use.It captures the widely accepted expansion for learning purposes.', 0, 0, 0, 1790966334114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9685af557992c772', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'CAD stands for _______?', '{"A":"Computer aided design","B":"Computer algorithm for design","C":"Computer application in dosing","D":"Computer analogue design"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CAD, or CADD, is short for computer-aided design or computer-aided design and drafting.CAD is a software used in the computer systems by: EngineersArchitectsDraftersArtists', 0, 0, 0, 1790966334114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_06940e65b6a259bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'RTF stands for:', '{"A":"Round Text Format","B":"Rich Text Format","C":"Rich Text File","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RTF stands for Rich Text Format It is a universal document file format and is easily read by many of the word-processing packages.', 0, 0, 0, 1790966334114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_81efd264dbabea73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'FIFO in inventory management stands for ______?', '{"A":"First in first out","B":"First in last out","C":"First in fast out","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FIFO (First In, First Out) means that the oldest inventory items are sold or used first. It is commonly used in inventory management to prevent obsolescence and spoilage, especially in perishable goods.', 0, 0, 0, 1790966334114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_649e1939dd560167', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'DBMS stands for ______?', '{"A":"Database Management Software","B":"Database Management System","C":"Database Management Service","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DBMS is a software system that allows users to create, manage, and manipulate databases.It ensures data integrity, security, and easy access to data.', 0, 0, 0, 1790966334114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a4cfe0f0f4ea1314', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'What does DVR stand for?', '{"A":"Digital Voice Recorder","B":"Data Visual Register","C":"Digital Video Recorder","D":"Dynamic Voltage Regulator"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DVR stands for Digital Video Recorders.They are devices used to record and store video content, as explained by Infiniti Electro-Optics.', 0, 0, 0, 1790966334114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_c5755a7e15872660', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'What does NVR stand for?', '{"A":"Network Video Recorder","B":"National Video Receiver","C":"New Visual Radar","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NVR (Network Video Recorder) is a device used to record video footage from IP (network) cameras.It stores and manages surveillance video data digitally over a network.', 0, 0, 0, 1790966334114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_88afa13d71cc69f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'ISP in computer terminology stand for _____?', '{"A":"Internet service provider","B":"Intel system password","C":"Internet service protocol","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Internet service provider is an organization that provides services for accessing, using, or participating in the Internet. *************VU CBT FIA PAPER 13-12-2021', 0, 0, 0, 1790966334114) ON CONFLICT(id) DO NOTHING;
