INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0d7ee4834f69ed84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'DPI stands for ____?', '{"A":"Dots processing inch","B":"Diagram per inch","C":"Dots per inch","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DPI (dots per inch) refers to the output resolution of a printer or image setter.PPI (pixels per inch) refers to the input resolution of a photograph or image.', 0, 0, 0, 1790966334202) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5443e9f75833b9cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'API stands for _____?', '{"A":"Algorithmic Protocol Interface","B":"Adapter Protocol Interface","C":"Application Programming Interface","D":"Accellerated Programming Interface","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation API stands for Application Programming Interface. API is a software intermediary that allows two applications to talk to each other.AGM 09-2-2023', 0, 0, 0, 1790966334202) ON CONFLICT(id) DO NOTHING;
