INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_968f5d7cb2ef64fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'In computing, KB stands for what ?', '{"A":"Kili Bind","B":"KiloByte","C":"Kilo Basic","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation KB stands for KilobyteMB stands for MegabyteGB stands for GigabyteTB stands for Terabyte*******VU CBT FIA SI ASI PAPER 13-12-2021', 0, 0, 0, 1790966334202) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_54f6f984333cb761', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'CSS stands for _________', '{"A":"cascading stylish sheet","B":"cascade style sheet","C":"cascading style sheet","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CSS stands for cascading style sheet CSS is a cornerstone technology of the World Wide Web, alongside HTML and JavaScript.CSS is Container for Style rules for HTML elements (tags)CSS is Developed by: World Wide Web Consortium (W3C)CSS is Initial release: on 17 December 1996The latest release of CSS is: CSS 2.1: Level 2 Revision 1; 12 April 2016*********FIA VU CONSTABLE PAST PAPER 2021****nd9-2-2023', 0, 0, 0, 1790966334202) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8c82c33b5ac39cee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'MIME is an abbreviation of:', '{"A":"Multipurpose Internet Mail Extensions","B":"Multipurpose International Mail Entity","C":"Multipurpose Internet Mail Email","D":"Multipurpose International End","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Multipurpose Internet Mail Extensions (MIME) is an Internet standard that extends the format of email messages to support text in character sets other than ASCII, as well as attachments of audio, video, images, and application programs.', 0, 0, 0, 1790966334202) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_cd2690d814ab7d72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'SSI stand for', '{"A":"small-school integration","B":"small-scale internet","C":"small-scale integration","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Short for small-scale integration, SSI is a chip generation first introduced in 1964 with between 1 and 10 transistors and 1 and 12 logic gates.************FIA CBT VU PAPER 17-12-2021', 0, 0, 0, 1790966334202) ON CONFLICT(id) DO NOTHING;
