INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d5b72027335c3d7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'CU stands for', '{"A":"central  unit","B":"computer unit","C":"control unit","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The control unit (CU) is a component of a computer''s central processing unit (CPU) that directs the operation of the processor.', 0, 0, 0, 1790966334274) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3d58a250e6eec703', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'COBOL stands for _______', '{"A":"Common Business Oriented Language","B":"Computer Binary Operation Language","C":"Common Basic Output Language","D":"Central Business Operating Language"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation COBOL stands for Common Business-Oriented Language. It is a high-level programming language developed in 1959, Designed specifically for business applications like financial and administrative systemsStable release: ISO/IEC 1989:2023 / 2023', 0, 0, 0, 1790966334274) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_80d1aef00f8bc070', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'PROM stands for _______', '{"A":"Program Read-Only Memory","B":"Programmable read memory","C":"Programmable Read-Only Memory","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PROM stands for Programmable Read-Only Memory. A programmable read-only memory (PROM) is a form of digital memory where the setting of each bit is locked by a fuse or anti-fuse. It is one type of read-only memory .', 0, 0, 0, 1790966334274) ON CONFLICT(id) DO NOTHING;
