INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0c152077a9cda28e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Third generation computers used ______?', '{"A":"Vacum  Tubes","B":"Transistors","C":"Integrated circuits","D":"Artificial Intelligence"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Third Generation (1965–1971): Integrated Circuits (ICs)A small semiconductor chip, usually made of silicon.Contains many tiny electronic components, including transistors/MOSFETs.Additional information:First Generation (1946–1959): Vacuum tubesSecond Generation (1959–1965): TransistorsThird Generation (1965–1971): Integrated Circuits (ICs)Fourth Generation (1972–1980): VLSI and microprocessors', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_582642ff16c26e80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'IBM 1401 is_____?', '{"A":"Fourth generation computer","B":"First generation computer","C":"Third generation computer","D":"Second generation computer","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IBM 1401 belongs to the second generation. Second generation of computers: 1956 to 1963Used in the second generation: TransistorsAdditional information:IBM stands for International Business MachinesFounded on June 16, 1911. Formerly: Computing-Tabulating-Recording Company (1911–1924)Renamed to IBM: 1924Founders George Winthrop FairchildCharles Ranlett FlintHerman HollerithHeadquarters: 1 Orchard Road, Armonk, New York, United StatesArea served: 170 countries', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d23eb17ca6245bbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'IBM stands for?', '{"A":"International Business Machine","B":"Integrated Business Machine","C":"Information Business Machines","D":"International Business Model","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IBM: International Business Machines CorporationNickname: Big BlueFounded: June 16, 1911Headquarters: Armonk, New York, USANature: American multinational technology corporationOperations: Over 175 countriesFounders: Herman Hollerith, Charles Ranlett Flint, Thomas J. WatsonLast verified on 03-09-2026', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6c5ec01c56e23490', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Who is known as the father of computer?', '{"A":"Barbara Liskov","B":"Tim Berners-Lee","C":"Charles Babbage","D":"John von Neumann"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charles Babbage is known as the Father of the Computer.He designed the more advanced Analytical Engine, which featured a "Mill" (CPU) and a "Store" (memory).Additional information:He was an English polymath.Born: 26 December 1791 London, EnglandDied: 18 October 1871 (aged 79) London, EnglandLast updated on 09-03-2026', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eb047cef7a0463d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Who develop the idea for universal turing machines which become the basis for the first computer?', '{"A":"Bill gates","B":"Alan Turing","C":"Babbage","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charles Babbage designed the first concept of a programmable mechanical computer, earning him the title Father of the Computer.Alan Turing developed the theoretical foundation of modern computers and is regarded as the Father of Theoretical Computer Science and Artificial Intelligence.', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
