INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_05a2bb185cfeb98b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'UNIVAC is a _________?', '{"A":"Universal Automatic Computer","B":"First-generation computing device","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation UNIVAC (Universal Automatic Computer) was the first commercially produced computer.It delivered to the U.S. Census Bureau in 1951. It was a first-generation computing device.It is using vacuum tubes for processing, like ENIAC.', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
