INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9a0d31750415ba27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Who invented liquid crystal display panel?', '{"A":"Louis Zanoni","B":"David Sarnoff","C":"George Heilemier","D":"Friedrich Reinitor"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A liquid-crystal display is a flat-panel display or other electronically modulated optical device that uses the light-modulating properties of liquid crystals combined with polarizers. Liquid crystals do not emit light directly,instead using a backlight or reflector to produce images in color or monochrome.', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_564ed2aac4a6bd60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Who invented the first computer?', '{"A":"Barbara Liskov","B":"Tim Berners-Lee","C":"John von Neumann","D":"Charles Babbage"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charles Babbage is known as the Father of the Computer.He was an inventor from the UK.He was born in 1791.He was died in 1871.', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_283afd05594dae24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Which of the following technologies was used in fifth generation computer??', '{"A":"Vacum  Tubes","B":"Transistors","C":"Integrated circuits","D":"Artificial intelligence"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Artificial intelligence is intelligence demonstrated by machines, as opposed to the natural intelligence displayed by humans or animals.First generation (1940 - 1956) vacuum tubes as a major piece of technology. The ENIAC is example of 1st generation computer.Second generation (1956 - 1963) use of transistors.Third generation (1964 - 1971) use of Integrated circuits.Fourth generation (1972 - 2010) use of the microprocessorFifth generation (2010 to present) use Artificial intelligence*********FIA VU CONSTABLE PAST PAPER 2021', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_869fa5f60b4307e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Microprocessors was introduced in which generation of computer?', '{"A":"Second Generation","B":"Fourth Generation","C":"Third Generation","D":"Both (A) and (B)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microprocessors are used in many other electronic devices, including:Computers,Digital systems,CalculatorsInventor of Microprocessors: Marcian E HoffMicroprocessors in 4th generation computer.ND7-5-2023AGM 09-2-2023', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
