INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_321c94c60d09a126', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Which of the following computer generation uses concept of artificial intelligence?', '{"A":"First generation","B":"Second generation","C":"Third generation","D":"Fifth generation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the fifth generation of computers, artificial intelligence was used.Artificial Intelligence came into use in fifth-generation computing devices.Fifth-generation computing devices were faster and more efficient.Using high-speed logic, and memory chips help in using Artificial Intelligence.The period of fifth-generation was 1980-onwards. ULSI-based microprocessors were used.****', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f27bac368317c8fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Who invented the the first Digital Computer?', '{"A":"John Vincent Atanasoff","B":"Daglus Elbert","C":"Charles Babbage","D":"Isaac Newton","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation John Vincent Atanasoff invented the first digital computer in 1930. The inventor of the first Digital Computer belonged to the country: USAJohn Vincent Atanasoff died in 1995.Digital computer:The Digital Computer operates on a Binary systemThe computer that processes both analog and digital signals is called a hybrid computer.ND7-5-2023', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a5cbf64684e141f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Which is used as first generation language?', '{"A":"Machine language","B":"Compiler","C":"HTML","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Machine language, or machine code, is a low-level language comprised of binary digits (1 and 2). Since computers are digital devices, they only recognize binary data.', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
