INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_fec6fe88dbc935de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Integrated Circuits (ICs) belonged to which generation of computers?', '{"A":"Second","B":"Fourth","C":"First","D":"Third","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An integrated circuit is a set of electronic circuits on one small flat piece of semiconductor material, usually silicon.Large numbers of tiny MOSFETs integrate into a small chip. First generation (1940 - 1956) vacuum tubes as a major piece of technology. The ENIAC is example of 1st generation computer.Second generation (1956 - 1963) use of transistors.Third generation (1964 - 1971) use of Integrated circuits.Fourth generation (1972 - 2010) use of the microprocessorFifth generation (2010 to present) use Artificial intelligence', 0, 0, 0, 1790966334612) ON CONFLICT(id) DO NOTHING;
