INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_8df9f15b39c86206', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Who invented C.D. (Compact Disc).', '{"A":"David Nobel with IBM","B":"Renold Johnson with IBM","C":"Bob Meltcofe","D":"James T. Russell"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Laser technology is used in compact discCompact Disc is an example of Optical StorageJames T. Russell invented C.D. (Compact Disc). co-developed by Philips and Sony to store and play digital audio recordings.history In August 1982, the first compact disc was manufactured.It was then released in October 1982 in Japan and branded as Digital Audio Compact Disc.It was released on March 2, 1983, in North America and Europe.FIA CBT VU PAPER 22-12-2021ND30-4-2023', 0, 0, 0, 1790966334612) ON CONFLICT(id) DO NOTHING;
