INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_791ca6713ecea7e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Third generation of computer are included:', '{"A":"Mainframe Computer","B":"Mini Computer","C":"Desktop compute","D":"All","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The period of third generation was from 1965-1971. The computers of third generation used Integrated Circuits (ICs) in place of transistors.*********VU FIA ASSISTANT PAST PAPER 02-01-2022', 0, 0, 0, 1790966334612) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_432934e58f6c4d89', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Tiktok invented year ______?', '{"A":"2010","B":"2014","C":"2016","D":"2020"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The app was launched in 2016 by the Chinese technology company ByteDance.Zhang Yiming founded ByteDance in 2012 and developed the news aggregator Toutiao and the video-sharing platform TikTok, formerly known as Musical.ly.***Facebook was Launched In February 2004YouTube was Launched In February 2005Twitter was Launched In March of 2006Whatsapp was Launched In May 2009Instagram was Launched In Oct 2010Tiktok was Launched In Oct 2016***************vu FIA CBT PAPER 15-12-2021', 0, 0, 0, 1790966334670) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eef65980471cc132', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'In 1940 the first electronic computer was invented by ____ .', '{"A":"Atana Soff","B":"Berry","C":"Both","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Atanasoff–Berry computer was the first automatic electronic digital computer. Limited by the technology of the day, and execution, the device has remained somewhat obscure.', 0, 0, 0, 1790966334670) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ed1d016886095d65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'IBM is also a big blue company ___', '{"A":"American calculator  company","B":"British computer company","C":"American computer company","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation International Business Machines Corporation (IBM) is an American company began in 1911, founded in Endicott, New York by trust businessman Charles Ranlett Flint, as the Computing-Tabulating-Recording Company (CTR) and was renamed "International Business Machines" in 1924. IBM is incorporated in New York', 0, 0, 0, 1790966334670) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_comp_office', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'MS Office', 'top_computer', 14, 1790966334727) ON CONFLICT(id) DO UPDATE SET total_mcqs = 14;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b0a92a768bc0f487', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'In MS Office, how we can change lowercase characters to uppercase characters, select correct combination of keys?', '{"A":"Shift + F3","B":"Shift + F2","C":"Shift + F1","D":"Shift + F4"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shift + F3 → Changes text case in MS Word.It cycles through:lowercaseUPPERCASECapitalize Each WordAdditional information:MS Word — Useful ShortcutsCtrl + B → BoldCtrl + I → ItalicCtrl + U → UnderlineCtrl + C → CopyCtrl + X → CutCtrl + V → PasteCtrl + Z → UndoCtrl + Y → RedoCtrl + S → SaveCtrl + P → PrintCtrl + A → Select All', 0, 0, 0, 1790966334785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_5f45df26c9bd929f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'What is the function of "Save as" in Microsoft Office?', '{"A":"To print the document","B":"Create a copy with new name/location","C":"To ask the file name and store data in the desired location","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Save As is used to save a file with a new name, location, or file format.It allows the user to specify the file name and storage location.The original file generally remains unchanged.Save updates the existing file, while Save As creates a new saved version.Last verified on 24-08-2026', 0, 0, 0, 1790966334785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6a7d8d4f47c352fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'In MS Office a feature that saves the document automatically after certain intervals is called?', '{"A":"Save","B":"Save As","C":"Auto Save","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Auto Save is a feature that automatically saves changes to a document at regular intervals.It helps reduce the risk of losing unsaved work if the program closes unexpectedly.Additional information:Save manually saves the current document.Save As saves the document with a new name, location, or file format.Last verified on 09-08-2026', 0, 0, 0, 1790966334785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_80ac8a71696055c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'Reasons to use Macro in Microsoft Office ?', '{"A":"Automate Frequently used tasks","B":"Home page","C":"Both a and b","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Macros in Microsoft Office automate repetitive, multi-step tasksSuch as formatting reports, cleaning data, or generating daily backups—into a single click or keyboard shortcut. They significantly increase productivity, ensure 100% consistency, and reduce human error Last updated 15-feb-2026', 0, 0, 0, 1790966334785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a12d1548dff0955a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'Which one is the most suitable reason to use Macro in MS Office (Word, Excel, PPT, etc)?', '{"A":"To record mouse move","B":"To record sound","C":"To automate repetative tasks","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The most suitable and primary reason to use Macros in MS Office (Word, Excel, PowerPoint) is to automate repetitive tasksLast updated 15-feb-2026', 0, 0, 0, 1790966334785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a4f1af27d615f71f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'Which of the following line spacing is invalid in MS Office?', '{"A":"Triple","B":"Multiple","C":"Double","D":"Single"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In MS Office, the valid line spacing are:Single (1.0)Double (2.0)Multiple (1.5, 2.5, etc.)Triple is not a standard line spacing in MS Office.Apply single spacing to the paragraph. Ctrl+1Apply double spacing to the paragraph. Ctrl+2Apply 1.5-line spacing to the paragraph. Ctrl+5', 0, 0, 0, 1790966334785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_de77bfc6ad0b6925', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'Which Version of the Microsoft office is not valid?', '{"A":"Office Vista","B":"Office XP","C":"Office 2007","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A version office Vista of Microsoft office is not validMicrosoft office:****ND4-12-2022ND11-2-2023ND10-3-2023', 0, 0, 0, 1790966334785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_95f6f3a3a685109d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'MS Office is a software  _____?', '{"A":"Horizontal Market Software","B":"Free ware","C":"Deep curve","D":"All of these above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation .Microsoft is an application softwareMicrosoft Office is an example of Horizontal market software.Microsoft Office 2016 for Mac apps from top left to bottom right: Word, Excel, PowerPoint, and Outlook. Microsoft Office was first announced by Bill Gates on August 1, 1988Microsoft Office Initial release date: November 19, 1990Programming languages of Microsoft Office: C++, Objective-CMicrosoft Office Developer: Microsoft Corporation, Jive SoftwareND10-3-2023', 0, 0, 0, 1790966334785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d58ef3fd3699501f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'Which of the not a valid MS Office Document?', '{"A":".docx","B":".pptx","C":".vob","D":".doc"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ".vob" file extension is not a valid MS Office document format. It is commonly associated with DVD video files. The other extensions listed (.docx, .pptx, .doc) are valid MS Office document formats for Word and PowerPoint files.', 0, 0, 0, 1790966334844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ffebf10b851c2bfd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'How many ways to save file in MS Office?', '{"A":"3","B":"4","C":"6","D":"1"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You can save the document in Microsoft Word in three ways:You can save by clicking File on the top left corner You can also save by just pressing ctrl + S Just press F12 ND10-3-2023', 0, 0, 0, 1790966334844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_3d3d83d0889ab5b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'MS office is ____?', '{"A":"Application Software","B":"Compiler","C":"programming","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft is an application softwareMicrosoft Office is an example of Horizontal market software.Microsoft Office 2016 for Mac apps from top left to bottom right: Word, Excel, PowerPoint, and Outlook. Microsoft Office was first announced by Bill Gates on August 1, 1988Microsoft Office Initial release date: November 19, 1990Programming languages of Microsoft Office: C++, Objective-CMicrosoft Office Developer: Microsoft Corporation, Jive SoftwareND10-3-2023', 0, 0, 0, 1790966334844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_2d4be3393196d4e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'Does MS Office save the Outlook file with an extension?', '{"A":".pps","B":".ppt","C":".pst","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Outlook Data File (. pst) contains your messages and other Outlook items and is saved on your computerpersonal-storage-table (. pst) off-line-storage-table (. ost)ND10-3-2023Sh4-9-2023', 0, 0, 0, 1790966334844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_b9504c6adf8a5e4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'Ms office provides help in many ways, which of these is one of them ?', '{"A":"What is this?","B":"Office assistant","C":"Help menu","D":"All"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Under the drop down where it says Choose commands from, select All Commands.Select Help from the list of commands to add to the Quick Access Toolbar.When you''re done, click OK.', 0, 0, 0, 1790966334844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_21c27492ea11fe0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_office', 'Which of these software applications was not part of the first version of Microsoft Office?', '{"A":"PowerPoint","B":"Outlook","C":"Paint","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft Outlook is an application that''s used mainly to send and receive emails. It''s also used to manage various types of personal data including calendar appointments and similar entries, tasks, contacts, and notes.', 0, 0, 0, 1790966334844) ON CONFLICT(id) DO NOTHING;